window.META_DB=[{"type":"pc","id":"vice-city","slug":"vice-city","title":"Grand Theft Auto: Vice City","description":"Tommy Vercetti takes over 1980s Miami in an open world that runs entirely in your browser. No plugins and no installer.","system":"PC (native WASM)","genre":"Open-world action","categories":"Open-world action","developer":"Rockstar North","publisher":"Rockstar Games","year":"2002 on PlayStation 2","players":"Single player"},{"type":"pc","id":"gta3","slug":"gta3","title":"Grand Theft Auto III","description":"The original 3D open world. Liberty City, 2001, running natively on WebAssembly with streamed assets.","system":"PC (native WASM)","genre":"Open-world action","categories":"Open-world action","developer":"DMA Design","publisher":"Rockstar Games","year":"2001 on PlayStation 2","players":"Single player"},{"type":"pc","id":"simpsons","slug":"simpsons","title":"The Simpsons: Hit & Run","description":"Springfield opens up across seven levels. Drive, walk and follow the story with the whole soundtrack streaming as you play.","system":"PC (native WASM)","genre":"Action-adventure with racing","categories":"Action-adventure with racing","developer":"Radical Entertainment","publisher":"Vivendi Universal Games","year":"2003 on PS2, Xbox, GameCube and PC","players":"Single player"},{"type":"pc","id":"minecraft","slug":"minecraft","title":"Minecraft","description":"Build, mine and survive in endless block worlds. Minecraft 1.8.8 running as a WebAssembly build, with your worlds saved on your device.","system":"PC (native WASM)","genre":"Sandbox survival","categories":"Sandbox survival","developer":"Mojang Studios","publisher":"Xbox Game Studios","year":"2011 on PC","players":"Single player"},{"type":"flash","id":"the-last-stand-union-city","slug":"the-last-stand-union-city","title":"The Last Stand: Union City","description":"The Last Stand: Union City is a 2011 zombie action RPG where players scavenge, shoot and survive through a ruined metropolis.","about":"Set in a city overrun by the undead, this action RPG mixes shooting with scavenging and survival. Players can choose Survivor mode, which adds hunger and sleep as ongoing needs, or Run'n'Gun mode for a more action-focused approach. Movement, combat, inventory and companion options are all handled through keyboard controls as the player fights toward escape.","system":"Flash","genre":"shooter","categories":"shooter|adventure|action","core":"swf","width":760,"height":400},{"type":"flash","id":"alien-hominid","slug":"alien-hominid","title":"Alien Hominid","description":"Alien Hominid is a 2002 side-scrolling platformer from Tom Fulp and Dan Paladin where a stranded alien battles the FBI.","about":"After a crash landing, the alien's UFO is down and the FBI is closing in. Players move with the arrow keys, aim and fire a gun, and jump to avoid or confront enemies. A special freak attack can be triggered while leaping over foes, and enemy heads can be ridden to get past roadblocks. The game was programmed by Tom Fulp with art by Dan Paladin.","system":"Flash","genre":"platformer","categories":"platformer|adventure|action","core":"swf","width":550,"height":400},{"type":"flash","id":"cactus-mccoy","slug":"cactus-mccoy","title":"Cactus McCoy","description":"Cactus McCoy is a 2011 platformer brawler from Flipline Studios set in a strange Wild West full of treasure and enemies.","about":"Hired to find the Thorned Emerald, McCoy falls under the Curse of Thorns and becomes a walking, talking, brawling cactus. Players guide him through a strange Wild West world, picking up many kinds of weapons and fighting off enemies along the way. The goal is to return the jewel to its rightful home before the curse turns McCoy into lifeless stone.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":608,"height":480},{"type":"flash","id":"bloxorz","slug":"bloxorz","title":"Bloxorz","description":"Bloxorz is a 2007 logic puzzle game from Miniclip and Damien Clarke in which a block must be rolled into a square hole.","about":"The goal in Bloxorz is to guide a block across the level until it drops into the square hole. Rolling the block changes which side rests on the ground, so each move has to be planned around the space it occupies. Miniclip and Damien Clarke released the puzzle game in 2007.","system":"Flash","genre":"puzzle","categories":"puzzle|logic","core":"swf","width":550,"height":300},{"type":"flash","id":"swords-and-sandals-crusader","slug":"swords-and-sandals-crusader","title":"Swords and Sandals: Crusader","description":"Swords and Sandals: Crusader is a 2007 turn-based strategy and action game where players command armies across the realm of Brandor.","about":"Swords and Sandals: Crusader expands the series beyond the gladiator arena, putting players in charge of hundreds of troops in battles against powerful lords. The game blends fast arcade combat with RPG strategy, with fights set in locations such as rainy castle sieges, dank swampland, and scorching desert. Particle weather and spell effects accompany a range of army and game types, and the story continues the conflict with the undead Emperor Antares.","system":"Flash","genre":"strategy","categories":"strategy|action","core":"swf","width":640,"height":480},{"type":"flash","id":"strike-force-heroes-2","slug":"strike-force-heroes-2","title":"Strike Force Heroes 2","description":"Strike Force Heroes 2 is a 2013 side-view sci-fi shooter from Sky9 Games with cartoon action and character customization.","about":"Strike Force Heroes 2 is a side-view science fiction shooter for a single player. It comes from Sky9 Games and continues the Strike Force Heroes series, with cartoon action, voice acting, achievements and customization options.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":600},{"type":"flash","id":"riddle-school-3","slug":"riddle-school-3","title":"Riddle School 3","description":"Riddle School 3 is a 2008 point-and-click adventure game by JohBro in which Phil tries to escape from his high school.","about":"Phil is a student who wants out of his high school, and the player helps him get there using point-and-click adventure skills. The game tracks how long the escape takes with a hidden timer, so players can compare their finishing time once they succeed. JohBro released it in 2008 as the third entry in the Riddle School series, and it is described as the largest and most difficult of the three.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":700,"height":475},{"type":"flash","id":"riddle-school-5","slug":"riddle-school-5","title":"Riddle School 5","description":"Riddle School 5 is a point-and-click adventure from 2010 and the final chapter of JonBro's series, with puzzles and plot twists to uncover.","about":"JonBro's point-and-click adventure series reaches its conclusion in this fifth entry, released in 2010. Players work through puzzles and uncover plot twists across a lengthy quest that takes most people over ten minutes to finish, and longer on a first attempt. A timer records how long the playthrough lasted, and special features become available once the game is completed.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"bang-boom-splat","slug":"bang-boom-splat","title":"Bang, Boom, Splat!","description":"Bang, Boom, Splat! is a 2008 shooting gallery game from Eddsworld where players control Edd across ten levels.","about":"Bang, Boom, Splat! is a shooting gallery game starring Edd from Eddsworld. Players work through ten levels, aiming for the best score they can reach in each one. Levels unlock as higher scores and medals are earned, and codes can also be entered. The game was developed by Eddsworld and released in 2008.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":550,"height":450},{"type":"flash","id":"cactus-mccoy-2","slug":"cactus-mccoy-2","title":"Cactus McCoy 2","description":"Cactus McCoy 2 is a 2011 platformer brawler from Flipline Studios, continuing the treasure hunter's journey to the Ruins of Calavera.","about":"Cactus McCoy returns for a larger adventure in this sequel from Flipline Studios. He joins forces with a rival treasure hunter to reach the mythical Ruins of Calavera, but becomes entangled in an old conflict over the Serpent Blade. McCoy must make his way to the ruins alone and keep the blade from falling into the wrong hands. The platformer brawler gameplay continues the series' focus on battling through enemies on the way to the destination.","system":"Flash","genre":"platformer","categories":"platformer|arcade|action","core":"swf","width":608,"height":480},{"type":"flash","id":"escaping-the-prison","slug":"escaping-the-prison","title":"Escaping the Prison","description":"Escaping the Prison is a 2010 adventure game from PuffballsUnited where players find a route out of jail through three possible endings.","about":"This adventure game continues the story started in Breaking the Bank, though it plays differently from that earlier title. The player works to get out of prison, and success is possible this time. Three separate winning endings can be reached: the Lame Way, the Sneaky Way, and the Badass Way. Finding all of them is the goal.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":650,"height":450},{"type":"flash","id":"raft-wars","slug":"raft-wars","title":"Raft Wars","description":"Raft Wars is a 2007 action game by Martijn Kunst where Simon and his baby brother defend found diamonds from pirates and Vikings.","about":"Simon found diamonds while playing in the sand, and now pirates want to take them. He fights back with his baby brother and dog, aiming and shooting tennis balls and other items at each opponent. Players set the angle and strength with the mouse, then watch as enemies take their own turn in response. Beating one group of pirates opens the way to later levels with foes such as Vikings, and cash earned along the way can buy upgrades for better tools and rafts.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"age-of-war","slug":"age-of-war","title":"Age of War","description":"Age of War is a 2008 strategy game by Louissi where players advance through eras of history to defeat a rival civilization.","about":"In Age of War, the aim is to reach more advanced ages so the army can better fight a long-standing enemy. Troops are sent out to push progress through the different stages of life. Every level upgrades the available forces, though a less developed civilization can still prevail by relying on sheer numbers.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":650,"height":450},{"type":"flash","id":"gun-mayhem-2-more-mayhem","slug":"gun-mayhem-2-more-mayhem","title":"Gun Mayhem 2: More Mayhem","description":"Gun Mayhem 2: More Mayhem is a 2012 cartoony arena shooter by Kevin Gu, supporting up to four players in battles against AI or friends.","about":"Gun Mayhem 2: More Mayhem is an arena-style platform shooter with cartoon visuals. Players fight against AI opponents or with friends, and up to four people can join a match. The game includes a campaign of sixteen missions that grow harder, plus challenge levels and seven custom game modes. New maps, guns, perks, and customization options expand the action, and controls can be edited in the options.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":900,"height":600},{"type":"flash","id":"riddle-school-4","slug":"riddle-school-4","title":"Riddle School 4","description":"Riddle School 4 is a 2010 adventure game by JonBro in which Phil arrives at Riddle University and starts planning his escape.","about":"Phil has reached Riddle University and is thinking about how to get away. The school he applied to turns out to hold more than it first appears. This fourth entry in the series came after a long gap, and beating it once unlocks special features in the main menu.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"strike-force-heroes","slug":"strike-force-heroes","title":"Strike Force Heroes","description":"Strike Force Heroes is a 2012 action shooter from Sky9 Games where four classes level up to unlock weapons, skills, and killstreaks.","about":"Players pick from four distinct classes and level them up to open up more than 65 weapons, several skills, and killstreaks, which can then be arranged into a custom loadout. A fully voiced campaign tells a story across its missions, while custom quickmatches offer a looser way to play. Challenges are also available for those who want to push their abilities further.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":600},{"type":"flash","id":"learn-to-fly-3","slug":"learn-to-fly-3","title":"Learn to Fly 3","description":"Learn to Fly 3 sends a penguin from the slopes to outer space in this 2015 arcade launch game from Light Bringer Games.","about":"The third entry in the Learn to Fly series tasks a penguin with flying and eventually reaching space. Players build up their launch setup and track how earlier flights performed, with a Black Market offering extra items, cheat options, and time controls. Later updates added omega items, medals, and tougher late-game goals, while booster packs now favor cards tied to each pack's theme.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":720,"height":540},{"type":"flash","id":"robot-unicorn-attack","slug":"robot-unicorn-attack","title":"Robot Unicorn Attack","description":"Robot Unicorn Attack is a 2010 side-view action runner from Adult Swim Games and Spiritonin Media Games.","about":"Robot Unicorn Attack is a side-view action runner released in 2010 by Adult Swim Games and Spiritonin Media Games. It is a single-player score-attack game in the Robot Unicorn Attack series, built around an equine robot protagonist.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"3-foot-ninja-ii","slug":"3-foot-ninja-ii","title":"3 Foot Ninja II","description":"3 Foot Ninja II is a 2004 action game from MiniClip where a small ninja battles enemies to rescue a princess.","about":"In 3 Foot Ninja II, the player controls a ninja on a journey through a distant land. The goal is to defeat evil enemies and bring the Princess back to the King of the southern lands. Arrow keys handle movement, while the A, S, and D keys are used to fight. The space bar lets the ninja crouch and block, and pressing 1, 2, or 3 activates the corresponding bonuses.","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":420},{"type":"flash","id":"achievement-unlocked","slug":"achievement-unlocked","title":"Achievement Unlocked","description":"Achievement Unlocked is a 2008 puzzle platformer from Armor Games and jmtb02 where collecting achievements is the whole point.","about":"There are no levels to beat, enemies to kill, or final boss to fight. The goal is simply to complete random tasks and rack up achievements that have little connection to anything else. Players explore a small world and work out the controls themselves while chasing each accomplishment. The result is a game about the pursuit of achievements rather than traditional platforming challenges.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":720,"height":400},{"type":"flash","id":"flight","slug":"flight","title":"Flight","description":"Flight is a 2010 arcade game from Armor Games and Krin where a paper plane is thrown to collect points and save the world.","about":"The player throws a paper plane and guides it to collect points. Points earned along the way can be used for upgrades. The goal of the game is to save the world, and the plane's flight is the means of making progress toward that end.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":720,"height":480},{"type":"flash","id":"the-impossible-quiz-2","slug":"the-impossible-quiz-2","title":"The Impossible Quiz 2","description":"The Impossible Quiz 2 is a 2007 logic quiz by Splapp-me-do where every answer must be chosen without dying.","about":"This sequel to the first Impossible Quiz asks players to work through a series of questions while avoiding death. The questions begin somewhat easier than before but become harder as the quiz goes on. Skips and Fusestoppers can be used at any time, so there is no need to save them. The music was removed due to problems, and the game runs without it.","system":"Flash","genre":"quiz","categories":"quiz|logic","core":"swf","width":550,"height":400},{"type":"flash","id":"mario-combat","slug":"mario-combat","title":"Mario Combat","description":"Mario Combat is a 2008 action game from Sun-Studios in which Mario faces off against Bowser.","about":"In this short action game, the player takes control of Mario and fights Bowser. It was built from the developer's own sprites and began as a project called the Power Star Game before being turned into a brief, lighthearted experience. The result is a compact brawl rather than a longer adventure.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":400},{"type":"flash","id":"the-fancy-pants-adventure","slug":"the-fancy-pants-adventure","title":"The Fancy Pants Adventures: World 1","description":"The Fancy Pants Adventures: World 1 is a 2006 adventure game that opens the series, with later code updates improving its frame rate.","about":"This is the opening world of the Fancy Pants Adventures series, released in 2006 by its original creators. The game was later updated with code carried over from World 2, most notably re-timing code. That change lets it run at 30 fps on a fast enough computer, rather than around 20 fps regardless of machine speed. Players are encouraged to move on to World 2 afterward.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":720,"height":480},{"type":"flash","id":"minecraft-tower-defence-2","slug":"minecraft-tower-defence-2","title":"Minecraft Tower Defence 2","description":"Minecraft Tower Defence 2 is a 2012 strategy game by Microwave Games with 16 maps, 18 items, and an Adventure Mode starring Steve.","about":"In Adventure Mode, players follow Steve, a new Minecraft owner whose village is destroyed by a white-eyed griefer, and learn the game by completing missions that unlock items. Progress saves automatically, though clearing browser cookies removes it. After finishing Adventure Mode, Survival Mode opens up all standard items and endless waves of mobs across 12 maps, each with its own leaderboard. Challenges tie into medals, with mission challenges giving standard items and item challenges unlocking bonus items or lowering their cost.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":480},{"type":"flash","id":"super-mario-sunshine-64","slug":"super-mario-sunshine-64","title":"Super Mario Sunshine 64","description":"Super Mario Sunshine 64 is a side-view platformer and adventure game from Runouw where players explore, collect, and build their own levels.","about":"Runouw's Super Mario Sunshine 64 is a side-scrolling platformer and adventure game released in 2006. Players move through stages in a side view, collecting items and hunting for hidden content. The game also includes a level editor, letting players build their own stages. It is a single-player experience with pixel visuals.","system":"Flash","genre":"platformer","categories":"platformer|adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"3-foot-ninja","slug":"3-foot-ninja","title":"3 Foot Ninja","description":"3 Foot Ninja is a 2003 action game by Denni Ames where a small warrior cuts through deadly foes while chasing his destiny.","about":"In 3 Foot Ninja, the player sets out to find a personal destiny, and the road there is crowded with obstacles and enemies. A sword is the main tool, and it needs to be used with care and speed because the foes are both many and dangerous. The game is an action title from developer Denni Ames, released in 2003.","system":"Flash","genre":"action","categories":"action","core":"swf","width":560,"height":400},{"type":"flash","id":"drag-racer-v3","slug":"drag-racer-v3","title":"Drag Racer V3","description":"Drag Racer V3 is a 2004 racing game from Phantom Games where players shift gears and use nitrous to win drag races.","about":"Drag Racer V3 is a drag racing game released in 2004 by Phantom Games. Players control gear changes with the up and down keys, apply gas with the space bar, and trigger a nitrous boost with the N key. The space bar also skips the introduction. An options menu allows switching to the control scheme used in Drag Racer 2.","system":"Flash","genre":"sports","categories":"sports|racing","core":"swf","width":800,"height":600},{"type":"flash","id":"learn-to-fly","slug":"learn-to-fly","title":"Learn to Fly","description":"Learn to Fly, a 2009 arcade game by Light Bringer, follows a penguin determined to prove he can take to the skies.","about":"A penguin comes across a website claiming he cannot fly, and decides to prove otherwise through research and practice. Players help him work toward that goal, upgrading gear such as gliders and rocket fuel along the way. Each glider has a redzone, a speed above which speed drops quickly, so staying out of it for long stretches helps cover more distance. Unlocking every achievement is required before the game can be finished.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"big-time-butter-baron","slug":"big-time-butter-baron","title":"Big Time Butter Baron","description":"Big Time Butter Baron is a 2012 arcade puzzler from Megadev about packing butter shapes onto a factory board for delivery.","about":"A.P. Butterworth owns the world's leading butter factory, and keeping that position depends on having the right crew. Players work the factory floor, fitting butter shapes onto the board as tightly as they can. The mouse places each shape, while the arrow keys or Z/X and A/S rotate it. Once more than half the board is covered, the batch goes out for delivery, though blocker and eraser shapes can get in the way.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"canyon-defense","slug":"canyon-defense","title":"Canyon Defense","description":"Canyon Defense is a 2008 top-down tower defense strategy game from IriySoft, played solo as part of the Canyon Defense series.","about":"Canyon Defense is a top-down tower defense game from IriySoft, released in 2008 as part of the Canyon Defense series. One player builds and arranges defenses along a canyon to hold off incoming waves. Strategy comes from choosing where to place each tower so the path is covered. It is a single-player game.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":650,"height":450},{"type":"flash","id":"epic-battle-fantasy","slug":"epic-battle-fantasy","title":"Epic Battle Fantasy","description":"Epic Battle Fantasy is a 2009 action platformer by Matt Roszak in which the player fights through successive waves of enemies.","about":"Epic Battle Fantasy is an action platformer from 2009 by developer Matt Roszak. The player battles through waves of enemies. An updated version of the game was later released for Android.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":700,"height":400},{"type":"flash","id":"interactive-buddy","slug":"interactive-buddy","title":"Interactive Buddy","description":"Interactive Buddy is a 2005 creative sandbox from Shock Value where players poke, prod and play with a virtual character.","about":"Interactive Buddy is a creative sandbox toy from Shock Value, released in 2005. Players interact with a virtual buddy in an open-ended way, experimenting with the character rather than following a set goal. The game became a long-running series, with later versions and mobile releases following the original.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":550,"height":400},{"type":"flash","id":"vex2","slug":"vex2","title":"Vex 2","description":"Vex 2 is a platformer with 11 stages of swimming, wall jumps, zip-lines, cannons and gravity changes, plus a stage builder.","about":"Vex returns in a sequel with 11 stages that are larger and more difficult than before. Players move through them by swimming, sliding, wall jumping, riding zip-lines, swinging on poles, launching from cannons and even altering gravity. Achievements add extra goals for those who want to complete everything, and a Stage Builder lets players assemble their own levels using simple dragging and send them to a friend.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":640,"height":560},{"type":"flash","id":"learn-to-fly-2","slug":"learn-to-fly-2","title":"Learn to Fly 2","description":"Learn to Fly 2 is a 2011 arcade launch game from Light Bringer where a penguin seeks revenge on the icebergs that ended its first flight.","about":"The penguin learned to fly in the first game, but icebergs crushed that dream. In this sequel, the bird returns for revenge, launching itself across an arctic setting. Players steer with the arrow keys or A and D, use the space bar to boost, and press any key to activate special sleighs. Controls can be customized in the options menu, including mouse input.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"papas-donuteria","slug":"papas-donuteria","title":"Papa’s Donuteria","description":"Papa's Donuteria is a 2014 simulation game from Flipline Studios where players cook and decorate donuts for customers in Powder Point.","about":"In Papa's Donuteria, the player takes a job at the donut shop in Powder Point, a carnival-like town where coasters run overhead. The work involves cutting out donuts, frying them, and decorating each order with a range of toppings. Serving the town's many customers throughout the day is the core of the time-management challenge. The job comes with good pay and benefits, though the real draw was a Line-Jump Pass.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"madness-accelerant","slug":"madness-accelerant","title":"Madness Accelerant","description":"Madness Accelerant is a 2009 action shooter from TomFulp that remakes Krinkel's Madness Consternation as a playable, shot-by-shot tribute.","about":"Madness Accelerant is a playable remake of Krinkel's Madness Consternation, following the original's progression closely with a few changes. Players fight through waves of enemies as Hank, swapping between weapons and collecting ammo by walking over guns they already carry. Beating the game unlocks Madness Mode, a harder challenge. A fan-art gallery is also included.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":720,"height":405},{"type":"flash","id":"super-mario-flash-2","slug":"super-mario-flash-2","title":"Super Mario Flash 2","description":"Super Mario Flash 2 is a 2011 single-player action platformer from Pouetpu Games with pixel visuals and a level editor.","about":"Super Mario Flash 2 is a single-player platformer from Pouetpu Games, released in 2011 as part of the Super Mario Flash series. It pairs score-attack platforming with pixel art and includes a level editor for building custom stages.","system":"Flash","genre":"action","categories":"action","core":"swf","width":320,"height":240},{"type":"flash","id":"super-smash-flash","slug":"super-smash-flash","title":"Super Smash Flash","description":"Super Smash Flash is a 2006 action game from McLeodGaming and Cleod-9 with 28 playable characters and several solo modes.","about":"Super Smash Flash lets players pick from 28 characters and take on modes such as Multi-man Melee, Target Test, Adventure, Classic and All-Star. Progress saves automatically, so the game does not have to be finished in one sitting. Matches can also be watched as CPU fighters battle each other. It was released in 2006 by McLeodGaming and Cleod-9.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":400},{"type":"flash","id":"motherload","slug":"motherload","title":"MotherLoad","description":"MotherLoad is a 2004 simulation game from XGen Studios where players dig beneath the surface of Mars in search of valuable minerals.","about":"Players guide a Mining Pod through the Martian substrata, digging for rare and valuable minerals in pursuit of the fabled Motherload. The soil hides gas pockets, earthquakes and other hazards. Earnings from mining can be spent on powerful upgrades for the pod, and high scores can be compared with friends. After finishing the game, more difficult modes are available to try.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":550,"height":400},{"type":"flash","id":"papas-cheeseria","slug":"papas-cheeseria","title":"Papa’s Cheeseria","description":"Papa's Cheeseria is a 2015 restaurant simulation from Flipline Studios where players build grilled cheese sandwiches and serve customers.","about":"In Papa's Cheeseria, the player takes orders from customers and assembles giant grilled cheese sandwiches at the Build Station, choosing from breads, toppings, and cheeses. Sandwiches are cooked at the Grill Station, while fries are prepared at the Fry Station and topped before being plated alongside the order. The goal is to serve each waiting customer correctly, with the game centering on time management and cooking across multiple stations.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"raft-wars-2","slug":"raft-wars-2","title":"Raft Wars 2","description":"Raft Wars 2 is a 2013 action game by Martijn Kunst in which a waterpark has been built over buried treasure.","about":"A waterpark has been constructed directly on top of the spot where treasure lies buried. The player slips into the park and battles through the security guards standing in the way. The goal is to recover the gold and diamonds that were hidden there.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":500},{"type":"flash","id":"riddle-school-2","slug":"riddle-school-2","title":"Riddle School 2","description":"Riddle School 2 is a 2006 point-and-click adventure from JonBro, continuing the series' puzzle-driven school escape story.","about":"Riddle School 2 is an adventure game released in 2006 by JonBro. It continues the story of the Riddle School series, in which players work through puzzles to progress. The game is part of a longer narrative that spans several entries.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":700,"height":400},{"type":"flash","id":"papa-louie-when-pizza-attack","slug":"papa-louie-when-pizza-attack","title":"Papa Louie: When Pizza Attack!","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"stick-war","slug":"stick-war","title":"Stick War","description":"Stick War is a 2009 arcade strategy game where players command an army, gather gold, and train sword, spear, archer, mage, and giant units.","about":"In the land of Inamorata, rival nations each put their faith in a single style of combat, and the peaceful Order is threatened by their ambitions. Players direct an army either through set formations or by taking charge of individual units on the field. Gold must be mined and new fighters trained, from swordsmen and spearmen to archers, mages, and giants. Victory comes from toppling the opposing statue and seizing every territory.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"breaking-the-bank","slug":"breaking-the-bank","title":"Breaking The Bank","description":"Breaking The Bank is a 2008 adventure game from PuffballsUnited where a hapless stick figure attempts a series of failed heists.","about":"Breaking The Bank is a stick-figure animation about a poor man who keeps failing at his attempts to rob a bank. The humor is similar in style to Spy vs. Spy. Players watch the character try methods such as a laser drill, a disguise, an explosion, a wrecking ball, a teleporter, or a tunnel to see how the heist turns out.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"burger-tycoon","slug":"burger-tycoon","title":"Burger Tycoon","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":660,"height":410},{"type":"flash","id":"portal-the-flash-version","slug":"portal-the-flash-version","title":"Portal: The Flash Version","description":"Portal: The Flash Version is a 2007 puzzle game by We Create Stuff with over 40 2D levels built around portal-based thinking.","about":"This 2D puzzle game from We Create Stuff adapts the portal mechanic into a side-scrolling format with more than 40 levels. Players move through each stage and use portals to solve the challenges in their path. Energy balls, cubes, turrets and a crusher all appear, bringing much of the original game's toolkit into two dimensions. A console becomes available once the levels are finished, or whenever the puzzles prove too frustrating.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":800,"height":450},{"type":"flash","id":"stick-rpg-complete","slug":"stick-rpg-complete","title":"Stick RPG Complete","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"jacksmith","slug":"jacksmith","title":"Jacksmith","description":"Jacksmith is a 2012 simulation game from Flipline Studios where a blacksmith forges weapons for warriors.","about":"Players take on the role of a blacksmith who makes weapons for a group of warriors. The crafting is hands-on: ore is selected, a mold is chosen, and the metal is melted, poured, constructed, and designed. Swords, bows, arrows, and axes are among the items that can be made. After the weapons are finished, the warriors go into battle, where the player collects loot and operates the cannons while advancing toward the Great Wizard Dudley.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"madness-project-nexus","slug":"madness-project-nexus","title":"Madness: Project Nexus","description":"Madness: Project Nexus is a 2012 side-scrolling shooter from Michael Swain and Matt Krinkels Jolly, set in the Madness universe.","about":"Players move through the Madness universe in a side-scrolling shooter. Arena Mode has them working through the Nexus Training Program to become the strongest L337 Unit in Nevada, while Story Mode lets them pick from several heroes of the Madness universe and take down Project Nexus. The game was planned to grow after launch with additional missions, story and modes.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":850,"height":530},{"type":"flash","id":"raze-2","slug":"raze-2","title":"Raze 2","description":"Raze 2 is a 2011 action shooter from Addisonr and Juice-Tin where players battle alien forces or join them to decide humanity's fate.","about":"Raze 2 is an action shooter in which the player chooses a side: defending the human race against an alien invasion or fighting alongside the aliens to bring about its destruction. A large selection of weapons, equipment, and abilities is available to arm the player for combat. The choice of allegiance shapes the conflict, letting the player either repel the alien forces or help them wipe out humanity.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":600},{"type":"flash","id":"strike-force-heroes-3","slug":"strike-force-heroes-3","title":"Strike Force Heroes 3","description":"Strike Force Heroes 3 is a 2015 side-view sci-fi shooter from Sky9 Games, part of the Strike Force Heroes series.","about":"Strike Force Heroes 3 is a side-view action shooter set in a science-fiction world, made by Sky9 Games in 2015 as part of the Strike Force Heroes series. It is played solo, with a cartoon art style, achievements to earn and daily content.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":600},{"type":"flash","id":"earn-to-die","slug":"earn-to-die","title":"Earn to Die","description":"Earn to Die is a 2011 action game from Toffee Games about upgrading a car and driving through zombie hordes to reach a destination alive.","about":"Earn to Die is an action game released in 2011 by Toffee Games. The player upgrades a car and drives it through hordes of zombies, with the goal of reaching a destination while staying alive. Progress depends on improving the vehicle to survive the journey.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":500},{"type":"flash","id":"happy-wheels","slug":"happy-wheels","title":"Happy Wheels","description":"Happy Wheels is a 2010 simulation game from Total Jerkface and Jim Bonacci, built around ragdoll riders and user-made levels.","about":"Happy Wheels is a simulation game from Total Jerkface and Jim Bonacci, worked on part-time over roughly four years before its 2010 release. Players control characters through levels, and the game includes a level editor that lets the community build and share their own stages. The developer describes it as functional but unfinished, with plans for additions such as sound, characters, editor items, cinematics, and more gore.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":900,"height":500},{"type":"flash","id":"mario-forever-flash","slug":"mario-forever-flash","title":"Mario Forever Flash","description":"Mario Forever Flash is a 2009 side-view platformer from developer Mauft in which Mario sets out to rescue Princess Toadstool.","about":"Bowser has taken Princess Toadstool, and Mario sets out through a colorful platforming world to defeat him and bring her back. The game mixes platformer action with score-attack and time-attack play, and it is built around the familiar Mario universe. A 2009 update smoothed out movement, allowed a jump to be queued by holding the button before landing, and changed Fire Mario so a hit drops him to big Mario rather than small Mario.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":400,"height":375},{"type":"flash","id":"one-chance","slug":"one-chance","title":"One Chance","description":"One Chance is a 2010 adventure game from Awkward Silence Games about a scientist facing the final six days before Earth's collapse.","about":"A pathogen created by scientist John Pilgrim and his team is destroying all living cells on Earth, leaving only six in-game days. Using the arrow keys to move and the space bar to interact, the player decides how Pilgrim spends his remaining time. He can be with his family, try to develop a cure, or simply lose control. The game centers on the choices made and the consequences that follow from them.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":350},{"type":"flash","id":"fishy","slug":"fishy","title":"Fishy","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"helicopter-game","slug":"helicopter-game","title":"Helicopter Game","description":"Helicopter Game is a classic arcade challenge of balance and timing, first released in 2002 by Silver Arcade.","about":"Steer a chopper through a series of obstacle courses using the mouse. Holding the left button provides lift, and the challenge lies in timing that lift against gravity to keep from crashing. Each stage grows faster and harder, testing reflexes and nerve as speed and altitude must be watched. The game is built to frustrate and intimidate even the most determined pilots.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":400,"height":300},{"type":"flash","id":"stealing-the-diamond","slug":"stealing-the-diamond","title":"Stealing The Diamond","description":"Stealing the Diamond is a 2011 adventure game from Puffballs United about a thief planning a diamond heist.","about":"Following the events of an earlier escape, the player turns to crime for money by targeting a diamond. The game is a 2011 adventure from Puffballs United. It continues the story of a character who has already broken out of prison and now sets out to steal the gem.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":650,"height":410},{"type":"flash","id":"toss-the-turtle","slug":"toss-the-turtle","title":"Toss The Turtle","description":"Toss The Turtle is a 2009 arcade game where players launch a turtle with cannons, bombs and jetpacks to send it as far as possible.","about":"In this arcade game from Foreverkul, the goal is to launch a turtle as far as possible using cannons, bombs, and jetpacks. Players click and hold to build power, then release to fire, and guide the turtle in flight with the WASD keys. Cash collected during the run can be spent on upgrading the equipment. Clicking the mouse also fires a shot at the turtle.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":500},{"type":"flash","id":"achievement-unlocked-3","slug":"achievement-unlocked-3","title":"Achievement Unlocked 3","description":"Achievement Unlocked 3 is a 2012 puzzle platformer from Armor Games starring the Blue Elephant on a hunt for 400 achievements.","about":"Players guide the Blue Elephant across tricky puzzle maps, aiming to collect all 400 achievements and break out to freedom. King Hamster, who is really a guinea pig, stands in the way, along with spikes, burning rodents and dangerous pits. Time itself is the main obstacle, so speed matters as much as careful route planning.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":900,"height":500},{"type":"flash","id":"ageofwar2","slug":"ageofwar2","title":"Age of War 2","description":"Age of War 2 is a 2014 single-player strategy game from developer Louissi, continuing the Age of War series.","about":"Age of War 2 is a strategy game released in 2014 by developer Louissi, and it is the second entry in the Age of War series. It is played by a single player and is built around strategic decision-making.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":720,"height":480},{"type":"flash","id":"max-dirt-bike","slug":"max-dirt-bike","title":"Max Dirt Bike","description":"Max Dirt Bike is a 2007 sports game from Max Games where players balance a dirt bike across hilly terrain using revving and braking.","about":"Max Dirt Bike is a physics-based dirt bike game released in 2007 by Max Games. Players use the up and down arrows to accelerate and brake, while the left and right arrows control balance. Success depends on mastering revving, charging hills, and braking at the right moments to climb slopes and cross valleys. The game tests dexterity and puzzle-solving skills as players work through levels and aim for a spot on the leaderboard.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":500,"height":400},{"type":"flash","id":"social-interaction-trainer","slug":"social-interaction-trainer","title":"Social Interaction Trainer","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":960,"height":540},{"type":"flash","id":"talking-tom-cat-2-in-2011-2","slug":"talking-tom-cat-2-in-2011-2","title":"Talking Tom Cat 2","description":"Talking Tom Cat 2 is a 2011 creative game from Outfit7 in which a cartoon cat mimics whatever is spoken into a microphone.","about":"This creative title from Outfit7 is the follow-up to the original Talking Tom Cat. Players speak into a microphone and the cat answers back, echoing their words in a comical voice. Mouse clicks on the cat and on the on-screen buttons let players interact with him and keep him entertained.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":320,"height":480},{"type":"flash","id":"a-koopas-revenge-2","slug":"a-koopas-revenge-2","title":"A Koopa’s Revenge 2","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":400},{"type":"flash","id":"achievement-unlocked-2","slug":"achievement-unlocked-2","title":"Achievement Unlocked 2","description":"Achievement Unlocked 2 is a 2010 puzzle platformer from Armor Games and John Cooney where a blue elephant hunts down strange goals.","about":"A blue elephant wanders a world with no clear purpose, so the player gives it one by chasing down unusual tasks and accomplishments. Squares and launchers block the way, coins must be collected to pay for things, and spikes threaten the elephant at every turn. The game is built around metagaming, turning the act of hunting achievements into the main objective. Armor Games and John Cooney released it in 2010.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":800,"height":500},{"type":"flash","id":"armed-with-wings-2","slug":"armed-with-wings-2","title":"Armed with Wings 2","description":"Armed with Wings 2 is a 2008 single-player action beat 'em up from Sun-Studios with samurai combat and a silhouette art style.","about":"Armed with Wings 2 is a single-player action beat 'em up released in 2008 by Sun-Studios. It presents samurai combat through a silhouette visual style, continuing the Armed with Wings series.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":400},{"type":"flash","id":"defend-your-castle","slug":"defend-your-castle","title":"Defend Your Castle","description":"Defend Your Castle is a 2003 arcade game from XGen Studios where players throw stick-wielding attackers away from their fortress.","about":"In this arcade title from XGen Studios, attackers carrying sticks advance toward a castle, and the player picks them up and throws them to keep the structure safe. Each stage grows harder than the last, and more enemy types, buildings, and challenges appear compared to the earlier beta version. Finishing a level brings an upkeep cost for every unit still held, so leftover points from the previous stage must cover the current force. Later updates addressed saved-game issues and other bugs.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"divine-intervention","slug":"divine-intervention","title":"Divine Intervention","description":"Divine Intervention is a 2003 side-scrolling shooter by Jim Bonacci in which a priest fights his way through waves of enemies.","about":"A priest advances through a side-scrolling shooter, gunning down attackers that appear as he moves forward. Walking too far too quickly draws a swarm, so a slow approach helps. Weapons include a pistol, an uzi, and a shotgun, and the boss can only be hit in the head while his shield is down. The game was built as a portfolio piece by developer Jim Bonacci.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":450},{"type":"flash","id":"earn-to-die-2012","slug":"earn-to-die-2012","title":"Earn to Die 2012","description":"Earn to Die 2012 is a side-view action game where players drive through a zombie apocalypse, smashing hordes and upgrading vehicles.","about":"In Earn to Die 2012, players drive through a zombie apocalypse, smashing through hordes of zombies while unlocking and upgrading vehicles. This standalone version features its own story separate from the mobile game, with fewer levels and vehicles but considered an improvement over the original Flash version. The game is a side-view action experience focused on vehicular combat and progression.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":750,"height":500},{"type":"flash","id":"flashtrek-broken-mirror","slug":"flashtrek-broken-mirror","title":"FlashTrek: Broken Mirror","description":"FlashTrek: Broken Mirror is a 2005 strategy game by Vex Xiang where players build an empire across space.","about":"FlashTrek: Broken Mirror is a strategy game set in the Star Trek universe. Players begin by selecting a race, then take part in commerce, combat, and exploration. Ships, weapons, and technology can be bought and sold, and planets can be colonized and stations built to grow an empire or assist another one. The game may lag on slower computers.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":600,"height":450},{"type":"flash","id":"gretel-and-hansel","slug":"gretel-and-hansel","title":"Gretel & Hansel","description":"Gretel & Hansel is a 2009 adventure game from makopudding where players use their wits to guide Gretel and her brother safely to the woods.","about":"In this hand-painted point-and-click adventure, Gretel and her brother must reach the woods alive, and only clever thinking will get them there. The game saves automatically, so progress is kept between sessions. Collecting all ten deaths in a single playthrough unlocks the Grimm Master medal, awarded after the credits. This is the first chapter of a three-part story.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":800,"height":600},{"type":"flash","id":"sports-heads-football-championship","slug":"sports-heads-football-championship","title":"Sports Heads: Football Championship","description":"Sports Heads: Football Championship is a 2011 sports game from Mousebreaker where two big-headed players face off in one-on-one football.","about":"Two players meet in a one-on-one football match, and each side has to protect its own goal. The space bar is used to kick the ball. Power ups appear during play and alter how the match works, with the super bouncy ball given as an example.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":800,"height":540},{"type":"flash","id":"the-impossible-quiz","slug":"the-impossible-quiz","title":"The Impossible Quiz","description":"The Impossible Quiz is a 2007 logic quiz by Splapp-me-do where each question demands fast reflexes, strange reasoning, or plain luck.","about":"The Impossible Quiz presents a series of questions that look straightforward but are built to mislead. Answering them correctly can call for quick reactions, odd leaps of logic, or simple luck, and a single mistake ends the run. The game is known for being extremely difficult rather than truly impossible, and it tracks how far a player gets before it is over. Splapp-me-do released it in 2007.","system":"Flash","genre":"quiz","categories":"quiz|logic","core":"swf","width":550,"height":400},{"type":"flash","id":"warlords-call-to-arms","slug":"warlords-call-to-arms","title":"Warlords: Call to Arms","description":"Warlords: Call to Arms is a 2008 strategy game by Ben Olding where players pick a race and lead an army through 25 battles.","about":"Players select a race and then guide their army across 25 battles in a campaign to take over the land. Between levels, the army can be expanded with new unit types and upgrades. The game supports large-scale combat, with more than 50 animated soldiers possible on screen at the same time. A later update adjusted archer balance, fixed a campaign-start issue, added statistics, and replaced the old easy, medium, and hard settings with a percentage-based difficulty.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":700,"height":500},{"type":"flash","id":"arcuz-behind-the-dark","slug":"arcuz-behind-the-dark","title":"Arcuz: Behind the Dark","description":"Arcuz: Behind the Dark is a 2009 action RPG from Funnaut where players battle monsters, train a hero and craft items.","about":"Arcuz: Behind the Dark is an action role-playing game in the style of Diablo or Zelda. Players fight monsters, train their hero, learn skills, and search for better weapons and equipment, and they can also compose new items. The game spans 18 maps, 25 quests, 21 battle skills, more than 10 monster types, and over 100 weapons and gear choices. It was translated into 7 languages.","system":"Flash","genre":"action","categories":"action","core":"swf","width":500,"height":450},{"type":"flash","id":"fat-ninja","slug":"fat-ninja","title":"Fat Ninja","description":"Fat Ninja is a 2006 action game where a stealthy ninja sneaks through a guarded building, hiding and attacking to avoid detection.","about":"In Fat Ninja, the goal is to move through a building without being seen by security guards. Players decide whether to stay hidden or take out a guard with an attack. Hiding spots include the space behind objects, and the ninja can also leap up and cling to the ceiling. Attacks come from a sword or from a secret weapon of flatulence. Each time a guard spots the ninja, an alarm bar rises, and the game ends when that bar fills completely.","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":400},{"type":"flash","id":"not-so-special-stage","slug":"not-so-special-stage","title":"Not-So Special Stage","description":"Not-So Special Stage is a 2007 arcade game by Edd Gould in which Edd runs a Sonic-style special stage to collect the Chaos Eddmerald.","about":"Edd Gould made a movie of himself running through a Sonic special stage, and this arcade game grew out of that clip. The player guides Edd on a coke run while trying to reach the Chaos Eddmerald. The result is a short experience inspired by the special stage format.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"red-ball-2-the-king","slug":"red-ball-2-the-king","title":"Red Ball 2: The King","description":"Red Ball 2: The King is a 2009 platformer by Evgeniy Fedoseev in which a round hero searches for a lost crown.","about":"The red ball has misplaced his crown and sets out across twenty levels to recover it. His journey takes him through puzzles and past hazards such as cannons, water, pins, toxic waste, invisible platforms and boats. The game builds on the first entry with more challenge and variety while keeping the same round protagonist at its center.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":550,"height":400},{"type":"flash","id":"run-3","slug":"run-3","title":"Run 3","description":"Run 3 is a 2014 arcade game by player_03 where players race through a galaxy of levels, jumping and rotating the world to progress.","about":"Run 3 challenges players to run and jump through a large galaxy of levels using the arrow keys. Landing on a side wall rotates the world, opening new paths. Beating levels unlocks characters with special abilities, and players can switch characters from the pause menu if a level proves difficult.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":600},{"type":"flash","id":"stark-tower-defense","slug":"stark-tower-defense","title":"Stark Tower Defense","description":"Stark Tower Defense is a 2009 strategy game from Soap Creative where Marvel heroes must hold the line against an assault on Stark Tower.","about":"Dr. Doom and the Lethal Legion have begun a large-scale attack aimed at seizing Stark Tower. The player takes charge of the defense, setting up a strategy to hold the building against the incoming force. It is a single-player tower defense game played from a top-down view, featuring characters from Marvel's Spider-Man, X-Men, Thor and Iron Man.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":750,"height":550},{"type":"flash","id":"super-mario-63","slug":"super-mario-63","title":"Super Mario 63","description":"Super Mario 63 is a 2009 fan-made platformer inspired by Super Mario 64, with Luigi, FLUDD power-ups, and a level designer.","about":"Super Mario 63 is a fan-made platformer inspired by Super Mario 64, with many levels and features drawn from Nintendo's games alongside original content. Players control Mario or Luigi, using power-caps, FLUDD upgrades, and moves like the spin attack and ground pound while collecting Shine Sprites and Star Coins. A detailed storyline and a customizable level designer with sharable codes round out the experience. The game is a remake of the developer's earlier Super Mario Sunshine 64.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":450,"height":300},{"type":"flash","id":"the-last-stand-2","slug":"the-last-stand-2","title":"The Last Stand 2","description":"The Last Stand 2 is a 2008 shooter from Con-Artists where players defend makeshift barricades while heading for Union City.","about":"The struggle is not finished, and the mainland is no longer safe. Over 40 days and nights, the player travels toward Union City in search of a way off the mainland. Along the route, hordes must be held back from makeshift barricades, mixing travel with defensive shooting.","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":800,"height":420},{"type":"flash","id":"warfare-1917","slug":"warfare-1917","title":"Warfare 1917","description":"Warfare 1917 is a 2008 strategy game from ConArtists that puts players in command of British or German forces in the First World War.","about":"Warfare 1917 is a First World War strategy game in which the player commands either the British or German army across the trenches of Europe. Infantry, armor and fire support are used to seize ground or bombard the opposition into surrender. Two campaigns cover the British and German sides, and a custom battle mode lets players set up skirmishes to their own specifications.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":420},{"type":"flash","id":"canterlot-siege-2","slug":"canterlot-siege-2","title":"Canterlot Siege 2","description":"Canterlot Siege 2 is a 2013 strategy tower defense game by futzi01 featuring pony characters and an elemental mode.","about":"Canterlot Siege 2 is a tower defense strategy game from 2013, developed by futzi01. Players place pony characters to defend against waves of enemies, and an Elemental mode makes some foes weaker or stronger against particular attack types. Endless mode and Sandbox mode can be combined, and the roster includes characters such as Vinyl Scratch, Octavia, Lyra and Bon Bon, whose abilities have been adjusted across updates.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":960,"height":720},{"type":"flash","id":"crush-the-castle-2","slug":"crush-the-castle-2","title":"Crush the Castle 2","description":"Crush the Castle 2 is a 2010 logic and action game from Armor Games and Joey Betz where players fire at fortified castles.","about":"The Redvonian King wants the castles of King Blutias destroyed. As the royal Siege Master, accompanied by the mason Halgrim, the player assembles a team of great minds to bring down Blutias's empire across the islands of Crushtania. The mouse fires, releases, and reloads the siege weapon, while the arrow keys move the view across each castle. This follow-up to Crush the Castle expands the scale of the destruction, with medals added in version 1.3.2.","system":"Flash","genre":"logic","categories":"logic|action","core":"swf","width":800,"height":550},{"type":"flash","id":"papas-cupcakeria","slug":"papas-cupcakeria","title":"Papa’s Cupcakeria","description":"Papa’s Cupcakeria is a 2013 simulation game from Flipline Studios where players run a cupcake shop, taking orders and baking treats for customers.","about":"In Papa’s Cupcakeria, the player manages a cupcake restaurant in the town of Frostfield. The job involves four stations: taking orders, preparing batter and wrappers, baking, and decorating. As the player levels up, seasons change and holidays bring new clothing, furniture, and toppings. The game includes over 100 menu items, 90 achievements, and more than 80 customers.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"shop-empire-2","slug":"shop-empire-2","title":"Shop Empire 2","description":"Shop Empire 2 is a 2012 simulation game from Little Giant World where players build and run a shopping mall.","about":"Players expand a shopping mall in this management simulation, adding booths and new facilities while hiring staff to keep everything running smoothly. A parking system for cars and trains is part of the setup, and thieves who try to rob the shops must be dealt with. It is the sequel to the earlier Shop Empire game, offering more booths and a greater focus on detailed resource management.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"the-visitor","slug":"the-visitor","title":"The Visitor","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":650,"height":400},{"type":"flash","id":"absolute-madness","slug":"absolute-madness","title":"absolute.Madness","description":"absolute.Madness is a 2007 shooter by DonutMaster where players battle waves of enemies, zombies, and bosses.","about":"absolute.Madness is a shooter built around surviving continuous waves of enemies, including zombies and bosses. DonutMaster handled the coding, with art by Coolio-Niato. The game can be paused and unpaused with the P key.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":650,"height":500},{"type":"flash","id":"bloons-tower-defense-3","slug":"bloons-tower-defense-3","title":"Bloons Tower Defense 3","description":"Bloons Tower Defense 3 is a 2009 strategy game from Ninja Kiwi where players place towers to pop waves of Bloons.","about":"Ninja Kiwi's Bloons Tower Defense 3 builds on its predecessor with new towers and upgrades to unlock. Players set up defenses along eight tracks, choosing from three difficulty modes as they try to pop every Bloon that comes through. The goal is total Bloon popping satisfaction across the added maps and options.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":480},{"type":"flash","id":"bowmaster-prelude","slug":"bowmaster-prelude","title":"BowMaster Prelude","system":"Flash","genre":"strategy","categories":"strategy|action","core":"swf","width":2000,"height":1000},{"type":"flash","id":"electric-box","slug":"electric-box","title":"Electric Box","description":"Electric Box is a 2009 puzzle game from Twinkle Star Games and Funtank where players wire components together to power a target.","about":"Electric Box is a single-player puzzle game from Twinkle Star Games and Funtank, released in 2009. Players work through fixed-screen challenges using only the mouse to connect and route parts so that power reaches its goal. A level editor lets players build and share their own puzzles.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":720,"height":540},{"type":"flash","id":"snoring-2-wild-west","slug":"snoring-2-wild-west","title":"Snoring 2: Wild West","description":"Snoring 2: Wild West is a 2011 puzzle game from Alma Games in which animals are used to wake a sleeping elephant and knock it down.","about":"The aim in Snoring 2: Wild West is to rouse the elephant from its sleep and send it falling. Other animals serve as the tools for this, and every one of them behaves differently. Working out how each animal's function can be applied is the core of the puzzle.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":630,"height":420},{"type":"flash","id":"sonny","slug":"sonny","title":"Sonny","description":"Sonny is a 2007 action game from Armor Games and Krin Juangbhanich where the player takes the role of a zombie fighting to survive.","about":"Sonny casts the player as a zombie struggling to stay alive in a strange and dangerous world. It is an interactive story told through action, and it was produced over roughly two months. The game received patches based on player feedback, adjusting battle speed, ability cooldowns, and other mechanics. Players who want to share thoughts or ideas can leave a review.","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":575},{"type":"flash","id":"sports-heads-ice-hockey","slug":"sports-heads-ice-hockey","title":"Sports Heads: Ice Hockey","description":"Sports Heads: Ice Hockey is a cartoon side-view hockey game from Mousebreaker, released in 2013 as part of the Sports Heads series.","about":"Sports Heads: Ice Hockey is a single-player sports game from developer Mousebreaker, released in 2013 as an entry in the Sports Heads series. Played from a side view, it presents hockey action with a cartoon style.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":800,"height":540},{"type":"flash","id":"ultimate-flash-sonic","slug":"ultimate-flash-sonic","title":"Ultimate Flash Sonic","description":"Ultimate Flash Sonic, a 2004 action game by Dennis-Gid, lets players control Sonic and other characters in a side-scrolling adventure.","about":"Ultimate Flash Sonic is an action game from 2004 by Dennis-Gid. Players can choose from four characters right away, with two more secret characters to unlock. A password system saves progress so the game does not have to be restarted. The developer notes that the controls were challenging to build.","system":"Flash","genre":"action","categories":"action","core":"swf","width":350,"height":250},{"type":"flash","id":"heli-attack-3","slug":"heli-attack-3","title":"Heli Attack 3","description":"Heli Attack 3 is a 2005 action shooter by SquareCircleCo where players battle enemy units across varied terrain.","about":"SquareCircleCo's 2005 shooter sends players into battle against hostile units. Clearing out those enemies is how progress is made, with the action moving through snow, jungle, canyon and laboratory settings. A large arsenal is available along the way, with more than thirty weapons to use.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":448,"height":320},{"type":"flash","id":"papas-bakeria","slug":"papas-bakeria","title":"Papa’s Bakeria","description":"Papa's Bakeria is a 2016 bakery simulation from Flipline Studios where players bake pies for customers in Whiskview Mall.","about":"Papa's Bakeria puts the player in charge of a busy bakery in Whiskview Mall, serving pies to a demanding crowd. The job involves picking the right crust, adding a range of fillings, and baking each pie correctly. Pies then go to the Top Station for finishing touches from a large selection of toppings. The game also introduces a Sticker Section, with 90 stickers earned by completing tasks, and 101 customers to unlock.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"the-right-mix","slug":"the-right-mix","title":"The Right Mix","description":"The Right Mix is a 2013 cartoon-style simulation game from Liquid Light where players run a restaurant and mix drinks.","about":"The Right Mix is a single-player simulation game from Liquid Light, released in 2013 as part of The Right Mix series. Viewed from the side, it is set in a cartoon restaurant where alcohol plays a central role.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":600,"height":440},{"type":"flash","id":"unfair-mario","slug":"unfair-mario","title":"Unfair Mario","description":"Unfair Mario is a 2013 arcade platformer that looks like Super Mario but hides traps at every turn.","about":"Unfair Mario is a pixel-style platformer from 2013 that is built to be intentionally infuriating. It is a single-player arcade game in which the familiar Super Mario look conceals constant hazards.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":480,"height":352},{"type":"flash","id":"whack-your-boss","slug":"whack-your-boss","title":"Whack Your Boss","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":750,"height":500},{"type":"flash","id":"xiao-xiao-no-4","slug":"xiao-xiao-no-4","title":"Xiao Xiao No. 4","description":"Xiao Xiao No. 4 is a 2001 action shooter from developer Zhu Zhiqiang that plays in a 3D style.","about":"Xiao Xiao No. 4 is a 3D shooter released in 2001 by Zhu Zhiqiang. Players take on the role of a gunman who aims and fires at targets in a three-dimensional setting. The game is aimed at people who enjoy the shooting action found in Virtua Cop.","system":"Flash","genre":"action","categories":"action","core":"swf","width":500,"height":375},{"type":"flash","id":"bart-simpson-saw-game","slug":"bart-simpson-saw-game","title":"Bart Simpson Saw Game","description":"Bart Simpson Saw Game is a 2011 point-and-click adventure from Inkagames in which Bart Simpson faces a Saw-style trap.","about":"Inkagames released this single-player point-and-click adventure in 2011, placing Bart Simpson inside a Saw-inspired situation. Players work through the adventure by clicking around the scene to solve the puzzle and help him escape.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":800,"height":500},{"type":"flash","id":"canabalt","slug":"canabalt","title":"Canabalt","description":"Canabalt, the 2009 arcade endless runner by Adam Saltsman and Adam Atomic, has players fleeing a ruined city using a single button.","about":"Canabalt is an arcade endless runner in which the player flees the destruction of a city. Control is limited to a single button, which is used to leap across the rooftops while the run continues. The game is credited with popularizing the infinite runner genre. This version adds a two-player mode along with new challenges, music, achievements and leaderboards.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":920,"height":320},{"type":"flash","id":"chaos-faction","slug":"chaos-faction","title":"Chaos Faction","description":"Chaos Faction is a 2006 action game by Dissolute Productions with 18 characters, 29 weapons, and 15 levels across three modes.","about":"Chaos Faction is an action game from Dissolute Productions, released in 2006. It includes 18 characters, 29 weapons, and 15 levels. Players choose from three modes: Campaign, where defeating each arena's boss unlocks extra characters, weapons, and levels; Deathmatch, where custom teams, settings, and rules create a melee-style blood-bath; and Survival, where the goal is to defeat as many enemies as possible and submit the score to an online scoreboard. Controls use the arrow keys to move, jump, and block, with Z to attack.","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":600},{"type":"flash","id":"papas-pizzeria","slug":"papas-pizzeria","title":"Papa’s Pizzeria","description":"Papa's Pizzeria is a 2007 simulation game from Flipline Studios where players take orders and run a busy pizza shop.","about":"Papa Louie has gone off on another trip, so Delivery Boy Roy ends up running the pizzeria. Customers expect their pizzas made exactly the way Papa Louie did, with very specific toppings, baking times and slicing requests. Players handle four stations and try to move up the ranks as a pizza chef.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":600,"height":450},{"type":"flash","id":"resort-empire","slug":"resort-empire","title":"Resort Empire","description":"Resort Empire is a 2013 pixel-art tycoon simulation from LittleGiantWorld in which players build and manage their own holiday resort.","about":"Resort Empire is a tycoon-style simulation game from LittleGiantWorld, released in 2013. Played from an axonometric, pixel-art viewpoint, it puts a single player in charge of running a resort.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"sands-of-the-coliseum","slug":"sands-of-the-coliseum","title":"Sands of the Coliseum","description":"Sands of the Coliseum is a 2012 action game from Berzerk Studio where players fight as a gladiator to climb the rankings.","about":"Sands of the Coliseum is an action game from Berzerk Studio in which the player takes on the role of a gladiator. Combat is gruesome and fast-paced, and the goal is to work up through the Coliseum rankings. Players can also challenge their friends along the way.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":550},{"type":"flash","id":"shop-empire-galaxy","slug":"shop-empire-galaxy","title":"Shop Empire Galaxy","description":"Shop Empire Galaxy is a 2016 simulation game from Little Giant World where players build a mall for alien and monster shoppers.","about":"Shop Empire Galaxy is a pixel art simulation game in which the player builds a large, luxurious shopping mall. Visitors come from across the galaxy, including aliens and monsters, so the mall needs staff and safety measures in place. It is the newest entry in the Shop Empire series from developer Little Giant World.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":700,"height":500},{"type":"flash","id":"vulpin-adventure","slug":"vulpin-adventure","title":"Vulpin Adventure","description":"Vulpin Adventure is a 2011 action adventure game by Firequill where players raise a customizable pet and battle monsters one on one.","about":"In Vulpin Adventure, the player adopts a creature known as a Vulpin and can change its appearance. Combat takes place as one-on-one fights against monsters. The game was created by Firequill and released in 2011.","system":"Flash","genre":"adventure","categories":"adventure|action","core":"swf","width":690,"height":510},{"type":"flash","id":"crush-the-castle","slug":"crush-the-castle","title":"Crush the Castle","description":"Crush the Castle is a 2009 logic and action game from Armor Games and Joey Betz where a trebuchet brings down medieval fortresses.","about":"The King sends the player to destroy every castle standing in the way of his kingdom's survival. Using a powerful trebuchet and eight different projectiles, the goal is to wipe out all inhabitants of each fortress. Players can also build and share their own custom castles or take on fortresses made by others. The game mixes physics-based artillery action with logic puzzle solving.","system":"Flash","genre":"logic","categories":"logic|action","core":"swf","width":760,"height":550},{"type":"flash","id":"decision-medieval","slug":"decision-medieval","title":"Decision Medieval","description":"Decision Medieval is a 2014 action shooter from FlyAnvil that pits a kingdom's defenders against zombies, orcs, werewolves and trolls.","about":"Decision Medieval is a shooter set in a Middle Ages world, and it continues the Decision series. The player commands a kingdom's forces in battle against waves of zombies, orcs, werewolves and trolls. Victory for the kingdom is the goal across these fights against the monstrous hordes.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":700,"height":600},{"type":"flash","id":"gunblood","slug":"gunblood","title":"Gunblood","description":"Gunblood is a 2010 reflex shooter where you face nine computer gunslingers in one-on-one duels and four bonus rounds.","about":"Gunblood is a one-on-one shooting game in which the player tries to become the most feared gunslinger by beating nine computer opponents. Each duel begins with six shots for both sides, and a match with no shots left while both are alive ends in a draw that must be replayed. Every two gun battles, a bonus round appears; there are four in total, and the aim is to hit the targets while avoiding the assistant. Scores are based on accuracy, speed, and remaining life.","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":720,"height":425},{"type":"flash","id":"home-sheep-home","slug":"home-sheep-home","title":"Home Sheep Home","description":"Home Sheep Home is a 2010 puzzle platformer from Aardman Digital where three sheep with different abilities must reach the barn.","about":"Three sheep, Shaun, Timmy and Shirley, need to make it back to the barn in one piece. Each one has its own abilities, and the way forward depends on using those abilities together to get past the obstacles in their path. The game mixes puzzle solving with platforming as the flock cooperates to reach home.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":640,"height":480},{"type":"flash","id":"line-rider","slug":"line-rider","title":"Line Rider","description":"Line Rider, a 2006 creative sandbox from Boštjan Čadež, lets players sketch slopes and watch a sledder ride their hand-drawn tracks.","about":"Players draw lines on a blank canvas, and a small figure on a sled then travels across the path they have made. The experience blends physics simulation with vector drawing and animation, so each track behaves according to the shapes placed on screen. It functions as both a game and an open-ended tool for experimentation.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":800,"height":600},{"type":"flash","id":"pacman-advanced","slug":"pacman-advanced","title":"Pacman Advanced","description":"Pacman Advanced is a 2007 arcade game from Start Games in which the player guides Pacman while avoiding ghosts.","about":"Pacman Advanced is an arcade take on the classic maze formula, released in 2007 by Start Games. The player moves Pacman through the game while ghosts pursue him, and being caught by a ghost ends the run. The title builds on the familiar Pacman setup with an advanced version of the action.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"pandemic-ii","slug":"pandemic-ii","title":"Pandemic II","description":"Pandemic II is a 2008 strategy and simulation game from Dark Realm Studios where players evolve a disease to infect and destroy mankind.","about":"In Pandemic II, the player customizes a disease and guides its evolution with the goal of infecting and wiping out the human population. Development and balancing work went into making this sequel surpass the original in every way. Tutorial videos and an online guide can be accessed from inside the game, and watching the videos is strongly advised.","system":"Flash","genre":"strategy","categories":"strategy|simulation","core":"swf","width":700,"height":500},{"type":"flash","id":"pokemon-trainer-creator","slug":"pokemon-trainer-creator","title":"Pokémon Trainer Creator","description":"Pokémon Trainer Creator is a 2013 dress-up game by Joy Chiang Ling where players assemble a trainer from a range of clothing and color options.","about":"Players build their own Pokémon trainer by choosing from a large set of clothing pieces and colors. Picking a basic color scheme first can make it easier to find pieces that match, though mixing things up is also possible. Items that are not needed can be moved aside, and returning them near their original spots keeps the workspace manageable. Finished trainers can be captured with Print Screen.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":765,"height":650},{"type":"flash","id":"riddle-school","slug":"riddle-school","title":"Riddle School","description":"Riddle School is a 2006 point-and-click adventure from JonBro in which a student tries to escape the classroom.","about":"Riddle School is a mouse-only adventure game released by JonBro in 2006. The player guides a student who wants to get out of school, solving the puzzles and obstacles that stand in the way. Everything is controlled with the mouse, with no keyboard input required. It is the first entry in the Riddle School series.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"samurai-jack-code-of-the-samurai","slug":"samurai-jack-code-of-the-samurai","title":"Samurai Jack: Code of the Samurai","description":"Samurai Jack: Code of the Samurai is a 2003 action game from Cartoon Network in which the cartoon hero battles his way into hostile lands.","about":"Players take control of the cartoon hero Samurai Jack and push into enemy-held ground, fighting the foes they meet along the way. A sword serves for close-range strikes that slice demons apart, while a shuriken, or ninja star, lets players hit targets from a distance. The mix of melee and ranged options shapes how each encounter is handled.","system":"Flash","genre":"action","categories":"action","core":"swf","width":432,"height":330},{"type":"flash","id":"star-island","slug":"star-island","title":"Star Island","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":640,"height":411},{"type":"flash","id":"acid-factory","slug":"acid-factory","title":"Acid Factory","description":"Acid Factory is a 2006 MiniClip platformer with pixel art and a zombie theme, played solo from an isometric-style view.","about":"Acid Factory is a single-player arcade platformer from MiniClip, released in 2006. It presents its pixel art world from an axonometric perspective, with zombies forming the backdrop of the action.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":782,"height":501},{"type":"flash","id":"blockhead-the-game","slug":"blockhead-the-game","title":"Blockhead: The Game","description":"Blockhead: The Game is a 2006 top-down adventure where you guide the world's ultimate idiot through eight hand-drawn stages.","about":"In this top-down adventure from Komix Games and Michael Swain, the player takes the role of Blockhead's Conscience and directs the world's ultimate idiot through eight hand-drawn stages. Progress depends on forethought, exploration and a great deal of strategy, so the tutorial is essential for learning the game system. The interactive world is viewed from above, and the challenge lies in steering Blockhead away from pain and toward peril.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"mini-golf","slug":"mini-golf","title":"Mini Golf","description":"Mini Golf is a 2006 sports game from Electrotank in which the goal is simply to sink the ball into the hole.","about":"This sports title from Electrotank dates back to 2006 and centers on the game of mini golf. The task is straightforward: get the ball into the hole. Play moves from one hole to the next as the player works on their putting.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":700,"height":400},{"type":"flash","id":"raze","slug":"raze","title":"Raze","description":"Raze is a 2010 action shooter from Addisonr and Juice-Tin where players fight aliens, robots and zombies in a battle over Earth's fate.","about":"Raze is a futuristic shooter set in a war for Earth's survival. Players take on aliens, robots and zombies, or switch sides and fight for the planet's destruction instead. The choice of allegiance is what sets the game apart from a straightforward fight against invaders.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":700,"height":600},{"type":"flash","id":"sonic-blox","slug":"sonic-blox","title":"Sonic Blox","description":"Sonic Blox is a 2004 arcade puzzler from Mikhail Kafanov that mixes Sonic the Hedgehog with block-stacking Tetris action.","about":"Sonic Blox is a block-stacking arcade game from 2004, made by Mikhail Kafanov. Figures fall and the player moves them left or right, rotates them, and drops them into place. Clearing two, three or four lines at once is the trick the game rewards. A cheat can be triggered by pressing something on the title screen, for anyone who gets stuck.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":400,"height":500},{"type":"flash","id":"tetris","slug":"tetris","title":"Tetris","description":"Tetris, Paul Neave's 2003 arcade take on the classic block-stacking game, challenges players to clear lines as falling pieces pile up.","about":"Paul Neave's 2003 arcade game is a version of the classic block-stacking puzzler. Players rotate and place falling pieces so they form complete rows, which then disappear to make room for more. The aim is to keep the stack from reaching the top for as long as possible.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":382,"height":380},{"type":"flash","id":"the-worlds-hardest-game-2","slug":"the-worlds-hardest-game-2","title":"The World’s Hardest Game 2","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":500},{"type":"flash","id":"american-racing","slug":"american-racing","title":"American Racing","description":"American Racing is a 2012 stock car game from Turbo Nuke where players take part in a calendar of events against large fields of rivals.","about":"American Racing is a stock car racing game built around a full calendar of events. Races can include as many as sixty other cars, and contact between vehicles is part of the action. The game offers a large selection of tracks and cars, and the cars can be damaged during races. It was developed by Turbo Nuke and released in 2012.","system":"Flash","genre":"sports","categories":"sports|racing","core":"swf","width":640,"height":480},{"type":"flash","id":"annoying-orange-escape-from-dr-fruitenstein","slug":"annoying-orange-escape-from-dr-fruitenstein","title":"Annoying Orange: Escape from Dr. Fruitenstein","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":480},{"type":"flash","id":"exmortis-2","slug":"exmortis-2","title":"Exmortis 2","description":"Exmortis 2 is a 2006 horror point-and-click adventure by Ben Leffler, continuing the story of the 2004 original.","about":"Exmortis 2 is a horror point-and-click adventure released in 2006 as the follow-up to the 2004 game Exmortis. Players click through the game's environments as the horror story continues. The game includes a Sudoku puzzle element that some players found difficult, and walkthroughs were made available to help with it. Developer Ben Leffler created the sequel after the positive response to the first game.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"madness-premeditation","slug":"madness-premeditation","title":"Madness Premeditation","description":"Madness Premeditation is a 2010 strategy-action game by BoMToons where players plan Hank's moves through a strange area of Nevada.","about":"In this strategy and puzzle game, the player plots Hank's actions across a peculiar part of Nevada, with the advice to think in four dimensions. Shots are assigned by clicking nodes, and the astral projection mode uses arrow keys. Two-handed weapons such as the shotgun and AK fire only forward, and glass shards can disrupt shots until things settle. The developer describes the design as chess-like.","system":"Flash","genre":"strategy","categories":"strategy|action","core":"swf","width":700,"height":400},{"type":"flash","id":"pandemic","slug":"pandemic","title":"Pandemic","description":"Pandemic is a 2007 strategy game from Dark Realm Studios and Blips in which players evolve a virus and try to wipe out mankind.","about":"In Pandemic, the player evolves a biological virus with the goal of wiping out mankind. Points are awarded based on how many people are newly infected after each turn, though the first few turns yield no points. Instructions explain how to play. The game's author notes that West Europe can be infected, but it is hard, and warns that it may be dangerous for people with epilepsy.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":750,"height":475},{"type":"flash","id":"pirateers-2","slug":"pirateers-2","title":"Pirateers 2","description":"Pirateers 2 is a top-down pirate strategy shooter from Labu Games, released in 2014 as a single-player follow-up in the Pirateers series.","about":"Pirateers 2 is a top-down single-player game from Labu Games that blends strategy and shooting within a pirate setting. Players can upgrade their abilities as they progress and earn achievements along the way, with mild violence throughout.","system":"Flash","genre":"strategy","categories":"strategy|shooter","core":"swf","width":750,"height":600},{"type":"flash","id":"raiden-x","slug":"raiden-x","title":"Raiden X","description":"Raiden X is a 2005 shooter from Go0gley that serves as a tribute to the classic Raiden series of arcade shoot-em-ups.","about":"Raiden X is a shoot-em-up built as a tribute to the Raiden series. The game follows the classic arcade shooter format, with the player taking on waves of enemies from a top-down view. It was released in 2005 by developer Go0gley.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":300,"height":350},{"type":"flash","id":"sports-heads-basketball","slug":"sports-heads-basketball","title":"Sports Heads: Basketball","description":"Sports Heads: Basketball is a 2012 single-player sports game from Mousebreaker with cartoon, side-view basketball action.","about":"Sports Heads: Basketball is a cartoon basketball game played from a side view. It comes from developer Mousebreaker and belongs to the Sports Heads series, and it is built for a single player.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":800,"height":540},{"type":"flash","id":"battle-of-britain-commando","slug":"battle-of-britain-commando","title":"Battle of Britain: Commando","description":"Battle of Britain: Commando, a 2006 MiniClip shooter, puts players in the role of defending the Allies against an enemy invasion.","about":"Battle of Britain: Commando is a shooter from MiniClip in which the player takes on the task of protecting the Allies. An enemy invasion is sweeping across Europe, and the goal is to hold it back. The game frames the action around stemming that advancing tide.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":400,"height":300},{"type":"flash","id":"create-a-touhou-character","slug":"create-a-touhou-character","title":"Create a Touhou Character","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":550,"height":400},{"type":"flash","id":"dad-n-me","slug":"dad-n-me","title":"Dad ‘n Me","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"penguin-diner","slug":"penguin-diner","title":"Penguin Diner","description":"Penguin Diner is a 2008 simulation game where Penny the Penguin waits tables to earn money and find her way home.","about":"Penny the Penguin gets lost and runs out of money during an Antarctic trek, until the owner of a local diner gives her a job. Players serve customers quickly to keep them happy and bring them back for more. Earning enough money helps Penny return home to her family. The game moves through three locations, and players can buy upgrades for the diner along the way.","system":"Flash","genre":"simulation","categories":"simulation|arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"picos-school","slug":"picos-school","title":"Pico’s School","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":350},{"type":"flash","id":"road-of-the-dead","slug":"road-of-the-dead","title":"Road of the Dead","description":"Road of the Dead is a 2010 shooter and action game from Evil-Dog in which a driver battles through a zombie-filled highway to leave a quarantined city.","about":"The military stands in the way as the player drives along a highway packed with hungry undead, wreckage and disorder, aiming to get out of a quarantined city. Four game modes, 24 medals and a points total of up to 1000 are included. A quality toggle on the Q key is available for slower machines, since the graphics are demanding.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":600,"height":400},{"type":"flash","id":"run-2","slug":"run-2","title":"Run 2","description":"Run 2 is a 2011 arcade game from developer player_03 about sprinting, leaping and gliding through space in unusual footwear.","about":"This arcade title puts the focus on movement: the player runs and jumps through each stage, and the usual rules of physics do not always apply. Roller skates can also be worn, changing how the character travels. Developer player_03 released the game in 2011.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"sports-heads-volleyball","slug":"sports-heads-volleyball","title":"Sports Heads: Volleyball","description":"Sports Heads: Volleyball is a 2012 cartoon sports game from Mousebreaker in which players take on volleyball matches from a side-on view.","about":"Sports Heads: Volleyball is a cartoon volleyball game played from a side view. Released in 2012 by Mousebreaker as part of the Sports Heads series, it offers single-player volleyball action.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":800,"height":540},{"type":"flash","id":"time-fcuk","slug":"time-fcuk","title":"Time Fcuk","description":"Time Fcuk is a 2009 puzzle platformer by Edmund McMillen that mixes block-based challenges with shifting perspectives.","about":"Players work through block and platform puzzles that hinge on seeing a situation from more than one angle. The game pairs that logic-driven design with themes of stasis, perspective, and the odd details of everyday life, from work to reunions. Edmund McMillen built it around the idea that rearranging letters in a word can change how people read it, even when nothing logical shifts. A community element lets players share their own levels.","system":"Flash","genre":"creative","categories":"creative|action","core":"swf","width":700,"height":450},{"type":"flash","id":"vex","slug":"vex","title":"Vex","description":"Vex is a platformer where spikes, traps and moving platforms test survival skills across levels that grow more complex.","about":"Vex is a platformer built around survival in a world that keeps shifting. Players deal with spikes, traps and moving platforms as they work through the game. Each battle level grows more complex than the last, so the challenge rises as progress continues.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":550,"height":550},{"type":"flash","id":"1-on-1-soccer","slug":"1-on-1-soccer","title":"1 on 1 Soccer","description":"1 on 1 Soccer is a 2012 sports game by Adam Wardle that strips the sport down to a single player per team.","about":"Each side fields one player in this soccer game, which sets it apart from more conventional takes on the sport. Beating the computer opponent on the Best difficulty setting, with no other cheats active, unlocks a cheat. The developer has included a few cheats aimed at fans of 1960s rock.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":550,"height":400},{"type":"flash","id":"black-licorice","slug":"black-licorice","title":"Black Licorice","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":320,"height":240},{"type":"flash","id":"game-over-gopher","slug":"game-over-gopher","title":"Game Over Gopher","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":600},{"type":"flash","id":"hot-dog-bush","slug":"hot-dog-bush","title":"Hot Dog Bush","description":"Hot Dog Bush is a 2007 simulation game from 2D Play about running a hot dog stand and keeping customers served.","about":"Hot Dog Bush is a single-player simulation game from 2D Play, released in 2007. Players manage a restaurant stand, cooking and serving food while handling the pressures of time management and a political theme centred on a famous person.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":600,"height":400},{"type":"flash","id":"papas-freezeria","slug":"papas-freezeria","title":"Papa’s Freezeria","description":"Papa's Freezeria is a 2011 simulation game from Flipline Studios where players run a tropical ice cream shop and serve sundaes to customers.","about":"In Papa's Freezeria, the player takes charge of an oceanfront ice cream shop on Calypso Island after Papa Louie leaves during tourist season. Customers arrive seeking freezer treats, and the player must blend ingredients and portion the right amount of ice cream into sundae cups. Dozens of syrups, candies, and toppings become available as the game progresses. The time-management and hands-on play of the series returns, along with Closer customers, the Food Critic, weekly paychecks, and upgrades.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"pirateers","slug":"pirateers","title":"Pirateers","description":"Pirateers is a 2012 shooter from Labu Games where players take on the role of a pirate on the open sea.","about":"Players step into the life of a pirate, taking on navy ships and rival pirate crews in combat. Merchant vessels can be robbed, and treasure islands hold lost riches waiting to be uncovered. The goal includes finding the legendary treasure known as Neptune's Eye.","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":750,"height":500},{"type":"flash","id":"super-mario-flash","slug":"super-mario-flash","title":"Super Mario Flash","description":"Super Mario Flash is a 2007 side-scrolling platformer by Pouetpu with pixel art, score attack runs and a built-in level editor.","about":"Super Mario Flash is a single-player platformer from 2007 by Pouetpu, built around pixel-art side-scrolling action and score-attack play. Players jump and run through stages in the Super Mario Flash series, and the game includes a level editor for building custom stages.","system":"Flash","genre":"action","categories":"action","core":"swf","width":320,"height":240},{"type":"flash","id":"bubble-tanks-ii","slug":"bubble-tanks-ii","title":"Bubble Tanks II","description":"Bubble Tanks II is a 2009 shooter from Hero Interactive where players burst through giant bubbles and battle enemy tanks to grow stronger.","about":"Players move between enormous bubbles, fighting hostile tanks and collecting the bubbles they leave behind to increase in size. Each stage of growth brings new and improved weaponry. The campaign ends with a final opponent that must be beaten to finish the game. Compared with the original, this sequel offers 26 tank forms, more than 30 weapons and over 50 kinds of enemies, with feedback from the first game shaping its design.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":500,"height":400},{"type":"flash","id":"dig-to-china","slug":"dig-to-china","title":"Dig To China","description":"Dig To China is a 2014 arcade mining game from Octopodo where players break through tiles to reach China.","about":"Players dig through a huge number of blocks in a race to reach China. Along the way, resources are collected and used to purchase upgrades. The goal is to get as deep as possible before time runs out, then try again. The game has a chunky, tile-busting style.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"hannah-montana-wireless-quest","slug":"hannah-montana-wireless-quest","title":"Hannah Montana: Wireless Quest","description":"Hannah Montana: Wireless Quest is a 2013 adventure game where Miley races to recover her diary before class begins.","about":"Sneaky Jackson has hidden Miley's diary somewhere in the school, leaving a trail of clues behind. Miley has thirty minutes to follow them before class starts. Oliver and Lilly pitch in with the search along the way. Players work through the clues to track down the diary in time.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":580,"height":420},{"type":"flash","id":"kindergarten","slug":"kindergarten","title":"Kindergarten","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":800,"height":600},{"type":"flash","id":"little-wheel","slug":"little-wheel","title":"Little Wheel","description":"Little Wheel is an adventure game in which a small robot sets out to rescue his world, played entirely with the mouse.","about":"A small robot named Little Wheel must save his world. Players guide him through the game using only the mouse. The adventure focuses on helping the robot on his mission.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"mahjongg","slug":"mahjongg","title":"Mahjongg","description":"Mahjongg is a 2003 tile-matching puzzle and simulation game from MiniClip where players clear the board by pairing identical tiles.","about":"This tile-matching puzzle is a solitaire take on an old Asian board game. Players remove tiles from the board by finding and pairing identical ones, working until none remain. A beginners mode helps newcomers learn how to spot available tiles and make matches, while hints and an unlimited undo option let players explore different ways through a layout.","system":"Flash","genre":"simulation","categories":"simulation|puzzle","core":"swf","width":610,"height":500},{"type":"flash","id":"potty-racers","slug":"potty-racers","title":"Potty Racers","description":"Potty Racers is a 2009 arcade launch game where a stick man rides a porta potty down a hill and off a cliff.","about":"In this arcade launch game from Gonzo Games, a stick man enters a porta potty racing and jumping competition. Players run and push the potty, jump inside, then charge down a hill and fly off a cliff to cover distance. Money earned from the run can be spent on upgrades such as wheels, an engine, wings, a parachute or fuel. While airborne, stunts can be pulled off using the number pad.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":500},{"type":"flash","id":"shop-empire","slug":"shop-empire","title":"Shop Empire","description":"Shop Empire is a 2011 simulation game from Little Giant World about building and running profitable shopping malls.","about":"Players construct shopping malls in different locations around the world, aiming to make them as large, luxurious and profitable as possible. Visitors spend money in the mall, and amenities such as restrooms, elevators, restaurants and shops can be added and upgraded to encourage more spending. Staff must also be hired: cleaners keep the building tidy, technicians handle power failures, and security guards deal with shoplifters. The game has a pixel art style.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"spongebob-saw-game","slug":"spongebob-saw-game","title":"SpongeBob Saw Game","description":"SpongeBob Saw Game is a 2012 point-and-click adventure from Inka Games set in an underwater parody world.","about":"Inka Games released this single-player point-and-click adventure in 2012, starring SpongeBob SquarePants in an aquatic parody setting. Players work through the story using only the mouse, with sliding elements woven into the adventure.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":800,"height":500},{"type":"flash","id":"takeover","slug":"takeover","title":"Takeover","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":600},{"type":"flash","id":"tom-loves-angela","slug":"tom-loves-angela","title":"Tom Loves Angela","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":320,"height":480},{"type":"flash","id":"truckloader5","slug":"truckloader5","title":"Truck Loader 5","description":"Truck Loader 5 is a puzzle game where a forklift with a magnetic arm collects crates and loads them onto a truck.","about":"Drive a forklift around each stage using the keyboard, steering with WASD or the arrow keys and jumping with the up or W key. A magnetic arm follows the mouse, and clicking switches it on so it can pick up crates. The same arm can also press buttons or shove objects out of the way. The goal is to place every crate on the truck, then drive off it to finish the level.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":700,"height":500},{"type":"flash","id":"625-sandwich-stacker","slug":"625-sandwich-stacker","title":"625 Sandwich Stacker","description":"625 Sandwich Stacker is a 2003 Disney arcade game where players stack sandwiches for a high score as Stitch's experiment 625.","about":"In 625 Sandwich Stacker, a single player takes on an arcade stacking challenge tied to Lilo and Stitch. The goal is to build sandwiches while chasing a high score in a score-attack format. It was developed by The Walt Disney Company in 2003.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":580,"height":320},{"type":"flash","id":"chao-maker","slug":"chao-maker","title":"Chao Maker","description":"Chao Maker is a 2006 creative game by geN8hedgehog where players build a Chao from the Sonic series by clicking words to change its features.","about":"Chao Maker lets players put together their own Chao based on the creatures from the Sonic games. Clicking on words changes the different parts of the character. The game includes a range of Chao options that the developer could think of at the time. Changing the shape resets the colour, a quirk the creator acknowledged.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":580,"height":400},{"type":"flash","id":"flash-pacman","slug":"flash-pacman","title":"Flash Pacman","description":"Flash Pacman is a 2001 arcade take on the classic maze-chase game from developer Francesco Pastore.","about":"This 2001 arcade game by Francesco Pastore presents a version of the classic Pacman formula. Players guide the character through the familiar maze-chase style of play. The source notes it as a solid take on the original.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":360,"height":440},{"type":"flash","id":"gold-miner","slug":"gold-miner","title":"Gold Miner","description":"Gold Miner is an arcade game from 2003 by GameRival where players reel in gold to hit each stage's cash goal.","about":"Players control a crank to pull up gold nuggets, and each stage sets a cash target that must be met to advance. Nuggets come in different sizes: larger pieces take longer to reel in but are worth more, while smaller ones come up quickly for little value. Ore pieces are worth almost nothing, and the large ones waste time. Mystery bags bring unpredictable results, and diamonds offer high value with little effort.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"submachine-1-the-basement","slug":"submachine-1-the-basement","title":"Submachine 1: The Basement","description":"Submachine 1: The Basement is a 2014 adventure game by Mateusz Skutnik set among ruins, runes and old artefacts.","about":"This adventure takes place in a world of ruins, runes and old artefacts, and the 2014 version of Submachine 1: The Basement refines that setting. The ambient music, long a signature part of the Submachine series, is now properly credited to its author, Marcus Gutierrez, whose name appears on the menu page. An ancient coin replaces the earlier Euro coin as an inventory item, a change made to keep the game consistent with its lore. The result is a small but meaningful update to the original basement experience.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":400,"height":425},{"type":"flash","id":"super-mario-world-flash","slug":"super-mario-world-flash","title":"Super Mario World Flash","description":"Super Mario World Flash is a 2008 single-player platformer by Nowe Reginald, blending pixel-style adventure with score-attack play.","about":"Super Mario World Flash is a single-player platformer from 2008 by Nowe Reginald, part of the Super Mario World Flash series. The game mixes platforming and adventure across pixel-style stages, with a score-attack structure that encourages replaying for better results.","system":"Flash","genre":"platformer","categories":"platformer|adventure","core":"swf","width":480,"height":320},{"type":"flash","id":"swords-and-sandals-2-emperors-reign","slug":"swords-and-sandals-2-emperors-reign","title":"Swords and Sandals 2: Emperor’s Reign","description":"Swords and Sandals 2: Emperor's Reign is a 2007 role-playing adventure set in Ancient Rome from 3RD SENSE Australia.","about":"Swords and Sandals 2: Emperor's Reign is a single-player role-playing adventure set in Ancient Rome, released in 2007 by 3RD SENSE Australia Pty Ltd. It belongs to the Swords and Sandals series, and its action and adventure elements unfold from a role-playing perspective.","system":"Flash","genre":"adventure","categories":"adventure|action","core":"swf","width":640,"height":420},{"type":"flash","id":"the-waitress","slug":"the-waitress","title":"The Waitress","description":"The Waitress is a 2007 simulation game from D-Man in which a server races to take customer orders and keep tables clean.","about":"Players take the role of a waitress working a shift, with the goal of serving each customer. Orders need to be taken as quickly as possible to keep up with the pace. Clean tables are also part of the job, so the work area has to be maintained alongside the serving. The game was developed by D-Man and released in 2007.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":620,"height":340},{"type":"flash","id":"awesome-tanks","slug":"awesome-tanks","title":"Awesome Tanks","description":"Awesome Tanks is a 2012 action game by Alexander Gette in which players steer a tank, aim with the mouse and spend coins on upgrades.","about":"Players control a tank with the WASD or arrow keys while the mouse handles aiming and firing. The spacebar or number keys switch between weapons during play. Coins collected along the way can be spent on upgrades for the tank.","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":600},{"type":"flash","id":"bloons-td-4","slug":"bloons-td-4","title":"Bloons Tower Defense 4","description":"Bloons Tower Defense 4 is a 2009 strategy game from Ninja Kiwi where players place towers to stop waves of Bloons.","about":"Bloons Tower Defense 4 builds on the series with sharper visuals and a larger set of tower types, each with its own upgrade paths. Players defend against incoming Bloons across many different tracks, and can use Kreds to buy optional content and upgrades. The game includes save games, a career mode, a sandbox mode and an apopalypse mode, giving it substantial replay value.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":640},{"type":"flash","id":"gems","slug":"gems","title":"Gems","description":"Gems is a 2008 puzzle game from Cublo Games in which players sort precious gems as quickly as possible to build up their score.","about":"Gems is a puzzle game from Cublo Games, released in 2008. The task is to sort precious gems, and speed matters: the faster the sorting is done, the higher the score climbs. Players watch their score grow as they work through the gems.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":386},{"type":"flash","id":"pixelspix","slug":"pixelspix","title":"Pixelspix","description":"Pixelspix is a 2005 arcade title built around a collection of music video and whack-a-mole mini-games with customization options.","about":"Pixelspix is a single-player arcade game from 2005 that gathers several activities, including music video segments, whack-a-mole, and brick breaker, all played with the mouse. It also features a print studio where players can customize and print images, with visuals that mix live action and pre-rendered 3D. The game is tied to the LazyTown series.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":340},{"type":"flash","id":"pony-creator","slug":"pony-creator","title":"Pony Creator","description":"Pony Creator is a 2011 character-building game by General Zoi where players design their own equine figure in a single-player creative tool.","about":"Pony Creator is a single-player creative activity from 2011, developed by General Zoi and themed around the My Little Pony universe. Players build and customize an equine character of their own design.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":830,"height":650},{"type":"flash","id":"stunt-dirt-bike","slug":"stunt-dirt-bike","title":"Stunt Dirt Bike","description":"Stunt Dirt Bike is a 2007 sports game where players guide a dirt bike or ATV across short obstacle courses without crashing.","about":"Players take a dirt bike or ATV from one side of the screen to the other on short obstacle courses. Arrow keys control the vehicle: up moves forward, down moves back, and left and right lean in those directions. Each course is packed with obstacles, and hitting one too fast causes a loss of control and a crash. Balancing speed and precision is the key to finishing each level cleanly.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":500,"height":350},{"type":"flash","id":"super-stacker","slug":"super-stacker","title":"Super Stacker","description":"Super Stacker is a 2008 physics puzzle game by Gaz Thomas in which shapes must be stacked with care.","about":"Super Stacker is a physics-based puzzle game from 2008, developed by Gaz Thomas. The player places shapes one on top of another, and the resulting stack has to hold together. Success depends on careful positioning, since the physics decide whether the pile stays upright. The challenge comes from keeping the stack stable as it grows.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":550},{"type":"flash","id":"swords-and-sandals-gladiator","slug":"swords-and-sandals-gladiator","title":"Swords and Sandals: Gladiator","description":"Swords and Sandals: Gladiator is a 2006 action adventure game of arena fighting and character building set in Ancient Rome.","about":"Swords and Sandals: Gladiator is an action adventure game from 3RD SENSE Australia Pty Ltd, set in Ancient Rome. Players fight in arena combat and develop their gladiator through role-playing style upgrades and customization. The cartoon presentation includes blood and moderate violence, and the game is played solo.","system":"Flash","genre":"adventure","categories":"adventure|action","core":"swf","width":640,"height":440},{"type":"flash","id":"warzone-tower-defense","slug":"warzone-tower-defense","title":"Warzone Tower Defense","description":"Warzone Tower Defense is a 2008 strategy game by Jeff Gold where players build high-tech towers on wide maps and try to last as long as possible.","about":"Set across expansive maps with different terrain, this strategy title from Jeff Gold challenges players to hold out for as long as they can. Towers and other high-tech defenses are placed using the mouse, while the number keys pick structures from the shop and other keys handle bombs and items. Several modes offer alternative ways to play, and later versions added map variants where flying enemies never appear.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":833,"height":607},{"type":"flash","id":"bikechamp2","slug":"bikechamp2","title":"Bike Champ 2","description":"Bike Champ 2 is a single-player motocross racing game in the Bike Champ series, putting players behind the handlebars of a dirt bike.","about":"Bike Champ 2 is a motocross racing game played solo. As part of the Bike Champ series, it focuses on dirt bike driving and sports competition, with the action shown from a rider's perspective.","system":"Flash","genre":"racing","categories":"racing","core":"swf","width":640,"height":480},{"type":"flash","id":"bubble-shooter","slug":"bubble-shooter","title":"Bubble Shooter","description":"Bubble Shooter is a 2001 arcade puzzler from Ilion Dynamics where players aim and fire at clusters of bubbles to clear them from the screen.","about":"Players aim a launcher with the mouse and click to fire at the bubbles above. Popping bubbles is the main goal, but a shot that hits nothing costs one point of health. When health runs out, another row of bubbles appears, raising the difficulty. Skilled play can clear the entire board.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":600},{"type":"flash","id":"civiballs","slug":"civiballs","title":"Civiballs","description":"Civiballs is a 2009 puzzle game by Andrey Kovalishin where colored balls must be guided into matching vases.","about":"Civiballs is a puzzle game from 2009 by Andrey Kovalishin. Players cut chains and use cannons to move colored balls around each level. The goal is to place every ball into the vase that matches its color. Each stage is solved by figuring out the right order and timing for those actions.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":480},{"type":"flash","id":"deep-sleep","slug":"deep-sleep","title":"Deep Sleep","description":"Deep Sleep is a 2012 point-and-click adventure by Mateusz Sokalszczuk and ScriptWelder, set inside a nightmare the player must escape.","about":"The player is trapped in a nightmare, with something hiding in the dark and a force inside the mind trying to drag them further down. Escape is the goal, though it is unclear who will manage it. The game took first place in the 10th Casual Gameplay Design Competition. Later fixes addressed volume resets, objects that failed to reset on restart, and browser zoom cropping.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"dont-whack-your-boss","slug":"dont-whack-your-boss","title":"Don’t Whack Your Boss","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":700,"height":540},{"type":"flash","id":"miami-shark","slug":"miami-shark","title":"Miami Shark","description":"Miami Shark, a 2009 arcade action game by Felix Wiesner, follows a shark causing destruction and mayhem through its daily routine.","about":"This arcade action game puts players in the role of a shark whose daily routine involves destruction and mayhem. The action includes explosions and widespread chaos as the shark goes about its business. It was created by Felix Wiesner and Mausland Entertainment in 2009.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":720,"height":450},{"type":"flash","id":"papa-louie-3-when-sundaes-attack","slug":"papa-louie-3-when-sundaes-attack","title":"Papa Louie 3: When Sundaes Attack!","description":"Papa Louie 3: When Sundaes Attack! is a 2015 platformer from Flipline Studios where Captain Cori battles food enemies to rescue captives.","about":"A cruise celebrating the opening of Seaside Freezeria is taken over by Radley Madish and Luau LePunch, who use Warp Coins to drag Papa Louie and the customers into the Land of Munchmore. There, Radley's Sundaesauruses hold the captives and force the chefs to build his army. Captain Cori travels through Munchmore's terrain, fighting food enemies and freeing passengers and crew. Rescued customers become playable, each bringing a distinct weapon and set of skills.","system":"Flash","genre":"platformer","categories":"platformer|arcade|action","core":"swf","width":700,"height":416},{"type":"flash","id":"pinch-hitter","slug":"pinch-hitter","title":"Pinch Hitter","description":"Pinch Hitter is a 2007 single-player baseball game from Mousebreaker where players step up to the plate in a sports challenge.","about":"Pinch Hitter is a single-player baseball game released in 2007 by Mousebreaker. It belongs to the Pinch Hitter series and focuses on the sport of baseball from a sports perspective.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":640,"height":480},{"type":"flash","id":"pix-city-adventure","slug":"pix-city-adventure","title":"Pix City Adventure!","description":"Pix City Adventure! is a 2012 adventure game by Rasmusiboy in which players explore Pix City while fighting enemies and facing crime.","about":"Players take on the role of a character exploring Pix City in this 2012 adventure from Rasmusiboy. The city is full of bad guys to fight. Corruption and crime are part of the setting, and the player tries not to get caught up in them. Combat and exploration are central to the experience.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":710,"height":480},{"type":"flash","id":"shop-empire-rampage","slug":"shop-empire-rampage","title":"Shop Empire Rampage","description":"Shop Empire Rampage is a 2014 strategy spin-off from Little Giant World, turning the pixel mall series toward a revenge-driven campaign.","about":"This follow-up to Shop Empire shifts away from running the shopping mall and toward a different kind of campaign. A group of employees who were fired by accident band together, and the player leads them as they seek revenge. The pixel art style of the earlier games carries over, while the gameplay itself works differently from what came before.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":700,"height":500},{"type":"flash","id":"sonic-boom-cannon","slug":"sonic-boom-cannon","title":"Sonic Boom Cannon","description":"Sonic Boom Cannon is a 2005 arcade game by Xanadu32 where a hedgehog-powered cannon launches Sonic characters down courses.","about":"Players adjust the cannon's power and angle, then fire a Sonic character down a course. The goal is to gather rings, collect all seven chaos emeralds, and unlock every character. Rings can also be spent to buy emeralds for 200 each, and there is a secret ending to reach. A save option keeps progress, and a mute button controls the music.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"space-is-key-2","slug":"space-is-key-2","title":"Space Is Key 2","description":"Space Is Key 2 is a 2012 platformer by Chris Jeff where every jump is a matter of timing and the space bar gets a serious workout.","about":"This sequel returns with more pixel-exploding platforming action. Players time their jumps through the original 20 levels, then can take on 10 extra levels in challenge mode. The space bar is the key to survival, and it takes a beating along the way.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":640,"height":480},{"type":"flash","id":"the-last-stand","slug":"the-last-stand","title":"The Last Stand","description":"The Last Stand, a 2007 shooter by Con-Artists, pits players against zombies from behind a barricade across 20 days and nights.","about":"Players defend a barricade from attacking zombies and must last through the night. Daylight hours are spent repairing the barricade, finding weapons, and locating other survivors who can assist with repairs. The game spans 20 days and nights, with more than 3,500 random zombie appearances and 11 weapons to use. Movement is handled with W, A, S, and D, while the mouse aims and fires, space switches weapons, and R reloads.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":420},{"type":"flash","id":"world-cup-headers-2006","slug":"world-cup-headers-2006","title":"World Cup Headers 2006","description":"World Cup Headers 2006 is a 2DPlay sports game where players head a football against 31 rival teams in a championship run.","about":"World Cup Headers 2006 is a sports game from 2DPlay in which the ball is played with the head rather than the feet. The player takes part in a headers championship and faces 31 other teams on the way to the title. Scores can be submitted so results are compared with other players around the world.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":650,"height":400},{"type":"flash","id":"bloons","slug":"bloons","title":"Bloons","description":"Bloons is a 2007 arcade puzzler from Ninja Kiwi in which players work through 50 levels by popping balloons.","about":"Bloons is built around a straightforward idea: popping balloons is enjoyable. Players make their way through 50 levels that combine puzzling challenges with arcade action. The game comes from developer Ninja Kiwi and was released in 2007.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"bubble-tanks","slug":"bubble-tanks","title":"Bubble Tanks","description":"Bubble Tanks is a 1997 shooter from Hero Interactive and Jared Riley where a bubble tank battles rivals and gathers bubbles.","about":"In Bubble Tanks, the player controls a bubble tank that fights other bubble tanks and collects bubbles inside a larger bubblefield. Movement uses the A, W, S, and D keys, while the mouse aims and fires. Controls can be remapped to other keys. The game generates and maintains more than 8,000 battlefields and 37,000 enemies despite its small size.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":500,"height":400},{"type":"flash","id":"charlie-and-lola-cloud-hopping","slug":"charlie-and-lola-cloud-hopping","title":"Charlie and Lola: Cloud Hopping","description":"Charlie and Lola: Cloud Hopping is a 2005 platformer from BBC and CBeebies in which Lola uses her net to catch butterflies among the clouds.","about":"Lola is up among the clouds, and her goal is to catch butterflies with her net. Players move through this platformer setting and try to snag the butterflies as they go. The game comes from BBC and CBeebies and follows the Charlie and Lola characters.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":500,"height":300},{"type":"flash","id":"family-crisis","slug":"family-crisis","title":"Family Crisis","description":"Family Crisis is a single-player logic puzzle from Plastelina Games, part of the Plastelina Logic Games series released in 2001.","about":"Family Crisis is a single-player puzzle game built around logic challenges, released in 2001 by Plastelina Games and Shlomir Hadad. It belongs to the Plastelina Logic Games series, which shares a connected set of titles.","system":"Flash","genre":"logic","categories":"logic|educational","core":"swf","width":500,"height":315},{"type":"flash","id":"generic-defense-game","slug":"generic-defense-game","title":"Generic Defense Game","description":"Generic Defense Game is a 2007 shooter by Josh Tuttle that pokes fun at the tower defense genre while still playing as one.","about":"Josh Tuttle made this shooter in 2007 as a joke about the many identical defense games that existed at the time. The project grew beyond its original plan and became a longer effort that plays as a defense game in its own right. The developer describes the result as fun despite its mocking intent.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":550,"height":400},{"type":"flash","id":"monkey-go-happy","slug":"monkey-go-happy","title":"Monkey GO Happy","description":"Monkey GO Happy is a 2008 puzzle adventure from Pencilkids and Robin Vencel about keeping a monkey entertained.","about":"This puzzle adventure from 2008 tasks the player with keeping a monkey amused. Monkeys are demanding, so the work of entertaining one takes up a great deal of time and effort. The game asks whether the player has what it takes to make the monkey happy.","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"queenly-portrait-maker","slug":"queenly-portrait-maker","title":"Queenly Portrait Maker","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":1200,"height":600},{"type":"flash","id":"roll-roll-pirate","slug":"roll-roll-pirate","title":"Roll Roll Pirate","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"smosh-fighter","slug":"smosh-fighter","title":"Smosh Fighter","description":"Smosh Fighter is a 2009 action game from SmoshTv in which players take control of Anthony or Ian for a bout of fighting.","about":"Released in 2009 by SmoshTv, Smosh Fighter is an action game built around combat. The player picks Anthony or Ian and then fights. Beyond the choice between those two characters, the game keeps its focus on the fighting itself.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"snail-bob","slug":"snail-bob","title":"Snail Bob","description":"Snail Bob, a 2010 puzzle game from Andrey Kovalishin, tasks players with guiding a brave snail safely to a new home.","about":"Bob is a snail who needs to reach a new home, and the path runs through a building site full of hazards. Players use the tools provided to help him make it past the tricky obstacles in his way. The game is a puzzle in which each step of Bob's journey has to be worked out.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":480},{"type":"flash","id":"the-boohbah-zone","slug":"the-boohbah-zone","title":"The Boohbah Zone","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":800,"height":600},{"type":"flash","id":"wolf-sheep-cabbage","slug":"wolf-sheep-cabbage","title":"Wolf Sheep & Cabbage","description":"Wolf Sheep & Cabbage is a single-player logic puzzle from 2001, part of the Plastelina Logic Games series.","about":"Wolf Sheep & Cabbage is a single-player puzzle game built around logic challenges, released in 2001 by Plastelina Games and Shlomir Hadad. It belongs to the Plastelina Logic Games series, and its educational focus makes it a fit for players who enjoy working through reasoning puzzles.","system":"Flash","genre":"logic","categories":"logic|educational","core":"swf","width":500,"height":315},{"type":"flash","id":"x-tract-paperclip","slug":"x-tract-paperclip","title":"X-Tract Paperclip","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":570,"height":430},{"type":"flash","id":"animator-vs-animation-game","slug":"animator-vs-animation-game","title":"Animator vs. Animation Game","description":"Animator vs. Animation Game is a 2007 action title from Alan Becker and Charles Yeh where a stick figure battles on-screen tools.","about":"A stick figure takes on the animator's tools in this action game from Alan Becker and Charles Yeh. Players move and duck with WASD, pick a tool using IJKL, and grab or release it with Q. Attacks come from the space bar, while U swats the cursor and O defends. The game is challenging, with many features meant to keep players entertained.","system":"Flash","genre":"action","categories":"action","core":"swf","width":650,"height":500},{"type":"flash","id":"bike-champ","slug":"bike-champ","title":"Bike Champ","description":"Bike Champ is a 2009 sports game from 2DPlay that puts players on a motorcycle assault course.","about":"Bike Champ is a sports game released in 2009 by 2DPlay. It places the player on a motorcycle assault course. The course is described as the craziest of its kind in the world.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":640,"height":480},{"type":"flash","id":"crash-down","slug":"crash-down","title":"Crash Down","description":"Crash Down is a 2003 puzzle arcade game from MiniClip in which players race to clear squares as fast as they can.","about":"Crash Down is a puzzle arcade game released in 2003 by MiniClip. The goal is to clear all of the squares from the board. Speed matters, since the squares need to be cleared as quickly as possible.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":550,"height":550},{"type":"flash","id":"factory-balls","slug":"factory-balls","title":"Factory Balls","description":"Factory Balls is a 2007 puzzle game by Bart Bonte and BONTE games where each level asks for a specific ball, built by dragging it across tools.","about":"Every stage in Factory Balls presents a target ball that has to be matched. The player moves a plain ball across the available tools, using them in the right sequence to build up the required appearance and properties. Working out which tools to apply, and in what order, is the core of each logic puzzle. The game was created by Bart Bonte together with BONTE games.","system":"Flash","genre":"puzzle","categories":"puzzle|logic","core":"swf","width":640,"height":600},{"type":"flash","id":"feudalism-ii","slug":"feudalism-ii","title":"Feudalism II","description":"Feudalism II is a 2008 strategy action game by Vitaly Zaborov (BlackFox-of-ITMO) with medieval military battles and role-playing upgrades.","about":"Feudalism II is a single-player strategy action game from 2008, developed by Vitaly Zaborov (BlackFox-of-ITMO) as part of the Feudalism series. It blends medieval military combat with role-playing elements, including ninja themes and character upgrades.","system":"Flash","genre":"strategy","categories":"strategy|action","core":"swf","width":800,"height":600},{"type":"flash","id":"follow","slug":"follow","title":"Follow","description":"Follow is a 2011 puzzle adventure where a persistent bodyguard shadows the player during an attempt to find solitude.","about":"In this puzzle adventure from developer 01101101, the player values being alone, yet a bodyguard stays constantly nearby. The goal is to slip away from this unwanted companion and reclaim some quiet time. Escaping the bodyguard and enjoying peaceful moments drive the experience.","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":900,"height":180},{"type":"flash","id":"papas-pancakeria","slug":"papas-pancakeria","title":"Papa’s Pancakeria","description":"Papa's Pancakeria is a 2012 time-management simulation from Flipline Studios where players run a breakfast restaurant on Maple Mountain.","about":"A call from Papa Louie leads the player to Maple Mountain, where a pet has been left at Papa Louie's newest restaurant. While the owner is away, the player keeps the shop running, serving pancakes, waffles and french toast to a mix of familiar and new diners. Tasks include stacking orders, placing toppings and pouring syrup, all handled with the mouse. Badges, closers and furniture return, and each day ends with a mini-game hosted by the Great Foodini.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"planet-racer","slug":"planet-racer","title":"Planet Racer","system":"Flash","genre":"racing","categories":"racing","core":"swf","width":550,"height":400},{"type":"flash","id":"qwop","slug":"qwop","title":"QWOP","description":"QWOP, Bennett Foddy's 2008 sports arcade game, challenges players to sprint 100 meters using four keyboard keys.","about":"QWOP is a sports game from 2008 by Bennett Foddy. The player controls a runner's four limbs with the Q, W, O and P keys, attempting to move as quickly as possible along a 100 meter track. Its awkward, difficult control scheme has made it a popular subject for comics, speedruns, parody videos and television appearances.","system":"Flash","genre":"sports","categories":"sports|arcade","core":"swf","width":640,"height":400},{"type":"flash","id":"scary-maze-game","slug":"scary-maze-game","title":"Scary Maze Game","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":550,"height":400},{"type":"flash","id":"wonderputt","slug":"wonderputt","title":"Wonderputt","description":"Wonderputt is a 2011 sports game from Damp Gnat that mixes mini golf with cows, toads, ski slopes and more.","about":"Wonderputt is an adventure golf game released in 2011 by Damp Gnat. It sets putting across a course populated with unusual elements, including cows, toads, ski slopes, torpedoes and a touch of alien abduction. The result is a sports game that plays like mini golf but keeps introducing odd sights along the way.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":750,"height":650},{"type":"flash","id":"cargo-bridge","slug":"cargo-bridge","title":"Cargo Bridge","description":"Cargo Bridge is a 2009 puzzle game by Limex Games where players construct bridges so workers can haul cargo across a valley.","about":"In Cargo Bridge, the task on each level is to span a valley with a bridge so workers can reach cargo on the far side and carry it back. Every level comes with a budget limit, so planning the structure carefully matters as much as building it. The result is a construction challenge that puts a player's engineering sense to the test.","system":"Flash","genre":"puzzle","categories":"puzzle|creative","core":"swf","width":800,"height":550},{"type":"flash","id":"connect-the-world","slug":"connect-the-world","title":"Connect the World","description":"Connect the World is a 2003 educational matching game from WGBH and PBS, built around Arthur and a geography theme.","about":"Connect the World is an educational matching game from WGBH and PBS, released in 2003. Players work through card-matching play with a geography theme, set in the world of Arthur, as a single player.","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":550,"height":325},{"type":"flash","id":"fireys-candy-bar-adventure","slug":"fireys-candy-bar-adventure","title":"Firey’s Candy Bar Adventure","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"mario-combat-deluxe","slug":"mario-combat-deluxe","title":"Mario Combat Deluxe","description":"Mario Combat Deluxe is a 2009 action platformer by Sun-Studios where players battle through stages toward a castle and a final clash with Bowser.","about":"Players move through a sequence of stages, defeating enemies along the way, and each stage ends at a small castle that serves as the exit. Dying halves the score and sends the player back to try the stage again. Bowser waits at the end as the last opponent, and he presents a serious challenge.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":800,"height":450},{"type":"flash","id":"micro-sports","slug":"micro-sports","title":"Micro Sports","description":"Micro Sports is a 2009 sports mini-game collection from Mousebreaker and Tom Vencel with 30 timed levels to clear.","about":"Each level in Micro Sports presents a sport-related mini-game that has to be finished before the clock runs out. There are 30 levels in total, and the challenge lies in clearing every one of them against the time limit. Mousebreaker and Tom Vencel developed the game in 2009.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":640,"height":480},{"type":"flash","id":"monkey-lander","slug":"monkey-lander","title":"Monkey Lander","description":"Monkey Lander is a 2002 arcade game from Totebo and Niclas Åberg about gathering bananas and touching down safely.","about":"In Monkey Lander, the player has to pick up every banana in the level and then guide the craft down onto a platform. Fuel is limited, so the whole task has to be finished before it runs out. Landing safely is the last step once the bananas are collected.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":750,"height":400},{"type":"flash","id":"no-walking-no-problem","slug":"no-walking-no-problem","title":"No Walking, No Problem!","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":500},{"type":"flash","id":"papa-louie-2-when-burgers-attack","slug":"papa-louie-2-when-burgers-attack","title":"Papa Louie 2: When Burgers Attack!","description":"Papa Louie 2: When Burgers Attack! is a 2013 action arcade platformer from Flipline Studios about rescuing a kidnapped chef.","about":"Marty and Rita are working at the Burgeria when a portal opens and monstrous food creatures seize Papa Louie and the customers. The two set out through the Land of Munchmore, running, jumping and battling hostile snacks to bring everyone home. Every customer rescued joins the team as a playable character with a distinct weapon, and certain ones possess abilities that open new routes, allow further rescues and yield Warp Keys.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":700,"height":416},{"type":"flash","id":"quest-for-bacon","slug":"quest-for-bacon","title":"Quest For Bacon","description":"Quest For Bacon is a 2006 adventure game from Edd Gould and Eddsworld where players gather as much bacon as they can.","about":"In Quest For Bacon, the goal is to collect as much bacon as possible. A solo mode gives the player 60 seconds to gather it. A two-player mode lets two people compete against each other for the bacon. The game was developed by Edd Gould and Eddsworld.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":600},{"type":"flash","id":"regular-show-all-nighter","slug":"regular-show-all-nighter","title":"Regular Show: All-Nighter","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":600},{"type":"flash","id":"shift-4","slug":"shift-4","title":"SHIFT 4","description":"SHIFT 4 is a 2009 puzzle platformer from Armor Games and Antony Lavelle, continuing the series with new brain-teasing episodes.","about":"This puzzle platformer returns with a set of episodes and levels built around the series' shifting mechanic. Players work through each stage, using the ability to flip the world and navigate the challenges that follow. The levels are designed to make players think while keeping the experience engaging.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":500,"height":560},{"type":"flash","id":"smash-palace","slug":"smash-palace","title":"Smash Palace","description":"Smash Palace is a top-down action driving game from BulletProof Arcade, released in 2013 for a single player.","about":"Smash Palace is a single-player action game with a top-down view and pre-rendered 3D visuals. The focus is on driving and upgrading your vehicle.","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":600},{"type":"flash","id":"tanks","slug":"tanks","title":"Tanks","description":"Tanks is a 2004 turn-based artillery action game where players aim shots, battle AI or friends, and upgrade their tank.","about":"In Tanks, players take turns firing explosive shells at opponents, adjusting angle and power to hit the enemy or destroy the terrain. Matches can be played against computer-controlled opponents of varying difficulty or against friends in a duel. Victory earns money that can be spent on tank upgrades or additional items. The game is controlled entirely with the keyboard, using arrow keys to move and aim, Q and E to cycle items, and the space bar to fire.","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":400},{"type":"flash","id":"the-scale-of-the-universe-2","slug":"the-scale-of-the-universe-2","title":"The Scale of the Universe 2","description":"The Scale of the Universe 2 is a 2012 educational interactive by Cary Huang and Michael Huang that explores sizes from the very small to the very large.","about":"The Scale of the Universe 2 is an educational interactive from Cary Huang and Michael Huang. It presents a range of sizes, letting the player move between the extremely small and the extremely large. The experience is built as a single continuous scale rather than a set of separate levels or challenges. Loading can take some time, and the presentation may appear blank before it finishes.","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":960,"height":540},{"type":"flash","id":"zoo-keeper","slug":"zoo-keeper","title":"Zoo Keeper","description":"Zoo Keeper is a 2002 pixel-style match-3 puzzle game from Flash Fabrica and Robot, played solo on a fixed screen with mouse controls.","about":"This single-player puzzle game from Flash Fabrica and Robot challenges players to line up matching pieces on a fixed pixel-art board using only the mouse. It is built around score-attack play, so the aim is to rack up as high a score as possible through steady matching.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":350,"height":360},{"type":"flash","id":"billiards","slug":"billiards","title":"Billiards","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":800,"height":600},{"type":"flash","id":"elona-shooter","slug":"elona-shooter","title":"Elona Shooter","description":"Elona Shooter is a 2009 action shooter with RPG elements, offering eight playable classes and weapon customization.","about":"Elona Shooter mixes chaotic shooting with role-playing progression. Players pick one of eight classes, learn new skills, and modify their weapons as they go. Building up a troop of fighters is also part of the experience, and the goal is to stay alive.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":620,"height":380},{"type":"flash","id":"get-to-the-top-althrough-there-is-no-top-bfdi","slug":"get-to-the-top-althrough-there-is-no-top-bfdi","title":"Get to the Top Althrough There is No Top BFDI","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":550,"height":560},{"type":"flash","id":"jojos-a-circus-town-wedding","slug":"jojos-a-circus-town-wedding","title":"Jojo’s A Circus Town Wedding","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":480,"height":360},{"type":"flash","id":"scooby-doo-scooby-trap","slug":"scooby-doo-scooby-trap","title":"Scooby-Doo: Scooby Trap","description":"Scooby-Doo: Scooby Trap is a 2003 platformer from Cartoon Network in which Scooby navigates a series of tricks and traps.","about":"Scooby-Doo: Scooby Trap is a single-player platformer released by Cartoon Network in 2003. The player guides Scooby through a trail filled with tricks and traps. Along the way, Scooby hunts down some of his most fearsome foes.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":432,"height":330},{"type":"flash","id":"the-south-park-timmy-game","slug":"the-south-park-timmy-game","title":"The South Park Timmy Game","description":"The South Park Timmy Game is a 2001 action game from Comedy Central where Timmy navigates obstacles and gathers items.","about":"Players guide Timmy through each level, steering him around obstacles and picking up items that add bonus points. Timmy's special moves are triggered with a two-step action meter, and he can be moved using the arrow keys or by dragging the mouse over his wheelchair controller. When Mr. Garrison, Mr. Mackey, or Principal Victoria show up, Timmy becomes nervous and his controls reverse. Clues collected along the way help uncover who took Gobbles.","system":"Flash","genre":"action","categories":"action","core":"swf","width":470,"height":340},{"type":"flash","id":"abobos-big-adventure","slug":"abobos-big-adventure","title":"Abobo’s Big Adventure","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":256,"height":254},{"type":"flash","id":"adventure-time-princess-maker","slug":"adventure-time-princess-maker","title":"Adventure Time Princess Maker","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":750,"height":550},{"type":"flash","id":"edgy-wedgy-2","slug":"edgy-wedgy-2","title":"Edgy Wedgy 2","description":"Edgy Wedgy 2 is a 2000 arcade game from Teletoon, built for single-player sessions and part of the Edgy Wedgy series.","about":"Edgy Wedgy 2 is an arcade title released in 2000 by Teletoon. It is a single-player game and continues the Edgy Wedgy series.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"elevators-logic","slug":"elevators-logic","title":"Elevators Logic","description":"Elevators Logic is a 2001 single-player puzzle game from Plastelina Games built around logic challenges.","about":"Elevators Logic is a single-player puzzle game from Plastelina Games, released in 2001 as part of the Plastelina Logic Games series. Play centers on logic-based puzzling.","system":"Flash","genre":"puzzle","categories":"puzzle|logic","core":"swf","width":450,"height":300},{"type":"flash","id":"factory-balls-2","slug":"factory-balls-2","title":"Factory Balls 2","description":"Factory Balls 2 is a 2008 puzzle game from BONTE games and Bart Bonte where balls are dragged over tools to match each level's target.","about":"In Factory Balls 2, a ball is dragged over an assortment of tools to create the specific ball required by each level. The game builds on its predecessor with additional levels, more tools, and more balls to work with, along with a recycle bin. Working out the right combination of tools is the core of the logic puzzle.","system":"Flash","genre":"puzzle","categories":"puzzle|logic","core":"swf","width":640,"height":600},{"type":"flash","id":"fear-unlimited","slug":"fear-unlimited","title":"Fear Unlimited","description":"Fear Unlimited is a 2005 action game from Dizimz in which players control Encon, a demon slayer armed with swords and guns.","about":"Encon is an otherworldly demon slayer, and players take control of him as he fights with both swords and guns. The game spans seventeen missions, with the first few featuring a puppet rather than the character Urami. A sequel, Fear Unlimited 2 Kingdom Of Hell, was later made as a prequel to the original.","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":475},{"type":"flash","id":"grid","slug":"grid","title":"Grid","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":350},{"type":"flash","id":"indestructotank","slug":"indestructotank","title":"IndestructoTank!","description":"IndestructoTank! is a 2007 arcade action game from Antony Lavelle and The-EXP in which a tank takes on enemies.","about":"IndestructoTank! is an arcade action game released in 2007 by Antony Lavelle and The-EXP. The game centers on a tank, and a sequel, Indestruc2Tank, followed it. The original title was made by Antony Lavelle Industries and Joel Atkinson inc.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":600,"height":500},{"type":"flash","id":"minecraft-tower-defence","slug":"minecraft-tower-defence","title":"Minecraft Tower Defence","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":480},{"type":"flash","id":"papas-wingeria","slug":"papas-wingeria","title":"Papa’s Wingeria","description":"Papa's Wingeria is a 2012 simulation game from Flipline Studios where players run a busy wing restaurant.","about":"In Papa's Wingeria, the player takes charge of a restaurant in Starlight City after winning it through a prize machine. The job involves taking orders from customers, operating deep fryers, coating wings in sauce, and plating them with garnishes and sides. A new feature for the series lets players design their own worker, choosing details such as skin tone, height, facial features, posture, and hairstyle.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"raze-3","slug":"raze-3","title":"Raze 3","description":"Raze 3 is a 2014 action shooter from Sky9 Games that picks up the story where Raze 2 ended.","about":"Raze 3 continues the story from Raze 2, with the fight to save mankind carrying on against aliens, robots, and zombies. Players arm themselves with weapons, equipment, and abilities as they take on these enemies. The game is a shooter in the action genre, released in 2014 by Sky9 Games.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":600},{"type":"flash","id":"red-remover","slug":"red-remover","title":"Red Remover","description":"Red Remover is a 2009 logic puzzle by Gaz Thomas where red shapes must be cleared while keeping green ones on screen.","about":"The aim in Red Remover is to clear every red shape from each stage while making sure the green shapes stay on the screen. Early levels are straightforward, but from level ten onward gravity behaves in ways that change how the puzzles need to be solved. A walkthrough link is included for anyone who gets stuck, sound effects can be switched off through the right-click menu, and a level editor lets players build their own stages.","system":"Flash","genre":"puzzle","categories":"puzzle|logic","core":"swf","width":640,"height":480},{"type":"flash","id":"serious-santa","slug":"serious-santa","title":"Serious Santa","description":"Serious Santa is a 2006 arcade shooter by Josh Tuttle where Santa battles goblins across the north pole with a small weapons arsenal.","about":"In this shooter, the player guides Santa across a north pole overrun by goblins. A small set of weapons is available to clear out the enemies. Levels can be destroyed, and the game hides a number of secrets and easter eggs for players to discover.","system":"Flash","genre":"shooter","categories":"shooter|arcade","core":"swf","width":600,"height":360},{"type":"flash","id":"shanghai-dynasty","slug":"shanghai-dynasty","title":"Shanghai Dynasty","description":"Shanghai Dynasty is a 2010 simulation game in which players clear the board by pairing matching tiles from the top.","about":"Shanghai Dynasty is a tile-matching game built around a simple rule: two corresponding tiles are paired up and removed from the top. Play continues as the board is cleared this way. The game is listed under the simulation category and dates to 2010.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":636,"height":475},{"type":"flash","id":"tails-nightmare","slug":"tails-nightmare","title":"Tails’ Nightmare","description":"Tails' Nightmare is a 2008 Halloween-themed platformer by TheBlox in which Tails navigates a haunted dream world.","about":"In this platformer from 2008, the player controls Tails through a haunted dream setting. TheBlox built it as a gameplay demonstration for the Cosmic Rush 2.0 engine, giving the project a Halloween theme. The developer notes that a random freezing bug can occur and force a restart, and that other glitches may also be present.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":550,"height":400},{"type":"flash","id":"the-amazing-world-of-gumball-water-sons","slug":"the-amazing-world-of-gumball-water-sons","title":"The Amazing World of Gumball: Water Sons","description":"The Amazing World of Gumball: Water Sons is a 2014 Cartoon Network artillery puzzle game played from a side view.","about":"The Amazing World of Gumball: Water Sons is a side-view artillery puzzle game from Cartoon Network, released in 2014 and based on the animated series. A single player takes on action-oriented challenges that mix aiming and puzzle solving in a cartoon setting.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":640,"height":520},{"type":"flash","id":"themehotel","slug":"themehotel","title":"Theme Hotel","description":"Theme Hotel is a 2011 simulation game from Toffee Games where players construct and develop a hotel from the ground up.","about":"Theme Hotel is a simulation game from Toffee Games, released in 2011. The player constructs and develops a hotel, starting from nothing and working toward a highrise superior resort. Success is measured by how crowded the hotel becomes with happy guests.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":700,"height":500},{"type":"flash","id":"totem-destroyer","slug":"totem-destroyer","title":"Totem Destroyer","description":"Totem Destroyer is a physics puzzle game where players topple totems while keeping a golden idol from hitting the ground.","about":"In Totem Destroyer, the goal is to bring down each totem without letting the golden idol, called Tot, touch the ground. Players use balance to hold Tot up as they work through 25 levels. The game is presented by Armor Games and made by GABS.TV.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":420},{"type":"flash","id":"vintage-game-shop","slug":"vintage-game-shop","title":"Vintage Game Shop","system":"Flash","genre":"strategy","categories":"strategy|simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"8-ball-pool","slug":"8-ball-pool","title":"8 Ball Pool","description":"8 Ball Pool is a 2007 sports game from AR – FGJ where players take on a computer opponent in a top-down game of pool.","about":"This top-down simulator puts the player in a match of 8 ball against a computer-controlled rival. The aim is to line up the white ball and set the power of the shot, potting balls of one's own color. The computer opponent plays smartly, so the race is on to clear the assigned balls before it sinks its own.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":575,"height":435},{"type":"flash","id":"antbuster","slug":"antbuster","title":"Antbuster","description":"Antbuster is a strategy game where ants raid a picnic for cake, and players place cannons to defend the food.","about":"Ants have discovered a picnic and are after the cake. The player defends the food by placing cannons around the field to stop the ants. Cannons can be evolved, which increases their fire power. The challenge is to see how long the defense can hold out.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":500,"height":500},{"type":"flash","id":"armed-with-wings-3","slug":"armed-with-wings-3","title":"Armed with Wings 3","description":"Armed with Wings 3 is a 2010 single-player action game from Sun-Studios, a silhouette-style beat 'em up with a samurai theme.","about":"Armed with Wings 3 is a single-player action game in which the player fights through combat encounters as a samurai. The visuals use a silhouette art style, and the game is part of the Armed with Wings series from developer Sun-Studios, released in 2010.","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":450},{"type":"flash","id":"bloons-tower-defense","slug":"bloons-tower-defense","title":"Bloons Tower Defense","description":"Bloons Tower Defense is a 2007 strategy game from Ninja Kiwi where towers are built and upgraded to stop bloons escaping a maze.","about":"In this top-down tower defense game, the goal is to keep bloons from getting out of a maze. Players build and upgrade towers that pop the bloons, choosing from towers that throw darts, tacks, bombs, and ice. The game spans 50 levels.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":480},{"type":"flash","id":"bloons-tower-defense-2","slug":"bloons-tower-defense-2","title":"Bloons Tower Defense 2","description":"Bloons Tower Defense 2 is a 2008 strategy game from Ninja Kiwi where players build towers to stop balloons from crossing the map.","about":"Bloons Tower Defense 2 expands on the original with three new maps rated easy, medium and hard. A new tower type and additional upgrades give players more ways to plan their defenses. Monkey glue and road spikes can be placed directly on the track, and two new bloon types add to the challenge. The goal is to survive all 50 levels.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":480},{"type":"flash","id":"fireboy-and-watergirl-dark-temple","slug":"fireboy-and-watergirl-dark-temple","title":"Fireboy and Watergirl – Dark Temple","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":728,"height":480},{"type":"flash","id":"fleabag-vs-mutt","slug":"fleabag-vs-mutt","title":"Fleabag vs. Mutt","description":"Fleabag vs. Mutt is a 2000 cartoon artillery action game from Gametuner, pitting cat against dog in a side-view duel.","about":"Fleabag vs. Mutt is a cartoon artillery action game from Gametuner, released in 2000. It sets a cat and a dog against each other in side-view combat, and can be played alone or with another person.","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":430},{"type":"flash","id":"gun-mayhem","slug":"gun-mayhem","title":"Gun Mayhem","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":900,"height":600},{"type":"flash","id":"gun-mayhem-redux","slug":"gun-mayhem-redux","title":"Gun Mayhem Redux","description":"Gun Mayhem Redux is a 2014 side-view shooter from Kevin Gu, part of the Gun Mayhem series, with single-player, co-op and multiplayer modes.","about":"Gun Mayhem Redux is a side-view shooter in the Gun Mayhem series, developed by Kevin Gu in 2014. It offers single-player, cooperative and multiplayer play, along with customization options and cartoon action with mild violence.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":1000,"height":560},{"type":"flash","id":"league-bowling","slug":"league-bowling","title":"League Bowling","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":620,"height":450},{"type":"flash","id":"nick-jr-phone","slug":"nick-jr-phone","title":"Nick Jr. Phone","description":"Nick Jr. Phone lets players call Dora, Boots, and Blue, pressing buttons to hear what each character says in this creative game.","about":"Players pick up the phone to get in touch with their Nick Jr. pals. A row of buttons is there to click, and each one connects to a different character. Dora, Boots, and Blue each have something to say once their button is pressed. The simple setup centers on hearing the responses from the three friends.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":475,"height":285},{"type":"flash","id":"papas-burgeria","slug":"papas-burgeria","title":"Papa’s Burgeria","description":"Papa's Burgeria is a 2010 simulation game from Flipline Studios where players cook and stack burgers for demanding customers.","about":"In this sequel to Papa's Pizzeria, players take the role of Marty or Rita and must cook, build, and serve burgers to order for a demanding clientele. Success comes from managing time and working up the ranks to become a skilled burger flipper. A new Upgrade Shop lets players purchase furniture, posters, and tools to improve their burger-making setup.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"redball3","slug":"redball3","title":"Redball 3","description":"Redball 3 is a platformer where a bouncy ball rolls and jumps its way through each level.","about":"Redball 3 is a platformer built around a bouncy ball. The player guides this ball through the game's levels, using its bouncing motion to move around. It is a simple concept that focuses on rolling and rebounding as the main way to get through each stage.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":630,"height":420},{"type":"flash","id":"ricochet-kills","slug":"ricochet-kills","title":"Ricochet Kills","description":"Ricochet Kills is a 2009 puzzle shooter from Mikhail Bakanov and Alexey Semyonov where a well-aimed shot clears every enemy.","about":"Ricochet Kills is a shooter built around puzzle solving. The player has to eliminate all of the enemies, and the goal is reached by taking the correct shot. The 2009 game comes from developers Mikhail Bakanov (mibix) and Alexey Semyonov.","system":"Flash","genre":"shooter","categories":"shooter|puzzle|arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"sift-heads-world-act-1","slug":"sift-heads-world-act-1","title":"Sift Heads World: Act 1","description":"Sift Heads World: Act 1 is a 2010 stick-figure shooter from PopBrain in which Vinnie, Shorty and Kiro take on the Italian Mafia.","about":"Vinnie now works alongside Kiro and Shorty, and the three assassins set out to stop the Italian Mafia from returning to power. Players can switch between the three characters and travel through two large cities. The game offers fourteen weapons, ten main missions and ten secondary missions, plus character upgrades and fast cars. A Bounty Hunter account keeps items and stats across episodes.","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":800,"height":440},{"type":"flash","id":"spank-the-monkey","slug":"spank-the-monkey","title":"Spank The Monkey","description":"Spank The Monkey is a 2002 single-player action toy from developer H 69, built around mouse-only score-attack play.","about":"Spank The Monkey is a single-player action toy from developer H 69, released in 2002. It uses mouse-only controls and pre-rendered 3D visuals in a score-attack format centered on a primate.","system":"Flash","genre":"action","categories":"action","core":"swf","width":850,"height":400},{"type":"flash","id":"stick-cricket","slug":"stick-cricket","title":"Stick Cricket","description":"Stick Cricket, a 2003 single-player sports game from Mousebreaker and Colin Rowe, puts players in charge of a cricket side chasing victory.","about":"Stick Cricket is a single-player cricket game first released in 2003 by Mousebreaker and Colin Rowe. The player takes charge of a team and works to lead it to victory. It stands out as one of the earliest cricket games to appear online, and it remains enjoyable to play years after its debut.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":640,"height":480},{"type":"flash","id":"story-of-the-blanks","slug":"story-of-the-blanks","title":"Story of the Blanks","description":"Story of the Blanks is a short adventure fan-game from 2011 by Donitz, built around genuine NES graphics and music.","about":"Story of the Blanks is a short creepypasta fan-game made in Adobe Flash by Donitz for a contest at Equestria Gaming. The game sticks to authentic NES graphics and hardware limits, including the restriction of eight sprites per line. Its soundtrack comes from several composers who used Famitracker, a NES tracker. It is a fan work and is not connected with Hasbro.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":512,"height":480},{"type":"flash","id":"tank-trouble","slug":"tank-trouble","title":"Tank Trouble","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":712,"height":490},{"type":"flash","id":"the-worlds-hardest-game","slug":"the-worlds-hardest-game","title":"The World’s Hardest Game","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"thing-thing-arena","slug":"thing-thing-arena","title":"Thing-Thing Arena","description":"Thing-Thing Arena is a 2006 single-player shooter from Diseased Productions and Sean McGee, built around frantic gun battles and worldwide high scores.","about":"Thing-Thing Arena is a single-player action shooter released in 2006 by Diseased Productions and Sean McGee. Players fight through intense gun battles across several modes of play, each with its own online scoreboard to climb. The game introduces a new set of weapons and was designed as an expanded take on the survival mode from Thing-Thing 2. It is a spin-off rather than a numbered sequel.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":700,"height":400},{"type":"flash","id":"arachnophilia","slug":"arachnophilia","title":"Arachnophilia","description":"Arachnophilia is a 2008 arcade game from Littlegrey Media and Teale Fristoe in which a hungry spider spins webs to trap bugs.","about":"Players take control of a spider that needs to eat. The spider builds webbing in order to catch bugs, and the trapped insects then become its meal. Littlegrey Media and Teale Fristoe released the arcade game in 2008.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"armed-with-wings-culmination","slug":"armed-with-wings-culmination","title":"Armed with Wings: Culmination","description":"Armed with Wings: Culmination is a 2011 action platformer from Sun-Studios with 15 levels, 20 medals, and multiple difficulty settings.","about":"A fallen hero, provoked into rage by his King, sets out on a final journey to meet the destiny he believes is his. The player guides him across 15 levels, defeating many kinds of enemies along the way. The game offers several difficulty settings and 20 medals to earn, and its combat system carries deeper mechanics for players who want them. An automatic leveling system lets those with less time still see the whole game.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":800,"height":480},{"type":"flash","id":"crimson-room","slug":"crimson-room","title":"Crimson Room","description":"Crimson Room is a 2004 escape-the-room adventure by Toshimitsu Takagi, played with the mouse alone.","about":"Crimson Room is a single-player escape-the-room adventure from 2004, created by Toshimitsu Takagi. The game uses pre-rendered 3D scenes and mouse-only controls as the player works to get out of the room. It is the first entry in the Crimson Room series.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":480,"height":330},{"type":"flash","id":"me-and-the-key","slug":"me-and-the-key","title":"Me and the Key","description":"Me and the Key is a 2009 point-and-click puzzle game by Bart Bonte in which each level challenges players to obtain a key.","about":"Me and the Key is a point-and-click puzzle game from developer Bart Bonte. In every level, the goal is to get the key, using actions such as pointing, clicking, dragging and dropping. Thinking through each screen is part of the challenge.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":600},{"type":"flash","id":"mecha-arena","slug":"mecha-arena","title":"Mecha Arena","description":"Mecha Arena is a 2012 action game from Little Giant World where players build and upgrade a combat robot.","about":"In Mecha Arena, players put together a combat robot of their own, then keep it upgraded and in working order. The robot is entered into tournaments and other matches against opposing mechas, some arranged at random. Beyond the fighting, the game covers running a mecha garage: the rider's abilities can be trained, and staff can be brought on board.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"multishop-tycoon","slug":"multishop-tycoon","title":"Multishop Tycoon","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":720,"height":480},{"type":"flash","id":"neon-rider","slug":"neon-rider","title":"Neon Rider","description":"Neon Rider is a 2010 reflex driving game by Louis-Simon Ménard where players race a bike through a cyber world and match colors to stay on track.","about":"Neon Rider is a fast reflex driving game set in a cyber world. The goal is to complete each track as quickly as possible while performing flips and collecting bonus points. Riders must change the bike's color to match the lines they drive on, though blue lines are always safe to stand on. A minimap helps plan the route, and the heads-up display reminds players of the color controls.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":780,"height":540},{"type":"flash","id":"outdoor-basketball","slug":"outdoor-basketball","title":"Outdoor Basketball","description":"Outdoor Basketball is a 2014 sports game from Bit of Games where players pick a mode and try to score as many points as possible.","about":"Outdoor Basketball is a sports game released in 2014 by Bit of Games. Players choose between a time trial mode and a challenge mode, then work on scoring as many points as they can. The two modes give the game its structure, with each session built around putting up a strong scoring total.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":640,"height":480},{"type":"flash","id":"potty-racers-ii","slug":"potty-racers-ii","title":"Potty Racers II","description":"Potty Racers II is a 2010 arcade launch game from Gonzo Games where players send a porta-potty through the air on a new island.","about":"Potty Racers II continues the series with a second, newly unlocked island to explore. Players steer and balance a porta-potty, power its engine, adjust the wheels, and perform tricks, earning score along the way. Upgrades can be bought to improve the ride. The humor is crude and the tone is silly throughout.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":400},{"type":"flash","id":"shark-lifting","slug":"shark-lifting","title":"Shark Lifting","description":"Shark Lifting is a 2014 arcade game from Felix Wiesner and Mausland Entertainment about hoisting a shark.","about":"Shark Lifting is an arcade game built around the unusual task of lifting a shark. Players work through five levels, and finishing all of them earns the cup and the chance to submit a score. It was made by Felix Wiesner (Wiesi) and Mausland Entertainment in 2014.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":480,"height":720},{"type":"flash","id":"space-invaders","slug":"space-invaders","title":"Space Invaders","description":"Space Invaders is a 2003 arcade game from Smashing Arcade that brings the classic alien-shooting action to the browser.","about":"Space Invaders is an arcade game from 2003, developed by Smashing Arcade. It follows the classic formula of the original arcade hit, with players defending against waves of invading aliens. The game was built with JavaScript, allowing it to run directly in a web browser.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":500,"height":410},{"type":"flash","id":"sugar-sugar-2","slug":"sugar-sugar-2","title":"Sugar, Sugar 2","description":"Sugar, Sugar 2 is a 2012 puzzle game by Bart Bonte where players draw lines to guide falling sugar into cups.","about":"Sugar, Sugar 2 is a puzzle game from Bart Bonte in which the goal is to get enough sugar into the cups. Players draw lines to direct the falling sugar, and steeper lines make it drop faster. The game has 30 levels to complete, and finishing them unlocks a bonus freeplay mode.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":800,"height":600},{"type":"flash","id":"territory-war","slug":"territory-war","title":"Territory War","description":"Territory War is a 2006 strategy shooter from Shawn Tanner and Afro-Ninja Productions with mission, challenge and custom battle modes.","about":"Territory War offers three ways to play: mission mode, challenge mode, and custom battle mode. Matches can be set up against either a computer-controlled opponent or another person. Winning unlocks new stages, missions, and hats, and the game keeps a record of statistics such as kills, head shots, and accuracy.","system":"Flash","genre":"strategy","categories":"strategy|shooter","core":"swf","width":650,"height":500},{"type":"flash","id":"the-gummibar-game","slug":"the-gummibar-game","title":"The Gummibär Game","description":"The Gummibär Game is a jump-and-run arcade platformer starring the gummy bear, with five levels that grow harder as you go.","about":"Gummibär, the gummy bear, headlines this jump and run arcade platformer. Players work through five levels, each one more difficult than the last. Reaching the high score board is the goal. The game sets itself apart with its gummy bear star and its steadily rising challenge.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"1066","slug":"1066","title":"1066","description":"1066 is a 2010 strategy game from Preloaded where players command English, Viking or Norman armies in battle.","about":"Players take charge of English, Viking or Norman forces in this 2010 strategy title from Preloaded. Victory comes from eliminating or routing the opposing army, with direct control over archery, cavalry charges and defensive stands. Orders are issued and then executed in a battle view, where mini-games decide the round's outcome. Morale is central: taunts, chants and a strong leader help keep troops steady while undermining the enemy. A multiplayer option allows matches against friends.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":700,"height":600},{"type":"flash","id":"clear-vision","slug":"clear-vision","title":"Clear Vision","description":"Clear Vision is a 2007 action sniper game by Daani where a stick-figure hitman takes on assassination jobs and confronts his past.","about":"Clear Vision is a stick-figure sniper game from 2007 by Daani. Players take the role of a hired assassin, using basic sniper mechanics to carry out hits and build a kill count. Between jobs, the game reveals the troubled history of its main character, a man who has lived a hard life. The story mixes dark themes with a look at his apartment and the people around him, offering a narrative-driven take on the stick shooter genre.","system":"Flash","genre":"action","categories":"action","core":"swf","width":650,"height":325},{"type":"flash","id":"cyclomaniacs","slug":"cyclomaniacs","title":"Cyclomaniacs","description":"Cyclomaniacs is a 2009 sports racing game from LongAnimals where players steer a bike and hop over obstacles.","about":"Cyclomaniacs is a racing game built around bicycle control. Players steer their bike with the arrow keys or WASD, and can bunny hop with X or the space bar. A horn can be used if the rider has one. The 2009 title comes from developer LongAnimals.","system":"Flash","genre":"sports","categories":"sports|racing","core":"swf","width":640,"height":480},{"type":"flash","id":"epic-rail","slug":"epic-rail","title":"Epic Rail","description":"Epic Rail is a 2011 puzzle game by Scott Griffiths and Craig Yates where players direct trains to their stations by switching track junctions.","about":"Players take charge of train-track junctions, switching them so each train reaches the station it belongs to. The challenge comes from keeping the trains apart, since a collision ends the run. Every junction decision has to be timed and sequenced correctly to keep the network running.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":560,"height":400},{"type":"flash","id":"flash-strike","slug":"flash-strike","title":"Flash Strike","system":"Flash","genre":"shooter","categories":"shooter|arcade","core":"swf","width":650,"height":450},{"type":"flash","id":"flea-1-5","slug":"flea-1-5","title":"Flea 1.5","description":"Flea 1.5 is a 2009 arcade game from kChamp Games where a tiny flea hops through levels, collecting coins and dodging spikes.","about":"In this arcade game from kChamp Games, the player controls a tiny flea and moves it through many levels. Coins can be picked up along the way, while spikes must be avoided. It is a follow-up to the original Flea.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":450},{"type":"flash","id":"grand-theft-grotto","slug":"grand-theft-grotto","title":"Grand Theft Grotto","description":"Grand Theft Grotto is a 2008 arcade game from Presence Multimedia and Steve Rutherford where arrow keys guide a character to collect presents.","about":"Grand Theft Grotto is an arcade game in which the player moves around and gathers presents. The arrow keys control movement. The game was released in 2008 by Presence Multimedia and Steve Rutherford.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":380},{"type":"flash","id":"heli-attack-2","slug":"heli-attack-2","title":"Heli Attack 2","description":"Heli Attack 2 is a 2003 action shooter from SquareCircleCo in which waves of helicopters attack and the goal is to bring down as many as possible.","about":"In this action shooter, helicopters arrive in waves and the player's task is to destroy as many of them as possible. Allied drops provide weapons and upgrades that can be collected during the fight. SquareCircleCo released the game in 2003.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":450,"height":320},{"type":"flash","id":"paladin-the-game","slug":"paladin-the-game","title":"Paladin: The Game","description":"Paladin: The Game is a 2007 adventure sidescroller from Jazza Studios and Biclops Games, starring Auron against zombies, skeletons, giants and gods.","about":"Players control Auron in a fast-paced sidescroller spread across nine acts, using spells and attack combos against zombies, skeletons, giants and gods. A levelling system, six bosses, unlockable cheats and special characters, plus animated sequences between acts, round out the adventure. Controls can be remapped, and progress saves automatically, including potions and levels, so a session can be left and resumed later. An in-game toolbox offers tips and settings without interrupting play.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":600,"height":400},{"type":"flash","id":"papas-scooperia","slug":"papas-scooperia","title":"Papa’s Scooperia","description":"Papa's Scooperia is a 2018 simulation game from Flipline Studios where players run an ice cream shop in Oniontown.","about":"After losing money and belongings on a trip to the big city, the player is stuck in Oniontown and takes over Papa Louie's new ice cream shop. The job involves baking fresh cookies for each sundae, adding hand-scooped ice cream in various flavors, and finishing with syrups, drizzles, shakers, and candies. Customers begin with simple orders of one cookie and one scoop, but as they are served, they level up and request larger sundaes. The game focuses on time management and cooking as orders grow and evolve.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"pico-vs-uberkids","slug":"pico-vs-uberkids","title":"Pico vs. Uberkids","description":"Pico vs. Uberkids is a 2000 adventure game from Tom Fulp in which Pico faces genetically engineered rivals in Rock Paper Scissors Roulette.","about":"Pico's school has gained new students: the Uberkids, who were created through genetic engineering. The question is whether they really excel at every single thing. Pico settles the matter by taking them on in a match of Rock Paper Scissors Roulette.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"red-moon","slug":"red-moon","title":"Red Moon","description":"Red Moon is a 2009 action game from Sun-Studios in which Eivana fights to overthrow the king across 20 levels and two boss battles.","about":"Every ten years the moon turns red, and the Red Samurai draw great power from it. In Red Moon, the player joins Eivana on a quest to overthrow the king. The journey spans 20 levels and includes two boss fights. Along the way, 13 medals can be unlocked, along with concept art and music.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":400},{"type":"flash","id":"sas-zombie-assault","slug":"sas-zombie-assault","title":"SAS: Zombie Assault","description":"SAS: Zombie Assault is a 2008 shooter from Ninja Kiwi where players hold out against wave after wave of undead attackers.","about":"In SAS: Zombie Assault, the goal is to stay alive as undead monsters attack in waves. Money earned during play goes toward improving both defenses and guns. Each level brings tougher waves of zombies to repel, and the challenge runs across twenty waves in total.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":480},{"type":"flash","id":"solipskier","slug":"solipskier","title":"Solipskier","description":"Solipskier is a 2010 arcade sports game where players paint snow to propel a skier through tricks and gates.","about":"In Solipskier, the player draws snow by holding down the left mouse button, creating slopes that the skier rides to build speed. Releasing the button while the skier is airborne triggers tricks. The goal is to reach a high score by passing through bonus gates while avoiding jump chasms and red gates. Green gates, when hit in the air, award a multiplier and a speed boost, and faster skiing leads to more points. The game also allows sharing scores with friends.","system":"Flash","genre":"sports","categories":"sports|arcade","core":"swf","width":768,"height":432},{"type":"flash","id":"stealth-hunter","slug":"stealth-hunter","title":"Stealth Hunter","description":"Stealth Hunter is a single-player action game from 2DPlay, played from an axonometric view with pre-rendered 3D visuals and a stealth theme.","about":"Stealth Hunter is a single-player action game from developer 2DPlay, part of the Stealth Hunter series. It presents its stealth-themed action from an axonometric perspective, with pre-rendered 3D visuals.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":400},{"type":"flash","id":"tower-blaster","slug":"tower-blaster","title":"Tower Blaster","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":400},{"type":"flash","id":"whip-the-worker","slug":"whip-the-worker","title":"Whip the Worker","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":400},{"type":"flash","id":"combat-instinct-3","slug":"combat-instinct-3","title":"Combat Instinct 3","description":"Combat Instinct 3 is a 2002 shooter by McFretN, offering the full game with enhanced audio and two hidden weapons.","about":"Combat Instinct 3 is a shooter released in 2002 by McFretN. The game was originally hosted on Flashstyle.org before moving to another site, where the full version became available with improved sound quality and a smaller file size. Two secret weapons were added to levels 2 and 3, described as extremely powerful and considered cheats. The game requires Flash 6 to play.","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":625,"height":325},{"type":"flash","id":"dolphin-olympics-2","slug":"dolphin-olympics-2","title":"Dolphin Olympics 2","description":"Dolphin Olympics 2 is a 2007 arcade game where players guide a dolphin through two minutes of swimming and tricks for points.","about":"In this arcade sequel from 2007, the player controls a dolphin and has two minutes to collect as many points as possible. Points come from swimming and performing flips, and successful jumps build up speed. That extra speed opens the way to larger and more impressive tricks. Compared with the first game, the developer has made the play smoother and added more tricks and more sights to see.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"dragon-boy-ii","slug":"dragon-boy-ii","title":"Dragon Boy II","description":"Dragon Boy II is a 2013 adventure game from Godlimations where a dragon is raised to fight alongside the player in battle.","about":"In this 2013 adventure title from Godlimations, the player raises a dragon that fights at their side. Movement uses the WASD or arrow keys, while the mouse aims attacks in a chosen direction. A second player can join using WASD to move and the J or K keys to attack, with number keys triggering skills. Menus cover inventory, a skill tree, the team party and options, and the game text appears in English, Spanish and Mandarin.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":600,"height":500},{"type":"flash","id":"feudalism-iii","slug":"feudalism-iii","title":"Feudalism III","description":"Feudalism III is a 2013 strategy and action game by Vitaly Zaborov where players command armies in a war between five factions.","about":"Five factions battle for control of a continent, each with its own strengths and weaknesses. The player chooses a side and works to capture the whole world. The game mixes strategy and action, with recruitable monsters, skills such as Venom Thorns and Killstreak, and ranged and melee combat that was rebalanced in later updates.","system":"Flash","genre":"strategy","categories":"strategy|action","core":"swf","width":800,"height":500},{"type":"flash","id":"flood-runner-4","slug":"flood-runner-4","title":"Flood Runner 4","description":"Flood Runner 4 is a 2012 arcade endless runner from Bryan Devlin where players run, jump and glide past obstacles.","about":"In this fourth entry in the series, the player runs, jumps and glides while avoiding obstacles. Experience earned through play feeds an automatic upgrade system with 30 levels, unlocking new abilities and creatures such as dragons and panthers as more levels open up. Controls can be reassigned from the main menu, where clicking the arrow keys image switches to mouse play, and clicking the character shows what each upgrade does and what every level increase brings.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":400},{"type":"flash","id":"shift-3","slug":"shift-3","title":"SHIFT 3","description":"SHIFT 3 is a 2008 puzzle platformer from Armor Games and Antony Lavelle, continuing the series with an adventure mode and classic levels.","about":"The third entry in the SHIFT series sends players into an Adventure mode that explores the origins of the SHIFT experiment. Along the way there are achievements to collect and a secret celebrity character to unlock. For those who prefer the older format, 18 Classic style levels created by Shift players from around the world are included, with highscore boards tracking results.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":500,"height":580},{"type":"flash","id":"splitter-splatter-spots","slug":"splitter-splatter-spots","title":"Splitter Splatter Spots","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":730,"height":390},{"type":"flash","id":"super-pinkie-world-2","slug":"super-pinkie-world-2","title":"Super Pinkie World 2","description":"Super Pinkie World 2 is a 2011 platformer from CertaintyPrinciple in which Pinkie hops through stages to find her missing friends.","about":"Pinkie sets out across side-scrolling stages to locate friends who have gone missing in several locations. Cupcakes can be gathered along the route, while parasprites must be dodged. The look of the stages draws on color schemes associated with Super Mario World, and the soundtrack is an 8-bit arrangement of \"At The Gala\". Movement uses A and D for left and right, with W to jump. A sequel to Super Pinkie World, it was developed by CertaintyPrinciple in 2011.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":550,"height":400},{"type":"flash","id":"the-legends-of-hiro","slug":"the-legends-of-hiro","title":"The Legends of Hiro","description":"The Legends of Hiro is a 2004 adventure game in which Hiro gathers items and speaks with characters on a quest to defeat a demon.","about":"The Legends of Hiro is an adventure game from 2004 by Visual Noize and Michael Vogt. The player takes the role of Hiro and sets out to save the world by locating the correct items, talking to the right people, and killing the bad demon. Progress depends on choosing whom to speak with and which objects to collect along the way.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"transylmania","slug":"transylmania","title":"Transylmania","description":"Transylmania is a 2005 arcade action game from Games Zeeks in which a castle's vampire lord turns invading villagers into the undead.","about":"Transylmania is an arcade action game released in 2005 by Games Zeeks. Invaders have entered your castle, and the goal is to clear every one of them out. Rather than driving them off directly, you convert the villagers into the walking dead. The task is not finished until the castle is emptied of all the intruders.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":704,"height":480},{"type":"flash","id":"bloons-super-monkey","slug":"bloons-super-monkey","title":"Bloons Super Monkey","description":"Bloons Super Monkey is a 2010 shooter from Ninja Kiwi where the Super Monkey pops balloons across 15 waves of action.","about":"Players guide the Super Monkey through a balloon-popping frenzy that spans 15 waves. The game mixes shooter action with the balloon-popping mechanic of the Bloons series, drawing inspiration from RaidenX-style play. Ninja Kiwi originally planned it as a small side project, but the level design grew intense and the result became much larger in scope.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":480},{"type":"flash","id":"fracuum","slug":"fracuum","title":"Fracuum","description":"Fracuum is a 2012 action game by Tyler Glaiel, created in 48 hours for Ludum Dare #23 around the theme Tiny World.","about":"Fracuum is an action game built by Tyler Glaiel in 48 hours for Ludum Dare #23, where the theme was Tiny World. The game grew out of that short development sprint and reflects the theme in its design. It was entered into the Ludum Dare competition, where players could vote on the results.","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":650},{"type":"flash","id":"gretel-hansel-2","slug":"gretel-hansel-2","title":"Gretel & Hansel 2","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":800,"height":600},{"type":"flash","id":"hedgehog-launch","slug":"hedgehog-launch","title":"Hedgehog Launch","description":"Hedgehog Launch is a 2008 arcade game by John Cooney where players fling a hedgehog to reach space as fast as possible.","about":"Players pull back on a launcher with the mouse and use the left and right keys to move, aiming to send the hedgehog higher and farther. Coins and platforms provide cash that can be spent on upgrades, which in turn allow longer and higher launches and bigger multipliers. The goal is to reach space, with the fling formula reworked to give more control and a minor objective. John Cooney (jmtb02) developed the game in 2008.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":550},{"type":"flash","id":"i-will-not-ever-never-eat-that-lunch","slug":"i-will-not-ever-never-eat-that-lunch","title":"I Will Not Ever Never Eat That Lunch","description":"I Will Not Ever Never Eat That Lunch is a 2005 Playhouse Disney adventure and visual novel game based on Charlie and Lola.","about":"Based on the Charlie and Lola series, this single-player title from Playhouse Disney blends adventure and visual novel elements with creative play. Players follow the story through its interactive scenes and take part in imaginative activities along the way.","system":"Flash","genre":"creative","categories":"creative|adventure","core":"swf","width":480,"height":360},{"type":"flash","id":"jellydad-hero","slug":"jellydad-hero","title":"Jellydad Hero","description":"Jellydad Hero is a 2014 side-view puzzle platformer from Andrey Kovalishin in which a slime creature works through single-player stages.","about":"Jellydad Hero is a side-view puzzle platformer released in 2014 by Andrey Kovalishin. The game is played solo and centers on a slime creature that the player guides through fixed-screen stages built around physics and puzzle solving.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":690,"height":460},{"type":"flash","id":"mega-boulder-rampage","slug":"mega-boulder-rampage","title":"Mega Boulder Rampage","description":"Mega Boulder Rampage is a 2013 arcade action game from Sun-Studios where players try to outrun volcanoes and survive nature's chaos.","about":"Volcanic and seismic activity has thrown the world into havoc, and stone and rock are falling from the sky. Mega Boulder Rampage is an arcade action game about trying to make it through this mayhem. Players attempt to outrun unforgiving volcanoes and survive the chaos unleashed by Mother Nature.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":800,"height":600},{"type":"flash","id":"monster-corp","slug":"monster-corp","title":"Monster Corp","description":"Monster Corp is a 2011 simulation game from Little Giant World in which players run a theme park stocked with creatures instead of ordinary zoo animals.","about":"The park in Monster Corp displays monsters rather than lions and elephants. Players search the world for new monster specimens to add to their collection. Running the business involves building and upgrading the park, hiring staff, and meeting monthly targets to keep it operating. Little Giant World developed the game in 2011.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"notebook-wars","slug":"notebook-wars","title":"Notebook Wars","description":"Notebook Wars is a 2010 side-scrolling shooter drawn entirely in notebook style, with upgradeable weapons and planes to unlock.","about":"Everything in Notebook Wars is drawn to look like it came from a notebook. Players take control of a plane and fight through 15 large levels filled with more than 30 enemy types and four final bosses. Eight weapons can be upgraded, and five planes are available to buy, each with three slots for equipping weapons. Fifteen hidden badges are scattered through the game for players to find.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":600,"height":600},{"type":"flash","id":"ragdoll-invaders","slug":"ragdoll-invaders","title":"Ragdoll Invaders","description":"Ragdoll Invaders is a 2007 arcade shooter from Rag Doll Software and Matteo Guarnieri with stick-figure ragdoll action.","about":"Ragdoll Invaders is a single-player arcade shooter released in 2007 by Rag Doll Software and Matteo Guarnieri. The game features stick-figure ragdoll characters in a shooter format.","system":"Flash","genre":"shooter","categories":"shooter|arcade","core":"swf","width":550,"height":500},{"type":"flash","id":"red-code","slug":"red-code","title":"Red Code","description":"Red Code is a 2008 side-view action shooter from PlayStival, built for single-player play.","about":"Red Code is a side-view shooter from developer PlayStival, released in 2008 as part of the Red Code series. The game focuses on action combat from a side-on perspective, with a single player controlling the shooting as it unfolds.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":480},{"type":"flash","id":"shop-empire-fable","slug":"shop-empire-fable","title":"Shop Empire Fable","description":"Shop Empire Fable is a 2016 pixel-art simulation game from Little Giant World about running shops in a fantasy kingdom.","about":"In Shop Empire Fable, the player takes charge of shops in a fantasy kingdom and tries to make them profitable. A bookstore and a clothing boutique are among the businesses that can be opened. Success depends on building a retail empire across the realm, with pixel art visuals setting the scene. The game was developed by Little Giant World.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":700,"height":500},{"type":"flash","id":"shop-empire-underground","slug":"shop-empire-underground","title":"Shop Empire Underground","description":"Shop Empire Underground is a 2016 simulation game from Little Giant World where players build shops and run a mall in a changed world.","about":"The world above has changed and so has human life, yet shopping remains. Players construct the shops they prefer and bring in staff to keep those stores running. Serving tamed zombies is part of managing the mall, and villains can wreck everything if left unchecked. The zombie town can also be expanded by launching a special rocket.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":700,"height":500},{"type":"flash","id":"shopping-cart-hero","slug":"shopping-cart-hero","title":"Shopping Cart Hero","description":"Shopping Cart Hero is a 2009 arcade game from MonkeyWantBanana about launching a shopping cart as far as possible.","about":"In Shopping Cart Hero, the goal is to jump a shopping cart and achieve greatness. The game comes from developer MonkeyWantBanana and was released in 2009 as an arcade title. It plays on the familiar urge to try something reckless with a shopping cart.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"sushi-cat","slug":"sushi-cat","title":"Sushi Cat","description":"Sushi Cat, a 2010 arcade game from Armor Games, tasks players with guiding a hungry cat toward as much sushi as possible.","about":"Sushi Cat is a lonely creature with a large appetite. The player guides him toward sushi, and he grows fatter with each piece he consumes along the way. Filling his belly is the goal that wins the game.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":650},{"type":"flash","id":"bubble-spinner","slug":"bubble-spinner","title":"Bubble Spinner","description":"Bubble Spinner, a puzzle game where players build the largest possible group of bubbles while avoiding red edges.","about":"Players control a large bubble with the mouse, catching smaller bubbles to form the biggest group possible. Touching the red edges ends the game, so movement must be careful. A left click applies the brake and slows the spin, while the spacebar releases several bubbles at once. A brake bar shows how much slowing power remains.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":500,"height":540},{"type":"flash","id":"cartoon-network-snowbrawl-fight","slug":"cartoon-network-snowbrawl-fight","title":"Cartoon Network: SnowBrawl Fight!","system":"Flash","genre":"action","categories":"action","core":"swf","width":960,"height":500},{"type":"flash","id":"coaster-racer","slug":"coaster-racer","title":"Coaster Racer","description":"Coaster Racer is a 2010 sports racing game from LongAnimals where sixteen rivals compete on roller coaster-style tracks.","about":"Sixteen opponents share the track in this racing game from LongAnimals, which came out in 2010. The courses are built like roller coasters rather than ordinary roads. One piece of advice passed along to new drivers suggests letting go of the wheel in dense traffic can earn extra points.","system":"Flash","genre":"sports","categories":"sports|racing","core":"swf","width":640,"height":480},{"type":"flash","id":"combat-instinct-2","slug":"combat-instinct-2","title":"Combat Instinct 2","description":"Combat Instinct 2 is a 2000 shooter from McFretN, continuing the series with a visual overhaul built to raise the framerate.","about":"Combat Instinct 2 continues the series that began with Combat Instinct 1. This follow-up from developer McFretN is a shooter, released in 2000. Its graphics were changed with the goal of increasing the framerate.","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":550,"height":400},{"type":"flash","id":"cyclomaniacs-epic","slug":"cyclomaniacs-epic","title":"Cyclomaniacs Epic","description":"Cyclomaniacs Epic is a 2013 racing game from Turbo Nuke, continuing the bike series inside a movie studio.","about":"Cyclomaniacs Epic brings the bike racing series back, this time with a movie studio as its setting. A megalomaniac Haddock dominates the studio, though the details of that rivalry are left unclear. The game comes from developer Turbo Nuke and continues the racing action of the earlier Cyclomaniacs title.","system":"Flash","genre":"racing","categories":"racing","core":"swf","width":750,"height":500},{"type":"flash","id":"double-wires","slug":"double-wires","title":"Double Wires","description":"Double Wires is a 2006 arcade physics game from JayIsGames and D_of_I where a stick figure swings through a side-view course using only the mouse.","about":"Double Wires is a side-view arcade game built around simple physics and mouse-only control. The player guides a stick figure through the course, and the focus is on chasing a high score in a single-player run.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"elf-snowball-fight","slug":"elf-snowball-fight","title":"Elf Snowball Fight!","description":"Elf Snowball Fight! is a 2003 promotional arcade shooting gallery from New Line Productions Inc, played solo with live-action visuals and voice acting.","about":"Elf Snowball Fight! is a single-player arcade shooting gallery with a Christmas theme, released in 2003 by New Line Productions Inc. It presents live-action footage with voice acting as part of a promotional tie-in.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":450},{"type":"flash","id":"endless-war-2","slug":"endless-war-2","title":"Endless War 2","description":"Endless War 2 is a 2006 shooter from developer Vitaly Zaborov, pitting players against waves of enemies with a varied arsenal.","about":"Endless War 2 is a shooter that sends the player into battle against large numbers of enemies. The arsenal includes a flamethrower and hand grenades, which bounce off walls. Players who find the game difficult can enable an old bullets option, use alternate attacks, or employ cheat codes carried over from the first Endless War. Medkits and armor are also available.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":660},{"type":"flash","id":"euro-headers-2004","slug":"euro-headers-2004","title":"Euro Headers 2004","description":"Euro Headers 2004 is a 2004 arcade sports game where players choose a soccer player and bounce balls out of their net to score.","about":"Euro Headers 2004 is an arcade sports game from 2004. The player selects a soccer player and then works to bounce multiple balls out of their own net. Doing so earns points. The action centers on keeping balls away from the net while scoring through those bounces.","system":"Flash","genre":"sports","categories":"sports|arcade","core":"swf","width":600,"height":350},{"type":"flash","id":"flash-chess","slug":"flash-chess","title":"Flash Chess","description":"Flash Chess is a single-player strategy and simulation game from Digital Vision Multimedia that brings the classic tabletop game of chess to the screen.","about":"Digital Vision Multimedia's Flash Chess is a single-player take on chess, presented as a tabletop strategy and simulation game. It focuses on the classic board game, with play centered on the strategic decisions that define a match.","system":"Flash","genre":"strategy","categories":"strategy|simulation","core":"swf","width":800,"height":600},{"type":"flash","id":"flood-runner-armageddon","slug":"flood-runner-armageddon","title":"Flood Runner: Armageddon","description":"Flood Runner: Armageddon is a 2011 arcade runner by Ben Rad Vinyl where players jump, glide and kick through creatures for a high score.","about":"In this Armageddon-themed running game, the player moves through a series of creatures using jumps, double-jumps, glides and kicks. Multipliers can be collected along the way, and the goal is to reach a high score. Control is handled either with the keyboard arrows or the mouse, but not both at once. Choosing the arrows makes the up arrow jump, with other keys reserved for combos, while choosing the mouse makes a click perform the jumping actions.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":350},{"type":"flash","id":"gravitex-2","slug":"gravitex-2","title":"Gravitex 2","description":"Gravitex 2 is a 2009 puzzle arcade game from kChamp Games where players toss objects through gravity-driven challenges.","about":"Gravitex 2 is a single-player puzzle arcade game from kChamp Games, released in 2009 as the follow-up to Gravitex. Play centers on tossing objects through gravity-based challenges, and a level editor lets players build their own stages.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":700,"height":600},{"type":"flash","id":"high-dive-hero","slug":"high-dive-hero","title":"High Dive Hero","description":"High Dive Hero is a 2007 sports game from Mousebreaker where players perform stunts and positions in the air to score points.","about":"High Dive Hero puts players into an Olympic-style high diving competition. Points are earned by pulling off various stunts or positions while in the air, and the dive must end with a vertical entry into the water. The game was developed by Mousebreaker in 2007.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":600,"height":450},{"type":"flash","id":"i-love-traffic","slug":"i-love-traffic","title":"I Love Traffic","description":"I Love Traffic is a 2009 puzzle game by John Cooney where players time traffic lights to guide cars through busy intersections.","about":"In I Love Traffic, the player takes charge of traffic lights at intersections and must time them so that a set number of cars get through each level. As the game goes on, the levels grow more difficult and the roads fill with more vehicles, leading to serious gridlock. The mouse is used to control the lights, and the goal is to reach the required number of cars to advance.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":550},{"type":"flash","id":"khan-kluay-the-last-battle","slug":"khan-kluay-the-last-battle","title":"Khan Kluay – The Last Battle","system":"Flash","genre":"action","categories":"action","core":"swf","width":650,"height":400},{"type":"flash","id":"master-shakes-diving-contest","slug":"master-shakes-diving-contest","title":"Master Shake’s Diving Contest","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"meat-boy","slug":"meat-boy","title":"Meat Boy","description":"Meat Boy is a 2008 action platformer from Edmund McMillen and Jonathan McEntee, built around tough, precise jumps.","about":"Meat Boy is a difficult action platformer released in 2008 by Edmund McMillen and Jonathan McEntee. Players work through a series of levels and only need to clear three out of every five to move on to the next set. Collecting band aids unlocks extra characters, and pressing escape lets players leave a level and return to the level menu. Custom levels can be submitted by email with a name and level title for possible inclusion in a future map pack.","system":"Flash","genre":"action","categories":"action","core":"swf","width":300,"height":500},{"type":"flash","id":"multitask","slug":"multitask","title":"Multitask","description":"Multitask is a 2009 arcade game from IcyLime that challenges players to handle more than one game at the same time.","about":"Multitask is an arcade game built around the idea of playing several games at once. The player takes on more than one game simultaneously, testing their ability to split attention between them. It was developed by IcyLime in 2009.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":740,"height":530},{"type":"flash","id":"oobi-rhyme","slug":"oobi-rhyme","title":"Oobi Rhyme","description":"Oobi Rhyme is a 2003 educational quiz game from This Is Pop and Tim Lagasse in which players help Oobi find rhymes for words.","about":"Words appear on screen, and the player helps Oobi come up with rhymes for them. Each round works as a simple quiz, with the goal of matching the shown word to a rhyming answer. It is an educational title from This Is Pop and Tim Lagasse, released in 2003.","system":"Flash","genre":"quiz","categories":"quiz|educational","core":"swf","width":565,"height":310},{"type":"flash","id":"police-bike","slug":"police-bike","title":"Police Bike","description":"Police Bike is an arcade game from 2000 in which a rider steers through crowds and strikes protesters while collecting weapons.","about":"The player controls a motorcycle and rides through groups of people, hitting protesters along the way. Power-up items appear during play, including a machine gun and bombs that can destroy cars. The game was made in 2000 and draws on the Republican National Convention held in Philadelphia that year, using it as the basis for a satirical take on the events. Friends of the developer appear in the game, which was also noted in the city's City Paper.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":630,"height":350},{"type":"flash","id":"riddle-transfer","slug":"riddle-transfer","title":"Riddle Transfer","description":"Riddle Transfer is a 2011 adventure game by JonBro, part of the Riddle School series, where players work through puzzles and a new beginning.","about":"Riddle Transfer is an adventure game released in 2011 by JonBro, serving as a new beginning for the Riddle School series. Players progress through the game by solving puzzles, with a walkthrough available for guidance. A sequel, Riddle Transfer 2, followed. The game includes a puzzle room near the end, though its music is no longer online.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"amorphous","slug":"amorphous","title":"Amorphous","description":"Amorphous is a fast-paced 2007 action game by Caleb Rhodes that throws the player against hundreds of colorful little blobs.","about":"Amorphous is a fast-paced action game from 2007, created by Caleb Rhodes of innocuousGames. The player faces off against hundreds of colorful little blobs. A practice mode lets the player train against any Gloople that has been seen. Options allow muting music or effects separately, and the intro screens can be skipped with a left mouse click.","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":400},{"type":"flash","id":"arcane-the-armor-collector","slug":"arcane-the-armor-collector","title":"Arcane: The Armor Collector","description":"Arcane: The Armor Collector is a 2008 action RPG where players battle through medieval-style arenas with bows, swords, axes and more.","about":"Set in a medieval tournament, this real-time action RPG has players fighting to earn glory using a variety of ranged and melee weapons. The game offers a campaign with twenty challenges and three bosses, along with ten fighting arenas. Players can also customize their team members and collect over fifty different armors and weapons. A separate mode includes highscore tracking.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"battle-beavers","slug":"battle-beavers","title":"Battle Beavers","description":"Battle Beavers is a 2011 action adventure game from Rob Donkin in which a beaver named Bold sets out to stop Rangor the Terrible.","about":"Rob Donkin's Battle Beavers mixes brawling with role-playing progression. The player controls Bold, a beaver on a quest to bring down Rangor the Terrible. Fighting through many foes earns access to gear, character improvements and hidden techniques.","system":"Flash","genre":"adventure","categories":"adventure|action","core":"swf","width":640,"height":530},{"type":"flash","id":"blacksmith-lab","slug":"blacksmith-lab","title":"Blacksmith Lab","description":"Blacksmith Lab is a 2016 idle simulation from Aumgames and Lampogolovii in which players run a blacksmith business and level it up.","about":"In this idle game, the player takes on the role of a blacksmith and works to level up. Progress comes through a marketplace, a bank, an upgrades lab, and a news section. These varied systems give the blacksmith business more to manage than simple clicking.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":700,"height":525},{"type":"flash","id":"boxhead-the-zombie-wars","slug":"boxhead-the-zombie-wars","title":"Boxhead: The Zombie Wars","description":"Boxhead: The Zombie Wars is a 2008 top-down shooter from Sean Cooper where players fight off hordes of the undead and build defenses.","about":"The fifth entry in the Boxhead series, this 2008 shooter from Sean Cooper pits players against large numbers of zombies and their allies. A new addition to the series lets players build their own base using turrets and barricades. Keeping that base running at all times is necessary, since the zombie forces will otherwise overwhelm it. The game also features updated graphics and a wider range of enemies than earlier entries.","system":"Flash","genre":"shooter","categories":"shooter|arcade|action","core":"swf","width":700,"height":490},{"type":"flash","id":"castle-cat","slug":"castle-cat","title":"Castle Cat","description":"Castle Cat is a 2004 platformer from Wiesi and Mausland Entertainment in which a cat makes its way through a castle.","about":"Castle Cat is a platformer in which a cat travels through a castle. It was created by Felix Wiesner (Wiesi) and Mausland Entertainment in 2004. The developer made it as a break from work on another game.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":700,"height":500},{"type":"flash","id":"cat-god-vs-sun-king-2","slug":"cat-god-vs-sun-king-2","title":"Cat God vs Sun King 2","description":"Cat God vs Sun King 2 is a 2013 strategy game from Nerdook in which players call down disasters to topple a tower.","about":"In this strategy title, the Sun King's Tower must be brought down with an arsenal of divine attacks, including meteors, sandworms, locusts, fireballs and a Pillar of Flames. Aiming fireballs is done by moving the mouse, while clicking calls up the Pillar of Flame. A second player can join on the same computer, taking the role of the Sun King and using the arrow keys to move and the number keys 1 through 4 to summon minions. The game also includes a climactic last fight and a closing song.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":720,"height":480},{"type":"flash","id":"cider-attack","slug":"cider-attack","title":"Cider Attack","description":"Cider Attack is a 2012 arcade game by SylrePony in which a pony catches falling items across a single-player session.","about":"Cider Attack is an arcade catching game from 2012, developed by SylrePony. It is set in the My Little Pony world and features equine characters, with one player taking part.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"deadly-neighbours","slug":"deadly-neighbours","title":"Deadly Neighbours","description":"Deadly Neighbours is a 2010 strategy game from Nerdook where players equip a custom family and battle rival households.","about":"In this strategy game, the player builds and customizes a family, then arms its members from a selection of more than 75 weapons. The family is used to fight against other families living in the same neighbourhood. A multiplayer mode lets players export their family so it can be shared with others.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":550,"height":500},{"type":"flash","id":"dont-shoot-the-puppy","slug":"dont-shoot-the-puppy","title":"Don’t Shoot the Puppy","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":500,"height":325},{"type":"flash","id":"epicbattlefantasy2","slug":"epicbattlefantasy2","title":"Epic Battle Fantasy 2","description":"Epic Battle Fantasy 2 is a 2009 strategy game from Matt Roszak in which players fight through successive waves of enemies.","about":"Epic Battle Fantasy 2 continues the story of the first game and puts players against wave after wave of enemies. It adds leveling up and other upgrades to the earlier formula. The game comes from developer Matt Roszak and belongs to the Epic Battle Fantasy series.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":700,"height":400},{"type":"flash","id":"flick-headers-euro-2012","slug":"flick-headers-euro-2012","title":"Flick Headers Euro 2012","system":"Flash","genre":"sports","categories":"sports|arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"gemcraft","slug":"gemcraft","title":"GemCraft","description":"GemCraft is a 2008 strategy game from GameInABottle where players craft magic gems and place them in towers to fight invading monsters.","about":"The land is overrun by havoc and corruption, and only a handful of wizards can stop it. The player creates magic gems and combines them, then places the results into towers. These towers serve as the defense against waves of monsters that must be driven back. Strategy comes from deciding how to build and merge the gems for each tower.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":480},{"type":"flash","id":"go-george-go","slug":"go-george-go","title":"Go! George Go!","description":"Go! George Go! is a 2004 PBS Kids puzzle game starring Arthur, played solo with the mouse and featuring voice acting.","about":"Go! George Go! is a puzzle game from PBS Kids released in 2004, set in the world of Arthur. Players work through logic-based challenges alone, using only the mouse, with voice acting accompanying the experience.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":595,"height":350},{"type":"flash","id":"governor-of-poker","slug":"governor-of-poker","title":"Governor of Poker","description":"Governor of Poker is a 2008 single-player simulation from Youda Games that mixes poker playing with a Western setting.","about":"Governor of Poker is a single-player simulation from Youda Games, released in 2008 as the first entry in the Governor of Poker series. Set in the Old West, it builds its card play around poker and gambling, with a trial structure running through the experience.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":800,"height":600},{"type":"flash","id":"halloween-game-collab-07","slug":"halloween-game-collab-07","title":"Halloween Game Collab 07","description":"Halloween Game Collab 07 is a 2007 arcade action collection of Halloween-themed mini-games from Coolio-Niato and other contributors.","about":"Halloween Game Collab 07 gathers a set of Halloween-related games into one arcade action package. It was assembled by Coolio-Niato together with a group of contributors, who each supplied their own ideas and work to the project. The collection came together in roughly three weeks, and later updates addressed some glitches in the games.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"hedgehog-launch-2","slug":"hedgehog-launch-2","title":"Hedgehog Launch 2","description":"Hedgehog Launch 2 is a 2009 arcade game by John Cooney in which a hedgehog is fired through the planet's core and out toward deep space.","about":"This 2009 arcade title by John Cooney continues the original Hedgehog Launch, with the action now sending the hedgehog straight through the center of the earth. Players travel across a vast world map, with launches that can carry them far into space. The scale is larger than the first game, and its mechanics are built out further as well.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":600},{"type":"flash","id":"hobo-prison-brawl","slug":"hobo-prison-brawl","title":"Hobo Prison Brawl","description":"Hobo Prison Brawl is a 2009 action game from SeethingSwarm in which a hobo fights prisoners, guards and the government.","about":"The hobo returns, this time locked up and looking for another messy fight. He takes on prisoners, security guards and even the government, since none of them are off limits. Players move with the arrow keys, punch and pick up objects with A, and kick with S.","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":450},{"type":"flash","id":"hungry-knight","slug":"hungry-knight","title":"Hungry Knight","description":"Hungry Knight is a 2014 action game from Team Cherry in which a small adventurer battles through a hostile wasteland while staying fed.","about":"Made by Team Cherry for the Ludum Dare 27 game jam, whose theme was 10 Seconds, Hungry Knight puts a determined little adventurer with a large appetite into a strange wasteland. Players move with the arrow keys, strike with Z and dash with X as they cut down whatever stands in their way. Food must be found and eaten every ten seconds to keep going. The result is a difficult action game that rewards persistence and courage.","system":"Flash","genre":"action","categories":"action","core":"swf","width":896,"height":608},{"type":"flash","id":"hunted-forever","slug":"hunted-forever","title":"Hunted Forever","description":"Hunted Forever is a 2008 platformer by Evan Miller where a robot navigates a collapsing world, trying to survive as long as possible.","about":"In this action platformer from 2008, the player controls a robot moving through a world that is being destroyed. The goal is to stay alive and avoid dying, since death is counter-productive to the mission. Arrow keys or WASD are used to navigate the hazards. The game was developed by Evan Miller, also known as acrazycanadian.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":600,"height":600},{"type":"flash","id":"k-fed-dancing-with-fire","slug":"k-fed-dancing-with-fire","title":"K-FED: Dancing with Fire","description":"K-FED: Dancing with Fire is a 2006 action game by Tom Fulp in which players throw punches to stop K-Fed.","about":"K-Fed is causing trouble, and the goal is to put a stop to him before he does more damage. Players move the mouse across the screen and click to throw different punches, including jabs, swings and uppercuts. Holding down the mouse button charges up a super punch for a stronger hit. The game was programmed by Tom Fulp, with art by Jeff Bandelin.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":360},{"type":"flash","id":"keyboard-mayhem","slug":"keyboard-mayhem","title":"Keyboard Mayhem","description":"Keyboard Mayhem is a 2010 arcade typing game from Sun-Studios where players type displayed words to push a beast off a cliff.","about":"Words appear on screen and the player types them as shown. Each correct entry helps drive the beast toward the edge of a cliff. The game turns typing practice into an arcade challenge, with the goal of forcing the creature over the drop.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":360},{"type":"flash","id":"lazerman","slug":"lazerman","title":"Lazerman","description":"Lazerman is a 2013 action game from NSBrotherhood in which a lab experiment leaves a detached head trying to reunite with its body.","about":"A secret military laboratory ran an experiment that left the protagonist as nothing more than a head separated from its body. The goal is to get that body back. Along the way, the lab and everything in it can be smashed apart. NSBrotherhood released the game in 2013.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"mud-and-blood-2","slug":"mud-and-blood-2","title":"Mud and Blood 2","description":"Mud and Blood 2 is a 2008 strategy game by Urbz where players command a World War 2 squad in a highly random, unforgiving battle.","about":"Mud and Blood 2 places the player in charge of a World War 2 squad, making decisions under conditions that are deliberately harsh and unpredictable. The game is built around testing how well the player can adapt when little is fair or guaranteed. Players set up their defensive position using more than 42 options, which include different soldiers, weapons, buildings and airstrikes. How the battle unfolds is left largely in the player's hands.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":400,"height":600},{"type":"flash","id":"murloc-rpg","slug":"murloc-rpg","title":"Murloc RPG","description":"Murloc RPG is a 2006 adventure game from Gamer Disclaimer where players control a Murloc through a full role-playing storyline.","about":"Players take control of a Murloc in this role-playing adventure, moving left and right with the keyboard and holding a key to run. The game offers a complete storyline to follow, with more than fifty items, twenty talents, and many enemies to fight across a range of areas. A full playthrough takes over an hour, and the developer built the engine specifically for this project after wanting to play as a Murloc.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":700,"height":300},{"type":"flash","id":"my-friend-pedro","slug":"my-friend-pedro","title":"My Friend Pedro","description":"My Friend Pedro is a 2014 single-player shooter from DeadToast Entertainment, part of the My Friend Pedro series.","about":"My Friend Pedro is a single-player shooter from developer DeadToast Entertainment, released in 2014 as part of the My Friend Pedro series. The game focuses on shooter and action gameplay.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":600,"height":400},{"type":"flash","id":"newgrounds-rumble","slug":"newgrounds-rumble","title":"Newgrounds Rumble","description":"Newgrounds Rumble is a 2007 action fighting game from developer Aaron Worrall where characters from the site battle it out.","about":"Newgrounds Rumble is a fighting game that brings together characters from across the site. It went into production in December 2005 and was developed by a small group of Newgrounders led by Aaron Worrall, also known as NegativeONE. Players can adjust the options to match their preferred control style and their computer's processor. The game was updated over several years with new characters, bug fixes, and other changes.","system":"Flash","genre":"action","categories":"action","core":"swf","width":650,"height":450},{"type":"flash","id":"nick-jr-mailbox","slug":"nick-jr-mailbox","title":"Nick Jr. Mailbox","description":"Nick Jr. Mailbox is a 2001 educational game for young children from Nick Jr. in which familiar characters appear in a single-player mailbox activity.","about":"Nick Jr. Mailbox is a 2001 educational game from Nick Jr. in which characters such as Dora the Explorer, Blue's Clues, Bob the Builder, Little Bill, Little Bear and Kipper appear. It is a mouse-only, single-player toy in the Nick Jr's ClickJrs series, aimed at a young audience.","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":475,"height":285},{"type":"flash","id":"penguin-diner-2","slug":"penguin-diner-2","title":"Penguin Diner 2","description":"Penguin Diner 2 is a 2010 simulation game where players seat penguin customers, take orders, and serve food before the 9pm closing time.","about":"In Penguin Diner 2, penguin customers arrive at the restaurant and need to be seated, served, and cleared away. Players click to seat them, take orders when they raise a flipper, deliver dishes from the kitchen counter, and clean tables to collect tips. The shift ends at 9pm, and the cash register shows how much money must be earned. Between days, tips can buy upgrades that improve speed, patience, and earnings, while stars unlock outfits and restaurant themes.","system":"Flash","genre":"simulation","categories":"simulation|arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"penguinz","slug":"penguinz","title":"Penguinz","description":"Penguinz is a 2009 action shooter from LongAnimals and Jim P, offering gory penguin mayhem with 15 enemies and 4 bosses.","about":"Penguinz is an action shooter built around penguin gore mayhem. Players fight through 15 enemy types and four bosses. The game includes nine weapons, which can be improved with 33 upgrades plus six special upgrades. LongAnimals and Jim P developed it in 2009.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":480},{"type":"flash","id":"pirate-launch","slug":"pirate-launch","title":"Pirate Launch","description":"Pirate Launch is a 2009 arcade game by Goat-Man where a pirate is fired from a cannon and flips through the air for points.","about":"A pirate spots a red X on a far-off island and sets out to reach it. The boat is fired from a cannon, and the player performs flips in the air to earn points while collecting coins. Sharks, bombs, islands and other hazards stand in the way, and the run has to be completed in one go. Upgrades made from assorted junk can improve the boat and help the pirate fly further.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":450},{"type":"flash","id":"playing-with-fire-2","slug":"playing-with-fire-2","title":"Playing with Fire 2","description":"Playing with Fire 2 is an action game where players use bombs to eliminate opponents across selectable levels.","about":"Playing with Fire 2 is a multiplayer action game where bombs are the main weapon. After choosing the number of players and a level, the goal is to blow up opponents before they do the same. Blocks can be destroyed to reveal power-ups that grant special abilities when collected. Each player starts with three lives, so they must be eliminated three times, and every match has a three-minute limit. Winning awards points based on the seconds left on the timer multiplied by 250 and the number of opponents, while losing subtracts that same amount from the score.","system":"Flash","genre":"action","categories":"action","core":"swf","width":554,"height":410},{"type":"flash","id":"robot-wants-puppy","slug":"robot-wants-puppy","title":"Robot Wants Puppy","description":"Robot Wants Puppy is a 2010 action platformer from Hamumu Software in which a robot searches a maze for its puppy with help from a kitty.","about":"In this 2010 action platformer from Hamumu Software, a robot travels back into a maze to find its puppy. A kitty companion joins the search, slashing enemies along the way. Defeating foes yields upgrades that help the robot push deeper into the maze toward the puppy.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":640,"height":480},{"type":"flash","id":"rufus-snow-ride","slug":"rufus-snow-ride","title":"Rufus Snow Ride","description":"Rufus Snow Ride is a 2005 sports arcade game from Disney where a snowboarding Rufus dodges obstacles on Mount Middleton.","about":"Rufus is snowboarding down Mount Middleton to reach Ron. DNAmy, a bio-geneticist who specializes in animal hybrids, has released her genetically modified Cuddle Buddies, and these creatures are chasing Rufus. The player guides him past the obstacles in his path so he avoids being caught and finds Ron.","system":"Flash","genre":"sports","categories":"sports|arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"samurai-autumn","slug":"samurai-autumn","title":"Samurai Autumn","description":"Samurai Autumn is a 2013 arcade action platformer from Sun-Studios with 12 stages, four boss fights and combo-based combat.","about":"Dark creatures from the deep forest gather in hordes, and a samurai runs through the autumn woods to cut them down. Jumping on several enemies in a row builds combos, and Sun Flowers charge the blade so it can release a storm of energy blasts. The game spans 12 stages with four boss battles and upgrades along the way.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":480},{"type":"flash","id":"sindicate","slug":"sindicate","title":"Sindicate","description":"Sindicate is a 2007 gang simulation by Adam Telfer where players run a criminal crew, seize stores, and battle for territory.","about":"Sindicate is a crime simulation from 2007 by Adam Telfer and Renegade Entertainment. Players manage their own gang, choosing its appearance and expanding control by taking over stores and claiming territory. Selling drugs and handling gang wars, bribes, and protection keep the crew on top. Five missions and a long roster of gangs are included, along with skirmish mode on a large map and a sandbox mode for testing strategies.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":800,"height":600},{"type":"flash","id":"slay-with-santa","slug":"slay-with-santa","title":"Slay With Santa","description":"Slay With Santa is a 2012 action shooter where Santa battles zombies and other invaders in his lair using a blaster.","about":"Santa's lair has been overrun by zombies, creepies and other bad guys during Christmas in this 2012 shooter from Chaz Carter and Wayne Marsh. The player moves Santa around with the arrow keys or WASD, jumps with the up key, and fires with Z or M. The goal is to eliminate every enemy in the lair, all set to a dubstep Christmas soundtrack.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":720,"height":400},{"type":"flash","id":"sonic-boom-cannon-2","slug":"sonic-boom-cannon-2","title":"Sonic Boom Cannon 2","description":"Sonic Boom Cannon 2 is a 2009 arcade game where players launch a character down a stage to rack up distance and rings.","about":"In Sonic Boom Cannon 2, the goal is to fire a character down the stage and cover as much distance as possible. Longer shots earn rings, which can be spent to unlock more characters and items from the store. With 52 characters and five minigames to discover, the game opens up gradually as more is unlocked. Each shot's payout grows with the number of characters already collected, so progress tends to come faster over time.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"steakandjake","slug":"steakandjake","title":"Steak and Jake","description":"Steak and Jake is a 2010 adventure game where a cow and a bird deliver fresh milk across 30 worlds and hundreds of levels.","about":"Steak the cow and Jake the bird work together to deliver fresh milk to lactose-tolerant chickens. Steak is strong but clumsy, while Jake can change color to fill and interact with matching items and enemies. The pair travels through 30 worlds and hundreds of levels, switching between several play styles, including protecting Steak from milk bandits, aiding the Cookie Scouts, facing bosses, and racing the Cocoa Cow. Challenges and Milk Races can be replayed, and each level ends with a score based on Color Points, Cow Cash, and cookies eaten.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":672,"height":480},{"type":"flash","id":"strategy-defense","slug":"strategy-defense","title":"Strategy Defense","description":"Strategy Defense is a 2007 strategy game from Belugerin Games that mixes role-playing and tactical decision-making with mouse-driven menus.","about":"Strategy Defense combines role-playing elements with strategy gameplay. Players make selections from in-game menus using the mouse to guide their progress. The game was developed by Belugerin Games and Arief Raditya in 2007.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":600},{"type":"flash","id":"striped-escape","slug":"striped-escape","title":"Striped Escape","description":"Striped Escape is a platformer and action game about a bee breaking out of a space prison while gathering honey.","about":"In Striped Escape, the player guides a bee through a space prison in an attempt to break out. Each level is a platforming challenge that involves collecting honey and steering clear of other inmates. The action centers on careful navigation rather than combat.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":600,"height":350},{"type":"flash","id":"swords-souls","slug":"swords-souls","title":"Swords & Souls","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":800,"height":600},{"type":"flash","id":"the-binding-of-isaac-demo","slug":"the-binding-of-isaac-demo","title":"The Binding of Isaac Demo","description":"The Binding of Isaac Demo is a 2011 action adventure by Edmund McMillen and Florian Himsl, offering two of the full game's eight levels.","about":"Isaac flees to the basement after his mother hears a divine command to prove her faith through sacrifice. There he confronts deranged creatures, lost siblings, his own fears, and finally his mother. Played as a randomly generated action RPG shooter with strong Rogue-like elements, the game lets players collect strange treasures that alter Isaac's body and grant superhuman powers. This demo contains two of the eight levels found in the complete version.","system":"Flash","genre":"adventure","categories":"adventure|action","core":"swf","width":800,"height":600},{"type":"flash","id":"the-lonely-knight","slug":"the-lonely-knight","title":"The Lonely Knight","description":"The Lonely Knight, a 2001 logic puzzle from Plastelina Games and Shlomir Hadad, offers single-player brain teasers.","about":"The Lonely Knight is a single-player puzzle game built around logic challenges, released in 2001 by Plastelina Games and Shlomir Hadad. It belongs to the Plastelina Logic Games series, and its focus on reasoning makes it an educational entry in that collection.","system":"Flash","genre":"logic","categories":"logic|educational","core":"swf","width":500,"height":315},{"type":"flash","id":"tornado-button-smashing","slug":"tornado-button-smashing","title":"Tornado Button Smashing","description":"Tornado Button Smashing is a 2007 arcade game where players steer a twister and mash a key to grow it while wrecking buildings.","about":"Players guide a tornado with the W, A, S, and D keys or the arrow keys, then rapidly press Enter to make it expand. The goal is to demolish enough buildings to move on to the next level. Cars, trees, and tepees can occasionally award a time bonus, while police cars grant a speed bonus. The game was developed by Felix Wiesner (Wiesi) and Mausland Entertainment.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":460},{"type":"flash","id":"unreal-flash-2007","slug":"unreal-flash-2007","title":"Unreal Flash 2007","description":"Unreal Flash 2007 is a fast-paced shooter from Erik Sombroek with ten weapons, fifty-plus characters and eight maps.","about":"Unreal Flash 2007 is a pick-up-and-play shooter built for quick, fast-paced matches. Players choose from over fifty characters and assemble a custom team, then fight across eight maps using ten weapons that each offer a secondary fire. Seven game types are included, among them Capture the Flag, King of the Hill and Zombie Invasion, along with a twenty-level story mode where skill decides who becomes the Unreal Flash champion. It is the second entry in the Unreal Flash series.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":400},{"type":"flash","id":"warfare-1944","slug":"warfare-1944","title":"Warfare 1944","description":"Warfare 1944 is a 2009 strategy game from ConArtists where U.S. forces battle the German Wehrmacht in Normandy.","about":"Warfare 1944 is a strategy game set during the fight for Normandy, with U.S. forces facing the German Wehrmacht. Players command their side in this conflict, rising from the trenches to the battlefield. The game was developed by ConArtists in 2009.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":500},{"type":"flash","id":"warlords-heroes","slug":"warlords-heroes","title":"Warlords: Heroes","description":"Warlords: Heroes is a 2008 action game by Ben Olding where players fight through four fantasy episodes, buying moves and hiring henchmen.","about":"Warlords: Heroes is a side-scrolling action game set in the Warlords world, built on the Achilles engine. Players battle through four episodes of fantasy combat, earning money to purchase fighting moves, armour and magical items after each level. Henchmen can be hired to help during the journey, and three playable characters offer different weapons, moves, stories and personalities. A freely explorable map lets players roam and fight as they wish, while Survival and Gladiator modes provide additional challenges.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":500},{"type":"flash","id":"whack-your-ex","slug":"whack-your-ex","title":"Whack Your Ex","description":"Whack Your Ex is a 2007 comedy adventure by Tom Winkler where players act out relationship revenge fantasies through a menu.","about":"Whack Your Ex is a mouse-driven comedy adventure from Tom Winkler. Players who have felt let down by love pick from a menu to act out revenge fantasies. The whole thing plays out in the safe arena that most people know as the internet. It is a single-player toy built around relationship humor.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":750,"height":500},{"type":"flash","id":"zombotron","slug":"zombotron","title":"Zombotron","description":"Zombotron is an action game set on a planet overrun by mutants and zombies, where a lone bio-robot fights to survive.","about":"Zombotron takes place on a planet inhabited by human-mutants and zombies whose origins and diet remain unknown. Colonists once built laboratories to create bio-robots that would clear the planet of these threats, but the facilities now run under computer control with no people left. The player controls one of the few remaining bio-robots and must carry out the mission.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"armadillo-knight","slug":"armadillo-knight","title":"Armadillo Knight","description":"Armadillo Knight is a 2006 single-player action beat 'em up from developer Trent Halvorsen.","about":"Armadillo Knight is an action beat 'em up released in 2006 and developed by Trent Halvorsen. It is played solo as part of the Armadillo Knight series.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"cat-god-vs-sun-king","slug":"cat-god-vs-sun-king","title":"Cat God vs Sun King","description":"In Cat God vs Sun King, a 2011 strategy game by Nerdook, players use divine abilities to stop the Sun King's servants from finishing a temple.","about":"The Sun King's followers are trying to build a temple, and only the Cat God can stop them. Players pick from a set of God Powers and unleash them on the minions below, switching between abilities at will or via hotkeys 1 through 6. The game is a loose take on Babel Rising for the iOS.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":480,"height":678},{"type":"flash","id":"celebrity-fight-club","slug":"celebrity-fight-club","title":"Celebrity Fight Club","description":"Celebrity Fight Club is a 2002 single-player action game from TechRadium Studios that pits famous figures against each other in first-person combat.","about":"Celebrity Fight Club is a first-person fighting game released in 2002 by TechRadium Studios. It is played solo and features famous people as the combatants, with mild violence and blood.","system":"Flash","genre":"action","categories":"action","core":"swf","width":430,"height":400},{"type":"flash","id":"crazy-shuttle","slug":"crazy-shuttle","title":"Crazy Shuttle","description":"Crazy Shuttle is a 2001 action game by Tom Fulp in which a shuttle driver collects students and brings them to their stops.","about":"In Crazy Shuttle, the player controls a shuttle whose job is to collect students and carry them to their destinations. The trip is far from safe, since the vehicle can run down anything that gets in its way. Students may arrive alive or not, and the game does not require a careful approach. Tom Fulp made it in 2001, and the controls are explained inside the game itself.","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":395},{"type":"flash","id":"dice-mogul","slug":"dice-mogul","title":"Dice Mogul","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":800},{"type":"flash","id":"edgy-wedgy","slug":"edgy-wedgy","title":"Edgy Wedgy","description":"Edgy Wedgy is a 1999 single-player arcade game from Teletoon, part of the Edgy Wedgy series.","about":"Edgy Wedgy is an arcade game released in 1999 by Teletoon. It is played solo and belongs to the Edgy Wedgy series.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":480,"height":360},{"type":"flash","id":"egg-defender","slug":"egg-defender","title":"Egg Defender","description":"Egg Defender is a 2009 simulation game from Warb where a penguin guards its egg from a hungry polar bear.","about":"In Egg Defender, the player controls a penguin that must stay alive until its egg hatches. Movement uses the arrow keys, and the space bar makes the penguin slide on its belly. Sliding into other penguins knocks them off the edge, while the polar bear remains until it has eaten enough and can be bothered with the beak. Surprises also lurk in the water, and sitting on the egg in the nest speeds up the level timer. The game includes four unlockable modes, fifteen achievements, and five alternate endings.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":800,"height":600},{"type":"flash","id":"elastoman","slug":"elastoman","title":"Elastoman","description":"Elastoman is a 2009 arcade game from FreeWorldGroup where a bouncing hero rescues tied-up citizens across a city.","about":"In Elastoman, the player controls a bouncy character who moves through the city to rescue kidnapped citizens who have been tied up. A crime fighting map shows the locations of the people as yellow dots. After all of them have been rescued, the player must reach the helicopter to escape.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"endless-war-3","slug":"endless-war-3","title":"Endless War 3","description":"Endless War 3 is a 2007 top-down shooter from developer Vitaly Zaborov, set across historical and science fiction battlefields.","about":"Endless War 3 is a top-down shooter with a fixed screen, played solo in 2007 from developer Vitaly Zaborov. It mixes military and science fiction settings, with historical battles such as WWII, and includes the first two Endless War campaigns alongside its own.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":660},{"type":"flash","id":"epicbattlefantasy3","slug":"epicbattlefantasy3","title":"Epic Battle Fantasy 3","description":"Epic Battle Fantasy 3 is a 2010 adventure role-playing game by Matt Roszak where players walk around and interact in a 3/4 view world.","about":"In Epic Battle Fantasy 3, players move using WASD or arrow keys and press Space to interact, while the mouse handles other actions. The game is played from a 3/4 view and includes role-playing elements, anime style, mild violence, and cartoon visuals. It features achievements and a preloader, and is part of the Epic Battle Fantasy series. Sound and quality can be adjusted in the right-click menu.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":700,"height":400},{"type":"flash","id":"fantastic-contraption","slug":"fantastic-contraption","title":"Fantastic Contraption","description":"Fantastic Contraption is a 2008 puzzle game from Inxile Entertainment where players build machines to cross challenging levels.","about":"Fantastic Contraption is a puzzle game about constructing machines to move across tricky levels. Players assemble their own contraptions from available parts, then rely on those designs to solve each stage. Simple URLs let players share the creations they build with friends.","system":"Flash","genre":"puzzle","categories":"puzzle|creative","core":"swf","width":550,"height":400},{"type":"flash","id":"feudalism","slug":"feudalism","title":"Feudalism","description":"Feudalism is a 2007 single-player strategy and action game with role-playing elements set in a medieval world.","about":"Feudalism is a single-player strategy and action game from 2007 by Vitaly Zaborov, also known as BlackFox-of-ITMO. It mixes role-playing and upgrade elements into a medieval military setting with a ninja theme.","system":"Flash","genre":"strategy","categories":"strategy|action","core":"swf","width":800,"height":600},{"type":"flash","id":"flakboy","slug":"flakboy","title":"Flakboy","description":"Flakboy is a 2010 physics puzzle game from Spil Games where players experiment with a ragdoll in a fixed-screen sandbox.","about":"Flakboy is a single-player physics puzzle game released in 2010 by Spil Games. Players experiment with a ragdoll character in a fixed-screen sandbox, using physics interactions and upgrades to rack up a score in score-attack play.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":700,"height":540},{"type":"flash","id":"flea","slug":"flea","title":"Flea","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":450},{"type":"flash","id":"gravitee-wars","slug":"gravitee-wars","title":"Gravitee Wars","description":"Gravitee Wars is a 2010 space artillery shooter from FunkyPear where missiles are slingshotted around planets to defeat enemy forces.","about":"Set in space, this artillery-style shooter from FunkyPear pits teams against each other for control of the galaxy. Players aim by clicking and dragging from a highlighted unit, sending missiles on curved paths around planets to strike opponents. A selection of ten weapons and utilities is available during battles. Earning money allows upgrades such as better health and accuracy, or the purchase of additional units, while progress brings a range of awards and rewards.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":700,"height":500},{"type":"flash","id":"hapland-3","slug":"hapland-3","title":"Hapland 3","description":"Hapland 3 is a 2006 point-and-click puzzle game by Robin Allen, continuing the Hapland adventure with more interactive brain teasers.","about":"Hapland 3 carries on the Hapland adventure, with Robin Allen returning as developer in 2006. Players work through a point-and-click puzzle scenario, interacting with the scene to trigger events and solve the challenges placed in front of them. It is a continuation of the series, so the focus stays on the same style of interactive problem solving.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":750,"height":500},{"type":"flash","id":"mah-jong-connect","slug":"mah-jong-connect","title":"Mah Jong Connect","description":"Mah Jong Connect is a 2009 single-player puzzle game from Front Network that builds on the Mahjong Solitaire format.","about":"Released in 2009 by Front Network, Mah Jong Connect is a single-player puzzle game in the Mahjong Solitaire style. Play centers on matching tiles in a solitaire arrangement, with simulation elements woven into the experience.","system":"Flash","genre":"simulation","categories":"simulation|puzzle","core":"swf","width":750,"height":550},{"type":"flash","id":"metal-slug-rampage","slug":"metal-slug-rampage","title":"Metal Slug Rampage","description":"Metal Slug Rampage is a 2003 pixel-art run 'n' gun shooter from Emeciton, built for single-player action.","about":"Metal Slug Rampage is a single-player run 'n' gun shooter with a pixel-art look, released in 2003 by Emeciton. Players push through the action on foot, mixing shooting with the series' signature side-scrolling combat style.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":550,"height":400},{"type":"flash","id":"music-catch","slug":"music-catch","title":"Music Catch","description":"Music Catch is a 2008 arcade game by Reflexive Entertainment where players collect colorful shapes that appear as the music plays.","about":"In Music Catch, shapes appear in time with the music, and the player collects the colorful ones for points. Yellow shapes grant a bonus and multiply the score, while red shapes must be avoided. The soundtrack is \"Before Dawn\" by Isaac Shepard, from his album Swept Away.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":533,"height":400},{"type":"flash","id":"my-friend-pedro-arena","slug":"my-friend-pedro-arena","title":"My Friend Pedro Arena","description":"My Friend Pedro Arena is a 2014 action shooter where acrobatics, reflexes and heavy gunfire decide how long you last.","about":"This arena-mode take on My Friend Pedro drops the action into six levels built around survival. Players rely on acrobatic movement, quick reflexes and a large amount of gunfire while chasing a high score. A railgun has been added to the arsenal, and the result is a bloodier, more intense version of the original's standout moments.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":600,"height":400},{"type":"flash","id":"pogo-panic","slug":"pogo-panic","title":"Pogo Panic","description":"Pogo Panic is a 2006 arcade side-view game from Corus Entertainment, built around a single-player time-attack challenge.","about":"Pogo Panic is a single-player arcade game shown from a side view, with a time-attack format. It was developed by Corus Entertainment in 2006 and includes hidden content that players can uncover.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"pongnop","slug":"pongnop","title":"Pongnop","description":"Pongnop is a 2008 arcade twist on classic pong from developer kchamp, where the mouse moves the center paddle.","about":"Pongnop takes the familiar pong formula and changes it by placing the paddle in the center of the play area. The player controls that central paddle with the mouse instead of the usual keyboard or edge-mounted controls. It was made by kchamp as a second submission to Newgrounds in 2008.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":400},{"type":"flash","id":"redball1","slug":"redball1","title":"Redball","description":"Redball is a platformer where a bouncing red ball rolls through portals, dodging red ones and using black and yellow ones.","about":"The player moves a red ball left and right with the arrow keys. Red portals must be avoided, while black portals are the ones to pass through. Yellow portals add time to the run. The ball has a strong bounce, so keeping it under control takes care.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":550,"height":400},{"type":"flash","id":"return-to-riddle-school","slug":"return-to-riddle-school","title":"Return to Riddle School","description":"Return to Riddle School is a 2016 adventure remake by Graeme Noodle in which the player works to escape from school.","about":"Graeme Noodle's 2016 adventure game revisits the setting of the earlier Riddle School, rebuilt as a remake. The goal is to find a way out of school, and the expanded version is meant to challenge even players who know the original well. Later updates enlarged the resolution and added a Quit button along with extra dialogue.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":650,"height":450},{"type":"flash","id":"round-the-world","slug":"round-the-world","title":"Round the World","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"sports-heads-tennis","slug":"sports-heads-tennis","title":"Sports Heads: Tennis","description":"Sports Heads: Tennis is a 2010 cartoon side-view tennis game from Mousebreaker, made for single-player play in the Sports Heads series.","about":"Sports Heads: Tennis is a cartoon tennis game played from a side view, released in 2010 by Mousebreaker. It belongs to the Sports Heads series and is built for a single player, with achievements to pursue as matches are played.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":800,"height":540},{"type":"flash","id":"the-amazing-world-of-gumball-battle-bowlers","slug":"the-amazing-world-of-gumball-battle-bowlers","title":"The Amazing World of Gumball: Battle Bowlers","description":"The Amazing World of Gumball: Battle Bowlers is a 2015 single-player action adventure from Cartoon Network and Stellar Jay Studios.","about":"The Amazing World of Gumball: Battle Bowlers is a single-player action adventure built around beat 'em up combat. It draws on the world of The Amazing World of Gumball and was developed by Cartoon Network and Stellar Jay Studios in 2015.","system":"Flash","genre":"adventure","categories":"adventure|action","core":"swf","width":550,"height":400},{"type":"flash","id":"blind-fooled","slug":"blind-fooled","title":"The Amazing World of Gumball: Blind Fooled","description":"The Amazing World of Gumball: Blind Fooled is a 2012 single-player puzzle platformer from Cartoon Network and The Podge.","about":"The Amazing World of Gumball: Blind Fooled is a single-player puzzle platformer from 2012, developed by Cartoon Network and The Podge. It draws on the world of The Amazing World of Gumball, combining platforming and puzzle solving.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":800,"height":600},{"type":"flash","id":"toon-cup-2006","slug":"toon-cup-2006","title":"Toon Cup 2006","description":"Toon Cup 2006 is a single-player sports game from Cartoon Network where characters from several animated series take part in soccer matches.","about":"Toon Cup 2006 is a single-player soccer game from Cartoon Network, released in 2006 as part of the Toon Cup series. Players take part in matches featuring characters drawn from several animated shows, including The Powerpuff Girls, Dexter's Laboratory, Ed, Edd n Eddy and Foster's Home for Imaginary Friends.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":600,"height":400},{"type":"flash","id":"transylmania-ii","slug":"transylmania-ii","title":"Transylmania II","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":700,"height":400},{"type":"flash","id":"zombie-mayhem","slug":"zombie-mayhem","title":"Zombie Mayhem","description":"Zombie Mayhem is a 2009 arcade action game from Sun-Studios in which a bow and arrow are used to hold off attacking zombies.","about":"Zombies are on the attack, and the player holds them off using a bow and arrow. Speed matters in both directions: reacting too slowly ends the run, while shooting too quickly risks hitting friends instead of the undead. The goal is to last as long as possible, and scores can be sent to an online scoreboard. Up and down control aiming, and the space bar fires.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":800,"height":500},{"type":"flash","id":"armed-with-wings","slug":"armed-with-wings","title":"Armed with Wings","description":"Armed with Wings, Sun-Studios' 2008 action platformer, follows a lone warrior and his eagle companion on a mission of justice.","about":"A warrior sets out across the lands to punish the figure responsible for wiping out the rebellion army. His eagle aids him along the way, helping him work through puzzles and fight enemies. The game mixes platforming with combat and brain teasers. Sun-Studios released it in 2008.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":400},{"type":"flash","id":"beer-monster","slug":"beer-monster","title":"Beer Monster","description":"Beer Monster is a 2001 arcade platformer by Simon Ralston, played solo with themes of alcohol and blood.","about":"Beer Monster is a single-player platformer from developer Simon Ralston, released in 2001. The game mixes arcade platforming with alcohol and blood themes across its stages.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"castle-crashing-the-beard","slug":"castle-crashing-the-beard","title":"Castle Crashing The Beard","description":"Castle Crashing The Beard is a 2008 action boss battle where Castle Crashers characters fight Tom Fulp's beard.","about":"In this over-the-top arcade boss battle, players control characters from Castle Crashers to fight Tom Fulp's beard. The game is based on Tom's commitment not to shave until Castle Crashers was completed. Players move with the arrow keys, attack with the A button, and can charge a special attack by holding A. The game also includes a secret character to discover.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"field-command-2","slug":"field-command-2","title":"Field Command 2","description":"Field Command 2 is a 2005 strategy game by BARMan in which players direct troops in Iraq and make selections with the mouse.","about":"Field Command 2 is a single-player strategy title from developer BARMan, released in 2005 as part of the Field Command series. The action is set in Iraq, where the player gives orders to troops with the goal of reaching victory. Selections during play are made using the mouse.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":550,"height":400},{"type":"flash","id":"gravitex","slug":"gravitex","title":"Gravitex","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":700,"height":600},{"type":"flash","id":"indiana-jones-in-odd-world","slug":"indiana-jones-in-odd-world","title":"Indiana Jones in Odd-World","description":"Indiana Jones in Odd-World is a 2003 arcade maze game by Felix Wiesner where players guide the hero through dangerous maps.","about":"Released in 2003 by Felix Wiesner, this arcade title puts the player in control of Indiana Jones as he works through a series of maze-like maps known as Odd-World. Diamonds and keys must be gathered along the way, since the keys open the door that leads to the following world. Monsters patrol the paths, and a single misstep can leave the player trapped in a dead end or falling into a bottomless pit. The ultimate objective is to track down and capture the HOLY GRAIL.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":540,"height":400},{"type":"flash","id":"infectonator-2","slug":"infectonator-2","title":"Infectonator! 2","description":"Infectonator! 2 is a 2012 strategy game from Toge Productions about spreading a zombie outbreak across continents.","about":"In this sequel, the player works to infect entire continents one at a time. The game builds on the series with more depth, letting the player upgrade various things as the outbreak grows. It features more humorous characters and improved graphics, and the chain reaction style of play carries over from the earlier titles.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":720,"height":480},{"type":"flash","id":"into-space","slug":"into-space","title":"Into Space!","description":"Into Space! is a 2010 arcade game from Barbarian Games where a rocket must climb skyward and break out of the atmosphere.","about":"The aim in Into Space! is to send a rocket upward until it finally leaves the atmosphere behind. Progress is measured in days, and the challenge is to complete the climb in as few of them as possible. Barbarian Games developed the title in 2010.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":500},{"type":"flash","id":"monkey-kick-off","slug":"monkey-kick-off","title":"Monkey Kick Off","description":"Monkey Kick Off is a 2006 arcade game from Totebo and Niclas Åberg in which a monkey kicks a giant coconut toward the Monkey Village.","about":"In Monkey Kick Off, the player helps a monkey send a giant coconut on its way to the Monkey Village. The game is an arcade title from 2006, developed by Totebo and Niclas Åberg. The goal is simply to kick the coconut as far as it needs to go.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"monoliths-mario-world-3","slug":"monoliths-mario-world-3","title":"Monoliths Mario World 3","description":"Monoliths Mario World 3 is a 2008 fan-made platformer from Mono1337 and SBH, sending players across three worlds to rescue the princess.","about":"This fan game follows the classic Mario formula across three worlds, each ending in a boss fight. Players run, jump and climb through side-scrolling stages, defeating enemies by landing on their heads while avoiding spikes, lava and other hazards. Controls can be remapped in the options menu, and holding the run button while moving builds speed for higher jumps. It is the first complete entry in the Monoliths Mario World series.","system":"Flash","genre":"platformer","categories":"platformer|adventure","core":"swf","width":400,"height":320},{"type":"flash","id":"murder","slug":"murder","title":"MURDER","description":"MURDER is a 2014 arcade game by Exotworking where a vizier sneaks up behind the king to assassinate him.","about":"In MURDER, the player takes the role of a scheming vizier who creeps up behind the king and tries to take him out quickly and quietly. If the king catches the assassin, the dungeon awaits. Succeeding makes the player the new king, but the adviser then plots against the crown. The game tests observation and reaction skills, and the roles can be reversed so the king watches for an attempt.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":360},{"type":"flash","id":"pinch-hitter-2","slug":"pinch-hitter-2","title":"Pinch Hitter 2","description":"Pinch Hitter 2 is a 2007 Mousebreaker baseball game where players swing at pitches and climb from the sandlot to the major leagues.","about":"Pinch Hitter 2 tests batting ability across a series of baseball challenges, starting at the sandlot and advancing through the little leagues before reaching the major leagues. Each league sets objectives, such as hitting two home runs in a row or making contact ten times without strikes or outs. A swing is made by clicking the left mouse button at the right moment, and moving the cursor adjusts the bat's position. Hitting a home run requires meeting the ball at the correct instant with the correct part of the bat, so early attempts often end in misses until timing improves.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":640,"height":480},{"type":"flash","id":"red-ball-platformer","slug":"red-ball-platformer","title":"Red Ball Platformer","description":"Red Ball Platformer is a 2009 side-view action game from Evgeniy Fedoseev in which a red ball rolls and jumps through 17 physics-driven levels.","about":"Red Ball Platformer is a side-view action game built on physics, released in 2009 by Evgeniy Fedoseev. The player guides a red ball across 17 levels filled with obstacles and hazards. Lifts and thorns appear along the way, as do axes, a catapult, and a stretch of sloping ground. Other elements include a ninja on a bridge and a Pacman figure, and the ball must jump and roll over them to get through.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":550,"height":400},{"type":"flash","id":"red-code-2","slug":"red-code-2","title":"Red Code 2","description":"Red Code 2 is a 2009 action shooter from PlayStival where a trooper defends beacons against an alien insect horde.","about":"Aliens of the insect variety are swarming toward the beacons, and the trooper's job is to hold them off and keep mankind safe. Upgrading the trooper raises the odds of surviving the assault. With enough upgrades, the trooper evolves into a highly effective killing machine.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":480},{"type":"flash","id":"riddle-transfer-2","slug":"riddle-transfer-2","title":"Riddle Transfer 2","description":"Riddle Transfer 2 is a 2016 point-and-click adventure by JonoChrome that closes out the long-running Riddle School story.","about":"Riddle Transfer 2 continues the Riddle School series and resolves the cliffhanger left open by Riddle Transfer five years earlier. It was created for people who already know the earlier entries, since the plot only makes full sense after playing or watching the previous six games. The developer prepared it in about a month and later fixed spelling and animation errors while adding minor features.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":800,"height":600},{"type":"flash","id":"robot-dinosaurs-that-shoot-beams-when-they-roar","slug":"robot-dinosaurs-that-shoot-beams-when-they-roar","title":"Robot Dinosaurs That Shoot Beams When They Roar","description":"Robot Dinosaurs That Shoot Beams When They Roar is a 2009 mouse-only shooter where roaring dinosaurs fire beams at enemies.","about":"Tom Brien (I-smel) created this action shooter in 2009. Players control robot dinosaurs and fire beams by making them roar, using only the mouse. The game is a single-player shoot 'em up with a dinosaur theme. It was made over a couple of weeks.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":400},{"type":"flash","id":"shift-2","slug":"shift-2","title":"SHIFT 2","description":"SHIFT 2 is a 2008 puzzle platformer from Armor Games and Antony Lavelle where gravity itself is not what it seems.","about":"SHIFT 2 continues the flipping action of the series, this time with gravity that does not behave as expected. Players work through a world built around that twist, shifting their perspective to solve what the game presents. It comes from Armor Games and Antony Lavelle.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":500,"height":500},{"type":"flash","id":"sik-trix-bmx","slug":"sik-trix-bmx","title":"Sik Trix BMX","description":"Sik Trix BMX is a 2003 sports game from EntropicOrder where riders pull off BMX tricks across rooftops and levels.","about":"Sik Trix BMX lets players ride a BMX bike off ramps and onto building rooftops while performing tricks. There are 13 characters, 35 tricks, 5 pre-made levels and a level editor. Landing tricks raises a Confidence Level up to five bars, which unlocks special moves worth more points, while crashing lowers it. Collecting power-ups increases the bike's top speed, and secret codes can be entered to continue progress.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":540,"height":400},{"type":"flash","id":"slacker","slug":"slacker","title":"Slacker","description":"Slacker is a 2003 adventure game by Sam Cook with a style reminiscent of Escape from Monkey Island.","about":"Slacker is an adventure game from 2003, made by Sam Cook as a first attempt at game development. It shares similarities with Escape from Monkey Island and is aimed at analytical players as well as lazy ones. The puzzles can be tough to work out, so a mini-walkthrough is built into the game itself.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"spongebob-squarepants-gone-fishing","slug":"spongebob-squarepants-gone-fishing","title":"SpongeBob SquarePants: Gone Fishing","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":600,"height":400},{"type":"flash","id":"super-stacker-2","slug":"super-stacker-2","title":"Super Stacker 2","description":"Super Stacker 2 is a 2009 puzzle game by Gaz Thomas where players balance shapes into a stable tower across dozens of levels.","about":"Super Stacker 2 returns with 40 new levels, four speedruns, and a stack editor, along with updated graphics. The goal is to arrange shapes so that none of them fall off the screen. Each stack has to hold for 10 seconds, or until the shapes are content that they will not topple. A stack editor lets players build and test their own arrangements.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":550},{"type":"flash","id":"unreal-flash","slug":"unreal-flash","title":"Unreal Flash","description":"Unreal Flash is a 2006 arena shooter from Armor Games where players fight through waves of enemies to survive the onslaught.","about":"Unreal Flash is an arena-based fighting game released in 2006 by Armor Games. Players battle through waves of enemies in a fight for survival, with a selection of weapons, boss characters, and arenas to face. An in-game menu can be opened by pressing the P key. The game was created with programming and graphics by Erik S. and Cicla.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":600,"height":400},{"type":"flash","id":"zed","slug":"zed","title":"Zed","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":700,"height":500},{"type":"flash","id":"a-small-favor","slug":"a-small-favor","title":"A Small Favor","description":"A Small Favor is a 2009 adventure game from Zeebarf and RiftMaster about an alien assassin sent to kill a Senator.","about":"Set in a far-off galaxy where people trade favors instead of money, this adventure game follows an assassin tasked with taking out a notable Senator. The choices made along the way affect the player's rank, and collecting favors is an optional side activity. Completing favors without being asked marks the player as a good Samaritan, though no credit is given for them.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":650,"height":450},{"type":"flash","id":"awesome-planes","slug":"awesome-planes","title":"Awesome Planes","description":"Awesome Planes is a 2012 action game from EmitterCritter in which a player's plane destroys rival aircraft and buys upgrades.","about":"Awesome Planes is an action game released in 2012 by EmitterCritter. The player controls a plane and uses it to destroy other planes that are less impressive. Upgrades can be purchased along the way, and the goal is to cause as much destruction as possible.","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":600},{"type":"flash","id":"battle-gear","slug":"battle-gear","title":"Battle Gear","description":"Battle Gear is a 2008 strategy game by Arief Raditya where players pick a superpower and command forces across land, sea and air.","about":"Players select one of three superpowers, the USA, Russia or China, and set out to conquer the world. Commanding military operations means sending troops into hostile territory by land, sea and air. Units are trained by clicking them or using number hotkeys, while the battlefield can be scrolled with the arrow or A and D keys, and the P key pauses play. The game was developed by Arief Raditya, also known as belugerin.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":480},{"type":"flash","id":"bunny-invasion","slug":"bunny-invasion","title":"Bunny Invasion","description":"Bunny Invasion is a 2007 action shooter where Mr Frost defends his village from cloned, angry rabbits using nine weapons across fifty levels.","about":"Evil bunnies have escaped from a nearby research facility and laid siege to a village. As resident Mr Frost, the player holds them off, choosing among nine weapons while upgrading both house and arsenal. The fifty levels feature eight bunny types, from suicide bombers to oversized pregnant rabbits that launch pink baby bunnies at the house. Completing the game unlocks a few extras for replay value.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":680,"height":500},{"type":"flash","id":"chibi-knight","slug":"chibi-knight","title":"Chibi Knight","description":"Chibi Knight is a 2010 action-adventure RPG from Nick Pasto and BoMToons, following a small warrior against three beasts.","about":"Three beasts have laid waste to the kingdom of Oukoku, and legend speaks of a small warrior destined to rescue it. Players take on that role in this action RPG, which centers on a series of boss fights. The battles are designed to be both enjoyable and demanding as the story moves toward the kingdom's salvation.","system":"Flash","genre":"adventure","categories":"adventure|action","core":"swf","width":640,"height":480},{"type":"flash","id":"combat-instinct","slug":"combat-instinct","title":"Combat Instinct","description":"Combat Instinct is a 2000 space shooter from McFretN that sends players through three distinct levels of action.","about":"Combat Instinct is a space shooter released in 2000 by McFretN. It contains three different levels to play through. The game can run slowly in some sections, so turning off the high quality setting may help performance. Its preloader is broken, meaning the game has to be started manually by right-clicking and choosing play once it appears ready.","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":550,"height":400},{"type":"flash","id":"corporation-inc","slug":"corporation-inc","title":"Corporation, Inc.","description":"Corporation, Inc. is a 2010 simulation game from Armor Games where players build offices, hire staff, and chase profit.","about":"Corporation, Inc. tasks players with constructing a push-button company from the ground up. Offices are built and workers hired to fill them, and pushing profit opens up research into upgrades and new items. Meeting goals brings rewards such as larger build sizes, additional options, and more tech trees for workers and offices. The camera moves with WASD or the arrow keys, while the mouse handles building and interaction.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":800,"height":500},{"type":"flash","id":"crystal-story","slug":"crystal-story","title":"Crystal Story","description":"Crystal Story is a 2011 turn-based RPG from developer Emmanuel Salva Cruz in which four heroes explore a randomly generated dungeon.","about":"Crystal Story is a turn-based RPG built around a randomly generated dungeon. The player directs a party of four characters and decides which skill sets each one learns as the journey continues. Better equipment can be earned by defeating monsters or by playing minigames, and that gear helps the group make its way through Evil Cave. Battles use the mouse, with keyboard shortcuts available during combat.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"detective-grimoire","slug":"detective-grimoire","title":"Detective Grimoire","description":"Detective Grimoire is a 2007 puzzle adventure where players gather clues and question suspects to crack a grim fairground murder.","about":"A grim murder at a fairground drives this puzzle adventure from 2007. Players search for clues and interrogate suspects, piecing together the evidence to uncover the truth. The game offers a range of characters and detailed locations to explore while working through its fiendish mystery.","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"doodle-defender","slug":"doodle-defender","title":"Doodle Defender","description":"Doodle Defender is a 2008 single-player shooter from developer Mike Varilek, built around action-packed shooting in the Doodle Defender series.","about":"Doodle Defender is a single-player shooter released in 2008 by Mike Varilek. It belongs to the Doodle Defender series and focuses on shooter and action gameplay.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":480},{"type":"flash","id":"dungeons-of-kong","slug":"dungeons-of-kong","title":"Dungeons of Kong","description":"Dungeons of Kong is a 2013 strategy adventure where players lead a hero team into a randomly generated dungeon.","about":"Jim, Greg, Emily, Mojo and Nerdook make up the hero roster, and each one brings a different set of skills to the group. Players put together a team from these characters and enter a dungeon whose layout is generated at random. The goal is to reach an Ancient Evil and destroy it before it awakens.","system":"Flash","genre":"strategy","categories":"strategy|adventure","core":"swf","width":720,"height":480},{"type":"flash","id":"elephant-quest","slug":"elephant-quest","title":"Elephant Quest","description":"Elephant Quest is a 2011 adventure RPG-shooter from jmtb02 and Jimp where an elephant hunts for a stolen bowler cap.","about":"Wooly has stolen a bowler cap, and the elephant sets out across a freeform world of 45 areas to take it back. The game mixes RPG and shooter elements: sidequests yield power-ups, extra firepower, and experience, and a level-up tree lets the elephant grow stronger. Art is by Jimp and programming by John Cooney.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":800,"height":500},{"type":"flash","id":"epic-war","slug":"epic-war","title":"Epic War","description":"Epic War is a 2008 single-player strategy game from ArtLogic Games, part of the Epic War series.","about":"Epic War is a strategy game released in 2008 by ArtLogic Games, played solo as part of the Epic War series. It focuses on strategic decision-making from a single-player perspective.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":700,"height":525},{"type":"flash","id":"flaming-zombooka","slug":"flaming-zombooka","title":"Flaming Zombooka","description":"Flaming Zombooka is a 2010 arcade game from LongAnimals and RobotJam in which players toss projectiles at zombies using only the mouse.","about":"Flaming Zombooka is a single-player arcade game released in 2010 by LongAnimals and RobotJam. Played with the mouse alone, it centers on tossing projectiles at zombies, with blood as part of the action.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":500},{"type":"flash","id":"haunt-the-house","slug":"haunt-the-house","title":"Haunt the House","description":"Haunt the House is a 2010 arcade game by The Super Flash Bros where a ghost scares party guests out of its home.","about":"A ghost wakes to discover its quiet house has been taken over by noisy party guests. By possessing objects around the home, the player frightens the visitors and drives them away. Each successful scare increases the ghost's power. Scaring guests too much can cause them to panic and act unpredictably.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":525},{"type":"flash","id":"horse","slug":"horse","title":"HORSE","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":600,"height":400},{"type":"flash","id":"imperium","slug":"imperium","title":"Imperium","description":"Imperium is a 2008 strategy game from Max Games about building a town, managing resources, and conquering nearby empires.","about":"Players begin by founding a town and placing their first building, then gather resources to construct more and expand across the land. Building placement matters, since structures such as lumber mills and iron mines need to sit near the resources they use. As the settlement grows, units can be created and later sent to wage war against neighboring empires. The goal is to spread influence and territory until only one empire remains.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":680,"height":480},{"type":"flash","id":"jellygo","slug":"jellygo","title":"JellyGo!","description":"JellyGo! is a 2013 strategy game from avoxgames in which players protect the Jelly Kingdom from powerful attackers.","about":"JellyGo! is a strategy game set in the Jelly Kingdom, which comes under attack from powerful enemies. Players push back against these foes by taking over enemy buildings, building superweapons, or holding defensive forts. There is more than one route to victory, and the choice of approach is left to the player.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":600},{"type":"flash","id":"kill-the-heroes","slug":"kill-the-heroes","title":"Kill the Heroes!","description":"Kill the Heroes! is a 2012 strategy game from Nerdook where players act as a supervillain defending a facility from invading heroes.","about":"Players take the role of a Supervillain Mastermind whose facility is being invaded by Heroes. The goal is to eliminate every Hero by placing defenses and researching upgrades. Different strategies can be tried to stop the attackers. It is a single-player strategy game with tower defense elements.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":678,"height":480},{"type":"flash","id":"mario-remix-boss-edition","slug":"mario-remix-boss-edition","title":"Mario Remix: Boss Edition","description":"Mario Remix: Boss Edition is a 2008 adventure game from Greg Vottero where players face 35 bosses from past series.","about":"Mario Remix: Boss Edition is an adventure game built around fighting 35 bosses drawn from past series alongside original ones. It includes an item system and original minigames. Most bosses take eight to twelve hits to defeat, and standing on a boss after it recovers causes damage. Players can visit an item shop to buy mushrooms that help them survive hits.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":725,"height":550},{"type":"flash","id":"meeblings-2","slug":"meeblings-2","title":"Meeblings 2","description":"Meeblings 2 is a 2009 puzzle game from Ninja Kiwi in which two new Meeblings help players work through 50 levels.","about":"Ninja Kiwi's Meeblings 2 is a puzzle game that continues the series with two new Meeblings. It offers 50 levels that were not in the earlier game. The sequel also brings new graphics and new sounds to the Meeblings' world.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":480},{"type":"flash","id":"momentum-missile-mayhem","slug":"momentum-missile-mayhem","title":"Momentum Missile Mayhem","description":"Momentum Missile Mayhem is a 2007 arcade defense game from dz2001 built on collision physics.","about":"Momentum Missile Mayhem is a defense game in which collision physics drive the action. The player crushes enemies against walls and against one another rather than relying on direct attacks. It was developed by dz2001 and released in 2007.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":600},{"type":"flash","id":"monster-brawl","slug":"monster-brawl","title":"Monster Brawl","description":"Monster Brawl is a 2014 strategy action game from Godlimations where two players can fight using mouse and keyboard controls.","about":"Monster Brawl is a strategy and action game released by Godlimations in 2014. In single-player mode, the mouse is the only control method. A two-player mode is also included, where the first player uses the WASD keys and H to confirm, while the second player relies on the mouse. The game was sponsored by ArmorGames.com.","system":"Flash","genre":"strategy","categories":"strategy|action","core":"swf","width":600,"height":500},{"type":"flash","id":"monster-legions","slug":"monster-legions","title":"Monster Legions","description":"Monster Legions is a 2013 strategy game from Nerdook where players build an army with cards and battle enemy forces.","about":"Command a force of soldiers and creatures in this strategy title from Nerdook. Troops are brought into battle through a summon system built around cards, letting players assemble a lineup before facing opponents. The goal is to overcome the evil Beast and demonstrate which legion is strongest.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":720,"height":480},{"type":"flash","id":"mutiny","slug":"mutiny","title":"Mutiny","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"pico-of-the-dark-ages","slug":"pico-of-the-dark-ages","title":"Pico of the Dark Ages","description":"Pico of the Dark Ages is a 2007 action game by mongoid and James Dalby, pitting Pico against the Evil Dark Wizard Allucardis.","about":"In Pico of the Dark Ages, the player controls Pico in a fight against the Evil Dark Wizard Allucardis and his Army of UberGoths. Combat uses arrow keys for movement, with separate buttons for attacking, blocking and a strong attack. Three bosses each follow a set pattern, and learning that pattern is the key to beating them. Blocking no longer costs health, and boss attack power was reduced in a later update.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":350},{"type":"flash","id":"roly-poly-cannon","slug":"roly-poly-cannon","title":"Roly-Poly Cannon","description":"Roly-Poly Cannon is a 2009 physics puzzle game by Johnny-K in which shots are aimed to solve each stage.","about":"Roly-Poly Cannon is a physics-based artillery puzzle from developer Johnny-K, released in 2009 as part of the Roly-Poly Cannon series. Played solo, it centers on aiming shots to work through its stages.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"shadez-2-battle-for-earth","slug":"shadez-2-battle-for-earth","title":"Shadez 2: Battle for Earth","description":"Shadez 2: Battle for Earth is a 2009 strategy game from Sean Cooper where a hired mercenary commander defends a ruined world.","about":"As the general of a mercenary army, the player is hired by world governments to wage a war they cannot win on their own. An unidentified machine enemy has already left many nations in ruins, and what remains of their defenses is limited. The fight is for the survival of Earth itself, with the player aiming to stop the machines and become the dominant force. Sean Cooper followed up Shadez: The Black Operations with this 2009 strategy title.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":700,"height":500},{"type":"flash","id":"sin-mark","slug":"sin-mark","title":"Sin Mark","description":"Sin Mark is a 2009 action RPG adventure in which Akahn travels toward the origin of a persistent evil.","about":"Akahn sets out to find where a persistent evil comes from in this action RPG from 2009. Along the way he must bring down the Dark Gates that release devils into the world. Rune Stones can be gathered and joined together, allowing stronger spells to be cast. Chris \"Con\" Condon and Armor Games made the game as a nod to earlier action RPGs.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":800,"height":460},{"type":"flash","id":"smileys-war","slug":"smileys-war","title":"Smileys War","description":"Smileys War is a 2007 action platformer where players customize a smiley fighter and battle through fast-paced shooting stages.","about":"Players shape their own smiley character and then head into combat across platforming stages. The action moves quickly, and ten different weapons are available to choose from. A single-player mode offers a series of challenges, and a map development kit lets players build their own levels. The game was developed by Interactive-Pixels and Louis-Simon Ménard.","system":"Flash","genre":"action","categories":"action","core":"swf","width":500,"height":375},{"type":"flash","id":"spindle","slug":"spindle","title":"Spindle","description":"Spindle is a 2003 action game from AngryBinary in which a fighter takes on Cobalt City thugs for a small-time mob boss.","about":"Spindle is the first chapter of an action series set in Cobalt City, where the player fights thugs while working for a small-time mob outfit. Combat mixes guns, melee strikes and jumping, with combos built from timed button presses that can finish weakened enemies. Practice and Molotov Maelstrom minigames offer a way to warm up or dodge a hail of fire. Options let players adjust enemy numbers and difficulty before starting.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":400},{"type":"flash","id":"toms-trap-o-matic","slug":"toms-trap-o-matic","title":"Tom’s Trap-O-Matic","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":400},{"type":"flash","id":"totally-spies-shooter","slug":"totally-spies-shooter","title":"Totally Spies! Shooter","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":600,"height":400},{"type":"flash","id":"xenos","slug":"xenos","title":"Xenos","description":"Xenos is a 2011 action game from Oddity in which a pilot in a Xenos-powered battle-suit fights robots across 30 levels.","about":"A rogue scientist named Dr Crenson has used a new energy source, Xenos, to build a mechanical city and a robot army that threatens the earth. The player pilots Asterus, a battle-suit powered by Xenos energy, and must fight through 30 levels spread over 7 areas. Along the way are deadly bosses, minefields and giant lasers to get past. Finishing the game unlocks Survival mode, with endless waves, and Mission X.","system":"Flash","genre":"action","categories":"action","core":"swf","width":720,"height":480},{"type":"flash","id":"you-got-stuffed-and-served","slug":"you-got-stuffed-and-served","title":"You Got Stuffed and Served!","description":"You Got Stuffed and Served! is a 2006 arcade game from Corus Entertainment where Lil' Drumstix faces King Dindon Furious.","about":"In this arcade title, the player matches moves against King Dindon Furious. The outcome decides whether Lil' Drumstix has game or is simply lame. Feathers are said to fly during the contest.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"avoid-or-destroyed","slug":"avoid-or-destroyed","title":"Avoid or Destroyed","description":"Avoid or Destroyed is a 2009 arcade game from CrazyEgg where players steer an orb away from attacking enemies using the mouse.","about":"In Avoid or Destroyed, the player guides an orb around the screen with the mouse, keeping it clear of enemies that bombard it from various directions. Powerups can be collected to extend the orb's life span and build up a higher score. Results can be posted to a high score table, letting players compare their performance with others.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"bubble-struggle","slug":"bubble-struggle","title":"Bubble Struggle","description":"Bubble Struggle is a 2002 arcade shooter by Kresimir Cvitanovic where you pop bubbles while avoiding them.","about":"In Bubble Struggle, you control a character who must pop bubbles while avoiding them. The game uses the arrow keys to move and the spacebar to shoot. It was first released as Bubble Trouble but was renamed after a copyright claim. The character is a little devil, though players have guessed it might be a cat, pig, or alien. The idea came from Capcom's Superpang arcade game.","system":"Flash","genre":"shooter","categories":"shooter|arcade","core":"swf","width":700,"height":450},{"type":"flash","id":"bush-shoot-out","slug":"bush-shoot-out","title":"Bush Shoot-Out","description":"Bush Shoot-Out is a 2004 single-player shooter from MiniClip in which the player must get Bush and Condoleezza out of the White House alive.","about":"Bush Shoot-Out is a single-player shooter released by MiniClip in 2004. The goal is to guide Bush and Condoleezza safely out of the White House. The game carries tags for politics, blood, and famous people.","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":600,"height":420},{"type":"flash","id":"catscratch-this-means-war","slug":"catscratch-this-means-war","title":"Catscratch: This Means War!","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":300},{"type":"flash","id":"ed-edd-n-eddy-spin-stadium","slug":"ed-edd-n-eddy-spin-stadium","title":"Ed, Edd n Eddy: Spin Stadium","description":"Ed, Edd n Eddy: Spin Stadium is a 2002 Cartoon Network arcade game where players pick an Ed and battle other spinning tops.","about":"Players take control of one of the Eds and enter a spinning top competition. The goal is to knock the other tops out of play. Each match is a single-player arcade contest based on the cartoon series.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":432,"height":330},{"type":"flash","id":"four-second-fury","slug":"four-second-fury","title":"Four Second Fury","description":"Four Second Fury is a 2006 creative game by John Cooney where players tackle twenty rapid microgames, each lasting four seconds or less.","about":"Four Second Fury packs twenty different microgames into a single collection, and each one lasts no longer than four seconds. The games load in a random order, so the sequence changes from playthrough to playthrough. Controls stay simple, relying on the arrow keys and the space bar. That minimal setup keeps attention on reacting quickly as each short challenge appears and ends almost immediately.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":550,"height":400},{"type":"flash","id":"full-moon","slug":"full-moon","title":"Full Moon","description":"Full Moon is a 2009 point-and-click puzzle game by Bart Bonte in which a rabbit pursues its desires under the fullest moon.","about":"A rabbit has desires, and the fullest moon hangs overhead. The player explores the scene by pointing, clicking, dragging and dropping to bring the rabbit satisfaction. This puzzle game comes from Bart Bonte and dates to 2009.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":600},{"type":"flash","id":"gun-run","slug":"gun-run","title":"Gun Run","description":"Gun Run is a 2005 shooter from Felix Reidl in which survival depends on firing at everything that moves while the score climbs.","about":"Gun Run is an action shooter built around staying alive. The player fires at everything in the game, and survival is the main goal. The longer a run lasts, the more points are earned, so time itself is the measure of success.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":600,"height":400},{"type":"flash","id":"handy-manny-hop-up-jump-in","slug":"handy-manny-hop-up-jump-in","title":"Handy Manny: Hop Up, Jump In!","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":480,"height":360},{"type":"flash","id":"hapland-2","slug":"hapland-2","title":"Hapland 2","description":"Hapland 2 is a 2005 point-and-click puzzle game by Robin Allen in which the player lights two torches on a wheel.","about":"The goal in Hapland 2 is to light the two torches mounted on a wheel, using whatever objects are found in the surrounding scene. Some of those objects serve no purpose, so part of the task is working out which ones matter. Success depends on both logic and synchronization, since the solution relies on getting events to line up correctly.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":750,"height":500},{"type":"flash","id":"hero-rpg","slug":"hero-rpg","title":"Hero RPG","description":"Hero RPG is a 2007 action role-playing game by Michael Neumann where players pick a Warrior, Ranger, or Mage for a large adventure.","about":"Hero RPG lets the player choose between three classes: Warrior, Ranger, or Mage. Movement uses WASD, while the spacebar enters Battle Stance and acts as the action button, with the mouse used to attack and shift to pick up items. The adventure sends the player across battlefields against hordes of evil, with quests, secrets, and enemies to find. Reaching the Imperial City with the eternal orb marks the furthest point in the game.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":600},{"type":"flash","id":"hex-empire","slug":"hex-empire","title":"Hex Empire","description":"Hex Empire is a 2009 strategy game from MetaSauce set in an abstract world that echoes the realities of the World Wars.","about":"Hex Empire is a hex-based strategy game set in an abstract world that loosely resembles the conditions of World War I and World War II. Its rules are simple and are explained in the in-game help, but the gameplay is absorbing. Battles unfold across thousands of generated maps, and the game is a little similar to Risk.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":600},{"type":"flash","id":"magma-mayhem","slug":"magma-mayhem","title":"Magma Mayhem!","description":"Magma Mayhem! is a 2008 arcade game from Sun-Studios where players dodge falling magma and chase a high score.","about":"In Magma Mayhem!, the player moves left and right to avoid rocks of falling magma. Surviving longer raises the score, and the player starts with three lives; each hit costs one life. The run ends when all three lives are gone, and the score can then be submitted to an online leaderboard.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":650},{"type":"flash","id":"mickey-and-friends-super-racer","slug":"mickey-and-friends-super-racer","title":"Mickey and Friends: Super Racer","description":"Mickey and Friends: Super Racer is a 2008 Disney racing game where collecting lightning volts keeps your car charged during the race.","about":"This racing game from Disney features Mickey and Friends behind the wheel. As the car moves along the track, the player gathers lightning volts to keep the battery charged. Missing a volt drains power, so staying on top of every pickup matters. The challenge comes from balancing speed with collecting enough volts to keep the battery from running down.","system":"Flash","genre":"racing","categories":"racing","core":"swf","width":530,"height":345},{"type":"flash","id":"nuclear-eagle","slug":"nuclear-eagle","title":"Nuclear Eagle","description":"Nuclear Eagle is a 2007 action game from C404 in which players feed their babies and protect them when the food fights back.","about":"In Nuclear Eagle, the goal is to keep babies healthy and happy by giving them their favorite meal. The food eventually starts to fight back, so players must protect the babies for as long as possible. The game was developed by C404, with programming by Brad Borne and art and concept by luksy. It began as an idea by luksy in November 2005 and was later rewritten from scratch with a new gameplay style.","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":480},{"type":"flash","id":"replicat","slug":"replicat","title":"RepliCat","description":"RepliCat is a 2009 arcade game from Mindless Labs where players dodge copies of their own past selves while gathering items.","about":"RepliCat is an arcade game released in 2009 by Mindless Labs. The player collects essentials while avoiding past versions of themselves that appear during play. It draws partial inspiration from the game Time4Cat. The challenge comes from managing movement so earlier selves do not cause trouble.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"sesame-street-a-spotty-day-on-sesame-street","slug":"sesame-street-a-spotty-day-on-sesame-street","title":"Sesame Street: A Spotty Day on Sesame Street","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":306},{"type":"flash","id":"sesame-street-lets-grovercise","slug":"sesame-street-lets-grovercise","title":"Sesame Street: Let’s Grovercise!","system":"Flash","genre":"sports","categories":"sports|educational","core":"swf","width":600,"height":307},{"type":"flash","id":"shadez-the-black-operations","slug":"shadez-the-black-operations","title":"Shadez: The Black Operations","description":"Shadez: The Black Operations is a 2008 strategy game where players command a mercenary force hired for secret wars.","about":"Players take charge as a general leading a mercenary group that governments employ for conflicts they prefer to keep hidden. The task involves deploying troops, hardware, and airstrikes against an unconventional enemy army to eliminate it. Success leads to further missions and wars. Developer Sean Cooper aimed to create a simple real-time strategy game that still captures the essence of larger RTS titles, offering a distinct take on the genre.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":700,"height":550},{"type":"flash","id":"sled-shredding","slug":"sled-shredding","title":"Sled Shredding","description":"Sled Shredding is a 2009 arcade platformer from kChamp Games where arrow keys steer and the spacebar handles jumping.","about":"Sled Shredding is an arcade platformer released in 2009 by kChamp Games. Movement is handled with the arrow keys, while the spacebar makes the character jump. The game mixes sledding action with platforming challenges across its stages.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":800,"height":540},{"type":"flash","id":"sports-dude","slug":"sports-dude","title":"Sports Dude","description":"Sports Dude is a 2004 educational game from Sports Illustrated Kids about keeping a character fit, fed and happy.","about":"Players take charge of a character called Sports Dude, choosing what he eats and how he spends his time. Options range from pizza or salad to watching television, shooting hoops, sleeping or skateboarding. Each decision affects his health, hunger and mood, and the game ends if he is overfed, starved or bored. The activities and food on the left side of the screen are used to keep him in good shape, but too much of any one thing causes problems.","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":320,"height":240},{"type":"flash","id":"superfighters","slug":"superfighters","title":"Superfighters","description":"Superfighters is a chaotic 2011 action platformer by Mythologic Interactive where tiny fighters shoot, stab and smash each other.","about":"Superfighters is a physics-driven action platformer for one or two players. Matches are deliberately unfair: spawn points, weapon drops and map objects appear at random, and gunfire can land critical hits by chance, so chaos rather than balance drives each round. Thirteen weapons and four maps are included, along with bullet time powerups to grab during combat. A Stage Mode can be completed to unlock a new player skin, and a Survival Mode pits solo or co-op players against endlessly spawning enemies.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":600},{"type":"flash","id":"the-flood-runner","slug":"the-flood-runner","title":"The Flood Runner","description":"The Flood Runner is a 2010 arcade runner from Ben Rad Vinyl, part of the Flood Runner series and built for single-player play.","about":"The Flood Runner is an arcade runner from 2010, developed by Ben Rad Vinyl as part of the Flood Runner series. It is a single-player game in which the player takes on the runner format.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":750,"height":400},{"type":"flash","id":"this-is-the-only-level","slug":"this-is-the-only-level","title":"This Is The Only Level","description":"This Is The Only Level is a 2009 puzzle platformer by John Cooney where a single level is replayed under constantly changing rules.","about":"The elephant has forgotten every level except one, so the whole game takes place in that same room. Each attempt changes how the space works, and the player has to work out the new rules before they can move ahead. Beating the level means relying on familiarity with games and quick hands rather than memorising new layouts.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":700,"height":500},{"type":"flash","id":"vertical-drop-heroes","slug":"vertical-drop-heroes","title":"Vertical Drop Heroes","description":"Vertical Drop Heroes is a 2010 platformer from Nerdook in which players descend through a randomly generated world to rescue princesses.","about":"Players take control of one of five heroes and set out to rescue princesses, descending through a world that is generated anew each time. Along the way they can unlock artifacts that grant new powers to each hero, and collect masks that change a character's appearance. A two-player mode lets a friend or the AI join in. The game was developed by Nerdook in 2010.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":550,"height":500},{"type":"flash","id":"who-wants-to-be-a-millionaire","slug":"who-wants-to-be-a-millionaire","title":"Who Wants To Be A Millionaire?","system":"Flash","genre":"quiz","categories":"quiz","core":"swf","width":676,"height":536},{"type":"flash","id":"windows-xp-parody","slug":"windows-xp-parody","title":"Windows XP Parody","description":"Windows XP Parody is a 2002 simulation from Smoothstudios that recreates the look of the operating system with sounds, icons, and a start menu.","about":"This simulation from Smoothstudios offers a parody of Windows XP, built with its own icons, sounds, and start menu. Players can explore the interface and search for a few hidden files tucked away inside. The experience may prove annoying to some users. It also asks where Bill Gates should go today.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":500,"height":375},{"type":"flash","id":"a-koopas-revenge","slug":"a-koopas-revenge","title":"A Koopa’s Revenge","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":400},{"type":"flash","id":"arkandian-legends-1-crusade","slug":"arkandian-legends-1-crusade","title":"Arkandian Legends 1: Crusade","description":"Arkandian Legends 1: Crusade is a 2010 adventure game by Noxins where players pick a side in a war between heaven and hell.","about":"In this adventure from Noxins, the player is caught in a conflict between heaven and hell and must pick a side, a decision that shapes the world's fate. Time can be spent exploring dungeons for loot, protecting the kingdom alongside companions, or crafting powerful artifacts at a forge. Choices made along the way affect how the story unfolds. Achievements, skills, items and victories carry over between games in the Arkandian Legends series, opening up new features and advantages.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"choose-your-weapon-3","slug":"choose-your-weapon-3","title":"Choose Your Weapon 3","description":"Choose Your Weapon 3 is a 2008 arcade action game from Glowmonkey, part of the Choose your Weapon series, built for single-player play.","about":"Choose Your Weapon 3 is an arcade action game released in 2008 by Glowmonkey, continuing the Choose your Weapon series. It is a single-player experience with a primate theme, played from an arcade perspective.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"drivers-ed-direct-parking-game","slug":"drivers-ed-direct-parking-game","title":"Drivers Ed Direct: Parking Game","description":"Drivers Ed Direct: Parking Game is a 2006 simulation that lets players practice parallel parking and lot challenges.","about":"This driving simulation from Drivers Ed Direct gives players a chance to work on parallel parking and parking lot maneuvers across four levels. Players take the wheel of a Toyota Prius, line up the car, turn the tires correctly, and ease into the space. The game offers a low-pressure setting for building parking skills, and bumping another vehicle does not trigger an alarm.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"dungeon-developer","slug":"dungeon-developer","title":"Dungeon Developer","description":"Dungeon Developer is a 2010 strategy game from Nerdook in which the player builds and runs the dungeon rather than exploring it.","about":"In this twist on the dungeon crawler, the player takes the role of the dungeon itself. The goal is to construct the strongest possible dungeon and equip adventurers with a broad selection of magic items. The ultimate objective is to defeat the Red Dragon waiting on the dungeon's deepest level.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":550,"height":650},{"type":"flash","id":"effing-hail","slug":"effing-hail","title":"Effing Hail","description":"Effing Hail is a 2009 arcade game from Jiggmin and Greg Wohlwend in which players grow hailstones and throw them at targets.","about":"In this arcade title, the player forms large chunks of hail and launches them at a range of targets. Houses, buildings, planes and satellites are among the things that can be destroyed. The aim is to build up the hail and then send it flying at whatever stands in the way.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":700},{"type":"flash","id":"exmortis","slug":"exmortis","title":"Exmortis","description":"Exmortis is a 2004 point-and-click horror adventure by Ben Leffler in which an amnesiac wanders into a house that offers far worse than the cold outside.","about":"The player takes the role of someone who comes to in the woods with no recollection of arriving there, haunted by visions of blood and screaming. With darkness closing in and the temperature dropping, a house across a clearing becomes the only available refuge. Once inside, it becomes clear that the things waiting there make dying seem preferable. Ben Leffler built the game around atmosphere and detailed artwork rather than puzzles alone, and it was his first project in the medium.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"infectonator","slug":"infectonator","title":"Infectonator!","description":"Infectonator! is a 2009 strategy game by Toge Productions where each level gives 60 seconds to infect enough people and turn them into zombies.","about":"In Infectonator!, the goal in every level is to infect a set number of people and transform them into zombies. A strict 60-second time limit applies to each attempt, so the work has to be done quickly. The game was developed by Toge Productions and falls into the strategy genre.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":700,"height":500},{"type":"flash","id":"jungle-fruit","slug":"jungle-fruit","title":"Jungle Fruit","description":"Jungle Fruit is a 2005 puzzle game from Jetacer Interactive built around numbered barrels that players must clear.","about":"Jungle Fruit is a puzzle game from Jetacer Interactive, released in 2005. Play centers on numbered barrels, which form the basis of the game's challenges. It is designed as an addictive puzzle experience.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":560,"height":400},{"type":"flash","id":"monster-slayers","slug":"monster-slayers","title":"Monster Slayers","description":"Monster Slayers is a 2010 action strategy game from Nerdook where a five-member band hunts down monsters across the land.","about":"In Monster Slayers, the player commands a small group of five characters on a campaign to wipe out every monster in the land. The 2D strategy action game includes randomly generated quests and twelve boss encounters. It follows Nerdook's earlier Bongo Boom Battlegrounds, keeping that game's strengths while dropping its rhythm elements.","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":500},{"type":"flash","id":"my-pet-protector","slug":"my-pet-protector","title":"My Pet Protector","description":"My Pet Protector is a 2009 adventure game about guiding an apprentice's future through jobs, schooling and dungeon trips.","about":"Players take charge of a young apprentice and decide how his life unfolds. He can be given work, enrolled in school, or sent into dungeons, where he may come back with treasure or injuries. The choices made along the way determine whether he becomes a celebrated hero or a forgotten failure, and whether his path leads to life as a warrior or a poet.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"nightmares-the-adventures-episode-4-the-stolen-souvenirs-of-rob-r","slug":"nightmares-the-adventures-episode-4-the-stolen-souvenirs-of-rob-r","title":"Nightmares, the Adventures Episode 4: The Stolen Souvenirs of Rob.R","description":"Nightmares, the Adventures Episode 4: The Stolen Souvenirs of Rob.R is a 2006 point-and-click adventure from Sarbakan.","about":"This single-player point-and-click adventure continues the Nightmares, the Adventures series, released in 2006 by Sarbakan. Players work through an adventure scenario by clicking around the game world.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":675,"height":400},{"type":"flash","id":"nuclear-outrun","slug":"nuclear-outrun","title":"Nuclear Outrun","description":"Nuclear Outrun is a 2012 Nerdook shooter-racer where trucks flee a nuclear missile, blasting obstacles and zombies on the way to the exit.","about":"In Nuclear Outrun, a truck races toward the exit while a nuclear missile closes in from behind. Obstacles and zombies block the route, and the player blasts them out of the way. Points earned during the run feed a leveling system that unlocks new abilities and weapons. A 20 Truck Run provides a high score to beat, and repeated play can also be used to unlock every weapon.","system":"Flash","genre":"shooter","categories":"shooter|racing","core":"swf","width":600,"height":400},{"type":"flash","id":"pepe-le-pews-love-run","slug":"pepe-le-pews-love-run","title":"Pepe Le Pew’s Love Run","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"plazma-burst-forward-to-the-past","slug":"plazma-burst-forward-to-the-past","title":"Plazma Burst: Forward to the Past","description":"Plazma Burst: Forward to the Past is a 2009 action game from SiBiTrix and Eric Gurt about a time-travel mission gone wrong.","about":"Scientists on Earth build a time machine and choose two volunteers to travel into the past and alter history. The player takes the role of one of those volunteers, but the trip does not go as planned. The destination is not the intended one, and the time period may be wrong as well.","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":400},{"type":"flash","id":"rabbit-rustler","slug":"rabbit-rustler","title":"Rabbit Rustler","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":650,"height":450},{"type":"flash","id":"radio-zed","slug":"radio-zed","title":"Radio Zed","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":480},{"type":"flash","id":"scooby-doo-and-the-creepy-castle","slug":"scooby-doo-and-the-creepy-castle","title":"Scooby-Doo and the Creepy Castle","description":"Scooby-Doo and the Creepy Castle is a 2003 Cartoon Network puzzle game where players help Scooby rescue the gang.","about":"In this 2003 Cartoon Network puzzle game, players guide Scooby-Doo through a creepy castle setting in a side-view adventure. The goal is to rescue the rest of the gang from the King's Ghost. Play is mouse-only and aimed at a single player.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":432,"height":330},{"type":"flash","id":"scriball","slug":"scriball","title":"Scriball","description":"Scriball is a 2009 puzzle game where players draw a path for a rolling ball to follow across dozens of levels.","about":"Scriball is a puzzle game in which the player draws a line for a ball to roll along. The ball can pass upward through the drawn line but not downward, so the path can be used as a one-way surface. The game contains 43 levels, a boss battle, and extra levels that unlock after completing it with all three balls. High scores and a level editor are also included. Smooth curves help the ball keep its momentum, and a V shape can trap it.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":550},{"type":"flash","id":"simpleton","slug":"simpleton","title":"Simpleton","description":"Simpleton is a 2007 side-scrolling shooter where players use an arsenal of weapons to fight off waves of zombies.","about":"Simpleton began as a physics engine test before becoming a full action shooter. Players move and jump with the WASD keys, aim with the mouse, and switch between weapons using the number keys. The game focuses on zombie shooting rather than story, and includes graphics options to help performance on slower machines. To defeat the final boss, players must stun him with the RPG and then use the chainsaw.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":600,"height":300},{"type":"flash","id":"sinjid-shadow-of-the-warrior","slug":"sinjid-shadow-of-the-warrior","title":"Sinjid: Shadow of the Warrior","description":"Sinjid: Shadow of the Warrior is a 2004 action RPG where you guide the ninja Sinjid toward the Dark Portal.","about":"In this combat-focused role-playing game from 2004, the player takes the role of Sinjid, a ninja. Progress toward the Dark Portal involves using a variety of items and skills along the way. The journey ends with difficult boss encounters. It was developed by InfraRift and Krin.","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":470},{"type":"flash","id":"snake-runner","slug":"snake-runner","title":"Snake Runner","description":"Snake Runner is a 2009 arcade game from kChamp Games that puts a new spin on the classic snake formula across 25 levels.","about":"This arcade title from kChamp Games takes the familiar snake concept and builds 25 levels around it. Each stage asks the player to collect every coin on the board before reaching the finish line to move on. Fast reflexes matter, since the levels are designed to test how quickly players can react.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":550},{"type":"flash","id":"sock-and-awe","slug":"sock-and-awe","title":"Sock and Awe","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":709,"height":383},{"type":"flash","id":"solitaire","slug":"solitaire","title":"Solitaire","description":"Solitaire is a puzzle game that brings the classic card pastime to the screen, challenging players to order the deck.","about":"Solitaire is a puzzle game based on the classic card game. Players work with a deck of cards, arranging them into ordered piles. The game follows the familiar rules of the traditional pastime.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":560},{"type":"flash","id":"stickwar2","slug":"stickwar2","title":"Stick War 2","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":850,"height":700},{"type":"flash","id":"super-mega-ultra-battle-robot-2-0","slug":"super-mega-ultra-battle-robot-2-0","title":"Super Mega Ultra Battle Robot 2.0","description":"Super Mega Ultra Battle Robot 2.0 is a 2014 shooter from Nerdook in which players build a mecha and take on enemy forces.","about":"Players assemble a custom mecha and send it into battle against enemy forces. New upgrades can be unlocked along the way, and the fighting builds toward confrontations with randomised bosses. Defeating them brings total victory. The game was developed by Nerdook and released in 2014.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":720,"height":480},{"type":"flash","id":"super-samurai-sweeper","slug":"super-samurai-sweeper","title":"Super Samurai Sweeper","description":"Super Samurai Sweeper is a 2012 adventure game from Nerdook in which a samurai fights the Seven Daimyos and their Shogun.","about":"The player takes the role of a samurai with the goal of defeating the Seven Daimyos and their Shogun, which would restore peace to the land. Battles must be chosen with care rather than fought blindly. Super Samurai Sweeper was developed by Nerdook in 2012.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":678,"height":480},{"type":"flash","id":"treasure-seas-incorporated","slug":"treasure-seas-incorporated","title":"Treasure Seas Incorporated","description":"Treasure Seas Incorporated is a 2008 arcade action game from Felix Wiesner where players upgrade a submarine and search for treasure.","about":"Treasure Seas Incorporated is an arcade action game released in 2008 by Felix Wiesner. The player controls a submarine that can be upgraded, and the main goal is to hunt for treasure. The combination of submarine upgrades and treasure hunting gives the game its distinct focus.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"windosill","slug":"windosill","title":"Windosill","description":"Windosill is a 2009 single-player puzzle game from Vectorpark and Patrick Smith, presenting its challenges in a 3D style.","about":"Windosill is a puzzle game from Vectorpark and Patrick Smith, released in 2009. It is played by one person, and its puzzles are presented in a 3D style.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":900,"height":680},{"type":"flash","id":"wubbzys-underwater-adventure","slug":"wubbzys-underwater-adventure","title":"Wubbzy’s Underwater Adventure","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":340},{"type":"flash","id":"alien-attack","slug":"alien-attack","title":"Alien Attack","description":"Alien Attack is a 2003 shooter from MiniClip and X-Pressive in which the player identifies the alien responsible for a plot to destroy Earth.","about":"An alien has plotted to destroy the planet, and the player must work out which one is guilty. Play unfolds as a shooter with action elements, released in 2003 by MiniClip and X-Pressive. Light and its properties form the basis of the investigation that stands between Earth and its destruction.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":460},{"type":"flash","id":"antipacman","slug":"antipacman","title":"AntiPacman","description":"AntiPacman, a 2007 strategy arcade game by D-Mah and Dmitry Zheltobriukhov, flips the maze chase by putting the ghosts under the player's control.","about":"In this reversal of the classic maze chase, the player commands the ghosts rather than the dot-eater. The objective is to catch Pacman before every dot on the board is gone. Arrow keys steer whichever ghost is active, and the 1-2-3-4 keys swap between the four ghosts. A ghost that gets eaten is gone for good, so keeping them safe while they turn blue is part of the strategy.","system":"Flash","genre":"strategy","categories":"strategy|arcade","core":"swf","width":450,"height":550},{"type":"flash","id":"boxhead","slug":"boxhead","title":"Boxhead","description":"Boxhead is a 2006 action shooter by Sean Cooper where players battle endless waves of zombies across unlimited levels.","about":"Set during Halloween, Boxhead is a shooter in which the player fights off zombies. The levels never end, and the first seven stages gradually unlock a variety of weapons. Zombies grow quicker as the game goes on, eventually appearing in huge numbers. Civilians stay away from the undead out of fear, so the player must clear a path and keep it open. The game calls for a capable computer.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":480},{"type":"flash","id":"choose-your-weapon-2","slug":"choose-your-weapon-2","title":"Choose Your Weapon 2","description":"Choose Your Weapon 2 is a 2008 arcade action game from Glowmonkey, part of the Choose your Weapon series and played solo.","about":"Choose Your Weapon 2 is an arcade action game released in 2008 by Glowmonkey, forming part of the Choose your Weapon series. It is built for single player sessions and features a primate theme, with arcade style action driving the experience.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"cursor10","slug":"cursor10","title":"Cursor*10","description":"Cursor*10 is a 2008 arcade game by Nekogames and Yoshio Ishii in which players click stairs to climb toward the sixteenth floor.","about":"The goal in Cursor*10 is to reach the sixteenth floor by clicking on stairs. Each click moves the climb along, and the game is played entirely with the mouse. Nekogames and Yoshio Ishii released it in 2008 as an arcade title.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"disorderly-shady-acorns","slug":"disorderly-shady-acorns","title":"Disorderly: Shady Acorns","system":"Flash","genre":"action","categories":"action","core":"swf","width":750,"height":480},{"type":"flash","id":"ducklife-4","slug":"ducklife-4","title":"DuckLife 4","description":"DuckLife 4 is a 2012 simulation game from Wix Games where players raise and prepare ducks for racing competition.","about":"Players take charge of a group of ducks and get them ready to compete in races. Progress comes through training and upgrades as the birds work toward the highest level of the duck racing championship. The game is presented from a side view with cartoon visuals, and it is the fourth entry in the Duck Life series.","system":"Flash","genre":"simulation","categories":"simulation|arcade","core":"swf","width":750,"height":480},{"type":"flash","id":"field-command","slug":"field-command","title":"Field Command","description":"Field Command is a 2005 strategy game by BARMan in which the player directs troops toward victory in Vietnam.","about":"Field Command is a single-player strategy game set during the Vietnam War. The player gives orders to troops with the goal of winning the battle. Selections in the game are made using the mouse. It was developed by BARMan and released in 2005.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":550,"height":200},{"type":"flash","id":"guy-of-my-dreams","slug":"guy-of-my-dreams","title":"Guy of My Dreams","description":"Guy of My Dreams is a 2010 arcade game by Nerdook where players search for their ideal man and gather Happiness before turning 50.","about":"Made by Nerdook in 2010, this arcade title has a cute visual style and was created as a short experiment in making games aimed at a girlier audience. Players move with the arrow keys and spacebar, or with the mouse, to find a guy matching their dream partner. The goal is to collect as much Happiness as possible before the character reaches age 50.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":500},{"type":"flash","id":"ice-age-dawn-of-the-dinosaurs-memory-game","slug":"ice-age-dawn-of-the-dinosaurs-memory-game","title":"Ice Age: Dawn of the Dinosaurs – Memory Game","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":760,"height":560},{"type":"flash","id":"ignite-people-on-fire","slug":"ignite-people-on-fire","title":"Ignite people on Fire","description":"Ignite people on Fire is a 2008 arcade action game from Sun-Studios, built around score-attack play for a single player.","about":"Ignite people on Fire is an arcade action game released in 2008 by Sun-Studios. It is a single-player score-attack experience, part of the People on Fire series, and it carries an epilepsy warning.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":700,"height":400},{"type":"flash","id":"legends-of-kong","slug":"legends-of-kong","title":"Legends of Kong","description":"Legends of Kong is a 2011 action platformer RPG from Nerdook in which a party crosses a randomly generated city.","about":"Nerdook's Legends of Kong mixes action platforming with RPG elements. The player guides a party through a city that is generated randomly each time, choosing between a violent approach, a stealthy one, or something in between. The game offers 96 upgrades, 36 weapons, and a cast of different characters. Movement uses the WSAD or arrow keys, firing is mapped to Spacebar or X, and Q switches weapons, with Escape opening the pause menu.","system":"Flash","genre":"action","categories":"action","core":"swf","width":678,"height":480},{"type":"flash","id":"mario-mushroom-adventure-2","slug":"mario-mushroom-adventure-2","title":"Mario Mushroom Adventure 2","description":"Mario Mushroom Adventure 2 is a 2013 platformer from King of Games that continues the mushroom-themed journey of its predecessor.","about":"In this sequel from King of Games, players once again guide Mario through a mushroom-themed platforming adventure. The game picks up after the events of the first Mario Mushroom Adventure, where Mario managed to survive. Players join him for this second outing in the series.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":560,"height":525},{"type":"flash","id":"meeblings","slug":"meeblings","title":"Meeblings","description":"Meeblings is a 2008 puzzle game from Ninja Kiwi in which players use the creatures' abilities to save as many as they can.","about":"Each stage in Meeblings presents a group of small creatures that need rescuing, and the player relies on the different abilities those creatures possess to bring them to safety. The goal on every level is to save as many Meeblings as possible. Across 50 stages, the game takes players through the world these characters inhabit. Ninja Kiwi developed the title in 2008.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":480},{"type":"flash","id":"oobi-letters","slug":"oobi-letters","title":"Oobi Letters","description":"Oobi Letters is a 2003 educational quiz from This Is Pop in which young players build language skills with the Oobi characters.","about":"Oobi Letters is a single-player educational quiz from 2003, developed by This Is Pop and based on the Oobi series. It uses live-action footage and voice acting to teach language skills, and everything is controlled with the mouse alone.","system":"Flash","genre":"quiz","categories":"quiz|educational","core":"swf","width":565,"height":310},{"type":"flash","id":"samba-de-mausland","slug":"samba-de-mausland","title":"Samba De Mausland","description":"Samba De Mausland is a 2003 arcade game from Felix Wiesner and Mausland Entertainment in which players click samba shakers before they vanish.","about":"Samba De Mausland is an arcade game built around clicking samba shakers before they disappear. The 2003 title comes from developer Felix Wiesner (Wiesi) and Mausland Entertainment. It carries an epileptic warning, so players sensitive to flashing visuals should take care. The goal is simply to catch each shaker in time.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"sesame-street-dress-grover","slug":"sesame-street-dress-grover","title":"Sesame Street: Dress Grover","description":"Sesame Street: Dress Grover is a 2002 creative dress-up toy from Sesame Workshop for one player.","about":"Sesame Street: Dress Grover is a single-player dress-up toy from Sesame Workshop, released in 2002 as part of the Sesame Street series. Players choose outfits for Grover in a creative, open-ended activity built around the character.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":600,"height":306},{"type":"flash","id":"sesame-street-seasons","slug":"sesame-street-seasons","title":"Sesame Street: Seasons","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":600,"height":307},{"type":"flash","id":"sprout","slug":"sprout","title":"Sprout","description":"Sprout is a 2007 adventure game from Custom-Logic and Jeff Nusz in which a character moves, jumps and fires arrows.","about":"Sprout is an adventure game released in 2007 by Custom-Logic and Jeff Nusz. The player moves the character left and right, jumps, and shoots arrows. Movement is handled with the A and D keys, jumping with W, and the arrow keys are used for shooting.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"tasty-planet","slug":"tasty-planet","title":"Tasty Planet","description":"Tasty Planet, a 2011 arcade game from Dingo Games, puts players in charge of a growing ball of goo that consumes everything it touches.","about":"Players control a small grey ball of goo that eats whatever it encounters. Each meal makes the goo larger, allowing it to consume bigger things, from dirt and bacteria to bugs, mice, cats, cars, trees and houses. The goal is to keep growing until the whole planet has been eaten.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"the-skullkid","slug":"the-skullkid","title":"The skullkid","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":400},{"type":"flash","id":"thing-thing-arena-3","slug":"thing-thing-arena-3","title":"Thing-Thing Arena 3","description":"Thing-Thing Arena 3 is a 2009 single-player shooter from Diseased Productions and Sean McGee, continuing the Thing Thing Arena series.","about":"Thing-Thing Arena 3 is a single-player shooter in the Thing Thing Arena series, released in 2009 by Diseased Productions and Sean McGee. The action plays out from a shooter perspective, with the series name pointing to an arena setting.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":550,"height":400},{"type":"flash","id":"znax","slug":"znax","title":"Znax","description":"Znax is a 2005 puzzle game from Lightforce in which same-colored stones arranged in rectangles are clicked to clear them.","about":"Znax is a logic puzzle built around colored stones on a grid. Players click on stones of the same color that sit together in rectangular groups. The goal is to work through the board by finding and selecting these matching arrangements.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":459,"height":307},{"type":"flash","id":"zombocalypse","slug":"zombocalypse","title":"Zombocalypse","description":"Zombocalypse is a single-player action shooter from Ironzilla in which players face off against the undead.","about":"Zombocalypse is an action shooter played solo, built around gunning down waves of zombies. It comes from developer Ironzilla and belongs to the Zombocalypse series, which continues the same undead-shooting theme.","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":400},{"type":"flash","id":"airport-tycoon","slug":"airport-tycoon","title":"Airport Tycoon","description":"Airport Tycoon is a 2008 simulation game from Mousebreaker in which the player takes charge of running an airport.","about":"Airport Tycoon puts the player in charge of an airport and asks whether that business can be managed without failure. The work is demanding, and the outcome depends on how well the operation is handled. It is a single-player simulation from Mousebreaker, released in 2008.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":500,"height":375},{"type":"flash","id":"cat-with-bow-golf","slug":"cat-with-bow-golf","title":"Cat With Bow Golf","description":"Cat With Bow Golf is a 2007 sports game from D_of_I in which a cat is launched toward floating greens by bow and arrow.","about":"The aim in Cat With Bow Golf is to land a cat on each floating green using a bow. Physics govern every shot, so overshooting can carry the animal past the boundary. The challenge comes from judging each launch carefully, since the target is trickier to reach than it first appears. Standard golf scoring rules still apply to the floating courses.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":550,"height":400},{"type":"flash","id":"crimson-warfare","slug":"crimson-warfare","title":"Crimson Warfare","description":"Crimson Warfare is a 2004 strategy game from NTND in which players build and deploy military units, from soldiers and tanks to missiles.","about":"Crimson Warfare is a war strategy game about building an army and sending it into battle. Units range from soldiers and tanks to missiles and mass bombing runs. Only a few unit types are available on the first level, and the selection opens up afterward. The game was developed by NTND and released in 2004.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":700,"height":400},{"type":"flash","id":"demolition-city","slug":"demolition-city","title":"Demolition City","description":"Demolition City is a 2009 puzzle game from Armor Games and Joey Betz where dynamite brings down towers level by level.","about":"In Demolition City, each stage gives the player a set number of dynamite sticks and a target: bring the rubble down past a goal line. Dynamite is placed with the mouse, then detonated to collapse the structure. There are 20 levels to clear, and successful demolitions earn money along the way.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":700,"height":600},{"type":"flash","id":"etherena-beta","slug":"etherena-beta","title":"Etherena Beta","description":"Etherena Beta is a 2004 action game by arayh that supports one or two players and lets you adjust the controls.","about":"Etherena Beta is an action game from 2004 by arayh. It can be played by one or two people, and the controls can be changed. The author suggests reading the instructions before starting. A later update fixed a bug that caused only player 2 to lose energy when both players used a shield.","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":500},{"type":"flash","id":"glean","slug":"glean","title":"Glean","description":"Glean is a 2012 adventure game from Zuper Games where players mine alien worlds to upgrade their ship and character.","about":"Players travel to alien worlds and dig for the minerals needed to improve both their character and their vessel. The levels are generated procedurally, and an object-based crafting system handles the upgrades. Collecting 18 artifacts reveals every part of the story and brings the game to a close, though play can continue in pursuit of all upgrades. The game is an RPG-like take on the mining formula of MotherLoad.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":700,"height":550},{"type":"flash","id":"glean-2","slug":"glean-2","title":"Glean 2","description":"Glean 2 is a 2014 adventure sequel from Zuper Games, sending players across alien worlds to gather materials and survive hostile wildlife.","about":"Players explore three kinds of alien terrain: land, water, and sky. They collect resources and defend themselves against creatures native to each planet. By researching and building improvements, they gain the means to go further and recover every log entry, carrying the story of Glean forward. Compared with the first game, this follow-up adds two environments, additional resources, and a reworked research and crafting system. Progress saves automatically whenever the ship is entered.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":700,"height":550},{"type":"flash","id":"gravity-duck","slug":"gravity-duck","title":"Gravity Duck","description":"Gravity Duck is a 2010 puzzle platformer from Woblyware where players flip gravity to guide a duck through single-player stages.","about":"Gravity Duck is a puzzle platformer released in 2010 by Woblyware. Players guide an avian character through fixed-screen stages by flipping gravity, solving puzzles in single-player. The pixel art style and the Gravity Duck series give the game its distinct look and feel.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":640,"height":480},{"type":"flash","id":"mario-mushroom-adventure","slug":"mario-mushroom-adventure","title":"Mario Mushroom Adventure","description":"Mario Mushroom Adventure is a 2013 platformer from King of Games, sending players through a land of mushrooms across many levels.","about":"Mario Mushroom Adventure is a platformer released in 2013 by King of Games. The game follows Mario through mushroom adventure land, which is made up of many levels. Each of those levels presents a challenge for the player to work through. The result is a lot of fun across the journey.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":560,"height":525},{"type":"flash","id":"mini-putt","slug":"mini-putt","title":"Mini Putt","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":550,"height":440},{"type":"flash","id":"monster-truck-rampage","slug":"monster-truck-rampage","title":"Monster Truck Rampage","description":"Monster Truck Rampage is a 2008 action shooter and simulation game from GameTeam in which a truck is driven and its weapons fired.","about":"Monster Truck Rampage mixes simulation and shooter action, with the player controlling a truck from a top-down view. Movement uses the WASD or arrow keys, while the mouse handles aiming and shooting. GameTeam released it in 2008.","system":"Flash","genre":"simulation","categories":"simulation|shooter|action","core":"swf","width":550,"height":400},{"type":"flash","id":"ninja-hamsters-vs-robots","slug":"ninja-hamsters-vs-robots","title":"Ninja Hamsters vs Robots","description":"Ninja Hamsters vs Robots is a 2011 action game from Nerdook where players defend against waves of enemies and gather sushi recipes.","about":"Players place attack points by clicking the mouse to fight off incoming waves of enemies. Surviving a wave leads to a boss encounter, and clearing all 20 levels unlocks a special surprise. The game also includes upgrades and achievements, and collecting all 8 Sushi Recipes is required to win. Pausing the game opens additional options.","system":"Flash","genre":"action","categories":"action","core":"swf","width":678,"height":480},{"type":"flash","id":"no-time-to-explain","slug":"no-time-to-explain","title":"No Time to Explain","description":"No Time to Explain is a 2011 action game from developer Tom Brien, also known as I-smel, built around frantic, fast-paced play.","about":"No Time to Explain is an action game released in 2011 by Tom Brien, who also goes by I-smel. The game leans on urgency and speed, with the original page refusing to slow down long enough to explain anything. It is a short, quick experience rather than a lengthy one, and it later became the basis for a fuller commercial version.","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":300},{"type":"flash","id":"orbital-onslaught","slug":"orbital-onslaught","title":"Orbital Onslaught","description":"Orbital Onslaught is a 2011 strategy game from Nerdook where mercenary forces hunt fugitive criminals across a sector.","about":"Orbital Onslaught mixes real-time and turn-based play in a tactical-strategy framework. The player commands a mercenary group and takes on fugitive criminals operating within a sector, with fame and fortune as the rewards. A range of unique mercenaries can be brought to the fight, among them soldiers, turrets and gunships. The goal is to bring the fugitives to justice.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":678,"height":480},{"type":"flash","id":"pyro","slug":"pyro","title":"Pyro","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":400,"height":500},{"type":"flash","id":"rooney-on-the-rampage","slug":"rooney-on-the-rampage","title":"Rooney on the Rampage","description":"Rooney on the Rampage is a 2006 single-player sports game from 2DPlay that mixes soccer with a running challenge.","about":"Rooney on the Rampage is a single-player sports game from 2DPlay, released in 2006. It blends soccer with running, following a well-known footballer as the focus of the action.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":600,"height":400},{"type":"flash","id":"smokin-barrels","slug":"smokin-barrels","title":"Smokin Barrels","description":"Smokin Barrels is a 2007 action shooter where a young cowboy arrives in town and duels to become the fastest gringo in the west.","about":"A young cowboy rides into town carrying a fistful of dollars, and the aim is to win every duel. Each round begins by moving the crosshair into a safe area, which starts a countdown. Once the signal comes, the crosshair must be moved onto the target and fired before the opponent can shoot. Winning all the duels is the way to become the fastest gringo of the west.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":600,"height":400},{"type":"flash","id":"sonic-boom-link-n-smash","slug":"sonic-boom-link-n-smash","title":"Sonic Boom: Link ‘N Smash’","description":"Sonic Boom: Link ‘N Smash’ is a 2015 puzzle arcade game where falling hero portraits and items must be matched to score points.","about":"Falling pieces drop down the screen, and the player moves and positions them to line up each character's portrait with the items that belong to that character. Matching the two collects the items and adds to the score. Once a hero has gathered enough items, that character becomes stronger and their power can be used to earn more points. The game plays like a block-stacking puzzler set in the Sonic world, with portraits and themed items as the pieces.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":960,"height":600},{"type":"flash","id":"space-is-key","slug":"space-is-key","title":"Space is Key","description":"Space is Key is a 2011 platformer by Chris Jeff that tests timing and reflex as players guide a square through hazard-filled stages.","about":"Space is Key is a platformer from developer Chris Jeff, released in 2011. Players control a small square and must press the space bar to make it jump past obstacles. The game is built around precise timing, and the challenge comes from reacting quickly to the hazards in each stage. The title itself hints at the central mechanic: the space bar is the only key needed.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":640,"height":480},{"type":"flash","id":"spongebob-squarepants-dutchmans-dash","slug":"spongebob-squarepants-dutchmans-dash","title":"SpongeBob SquarePants: Dutchman’s Dash","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":600,"height":300},{"type":"flash","id":"straw-hat-samurai","slug":"straw-hat-samurai","title":"Straw Hat Samurai","description":"Straw Hat Samurai is a 2008 action game by lutc that centers on sword-fighting combat with heavy slashing and blood.","about":"Straw Hat Samurai is an action game built around sword combat, with an emphasis on slashing and blood. It was developed by lutc and released in 2008. A later update added a Survival Mode, and the game autosaves at the end of each turn. Quality settings can be lowered if the game lags.","system":"Flash","genre":"action","categories":"action","core":"swf","width":720,"height":400},{"type":"flash","id":"attack-of-the-puppybots","slug":"attack-of-the-puppybots","title":"The Powerpuff Girls: Attack of the Puppybots","description":"The Powerpuff Girls: Attack of the Puppybots is a 2007 side-scrolling action shooter from Cartoon Network and Bamtang.","about":"The Powerpuff Girls: Attack of the Puppybots is a side-scrolling shooter built around the show's characters. Cartoon Network and Bamtang released it in 2007 as a single-player action game.","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":400},{"type":"flash","id":"virtual-curling","slug":"virtual-curling","title":"Virtual Curling","description":"Virtual Curling is a 2004 sports game from Mousebreaker where players slide stones across the ice in a test of touch and control.","about":"Virtual Curling brings the winter sport to the screen, with players sliding stones over a slippery ice surface. The key is judging how much force to use, since pushing a stone too hard sends it past the target. It is a straightforward take on curling that focuses on careful aim and measured delivery.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":640,"height":480},{"type":"flash","id":"xiao-xiao-no-6","slug":"xiao-xiao-no-6","title":"Xiao Xiao No. 6","description":"Xiao Xiao No. 6 is a 2002 action game by Zhu Zhiqiang in which rapid space bar presses drive an interactive fight.","about":"Xiao Xiao No. 6 is an interactive fighting game from 2002, developed by Zhu Zhiqiang. The player takes part in a fight by pressing the space bar as quickly as possible. Speed of input is the core of the experience, turning each match into a test of how fast the player can hit the key. The result is a simple, fast-paced action game built around that single repeated action.","system":"Flash","genre":"action","categories":"action","core":"swf","width":450,"height":200},{"type":"flash","id":"bloons-tower-defense-4-expansion","slug":"bloons-tower-defense-4-expansion","title":"Bloons Tower Defense 4: Expansion","description":"Bloons Tower Defense 4: Expansion is a 2011 strategy game from Ninja Kiwi with new tracks, towers and a Deflation mode.","about":"This expansion for Bloons Tower Defense 4 adds four tracks to the tower defense action: Sandy Spiral, Subterrainian Sewers, Monkey Temple and Triangle of Insanity. The Dartling Gun and Spike Factory join the available towers. A new Deflation mode gives players 50,000 money at the start with no further income, and Tower Specialties can be unlocked by clearing the new tracks at various difficulty levels, making some towers cheaper while raising the cost of others.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":660},{"type":"flash","id":"candy-crush","slug":"candy-crush","title":"Candy Crush","description":"Candy Crush is a puzzle arcade game where matching candies by dragging and dropping them earns points before time runs out.","about":"The goal is to reach 200 points before the clock stops. Candies are moved by dragging and dropping them into place to create matches. Success depends on clearing enough combinations quickly, since the round is limited by time.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":755,"height":600},{"type":"flash","id":"cat-in-japan","slug":"cat-in-japan","title":"Cat in Japan","description":"Cat in Japan is a 2016 puzzle adventure from Bart Bonte in which the Bonte cat searches Japan for sushi.","about":"The Bonte cat has travelled to Japan and keeps dreaming about sushi. Players work through puzzles to track down every piece of sushi. Solving each one brings the cat closer to finding them all. It is a puzzle adventure from Bart Bonte, released in 2016.","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":960,"height":600},{"type":"flash","id":"cats-me-if-you-can","slug":"cats-me-if-you-can","title":"Cats Me If You Can!","description":"Cats Me If You Can! is a 2005 top-down racing game from Nickelodeon where players dodge their way through a Catscratch score attack.","about":"Cats Me If You Can! is a top-down racing game released by Nickelodeon in 2005 and tied to the Catscratch series. Played solo, it mixes dodging and time-attack pressure with a score-attack goal.","system":"Flash","genre":"racing","categories":"racing","core":"swf","width":450,"height":385},{"type":"flash","id":"choose-your-weapons","slug":"choose-your-weapons","title":"Choose Your Weapon","description":"Choose Your Weapon is a 2007 arcade action game from Glowmonkey in which a single player takes on the role of a primate.","about":"Choose Your Weapon is a single-player arcade action game released in 2007 by Glowmonkey. The game centers on a primate protagonist and belongs to the Choose your Weapon series.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"cranky-crabs","slug":"cranky-crabs","title":"Cranky Crabs","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":750,"height":400},{"type":"flash","id":"crazy-chess","slug":"crazy-chess","title":"Crazy Chess","description":"Crazy Chess is a 2006 single-player strategy puzzle game from 2DPlay that puts a chess-themed twist on the classic board game.","about":"Crazy Chess is a single-player strategy and puzzle game built around chess, released in 2006 by 2DPlay. Players work through chess-themed strategic and puzzle challenges on their own.","system":"Flash","genre":"strategy","categories":"strategy|puzzle","core":"swf","width":550,"height":400},{"type":"flash","id":"demons-took-my-daughter","slug":"demons-took-my-daughter","title":"Demons Took My Daughter","description":"Demons Took My Daughter is a 2010 action game from Nerdook mixing platforming and defence as a father sets out to save his child.","about":"A father sets out to rescue his daughter from a group of demons in this hybrid of platforming and defence gameplay. Along the way he faces many different enemies, including the seven deadly sins. Nerdook developed the game in 2010.","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":500},{"type":"flash","id":"drago-adventure","slug":"drago-adventure","title":"Drago Adventure","description":"Drago Adventure is a 2009 platformer from Agamecom in which a small dragon uses elemental powers to grow stronger.","about":"A small dragon sets out to prove that size is not everything. By drawing on the powers of the elements, the dragon can build up strength and take on the challenges of this platformer. The game was released in 2009 by Agamecom.","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":580,"height":380},{"type":"flash","id":"endless-war","slug":"endless-war","title":"Endless War","description":"Endless War is a 2005 arcade shooter by Vitaly Zaborov with a large arsenal of guns and plenty of enemies to fight.","about":"Endless War is an arcade shooting game built around combat against many enemies using a wide variety of guns. The developer set out to create a shooter packed with weapons and foes. Playing through every mission takes roughly two hours.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":600},{"type":"flash","id":"factory-balls-3","slug":"factory-balls-3","title":"Factory Balls 3","description":"Factory Balls 3 is a 2010 puzzle game from BONTE games and Bart Bonte where balls are dragged over tools to match each level's target.","about":"Each level in Factory Balls 3 presents a goal ball that has to be produced. The player drags a ball over the available tools, using them in the right order to build up the required look. It is a logic puzzle from BONTE games and Bart Bonte, released in 2010.","system":"Flash","genre":"puzzle","categories":"puzzle|logic","core":"swf","width":640,"height":600},{"type":"flash","id":"garfield-mix-match","slug":"garfield-mix-match","title":"Garfield Mix & Match","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":500,"height":380},{"type":"flash","id":"grow-rpg","slug":"grow-rpg","title":"GROW RPG","description":"GROW RPG is a 2005 single-player adventure from Eyezmaze and On Nakayama, with hidden content and multiple endings to uncover.","about":"GROW RPG is a single-player adventure from Eyezmaze and On Nakayama, released in 2005 as part of the GROW series. The game includes hidden content and multiple endings, giving players reasons to explore its world more than once.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"ice-age-the-meltdown-rising-water","slug":"ice-age-the-meltdown-rising-water","title":"Ice Age: The Meltdown – Rising Water","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"johnny-rocketfingers","slug":"johnny-rocketfingers","title":"Johnny Rocketfingers","description":"Johnny Rocketfingers is a 2003 point-and-click adventure by Ryan Khatam. Progress depends on careful observation of each scene.","about":"This adventure game asks players to search each scene closely for objects they can pick up. Moving the pointer slowly helps when scanning for items, since some are easy to miss. When progress stalls, the advice is to stay patient and examine the surroundings with extra care. Johnny Rocketfingers was developed by Ryan Khatam and released in 2003.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":400,"height":300},{"type":"flash","id":"kill-the-dog-from-duck-hunt","slug":"kill-the-dog-from-duck-hunt","title":"Kill The Dog From Duck Hunt","description":"Kill The Dog From Duck Hunt is a 2004 single-player shooter from I-Mockery with pixel art and mouse-only controls.","about":"A single-player shooter with pixel visuals from I-Mockery, released in 2004. Played entirely with the mouse, it centers on the dog from Duck Hunt and includes blood.","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":512,"height":467},{"type":"flash","id":"leading-edge","slug":"leading-edge","title":"Leading Edge","description":"Leading Edge is a 2007 side-view shooter from ChronoBell in which a stick man fights armed enemies across a mission.","about":"Leading Edge is a side-view shooter built around a stick man soldier working through enemy opposition. A wide selection of weapons is available for taking down the stick man foes that stand in the way. Checkpoints along the route allow health to be refilled, provided the player reaches them. Cash earned during the mission can be spent on ammunition refills.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":640,"height":375},{"type":"flash","id":"little-bills-adventure-with-captain-brainstorm","slug":"little-bills-adventure-with-captain-brainstorm","title":"Little Bill’s Adventure with Captain Brainstorm","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":475,"height":285},{"type":"flash","id":"microbe-kombat","slug":"microbe-kombat","title":"Microbe Kombat","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":550},{"type":"flash","id":"pacs-jungle-trip","slug":"pacs-jungle-trip","title":"Pac’s Jungle Trip","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":500},{"type":"flash","id":"quiz-parampaa-2","slug":"quiz-parampaa-2","title":"Quiz Parampaa 2","system":"Flash","genre":"quiz","categories":"quiz","core":"swf","width":550,"height":400},{"type":"flash","id":"redball4","slug":"redball4","title":"Redball 4","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":640,"height":480},{"type":"flash","id":"skylocopter","slug":"skylocopter","title":"Skylocopter","description":"Skylocopter is an arcade game where players pilot a helicopter through levels, gathering diamonds and treasures while avoiding enemies.","about":"In Skylocopter, the player controls a helicopter and moves through a series of action-filled levels. Along the way, diamonds and other treasures can be collected. Enemies appear throughout these stages and must be avoided. The game combines flying, treasure gathering, and dodging threats as its main elements.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":500,"height":300},{"type":"flash","id":"spongebob-squarepants-boo-or-boom","slug":"spongebob-squarepants-boo-or-boom","title":"SpongeBob SquarePants: Boo or Boom","description":"SpongeBob SquarePants: Boo or Boom is a 2007 Nickelodeon arcade game with a Halloween theme and single-player bomb maze action.","about":"SpongeBob SquarePants: Boo or Boom is a single-player arcade game from Nickelodeon, released in 2007 with a Halloween theme. Play centers on a bomb maze, and an Easter egg lets players press H during play to put Santa hats on the Plankton buildings and hear Jingle Bells for a few seconds.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"spongebob-atlantis-squarepantis-bus-rush","slug":"spongebob-atlantis-squarepantis-bus-rush","title":"SpongeBob: Atlantis Squarepantis Bus Rush","description":"SpongeBob: Atlantis Squarepantis Bus Rush is a 2007 top-down arcade maze game from Nickelodeon and Sarbakan.","about":"In this arcade maze game, SpongeBob and Patrick drive a bus toward Atlantis. Players steer the vehicle through the course in a top-down view. The game was released in 2007 by Nickelodeon and Sarbakan.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"super-sewer-scramble","slug":"super-sewer-scramble","title":"Super Sewer Scramble","description":"Super Sewer Scramble is a 2002 arcade game from Corus Entertainment about rescuing a mother fly's larvae from a dangerous sewer.","about":"A mother fly has lost her larvae, and they must be saved from the hazards found throughout the open sewer. This arcade title from 2002, developed by Corus Entertainment, turns that rescue mission into the core of the game. Players work to recover the missing larvae before the sewer's perils can do them harm.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":680,"height":440},{"type":"flash","id":"the-amazing-dare-dozen","slug":"the-amazing-dare-dozen","title":"The Amazing Dare-Dozen","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":300,"height":400},{"type":"flash","id":"achilles","slug":"achilles","title":"Achilles","system":"Flash","genre":"action","categories":"action","core":"swf","width":700,"height":500},{"type":"flash","id":"apocalyptic-tower","slug":"apocalyptic-tower","title":"Apocalyptic Tower","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":720,"height":520},{"type":"flash","id":"backyardigans-mission-to-mars","slug":"backyardigans-mission-to-mars","title":"Backyardigans: Mission to Mars","description":"Backyardigans: Mission to Mars is a platformer adventure where the Backyardigans gather Boinga Crystals on the red planet.","about":"The Backyardigans set out for Mars with the goal of collecting Boinga Crystals. The task is not a simple one, and the group needs help to see it through. Players join the mission as a platforming adventure.","system":"Flash","genre":"platformer","categories":"platformer|adventure","core":"swf","width":600,"height":340},{"type":"flash","id":"charlie-and-lola-sock-pony-race","slug":"charlie-and-lola-sock-pony-race","title":"Charlie and Lola: Sock Pony Race","description":"Charlie and Lola: Sock Pony Race is a 2005 BBC and CBeebies racing game where players race as Lola or Lotta over fences and tumbleweed.","about":"Players pick either Lola or Lotta and take part in the Sock Pony Race. The course runs over fences and tumbleweed. The game is a racing title from the BBC and CBeebies, released in 2005.","system":"Flash","genre":"racing","categories":"racing","core":"swf","width":500,"height":300},{"type":"flash","id":"ducklife5","slug":"ducklife5","title":"DuckLife 5","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":800,"height":450},{"type":"flash","id":"ducklife3-evolution","slug":"ducklife3-evolution","title":"DuckLife3: Evolution","system":"Flash","genre":"simulation","categories":"simulation|arcade","core":"swf","width":750,"height":480},{"type":"flash","id":"frogs-logic","slug":"frogs-logic","title":"Frogs Logic","description":"Frogs Logic is a 2002 single-player puzzle game from Plastelina Games and Shlomir Hadad that challenges players with logic-based challenges.","about":"Frogs Logic is a single-player puzzle game built around logic challenges, released in 2002 by Plastelina Games and Shlomir Hadad. It belongs to the Plastelina Logic Games series and is designed for players who enjoy working through thoughtful, educational puzzles.","system":"Flash","genre":"logic","categories":"logic|educational","core":"swf","width":500,"height":315},{"type":"flash","id":"grow-cube","slug":"grow-cube","title":"GROW Cube","description":"GROW Cube is a 2005 puzzle game by On Nakayama where players click panels in a chosen order to make them grow.","about":"GROW Cube is the third entry in the GROW series and swaps dragging for clicking. Players select panels one at a time, and each click causes items to grow and level up. The panels influence one another as they develop, so the sequence of clicks matters. The goal is to bring every panel to its maximum level.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":400},{"type":"flash","id":"happy-tree-friends-dumb-ways-to-die","slug":"happy-tree-friends-dumb-ways-to-die","title":"Happy Tree Friends – Dumb Ways to Die","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":320,"height":430},{"type":"flash","id":"icarly-random-dancing","slug":"icarly-random-dancing","title":"iCarly: Random Dancing","description":"iCarly: Random Dancing is a 2009 arcade rhythm game from Nickelodeon where players take part in a single-player dancing challenge.","about":"iCarly: Random Dancing is an arcade rhythm game released by Nickelodeon in 2009. It is a single-player experience tied to the iCarly series, with gameplay built around rhythm and dancing.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"marios-adventure-2","slug":"marios-adventure-2","title":"Mario’s Adventure 2","system":"Flash","genre":"action","categories":"action","core":"swf","width":400,"height":300},{"type":"flash","id":"metele-al-ordenata-bash-the-computer","slug":"metele-al-ordenata-bash-the-computer","title":"Metele Al Ordenata (Bash the Computer)","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":390},{"type":"flash","id":"milk-the-cow","slug":"milk-the-cow","title":"Milk the Cow","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":350},{"type":"flash","id":"monster-evolution","slug":"monster-evolution","title":"Monster Evolution","description":"Monster Evolution is a 2009 arcade game from Nobstudio where players control a monster that feeds on humans and evolves.","about":"In Monster Evolution, the player takes control of a monster and causes destruction while feeding on humans. As the game progresses, the monster evolves into one of 25 different types. The game is controlled with the arrow keys and space bar, and the P key pauses play and handles evolution. Players can choose to evolve into another monster of the same level when their health is low.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"pac-xon-deluxe","slug":"pac-xon-deluxe","title":"Pac-Xon Deluxe","description":"Pac-Xon Deluxe is a puzzle arcade game where players wall off space to trap monsters and clear each level.","about":"The aim in Pac-Xon Deluxe is to claim open ground by drawing a wall that surrounds the monsters. A level is complete once 80 percent of the space has been filled. Touching a monster must be avoided, and power-ups show up at random points on the screen for players to collect.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":720,"height":540},{"type":"flash","id":"punk-o-matic","slug":"punk-o-matic","title":"Punk-o-Matic","description":"Punk-o-Matic, the 2004 arcade music game from Evil-Dog, lets players build their own punk tracks.","about":"Punk-o-Matic is a music-making arcade game from 2004 by Evil-Dog. Players piece together punk songs by arranging the game's sounds into their own compositions. It is the first entry in the series, and its soundtrack comes from the developer's band, Chucks Nation. A sequel, Punk-o-Matic 2, was announced.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":450,"height":450},{"type":"flash","id":"regular-show-dance-of-doom","slug":"regular-show-dance-of-doom","title":"Regular Show: Dance of Doom","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":750,"height":480},{"type":"flash","id":"regular-show-ride-em-rigby","slug":"regular-show-ride-em-rigby","title":"Regular Show: Ride ‘Em Rigby","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"run-ronaldo-run","slug":"run-ronaldo-run","title":"Run Ronaldo Run","description":"Run Ronaldo Run is a 2006 single-player sports game from 2DPlay that mixes soccer themes with endless runner action.","about":"Run Ronaldo Run is a single-player sports game built around a running challenge with a soccer theme. Released in 2006 by 2DPlay, it centers on a well-known figure and falls into the runner genre.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":600,"height":400},{"type":"flash","id":"rural-racer","slug":"rural-racer","title":"Rural Racer","system":"Flash","genre":"racing","categories":"racing","core":"swf","width":570,"height":400},{"type":"flash","id":"sesame-street-letters-to-big-bird","slug":"sesame-street-letters-to-big-bird","title":"Sesame Street: Letters to Big Bird","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":600,"height":307},{"type":"flash","id":"spongebob-squarepants-trail-of-the-snail","slug":"spongebob-squarepants-trail-of-the-snail","title":"SpongeBob SquarePants: Trail of the Snail","description":"SpongeBob SquarePants: Trail of the Snail is a 2005 arcade game from Sarbakan about tracking down the character's beloved mollusk.","about":"In this arcade title, the goal is to locate SpongeBob's most-beloved mollusk. The game was developed by Sarbakan and released in 2005. Its playful tone comes through in the original tagline, which describes it as a truly whack-y game.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"spongebob-bikini-bottom-carnival","slug":"spongebob-bikini-bottom-carnival","title":"SpongeBob: Bikini Bottom Carnival","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":300},{"type":"flash","id":"spongebob-patty-panic","slug":"spongebob-patty-panic","title":"SpongeBob: Patty Panic","description":"SpongeBob: Patty Panic is a 2007 arcade score-attack game from This Is Pop, played from a side view on a fixed screen.","about":"SpongeBob: Patty Panic is a single-player arcade score-attack game set in the SpongeBob SquarePants cartoon world. It is played from a side view on a fixed screen, with the aim of building up a score. Developer This Is Pop released it in 2007.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"spongebob-pyramid-peril","slug":"spongebob-pyramid-peril","title":"SpongeBob: Pyramid Peril","description":"SpongeBob: Pyramid Peril is a 2007 arcade tile-traveler from Nickelodeon and This Is Pop, played solo in an axonometric view.","about":"SpongeBob: Pyramid Peril is a single-player arcade game from 2007, developed by Nickelodeon and This Is Pop. Players move across tiled ground in an axonometric view while chasing a high score, with the Shift+7 and Shift+8 key combinations granting an extra life and skipping the current level.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"stanley-charades","slug":"stanley-charades","title":"Stanley: Charades","description":"Stanley: Charades is a single-player puzzle game from Playhouse Disney in 2001, built around logic and animal themes.","about":"Stanley: Charades is a mouse-only puzzle game from 2001 in which players work through logic challenges tied to a zoology theme. It is a single-player title from Playhouse Disney, part of the Stanley series.","system":"Flash","genre":"puzzle","categories":"puzzle|logic","core":"swf","width":640,"height":360},{"type":"flash","id":"top-that","slug":"top-that","title":"Top That!","description":"Top That! is a 2006 simulation game from Corus Entertainment where players serve fast food orders under time pressure.","about":"In this fast food simulator, players work at Mech-Droids and must complete orders for five customers. Each order appears in a speech bubble showing the requested food items, and the player selects those items from the right side of the screen. Performance is judged on speed and accuracy, with fewer mistakes and faster service leading to a higher customer satisfaction rating. Making an error means starting the order over and receiving a scolding from the customer.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":650,"height":400},{"type":"flash","id":"wone-2","slug":"wone-2","title":"wOne 2","description":"wOne 2 is a 2006 sports game by Sean Cooper, a sequel built around a bungee cord that wraps around platforms and edges.","about":"This sequel from developer Sean Cooper expands on the bungee cord mechanic, letting the cord wrap around platforms and edges, and even around itself. Players can also fall off the side of the world, which adds difficulty to the missions. The game includes a level selection screen where missions can be completed.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":700,"height":400},{"type":"flash","id":"zombotron2","slug":"zombotron2","title":"Zombotron 2","description":"Zombotron 2 is a 2012 single-player action shooter from developer Anton Karlov, continuing the Zombotron series with a zombie theme.","about":"Zombotron 2 is a single-player action shooter released in 2012 by Anton Karlov. It is part of the Zombotron series and centers on shooting zombies from a side-scrolling perspective.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"adventure-time-jumping-finn","slug":"adventure-time-jumping-finn","title":"Adventure Time: Jumping Finn","description":"Adventure Time: Jumping Finn is a 2011 arcade launch game where players fling Finn toward the Ice Kingdom to rescue Princess Bubblegum.","about":"The Ice King has taken Princess Bubblegum, and Finn needs to reach the Ice Kingdom quickly. Jake's solution is to launch him there, with help from Marceline and Lady Rainicorn. Players take part in these launches, sending Finn as far as possible. Credits earned along the way can be spent on upgrades to the characters' powers.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"base-jumping","slug":"base-jumping","title":"Base Jumping","description":"Base Jumping is a 2006 action game by Martijn Kunst where players jump against top rivals and climb through the leagues.","about":"Players take part in base jumping contests against the best jumpers in the world. Progress happens by working through the leagues, with each stage bringing the player closer to a match against the King. The game was developed by Martijn Kunst and released in 2006.","system":"Flash","genre":"action","categories":"action","core":"swf","width":485,"height":400},{"type":"flash","id":"battleships-general-quarters-ii","slug":"battleships-general-quarters-ii","title":"Battleships: General Quarters II","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":420},{"type":"flash","id":"canterlot-siege","slug":"canterlot-siege","title":"Canterlot Siege","description":"Canterlot Siege is a 2012 tower defense strategy game by futzi01 where players upgrade ponies to fend off waves of enemies.","about":"In Canterlot Siege, you place and upgrade pony characters to defend against incoming waves of enemies. Upgrading ponies is more effective than buying many, and level 5 upgrades are very powerful. The game is designed to be challenging, so winning on the first try is unlikely. Pony sprites were created by Desktop-Pony-Team.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":960,"height":720},{"type":"flash","id":"cartoon-cove-mini-golf","slug":"cartoon-cove-mini-golf","title":"Cartoon Network: Cartoon Cove Mini Golf","description":"Cartoon Network: Cartoon Cove Mini Golf is a 2003 sports game with nine cartoon-themed holes on a tropical island.","about":"Cartoon Network: Cartoon Cove Mini Golf is a single-player and multiplayer sports game from 2003. Players work through nine holes set on a tropical mini-golf island, each themed around Cartoon Network characters. The island setting and cartoon theming give the course its own identity.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":600,"height":400},{"type":"flash","id":"charlie-and-lola-what-makes-us-happy","slug":"charlie-and-lola-what-makes-us-happy","title":"Charlie and Lola: What Makes Us Happy?","description":"Charlie and Lola: What Makes Us Happy? is a 2005 puzzle game from the BBC and CBeebies, based on choosing what brings the characters joy.","about":"Charlie and Lola: What Makes Us Happy? is a puzzle game released in 2005 by the BBC and CBeebies. Players pick out the things that make Charlie and Lola happy. The game is built around those choices.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":500,"height":300},{"type":"flash","id":"code-lyoko-monster-swarm","slug":"code-lyoko-monster-swarm","title":"Code Lyoko: Monster Swarm","description":"Code Lyoko: Monster Swarm is a 2006 platformer from Cartoon Network in which swarms have overrun the jungle.","about":"Swarms have made their way into the jungle, and stopping them falls to Lyoko. The game is a platformer released in 2006 by Cartoon Network. Players take on the task of clearing out the invading swarms.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":600,"height":400},{"type":"flash","id":"ducklife2-world-champion","slug":"ducklife2-world-champion","title":"DuckLife2: World Champion","system":"Flash","genre":"simulation","categories":"simulation|arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"escape","slug":"escape","title":"Escape","description":"Escape is a 2007 vertical wall-jumper from Godlimations where the only direction is upward.","about":"This fast-paced adventure sends players climbing a vertical shaft by leaping between walls. Jumping is handled with the escape key, and holding it down produces a higher leap. A laser rises behind the climber and accelerates as time passes, so early speed matters. Jumping while already moving up grants a small extra boost.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"fish-tales","slug":"fish-tales","title":"Fish Tales","description":"Fish Tales is a 2005 arcade game from Howling Moon Games where a small fish must eat others to grow in a fish-eat-fish world.","about":"In this arcade game, a fish starts out small and must consume other fish to grow larger. The underwater setting operates on the principle that fish eat fish, so survival depends on eating before being eaten. The goal is to grow up by feeding on the creatures around you.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"flea-2","slug":"flea-2","title":"Flea 2","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":720,"height":540},{"type":"flash","id":"heavy-gunner","slug":"heavy-gunner","title":"Heavy Gunner","description":"Heavy Gunner is a 2009 arcade action game from Sun-Studios where a powerful weapon is used to hold off waves of alien ships.","about":"Alien ships arrive in large numbers, and the player controls a superior weapon to fight them back. The goal is to survive the ongoing assault and protect the planet from destruction. Failure would mean the enslavement and torture of the entire human race.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":500,"height":700},{"type":"flash","id":"icarly-ispace-out","slug":"icarly-ispace-out","title":"iCarly: iSpace Out","description":"iCarly: iSpace Out is a 2010 Nickelodeon arcade action game where players take on a run 'n' gun challenge in a score-attack format.","about":"iCarly: iSpace Out is a single-player arcade action game from Nickelodeon, released in 2010. It is built around run 'n' gun play and a score-attack structure, with the iCarly series providing the setting.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"insane-orb","slug":"insane-orb","title":"Insane Orb","description":"Insane Orb is a 2004 arcade game by Werner Valdez that takes the Pong formula and adds projectiles and surprises.","about":"Insane Orb is an arcade game from 2004 by Werner Valdez. It plays like Pong, but the player can fire projectiles during the match. A few surprises also appear as the game goes on. It is described as the developer's first Pong-like game.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":600},{"type":"flash","id":"kitten-cannon","slug":"kitten-cannon","title":"Kitten Cannon","description":"Kitten Cannon is a 2005 physics launch game by Dan Fleming where a cat is fired from a cannon into a field of hazards.","about":"Fluffy keeps climbing into the cannon, so the player aims and fires the cat across a field filled with bombs, spikes, and springs. The launch angle and power are adjustable, and the physics engine makes the flight path predictable. Dan Fleming's action puzzler dates from 2005 and centers on steering Fluffy through the obstacles after the shot.","system":"Flash","genre":"action","categories":"action","core":"swf","width":650,"height":400},{"type":"flash","id":"madness-deathwish","slug":"madness-deathwish","title":"Madness: Deathwish","system":"Flash","genre":"action","categories":"action","core":"swf","width":520,"height":320},{"type":"flash","id":"mario-cart","slug":"mario-cart","title":"Mario Cart","description":"Mario Cart is a 2012 single-player 3D racing game from KillHours with a third-person view and Super Mario theme.","about":"Mario Cart is a 2012 single-player racing game from developer KillHours, built in 3D with the Alternativa3D engine. Players take a third-person view behind the wheel for driving action set in the Super Mario universe.","system":"Flash","genre":"racing","categories":"racing","core":"swf","width":550,"height":400},{"type":"flash","id":"mario-cart-2","slug":"mario-cart-2","title":"Mario Cart 2","description":"Mario Cart 2 is a 3D racing game from developer KillHours, released in 2012, in which a single player takes the wheel for solo driving action.","about":"Mario Cart 2 is a 3D racing game released in 2012 by KillHours. It is built for a single player and takes its theme from the Super Mario world, with solo driving across its tracks.","system":"Flash","genre":"racing","categories":"racing","core":"swf","width":550,"height":400},{"type":"flash","id":"monster-master","slug":"monster-master","title":"Monster Master","description":"Monster Master is a 2007 single-player collectible card game with turn-based battles controlled entirely by mouse.","about":"Monster Master is a single-player collectible card game from 2007. Players build and use a deck of cards in turn-based matches, with all actions handled through the mouse.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":800,"height":600},{"type":"flash","id":"rail-of-war-demo","slug":"rail-of-war-demo","title":"Rail of War (Demo)","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":640,"height":550},{"type":"flash","id":"regular-show-high-flying-halloween","slug":"regular-show-high-flying-halloween","title":"Regular Show: High Flying Halloween","description":"Regular Show: High Flying Halloween is a 2015 Cartoon Network arcade game with an endless jumper format and a spooky holiday theme.","about":"Regular Show: High Flying Halloween is a single-player arcade game from Cartoon Network, released in 2015. Played with the mouse, it sets an endless jumper in a Halloween-themed world where upgrades and score-attack runs keep the action going.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":400,"height":600},{"type":"flash","id":"regular-show-killer-zs","slug":"regular-show-killer-zs","title":"Regular Show: Killer Z’s","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"robo-rps","slug":"robo-rps","title":"Robo RPS","description":"Robo RPS is a 2009 arcade game from Pencilkids and Robin Vencel that turns rock, paper, scissors into a test of speedy reactions.","about":"Robo RPS builds its battles on the familiar rock, paper, scissors system. Symbols appear and the player has to answer with the right counter before time runs out. Arrow keys pick the counter attack, while the space bar starts the game and keeps it going after each round. Quick reactions matter more than anything else here, since the challenge is about responding to each symbol fast enough.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"shift","slug":"shift","title":"SHIFT","description":"SHIFT is a 2008 puzzle platformer from Armor Games and Antony Lavelle where the floor and ceiling can swap roles.","about":"In SHIFT, the usual boundaries between floor and ceiling stop applying, and the player has to work out how that changes each room. A timer adds pressure while the puzzle platforming plays out. The game comes from Armor Games and Antony Lavelle.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":500,"height":500},{"type":"flash","id":"skywire2","slug":"skywire2","title":"Skywire 2","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":550,"height":400},{"type":"flash","id":"sports-heads-football","slug":"sports-heads-football","title":"Sports Heads: Football","description":"Sports Heads: Football is a side-view cartoon soccer game from 2011 by Mousebreaker, playable solo or against another player.","about":"Sports Heads: Football is a side-view cartoon take on soccer from Mousebreaker, released in 2011. It is part of the Sports Heads series and can be played alone or with another person.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":800,"height":540},{"type":"flash","id":"tank-man","slug":"tank-man","title":"Tank Man","description":"Tank Man is a 2010 side-scrolling shooter from MCSMstudios starring the Captain in a single-stage action game.","about":"Tank Man is a one-stage action shooter starring the Captain from Tankmen. Players move with the arrow keys, shoot with A, jump with S, and can pause or open a weapon select screen with Q. An easy mode and a control-swap option for shooting and jumping were added after release, along with a charge shot for Mega Man and a power kick for Tank Man. The developer handled most of the art, with Mega Man, Rush, some powerups, and a hidden cameo drawn by others.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":256,"height":240},{"type":"flash","id":"teen-titans-go-grab-that-grub","slug":"teen-titans-go-grab-that-grub","title":"Teen Titans Go! Grab that Grub","description":"Teen Titans Go! Grab that Grub is a 2013 side-view platformer from Cartoon Network, played solo and based on the animated series.","about":"Based on the Teen Titans cartoon, this 2013 side-view platformer from Cartoon Network puts a single player in control of a character from the show. The action unfolds from a side perspective as the player moves through platforming stages.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":640,"height":384},{"type":"flash","id":"the-backyardigans-adventure-maker","slug":"the-backyardigans-adventure-maker","title":"The Backyardigans: Adventure Maker","description":"The Backyardigans: Adventure Maker lets kids pick Uniqua, Tyrone or Pablo and send them to one of four places.","about":"Players choose Uniqua, Tyrone or Pablo to accompany them on a trip. The destination is one of four different locations. Outfits for the journey are selected as part of the adventure. The game mixes puzzle play with creative choices for young players.","system":"Flash","genre":"puzzle","categories":"puzzle|creative","core":"swf","width":600,"height":340},{"type":"flash","id":"a-dralien-day","slug":"a-dralien-day","title":"A Dralien Day","description":"A Dralien Day is a 2009 puzzle adventure from Pencilkids and Robin Vencel about a young alien crossing a hostile planet to find his mother.","about":"In A Dralien Day, a young creature named Dralien sets out across a hostile alien planet. His mother, a dragon, has been taken by Dragon Hunters, and he must travel the world in search of her. The journey mixes puzzle solving with adventure as he makes his way through the planet's dangers.","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"cartoon-network-operation-z-e-r-o-out-mandyd","slug":"cartoon-network-operation-z-e-r-o-out-mandyd","title":"Cartoon Network: Operation Z.E.R.O. Out-Mandy’d","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":400},{"type":"flash","id":"chisel2","slug":"chisel2","title":"Chisel 2","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":550},{"type":"flash","id":"cursor-chaos","slug":"cursor-chaos","title":"Cursor Chaos","description":"Cursor Chaos is a 2009 arcade game from Ninjadoodle that throws a variety of quick challenges at a single player against the clock.","about":"Cursor Chaos is an arcade game from Ninjadoodle, released in 2009, built around a variety of fast challenges. It is a single-player time-attack experience in which the clock is always running.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":500,"height":500},{"type":"flash","id":"deep-freeze","slug":"deep-freeze","title":"Deep Freeze","description":"Deep Freeze is a 2006 arcade shooter from Macrojoy in which a water gun is used to ice enemies and protect the holiday.","about":"In this action shooter, the player wields a water gun that encases foes in ice. The goal is to halt the troublemakers who threaten to spoil Christmas. Macrojoy released the game in 2006 as an arcade-style shooter.","system":"Flash","genre":"shooter","categories":"shooter|arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"digimon-ruki","slug":"digimon-ruki","title":"Digimon Ruki","description":"Digimon Ruki is a 2010 dress-up game in which players style Ruki Makino, the fashion model's daughter from the Digimon cartoon.","about":"Ruki Makino comes from the Digimon cartoon, and as the daughter of fashion model Rumiko Makino she has a standard to meet. Players give her a look that suits both battling and catching new digimon. The game is a dress-up activity built around this character from the series.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":500,"height":350},{"type":"flash","id":"ducklife","slug":"ducklife","title":"DuckLife","description":"DuckLife is a 2010 simulation and arcade game from Wix Games where a duckling is trained to race and save the farm.","about":"In this single-player game, a duckling is raised and trained with the goal of becoming the top racing duck and saving the farm. Players take their duck through running, swimming, and flying challenges as part of its training and racing career. Progress comes from building up the duck's abilities to lead the flock. Seed can be fed to the duck by dragging it from the pile on the menu.","system":"Flash","genre":"simulation","categories":"simulation|arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"effing-worms","slug":"effing-worms","title":"Effing Worms","description":"Effing Worms, a 2010 action game from Effing Games, puts players in control of a giant worm that devours stick figures to grow larger.","about":"Players control a huge worm and consume stick figures in this action game. Eating enough people causes the worm to grow bigger and fatter, similar to a larger parent worm. The goal is to see how large the worm can become. The developer notes that the game is still being worked on and will improve based on feedback.","system":"Flash","genre":"action","categories":"action","core":"swf","width":640,"height":480},{"type":"flash","id":"hapland","slug":"hapland","title":"Hapland","description":"Hapland is a 2005 point-and-click puzzle game by Robin Allen in which players must work out how to help a stick figure reach a castle.","about":"Hapland is a puzzle game from 2005 by Robin Allen. The player interacts with a scene containing a stick figure and a castle, working out the correct order of actions needed to help the figure reach the castle. The game is known for its high difficulty, and the original description warns that players may find it very hard.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":700,"height":500},{"type":"flash","id":"happy-tree-friends-splendids-first-flight","slug":"happy-tree-friends-splendids-first-flight","title":"Happy Tree Friends – Splendids First Flight","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":500,"height":500},{"type":"flash","id":"heli-attack","slug":"heli-attack","title":"Heli Attack","description":"Heli Attack is a 2001 shooter from SquareCircleCo in which a lone gunner fights off waves of enemy helicopters.","about":"Enemy helicopters press the attack from overhead, and the player has a machine gun to hold them off. The aim is to bring down as many of the aircraft as possible. Points are scored for each one destroyed, and the final tally shows how well the run went.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":550,"height":400},{"type":"flash","id":"kablooey-flew-throughy","slug":"kablooey-flew-throughy","title":"Kablooey Flew Throughy","description":"Kablooey Flew Throughy is a 2005 arcade game from Corus Entertainment about guiding a character through a cave to collect gems.","about":"Kablooey Flew Throughy is an arcade game in which the player guides a character through a cave. The goal is to collect gems while steering clear of bombs and other hazards. It was released in 2005 by Corus Entertainment.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"little-rocketman","slug":"little-rocketman","title":"Little Rocketman","description":"Little Rocketman is a 2003 platformer from Say Design in which a jetpack-wearing hero flies off to rescue his kidnapped girlfriend.","about":"A jealous robot has taken Little Rocketman's girlfriend, so the small hero sets out to win her back. He travels through the air using a jetpack, and the game plays as a platformer with arcade action. Say Design released it in 2003.","system":"Flash","genre":"platformer","categories":"platformer|arcade|action","core":"swf","width":550,"height":400},{"type":"flash","id":"sesame-street-oscars-trash-collection","slug":"sesame-street-oscars-trash-collection","title":"Sesame Street: Oscar’s Trash Collection","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":600,"height":306},{"type":"flash","id":"shrink","slug":"shrink","title":"Shrink","description":"Shrink is a 2008 arcade game from kChamp Games in which a blue ball must be kept from dwindling away to nothing.","about":"The blue ball loses size over time unless the player keeps the cursor hovering over it. Black balls drift around the play area, and touching them is what must be avoided. The task looks easy at first, but the game is much harder than it appears. Keeping the ball from shrinking into nothingness is the goal.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":700,"height":500},{"type":"flash","id":"snow-line","slug":"snow-line","title":"Snow Line","description":"Snow Line is a 2007 creative game from IriySoft in which Santa Claus gathers up presents.","about":"Snow Line is a creative game from IriySoft, released in 2007. The player takes on the task of helping Santa Claus as he works to collect presents. The game centers on that simple objective rather than on combat or complex rules.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":550,"height":400},{"type":"flash","id":"spongebob-squarepants-bubble-trouble-cereal-game","slug":"spongebob-squarepants-bubble-trouble-cereal-game","title":"SpongeBob SquarePants: Bubble Trouble Cereal Game","description":"SpongeBob SquarePants: Bubble Trouble Cereal Game is a 2004 single-player puzzle title from Nickelodeon and Kellogg's.","about":"SpongeBob SquarePants: Bubble Trouble Cereal Game is a single-player puzzle game released in 2004 by Nickelodeon and Kellogg's. It is a promotional title built around the SpongeBob SquarePants theme.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":480},{"type":"flash","id":"the-flood-runner-2","slug":"the-flood-runner-2","title":"The Flood Runner 2","description":"The Flood Runner 2 is a 2010 arcade runner from Ben Rad Vinyl, a single-player sequel in the Flood Runner series.","about":"This arcade runner is the second entry in the Flood Runner series, made by Ben Rad Vinyl in 2010. It is a single-player game with a stick-figure style.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":400},{"type":"flash","id":"the-legend-of-zelda-and-the-lampshade-of-no-real-significance","slug":"the-legend-of-zelda-and-the-lampshade-of-no-real-significance","title":"The Legend of Zelda and the Lampshade of No Real Significance","description":"The Legend of Zelda and the Lampshade of No Real Significance is a 2005 adventure RPG from Super Flash Bros set in the town of Hyscule.","about":"Link stars in what the developers call his oddest journey, an RPG released in 2005 by Super Flash Bros. Players wander through a place named Hyscule. The game is packed with guest appearances drawn from Decline, Newgrounds and the wider gaming world. Tom handled ActionScript, game design, music and extra script, while Dim contributed art, animation, design and script work.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"veggie-playground","slug":"veggie-playground","title":"Veggie Playground","description":"Veggie Playground is a 2002 creative game from BigIdeaFUN and iToons where Veggie pals head outside to play.","about":"The sun is out, and the Veggies are ready for some fun. Players click and drag each Veggie onto the playground equipment, then watch what happens as they go. It is a simple creative activity built around moving the characters and seeing them react.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":550,"height":400},{"type":"flash","id":"animatronic-jumpscare-factory","slug":"animatronic-jumpscare-factory","title":"Animatronic Jumpscare Factory","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":650,"height":400},{"type":"flash","id":"battlefield-general","slug":"battlefield-general","title":"Battlefield General","description":"Battlefield General is a 2007 strategy game from FreeWorldStudios set in Qin dynasty China, where each campaign is judged by the gold it brings in.","about":"Set during the Qin dynasty, the game puts the player in command of war campaigns ordered by the First Emperor to bring all lands under his rule. Gold is the measure of success: each mission must yield at least 5000 gold pieces, and falling short means the Emperor takes 250 from the war fund as punishment. Anything earned beyond that amount goes toward construction of the Great Wall. Players aim to gather as much gold as possible, survive, and earn a place on the highscore list.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":750,"height":580},{"type":"flash","id":"bendee-the-game","slug":"bendee-the-game","title":"Bendee: The Game","description":"Bendee: The Game is a 2003 shooter-adventure from Edd Gould and Eddsworld, built around the stick figure character Bendee.","about":"Bendee: The Game is a shooter and adventure title from 2003, created by Edd Gould and Eddsworld. It takes its premise from the Bendee Stick character. The developer notes it as a third attempt at making a game.","system":"Flash","genre":"shooter","categories":"shooter|adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"bowja-3-ninja-kami","slug":"bowja-3-ninja-kami","title":"Bowja 3 – Ninja Kami","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"bowja-the-ninja-2-in-bigmans-compound","slug":"bowja-the-ninja-2-in-bigmans-compound","title":"Bowja the Ninja 2 In Bigman’s Compound","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"chain-of-fire","slug":"chain-of-fire","title":"Chain of Fire","description":"Chain of Fire is a 2009 arcade game from Mike Sebele and Edward Sebele that puts a new spin on chain-reaction gameplay.","about":"Chain of Fire is an arcade title built around the chain-reaction style of play. Released in 2009 by Mike Sebele and Edward Sebele, it offers a different take on that familiar genre. Players set off reactions that build from one element to the next, though the specifics of the mechanics are left to the game itself.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":570,"height":420},{"type":"flash","id":"deadly-neighbours-2","slug":"deadly-neighbours-2","title":"Deadly Neighbours 2","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":720,"height":480},{"type":"flash","id":"el-chicken-fantastico","slug":"el-chicken-fantastico","title":"El Chicken Fantastico","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":476,"height":324},{"type":"flash","id":"fosters-home-for-imaginary-friends-team-work","slug":"fosters-home-for-imaginary-friends-team-work","title":"Foster’s Home for Imaginary Friends: Team Work","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":600,"height":400},{"type":"flash","id":"gen8-dressup-doll","slug":"gen8-dressup-doll","title":"Gen8 Dressup Doll","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":720,"height":450},{"type":"flash","id":"gus-vs-bus","slug":"gus-vs-bus","title":"Gus vs. Bus","description":"Gus vs. Bus is a 2006 arcade game from Corus Entertainment about a student racing to catch his ride before summer break.","about":"It is the final day of school, and Gus has to reach the bus or he will be stuck at school all summer. Players help him catch up before the bus gets away. The game comes from Corus Entertainment and was released in 2006.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"happy-tree-friends-after-amok","slug":"happy-tree-friends-after-amok","title":"Happy Tree Friends – After Amok","system":"Flash","genre":"shooter","categories":"shooter|arcade","core":"swf","width":1000,"height":500},{"type":"flash","id":"happy-tree-friends-crazy-kermis","slug":"happy-tree-friends-crazy-kermis","title":"Happy Tree Friends – Crazy Kermis","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":500},{"type":"flash","id":"happy-tree-friends-nuttys-party-smoochie","slug":"happy-tree-friends-nuttys-party-smoochie","title":"Happy Tree Friends – Nutty’s Party Smoochie","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":544,"height":458},{"type":"flash","id":"haunted-house","slug":"haunted-house","title":"Haunted House","description":"Haunted House is a 2006 adventure game from developer Kmart in which the player explores a spooky residence.","about":"Haunted House is an adventure title released in 2006 by developer Kmart. The game invites the player to enter a haunted residence and see what happens. It is one of several educational games the developer created for an external site before they were later posted elsewhere.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":600,"height":500},{"type":"flash","id":"higgly-beach-or-bust","slug":"higgly-beach-or-bust","title":"Higgly Beach or Bust","description":"Higgly Beach or Bust is a 2004 single-player adventure game from Playhouse Disney and Cricket Moon Media.","about":"Higgly Beach or Bust is a single-player adventure game released in 2004 by Playhouse Disney and Cricket Moon Media. It is part of the Higglytown Heroes series and mixes adventure with a variety of activities.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":480,"height":360},{"type":"flash","id":"impossible-quiz-book-1","slug":"impossible-quiz-book-1","title":"Impossible Quiz Book 1","system":"Flash","genre":"quiz","categories":"quiz","core":"swf","width":550,"height":400},{"type":"flash","id":"jack-black-soundboard","slug":"jack-black-soundboard","title":"Jack Black Soundboard","description":"Jack Black Soundboard is a 2003 creative soundboard by Andrew Baranyi that plays quotes from the actor for prank calls.","about":"This soundboard collects quotes from Jack Black, and the creator notes that the audio quality is the best of any board he has made, with little to no background distortion. The interface is kept simple, and the board was easy to put together. An update added eleven new quotes. The intended use is prank calling friends, and the creator recommends viewing it at a resolution of 1024 by 768, since lower settings can make the images look foggy.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":936,"height":600},{"type":"flash","id":"jojos-circus-jumpin-jojo","slug":"jojos-circus-jumpin-jojo","title":"JoJo’s Circus: Jumpin’ JoJo","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":480,"height":360},{"type":"flash","id":"logic-matches","slug":"logic-matches","title":"Logic Matches","description":"Logic Matches is a 2002 single-player puzzle from Plastelina Games that challenges players with logic-based matchstick problems.","about":"Logic Matches is a single-player puzzle game from Plastelina Games and Shlomir Hadad, released in 2002 as part of the Plastelina Logic Games series. It presents logic-based matchstick puzzles that players work through one at a time.","system":"Flash","genre":"logic","categories":"logic|educational","core":"swf","width":500,"height":315},{"type":"flash","id":"lrd-rebirth","slug":"lrd-rebirth","title":"LRD: Rebirth","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":550,"height":400},{"type":"flash","id":"monoliths-mario-world-2","slug":"monoliths-mario-world-2","title":"Monoliths Mario World 2","description":"Monoliths Mario World 2 is a 2008 side-view platformer from developer Mono1337, continuing the series with larger stages and more foes.","about":"Monoliths Mario World 2 is a side-view platformer and the follow-up to Monoliths Mario World. Compared with the first entry, it offers larger worlds, additional enemies and extra items to collect. Players move with the arrow keys, jump with A and hold S to run or jump higher; Space pauses the action or brings up the map. The game is an unfinished demo that concludes in the castle, and it can occasionally freeze, often while a vine is being climbed, though pressing Space usually restores it.","system":"Flash","genre":"platformer","categories":"platformer|adventure","core":"swf","width":320,"height":300},{"type":"flash","id":"nicholas-weird-adventure-2","slug":"nicholas-weird-adventure-2","title":"Nicholas’ Weird Adventure 2","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":568,"height":390},{"type":"flash","id":"nightmares-the-adventures-episode-1-broken-bones-complaint","slug":"nightmares-the-adventures-episode-1-broken-bones-complaint","title":"Nightmares, the Adventures Episode 1: Broken Bone’s Complaint","description":"Nightmares, the Adventures Episode 1: Broken Bone's Complaint is a 2006 point-and-click adventure from Sarbakan.","about":"Nightmares, the Adventures Episode 1: Broken Bone's Complaint is a single-player point-and-click adventure released in 2006 by Sarbakan. It opens a series of adventure games built around exploring and interacting with the world through point-and-click play.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":675,"height":400},{"type":"flash","id":"nitromemustdie","slug":"nitromemustdie","title":"Nitrome Must Die","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":550},{"type":"flash","id":"papas-pastaria","slug":"papas-pastaria","title":"Papa’s Pastaria","description":"Papa's Pastaria, a 2013 simulation game from Flipline Studios, puts players in charge of a pasta restaurant in the town of Portallini.","about":"Players run Papa's newest restaurant in the waterfront town of Portallini, where a destination wedding is taking place. The job involves taking orders, cooking noodles, and adding sauces and toppings to build each plate of pasta. It is a time management cooking simulation played with the mouse.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"playing-with-fire","slug":"playing-with-fire","title":"Playing with Fire","description":"Playing with Fire is an action remake of Bomberman where players plant bombs to defeat opponents within a two-minute time limit.","about":"Playing with Fire is an action game that reworks the classic Bomberman formula. Players place bombs to take out their rivals before the clock runs out, and each match lasts only two minutes. It supports multiplayer, allowing a two-player game or a match against one, two, or three opponents.","system":"Flash","genre":"action","categories":"action","core":"swf","width":554,"height":410},{"type":"flash","id":"quiz-parampaa","slug":"quiz-parampaa","title":"Quiz Parampaa","system":"Flash","genre":"quiz","categories":"quiz","core":"swf","width":550,"height":400},{"type":"flash","id":"redballv2","slug":"redballv2","title":"Redball 4 Vol 2","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":640,"height":480},{"type":"flash","id":"redballv3","slug":"redballv3","title":"Redball 4 Vol 3","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":640,"height":480},{"type":"flash","id":"robin-the-hoodlum-a-spot-the-difference-comic","slug":"robin-the-hoodlum-a-spot-the-difference-comic","title":"Robin the Hoodlum: A Spot the Difference Comic","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":480},{"type":"flash","id":"sesame-street-check-out-cookie","slug":"sesame-street-check-out-cookie","title":"Sesame Street: Check Out Cookie","system":"Flash","genre":"puzzle","categories":"puzzle|logic","core":"swf","width":600,"height":307},{"type":"flash","id":"elmo-rhymes","slug":"elmo-rhymes","title":"Sesame Street: Elmo Rhymes","description":"Sesame Street: Elmo Rhymes is a 2002 educational game from Sesame Workshop built around rhyming activities for one player.","about":"Sesame Street: Elmo Rhymes is an educational game from Sesame Workshop, released in 2002 as part of the Sesame Street series. It is designed for a single player and focuses on rhyming activities.","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":550,"height":285},{"type":"flash","id":"spec-ops-war-on-terrorism","slug":"spec-ops-war-on-terrorism","title":"Spec Ops: War on Terrorism","description":"Spec Ops: War on Terrorism is a 2001 action game from TechRadium and Denni with four missions and no mercy.","about":"Spec Ops: War on Terrorism is a 2001 action game built around four missions. It came from developers TechRadium and Denni (Thorsten) and was made in response to the wave of Bin Laden-themed material appearing at the time. The game presents itself as a way to pass time by taking on Taliban targets.","system":"Flash","genre":"action","categories":"action","core":"swf","width":630,"height":410},{"type":"flash","id":"spongebob-squarepants-sea-monster-smoosh","slug":"spongebob-squarepants-sea-monster-smoosh","title":"SpongeBob SquarePants: Sea Monster Smoosh","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"sprinter","slug":"sprinter","title":"Sprinter","description":"Sprinter is a platformer where running, dodging obstacles and collecting coins are the core of the challenge.","about":"Sprinter is a platformer built around constant forward motion. The player sprints through the level, avoiding whatever obstacles stand in the way while gathering coins. Success depends on keeping the run going and reacting to hazards as they appear.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":640,"height":480},{"type":"flash","id":"testsubjectarena","slug":"testsubjectarena","title":"Test Subject Arena","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":550},{"type":"flash","id":"testsubjectcomplete","slug":"testsubjectcomplete","title":"Test Subject Complete","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":550},{"type":"flash","id":"totem-destroyer-2","slug":"totem-destroyer-2","title":"Totem Destroyer 2","description":"Totem Destroyer 2 is a 2009 physics puzzle game from Gabs.tv in which players demolish totems to bring their idols down safely.","about":"The totems return in greater numbers, with more than a hundred of them to work through. Each one has to be taken apart so the idol resting on top comes down, and the idol cannot hit the ground. It has to settle on a dark block instead. The game is built on physics, so blocks and pieces move as they are removed.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":690,"height":480},{"type":"flash","id":"tri-achnid","slug":"tri-achnid","title":"Tri-achnid","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":400},{"type":"flash","id":"wone","slug":"wone","title":"wOne","description":"wOne is a 2006 physics-based sports game by Sean Cooper where a wheel bounces, spins and rolls through challenging levels.","about":"wOne began as a physics demo and grew into a game built around a rolling wheel. Bounce, gravity, spin and friction govern the wheel's movement, and its momentum carries it up slopes and into difficult spots. Collision detection uses line intersections, giving the wheel a precise position on every surface, including corners. A sequel, wOne part 2, followed.","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":700,"height":400},{"type":"flash","id":"yeti-sports-5-flamingo-drive","slug":"yeti-sports-5-flamingo-drive","title":"Yeti Sports 5: Flamingo Drive","description":"Yeti Sports 5: Flamingo Drive is a 2004 sports arcade game from Edelweiss Medienwerkstatt and Chris Hilgert, played solo.","about":"Yeti Sports 5: Flamingo Drive is a single-player sports arcade game released in 2004 by Edelweiss Medienwerkstatt and Chris Hilgert. It belongs to the Yeti Sports series, which builds its games around simple sports-themed arcade challenges.","system":"Flash","genre":"sports","categories":"sports|arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"abuba-the-alien","slug":"abuba-the-alien","title":"Abuba the Alien","description":"Abuba the Alien is a 2009 point-and-click puzzle adventure from Pencilkids and Robin Vencel about helping a stranded alien get home.","about":"Abuba the Alien is a puzzle adventure in which a stranded alien needs help returning home. Players use the mouse to click objects and locations shown on the screen, and each interaction moves the game forward. The title was released in 2009 by Pencilkids and Robin Vencel.","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"aooa","slug":"aooa","title":"AOOA","description":"AOOA is a 2004 adventure game from designer Michael Clague, made as a personal project while he was still a student.","about":"AOOA is a single-player adventure game designed by Michael Clague. He created it in 2004 during his time as a student, and it stands as a personal project rather than a studio release. Clague later went on to found Carbon Studio.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":521,"height":704},{"type":"flash","id":"bad-piggies","slug":"bad-piggies","title":"Bad Piggies","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":960,"height":600},{"type":"flash","id":"bob-the-inventor","slug":"bob-the-inventor","title":"Bob The Inventor","description":"Bob The Inventor is a 2014 simulation game from Potato On The Table about building inventions and chasing a fortune.","about":"Bob The Inventor is a creative simulation game in which the player builds inventions. Success is measured by wealth, with the goal of becoming a billionaire. The game was developed by Potato On The Table and released in 2014.","system":"Flash","genre":"simulation","categories":"simulation|creative","core":"swf","width":800,"height":480},{"type":"flash","id":"canopy","slug":"canopy","title":"Canopy","description":"Canopy is an adventure game from 2010 where players fall through a fractal tree in a vector style.","about":"Canopy is a fractal tree zoomer presented in a vector style. Pressing play starts the fall, and clicking makes the descent faster. Turning on Mutation and Bloom makes the tree a little weirder. The game leaves the nature of the forest open to interpretation.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":400},{"type":"flash","id":"chalkzone-double-trouble","slug":"chalkzone-double-trouble","title":"ChalkZone: Double Trouble","description":"ChalkZone: Double Trouble is a 2004 platformer from Nickelodeon and Sarbakan where Rudy must escape a dangerous area full of hostile creatures.","about":"Rudy finds himself in a hazardous place filled with creatures that can harm him, and his goal is to get out safely. Players guide him through the area using the arrow keys, while the space bar is used to attack. The challenge comes from avoiding the many damaging creatures standing between Rudy and escape.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"chaos-of-mana","slug":"chaos-of-mana","title":"Chaos Of Mana","system":"Flash","genre":"action","categories":"action","core":"swf","width":500,"height":450},{"type":"flash","id":"charlie-and-lola-butterfly-gallery","slug":"charlie-and-lola-butterfly-gallery","title":"Charlie and Lola: Butterfly Gallery","description":"Charlie and Lola: Butterfly Gallery is a 2005 creative game from the BBC and CBeebies where players design a butterfly of their own.","about":"Players put together their own butterfly in this creative activity from the BBC and CBeebies. Once the design is finished, the butterfly takes flight inside the Butterfly Gallery. The game is built around making a personalised butterfly rather than completing challenges or levels.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":500,"height":300},{"type":"flash","id":"clarences-amazing-day-out","slug":"clarences-amazing-day-out","title":"Clarence’s Amazing Day Out!","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":600,"height":400},{"type":"flash","id":"codename-kids-next-door-flight-of-the-hamsters","slug":"codename-kids-next-door-flight-of-the-hamsters","title":"Codename: Kids Next Door: Flight of the Hamsters","description":"Codename: Kids Next Door: Flight of the Hamsters is a 2007 arcade game from Cartoon Network starring the Treehouse rodents.","about":"In this arcade title from Cartoon Network, the hamsters living in the Kids Next Door Treehouse get their moment in the air. The game centers on launching the rodents skyward for a round of daredevil stunts. It is a single-player experience tied to the Codename: Kids Next Door cartoon.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"codename-kids-next-door-numbuh-generator","slug":"codename-kids-next-door-numbuh-generator","title":"Codename: Kids Next Door: Numbuh Generator","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":600,"height":400},{"type":"flash","id":"create-a-wolf","slug":"create-a-wolf","title":"Create a Wolf","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":610,"height":450},{"type":"flash","id":"dino-run","slug":"dino-run","title":"Dino Run","description":"Dino Run is a 2008 arcade game from PixelJam Games where a dinosaur races to outrun a pyroclastic wall of doom.","about":"In Dino Run, the player controls a dinosaur trying to escape an approaching pyroclastic wall and reach a sanctuary. Movement uses the WASD or arrow keys, with a recharging speed boost, a downward air attack while jumping, and ducking to eat items on the ground. The game offers a challenge mode with seven levels and unlockable speedrun modes, where bones earned by eating critters and hitting milestones unlock extras. DNA gathered from eggs and critters upgrades the dinosaur, and progress is saved across three slots.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"dogfight-the-great-war","slug":"dogfight-the-great-war","title":"Dogfight: The Great War","description":"Dogfight: The Great War, a 2008 side-view shooter from Rock Solid Arcade, puts players in a Sopwith Camel for World War 1 aerial combat.","about":"Dogfight: The Great War is a side-view shooter set in World War 1. Players take the controls of a Sopwith Camel and go up against Germany's best pilots in the air. The game comes from Rock Solid Arcade and was released in 2008, part of the Dogfight series. It can be played alone or with others.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":800,"height":600},{"type":"flash","id":"drakkens-lair","slug":"drakkens-lair","title":"Drakken’s Lair","system":"Flash","genre":"platformer","categories":"platformer|action","core":"swf","width":580,"height":410},{"type":"flash","id":"flash-portal-2-the-game","slug":"flash-portal-2-the-game","title":"Flash Portal 2: The Game","description":"Flash Portal 2: The Game is a 2012 puzzle platformer from Wix Games in which a portal gun opens doorways into the unknown.","about":"Players fire a portal gun to create doorways that lead into unfamiliar places. The result mixes puzzle solving, adventure and shooting into a tribute to the series that inspired it. Progress depends on working out how to escape, and the game leaves open what waits on the other side.","system":"Flash","genre":"puzzle","categories":"puzzle|platformer","core":"swf","width":600,"height":400},{"type":"flash","id":"icarly-watermelon-pirate-attack","slug":"icarly-watermelon-pirate-attack","title":"iCarly: Watermelon Pirate Attack","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":550,"height":400},{"type":"flash","id":"ice-age-the-meltdown-scrat-jump","slug":"ice-age-the-meltdown-scrat-jump","title":"Ice Age: The Meltdown – Scrat Jump","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"jimmy-neutron-alien-invasion","slug":"jimmy-neutron-alien-invasion","title":"Jimmy Neutron: Alien Invasion!","description":"Jimmy Neutron: Alien Invasion! is a 2006 puzzle game from Nickelodeon and Sarbakan in which players help Jimmy defend the planet from alien hordes.","about":"In this puzzle game, the player takes on the task of helping Jimmy Neutron protect the planet from an alien invasion. The game was developed by Nickelodeon and Sarbakan and released in 2006. It is a single-player experience built around puzzle challenges tied to the science fiction setting.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":300},{"type":"flash","id":"johnny-and-the-sprites-sprite-tag-songbook","slug":"johnny-and-the-sprites-sprite-tag-songbook","title":"Johnny and the Sprites: Sprite Tag Songbook!","description":"Johnny and the Sprites: Sprite Tag Songbook! is a 2007 puzzle arcade game from Playhouse Disney and Cricket Moon Media.","about":"Based on the Johnny and the Sprites series, this single-player game mixes arcade and puzzle play with a musical theme. Players work through its challenges alone, guided by the show's characters and songs. It was made by Playhouse Disney and Cricket Moon Media in 2007.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":480,"height":360},{"type":"flash","id":"micro-life","slug":"micro-life","title":"Micro Life","description":"Micro Life is a 2005 strategy game from Kerb in which players guide a small organism through survival challenges in a harsh world.","about":"Micro Life is a strategy game built around artificial intelligence, made by Kerb in 2005. Players must keep a small creature alive by feeding it and defending it, since failing to eat or protect itself leads to death. Illness is another threat: an infected creature that is not quarantined can die and spread the sickness to others. The game teaches children about the difficulties of life and won Best Game at the Flash Film Festival in New York.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":600,"height":400},{"type":"flash","id":"power-swing","slug":"power-swing","title":"Power Swing","description":"Power Swing is a 2007 action space shooter from Sun-Studios, a straightforward arcade game built around blasting through space.","about":"Power Swing is a space shooter in which the player takes on enemies in outer space. It keeps things simple, focusing on the core shooting action rather than elaborate extras. The game was made by Sun-Studios in 2007 and was the developer's first released title.","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":500},{"type":"flash","id":"pupzzle","slug":"pupzzle","title":"Pupzzle","description":"Pupzzle is a 2009 point-and-click puzzle adventure from Pencilkids and Robin Vencel, starring a pup working through small tasks.","about":"Pupzzle follows a puzzle pup who has a set of small tasks to finish. Players move through the game by using the mouse to click objects and locations on the screen. Bones can also be gathered along the way for extra score. The result is a light, cute point-and-click puzzle adventure.","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"scooby-doo-mirror-match","slug":"scooby-doo-mirror-match","title":"Scooby-Doo: Mirror Match","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":650,"height":550},{"type":"flash","id":"shaper","slug":"shaper","title":"Shaper","description":"Shaper is a 2009 puzzle game from kChamp Games where a chain of random shapes must be arranged from start to finish without touching mines.","about":"The goal is to place a series of random shapes so they form a path connecting the start point to the finish. Mines are scattered around, and the chain cannot come into contact with any of them. There are 25 levels to work through, and finishing them all allows a score to be submitted.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":640,"height":480},{"type":"flash","id":"sheriff-tripeaks","slug":"sheriff-tripeaks","title":"Sheriff Tripeaks","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":400},{"type":"flash","id":"stork-shot","slug":"stork-shot","title":"Stork Shot","description":"Stork Shot is a 2011 arcade action game from Sun-Studios that mixes shooting mechanics with an unusual and offbeat theme.","about":"Stork Shot is an arcade shooting game released in 2011 by Sun-Studios. It plays with a comedic tone, and the original description notes that it is not appropriate for all audiences. The game is built around shooting action rather than a serious premise.","system":"Flash","genre":"arcade","categories":"arcade|action","core":"swf","width":800,"height":600},{"type":"flash","id":"the-diner","slug":"the-diner","title":"The Diner","description":"The Diner is a 2004 single-player simulation from Kellogg's and Nickelodeon starring SpongeBob SquarePants.","about":"The Diner is a single-player simulation starring SpongeBob SquarePants, released in 2004 by Kellogg's and Nickelodeon. It is a promotional time management game in which the player runs a diner.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":500},{"type":"flash","id":"twinshot","slug":"twinshot","title":"Twin Shot","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"blobs","slug":"blobs","title":"BLOBS!","description":"BLOBS! is a 2003 arcade game by Matt Ruggia where the goal is to wipe out every blob on screen while chasing a high score.","about":"BLOBS! is an arcade game from 2003 by Matt Ruggia, also known as Lost50. The aim is to eliminate all of the blobs, and the game keeps track of a high score for players to beat. It is a short, score-focused arcade title built around clearing the blobs.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":490,"height":500},{"type":"flash","id":"cattlepult","slug":"cattlepult","title":"CattlePult","description":"CattlePult is a 2007 puzzle game from Armor Games, part of the CattlePult series and made for single-player play.","about":"CattlePult is a single-player puzzle game released in 2007 by Armor Games, and it belongs to the CattlePult series. Players work through puzzles built around the game's cattle-launching theme.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":400},{"type":"flash","id":"charlie-and-lola-germ-counting","slug":"charlie-and-lola-germ-counting","title":"Charlie and Lola: Germ Counting","description":"Charlie and Lola: Germ Counting is a 2005 arcade game from BBC and CBeebies where Lola's mouth germs need counting.","about":"Lola has germs in her mouth, and the player helps her keep track of how many there are. The counting task is the centre of the game, which comes from the BBC and CBeebies and dates to 2005. It is a simple arcade-style activity built around Charlie and Lola.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":500,"height":300},{"type":"flash","id":"chisel","slug":"chisel","title":"Chisel","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":550},{"type":"flash","id":"clown-killer","slug":"clown-killer","title":"Clown Killer","description":"Clown Killer is a 2005 shooter from Thistler in which the player clears clowns from city streets before the clock runs out.","about":"Clowns have overrun the city streets, and the player's task is to take out as many of them as possible before time expires. It is a small shooter built around a single timed challenge rather than a longer campaign. Thistler made it as a mini-game and has mentioned plans for another version featuring weapon powerups, scrolling backgrounds and different enemy types.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":550,"height":400},{"type":"flash","id":"donald-and-the-beanstalk","slug":"donald-and-the-beanstalk","title":"Donald and the Beanstalk","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":480,"height":360},{"type":"flash","id":"dora-the-explorer-crocodile-lake","slug":"dora-the-explorer-crocodile-lake","title":"Dora the Explorer: Crocodile Lake","description":"Dora the Explorer: Crocodile Lake is a point-and-click puzzle adventure that sends players across a crocodile-filled lake.","about":"Dora the Explorer: Crocodile Lake is a single-player point-and-click puzzle adventure. Players use the mouse to work through puzzles on a journey across the lake.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":474,"height":283},{"type":"flash","id":"dora-the-explorer-find-floatie","slug":"dora-the-explorer-find-floatie","title":"Dora the Explorer: Find Floatie","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":475,"height":285},{"type":"flash","id":"dora-the-explorer-say-it-two-ways","slug":"dora-the-explorer-say-it-two-ways","title":"Dora the Explorer: Say It Two Ways","description":"Dora the Explorer: Say It Two Ways is a 2000 educational game for one player, built around a toy theme with Dora the Explorer.","about":"Dora the Explorer: Say It Two Ways is a single-player educational game from 2000 that draws on the Dora the Explorer series. The activity has a toy theme and is aimed at young players.","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":475,"height":285},{"type":"flash","id":"duck-dodgers-plan-8-from-upper-mars-mission-4","slug":"duck-dodgers-plan-8-from-upper-mars-mission-4","title":"Duck Dodgers: Plan 8 from Upper Mars – Mission 4","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":600,"height":400},{"type":"flash","id":"factory-balls-4","slug":"factory-balls-4","title":"Factory Balls 4","description":"Factory Balls 4 is a 2011 puzzle game from BONTE games where each level asks players to produce the ball shown on the box.","about":"Each level presents a target ball on a box, and the goal is to make a ball that matches it. Tools are applied to a ball by dragging and dropping it onto them, or simply by clicking a tool. Working out the right order and combination of tools is the core of the logic puzzle. Factory Balls 4 is the fourth entry in the series by BONTE games and Bart Bonte.","system":"Flash","genre":"puzzle","categories":"puzzle|logic","core":"swf","width":680,"height":600},{"type":"flash","id":"fly-guy","slug":"fly-guy","title":"Fly Guy","description":"Fly Guy is a 2002 adventure game by Trevor van Meter where players glide over rooftops and try to cover as much distance as possible.","about":"In Fly Guy, the player takes to the air above the rooftops and attempts to travel as far as possible. Clicking the left mouse button launches the character into flight. A green bar tracks stamina: the more running that is done, the less time can be spent airborne, and once the bar is full, flapping is no longer possible. Managing the balance between speed and power is central to making progress.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":500,"height":300},{"type":"flash","id":"fullmetal-alchemist-quest-for-the-philosophers-stone","slug":"fullmetal-alchemist-quest-for-the-philosophers-stone","title":"Fullmetal Alchemist: Quest For The Philosopher’s Stone","description":"Fullmetal Alchemist: Quest For The Philosopher's Stone is a 2004 single-player platformer from FUNimation based on the anime series.","about":"Fullmetal Alchemist: Quest For The Philosopher's Stone is a promotional platformer released in 2004 by FUNimation Productions. It is a single-player game tied to the Fullmetal Alchemist anime, with side-scrolling platforming as its main focus.","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":750,"height":380},{"type":"flash","id":"fullmetal-alchemist-state-alchemy-exam","slug":"fullmetal-alchemist-state-alchemy-exam","title":"Fullmetal Alchemist: State Alchemy Exam","description":"Fullmetal Alchemist: State Alchemy Exam is a 2004 single-player puzzle game from FUNimation Productions with sudoku-style challenges.","about":"Fullmetal Alchemist: State Alchemy Exam is a single-player puzzle game from 2004, developed by FUNimation Productions and set in the Fullmetal Alchemist series. Play centers on sudoku-style grid puzzles that are solved using the mouse alone.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":400},{"type":"flash","id":"go-diego-go-rainforest-adventure","slug":"go-diego-go-rainforest-adventure","title":"Go Diego Go: Rainforest Adventure","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":600,"height":340},{"type":"flash","id":"icarly-ipinball","slug":"icarly-ipinball","title":"iCarly: iPinball","description":"iCarly: iPinball is a 2009 arcade pinball game from Nickelodeon and Seven2, playable alone or with another player.","about":"iCarly: iPinball is an arcade pinball game released in 2009 by Nickelodeon and Seven2. It is part of the Nick 2009 Superstuffed Games series and can be played by one person or with multiple players.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":750,"height":500},{"type":"flash","id":"jojos-circus-train","slug":"jojos-circus-train","title":"JoJo’s Circus Train","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":480,"height":360},{"type":"flash","id":"khan-kluay-kids-war","slug":"khan-kluay-kids-war","title":"Khan Kluay – Kids War","description":"Khan Kluay – Kids War is a 2006 strategy arcade game from Kantana Animation where players send animals across the field.","about":"In this arcade-style strategy game, players send animals toward the other side of the field. At the same time, each player has to stop the animals the opponent sends their way. It can be played by two people on a desktop or laptop, and single-player play is also supported.","system":"Flash","genre":"strategy","categories":"strategy|arcade","core":"swf","width":640,"height":480},{"type":"flash","id":"mario-stomping-frenzy","slug":"mario-stomping-frenzy","title":"Mario Stomping Frenzy","description":"Mario Stomping Frenzy is a 2013 side-view platformer from Sun-Studios that puts Super Mario into a fast-paced arcade setting.","about":"Mario Stomping Frenzy is a single-player platformer played from a side view, released in 2013 by Sun-Studios. It mixes arcade pacing with Super Mario-style platforming.","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":800,"height":480},{"type":"flash","id":"master-solitaire","slug":"master-solitaire","title":"Master Solitaire","description":"Master Solitaire is a 2003 single-player card puzzle from MiniClip, played entirely with the mouse.","about":"Master Solitaire is a puzzle game built around solitaire card play, released by MiniClip in 2003. It is a single-player experience controlled with the mouse alone, so the focus stays on arranging and sorting the cards rather than on quick reflexes.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":500},{"type":"flash","id":"mission-match-up","slug":"mission-match-up","title":"Mission Match-up","description":"Mission Match-up is a 2003 space-themed puzzle game from Smashing Ideas and Postopia, played solo as a mahjong solitaire challenge.","about":"Mission Match-up is a single-player puzzle game set in space, released in 2003 by Smashing Ideas and Postopia. Play follows the mahjong solitaire format, with players matching tiles in an arcade-style presentation.","system":"Flash","genre":"puzzle","categories":"puzzle|arcade","core":"swf","width":600,"height":370},{"type":"flash","id":"my-new-room","slug":"my-new-room","title":"My New Room","description":"My New Room is a 2008 creative scene creator from GirlsGoGames where you decorate and arrange a room to your liking.","about":"My New Room is a creative scene creator from GirlsGoGames, released in 2008. In this single-player entry in the My New Room series, you decorate and arrange a room of your own design.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":660,"height":480},{"type":"flash","id":"power-tank","slug":"power-tank","title":"Power Tank","system":"Flash","genre":"shooter","categories":"shooter","core":"swf","width":600,"height":500},{"type":"flash","id":"reincarnation-a-demons-day-out","slug":"reincarnation-a-demons-day-out","title":"Reincarnation: A Demon’s Day Out","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":800,"height":480},{"type":"flash","id":"ask-swami-shaggy","slug":"ask-swami-shaggy","title":"Scooby-Doo: Ask Swami Shaggy","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":485,"height":350},{"type":"flash","id":"sitekick-factory","slug":"sitekick-factory","title":"SiteKick Factory","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"spongebob-squarepants-anchovy-assault","slug":"spongebob-squarepants-anchovy-assault","title":"SpongeBob SquarePants: Anchovy Assault","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":300},{"type":"flash","id":"spongebob-squarepants-ship-o-ghouls","slug":"spongebob-squarepants-ship-o-ghouls","title":"SpongeBob SquarePants: Ship O’ Ghouls","system":"Flash","genre":"platformer","categories":"platformer|arcade","core":"swf","width":600,"height":300},{"type":"flash","id":"the-x-spot","slug":"the-x-spot","title":"The X-spot","description":"The X-spot is a 2009 puzzle adventure from Pencilkids in which each level hides a single mark waiting to be clicked.","about":"Each level presents a creative puzzle with one goal: locate the X-spot and click on it. The mark can take any shape or form, and it may appear at any point during a level, so players need to watch closely. There are 25 puzzles in total, and the aim is to work through them as quickly as possible.","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"wrath-ii","slug":"wrath-ii","title":"Wrath II","description":"Wrath II is a 2002 single-player action game from developer Armegalo, continuing the Wrath series.","about":"Wrath II is an action game released in 2002 by Armegalo. It is built for single-player play and follows the earlier entry in the Wrath series.","system":"Flash","genre":"action","categories":"action","core":"swf","width":550,"height":400},{"type":"flash","id":"yeti-sports-4-albatross-overload","slug":"yeti-sports-4-albatross-overload","title":"Yeti Sports 4: Albatross Overload","description":"Yeti Sports 4: Albatross Overload is a 2004 single-player sports arcade game from Edelweiss Medienwerkstatt and Chris Hilgert.","about":"Yeti Sports 4: Albatross Overload is a single-player sports arcade game released in 2004 by Edelweiss Medienwerkstatt and Chris Hilgert. Part of the Yeti Sports series, it sets its sporting action in a tropical setting.","system":"Flash","genre":"sports","categories":"sports|arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"adrenaline-challenge","slug":"adrenaline-challenge","title":"Adrenaline Challenge","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":550,"height":400},{"type":"flash","id":"ben-10-power-splash","slug":"ben-10-power-splash","title":"Ben 10: Power Splash","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":400},{"type":"flash","id":"ben-10-spore-attack","slug":"ben-10-spore-attack","title":"Ben 10: Spore Attack","description":"Ben 10: Spore Attack is a 2008 action game from Cartoon Network in which Ben and Gwen fly over a forest to destroy deadly spores.","about":"Killer spores threaten to end the world if they are allowed to erupt. Ben and Gwen fly over the forest to stop them. Their weapon against the spores is foot powder, which destroys them on contact.","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":400},{"type":"flash","id":"ben-10-ultimate-alien-ultimate-alien-rescue","slug":"ben-10-ultimate-alien-ultimate-alien-rescue","title":"Ben 10: Ultimate Alien: Ultimate Alien Rescue","system":"Flash","genre":"shooter","categories":"shooter|platformer|action","core":"swf","width":960,"height":640},{"type":"flash","id":"bowja-3-expansion-the-fall-of-yokai","slug":"bowja-3-expansion-the-fall-of-yokai","title":"Bowja 3 Expansion – The Fall of Yokai","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"bowja-the-ninja-on-factory-island","slug":"bowja-the-ninja-on-factory-island","title":"Bowja the Ninja On Factory Island","description":"Bowja the Ninja On Factory Island is a 2008 point-and-click puzzle adventure from Pencilkids and Robin Vencel.","about":"In this point-and-click adventure, Bowja the Ninja sets out to destroy the Gi8000. Players use the mouse to select objects and spots on the screen, which moves Bowja further along his quest. The game mixes puzzle solving with an adventure structure.","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":640,"height":480},{"type":"flash","id":"cartoon-network-operation-s-t-a-t","slug":"cartoon-network-operation-s-t-a-t","title":"Cartoon Network: Operation S.T.A.T.","description":"Cartoon Network: Operation S.T.A.T. is a 2003 puzzle game where players construct a transmitter for the Kids Next Door.","about":"In this single-player puzzle game from 2003, the goal is to assemble a new transmitter for the Kids Next Door. Building it supports the effort to keep Cartoon Network under kid rule. Characters from several Cartoon Network shows appear, including The Powerpuff Girls, Ed, Edd n Eddy, Dexter's Laboratory, and Courage the Cowardly Dog.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":600,"height":400},{"type":"flash","id":"changetype","slug":"changetype","title":"Change Type","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":550},{"type":"flash","id":"charlie-and-lola-dressing-up","slug":"charlie-and-lola-dressing-up","title":"Charlie and Lola: Dressing Up","description":"Charlie and Lola: Dressing Up is a 2005 creative game from the BBC and CBeebies where players use a dressing up box.","about":"Charlie and Lola: Dressing Up lets players pick out clothes from a dressing up box. The choices can be used to dress up either Charlie or Lola. It is a creative activity based on the two characters.","system":"Flash","genre":"creative","categories":"creative","core":"swf","width":500,"height":300},{"type":"flash","id":"codename-kids-next-door-rainbow-monkey-rundown","slug":"codename-kids-next-door-rainbow-monkey-rundown","title":"Codename: Kids Next Door: Rainbow Monkey Rundown","description":"Codename: Kids Next Door: Rainbow Monkey Rundown is a 2007 shooter and action game from Cartoon Network.","about":"In this action shooter, the player takes on the role of Numbuh Three. King Sandy is in pursuit, and the chase unfolds as a speedboat getaway. The goal is to help Numbuh Three escape him.","system":"Flash","genre":"shooter","categories":"shooter|action","core":"swf","width":600,"height":400},{"type":"flash","id":"connect4","slug":"connect4","title":"Connect 4","description":"Connect 4 brings the classic disc-dropping puzzle game to the screen, with solo play against the computer or a two-player mode.","about":"This version of Connect 4 keeps the rules players remember from the traditional game while presenting it in a digital form. A match can be played alone against the computer, or two people can take each other on in the two-player mode. Opponents can be a friend or a family member sitting at the same device. The aim is still to line up discs and outplay whoever is on the other side.","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":310,"height":405},{"type":"flash","id":"controlcraft2","slug":"controlcraft2","title":"Control Craft 2","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":800,"height":600},{"type":"flash","id":"dont-eat-me","slug":"dont-eat-me","title":"Don’t Eat Me!","system":"Flash","genre":"action","categories":"action","core":"swf","width":800,"height":500},{"type":"flash","id":"donkey-kong-ii-game-watch","slug":"donkey-kong-ii-game-watch","title":"Donkey Kong II Game & Watch","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":600},{"type":"flash","id":"dragon-mountain","slug":"dragon-mountain","title":"Dragon Mountain","system":"Flash","genre":"puzzle","categories":"puzzle|adventure","core":"swf","width":600,"height":400},{"type":"flash","id":"fancypantsadventure2","slug":"fancypantsadventure2","title":"Fancy Pants Adventure 2","system":"Flash","genre":"platformer","categories":"platformer","core":"swf","width":720,"height":480},{"type":"flash","id":"flash-element-td","slug":"flash-element-td","title":"Flash Element TD","description":"Flash Element TD is a 2007 strategy game by David Scott where players build towers to stop creeps from crossing a maze.","about":"Creeps move along a maze and must be stopped before they reach its end. Towers are placed on the grass beside the path: a tower is selected on the right side, then clicked onto the map. Built towers can be clicked to upgrade or sell. Gold left in the bank earns interest after every round, and wood gained every seven levels is spent on research upgrades. Certain rounds feature unusual creeps such as fast, air, immune or boss types.","system":"Flash","genre":"strategy","categories":"strategy","core":"swf","width":650,"height":450},{"type":"flash","id":"frisbee-dog","slug":"frisbee-dog","title":"Frisbee Dog","description":"Frisbee Dog is a single-player arcade game from Kinelco about catching with a canine companion.","about":"Frisbee Dog is a single-player arcade game from Kinelco built around catching and canine themes. The action plays out in an arcade style, with the player taking part in catching-focused play alongside a dog.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":600,"height":400},{"type":"flash","id":"gus-vs-bus-2-l8r-sk8r","slug":"gus-vs-bus-2-l8r-sk8r","title":"Gus vs. Bus 2: L8R SK8R","description":"Gus vs. Bus 2: L8R SK8R is a 2007 arcade game from Corus Entertainment about skating to catch a bus.","about":"Gus is trying to catch a bus, and this time he is on a skateboard. The challenge is to build up enough speed while clearing every obstacle that stands between him and his ride. It follows the same setup as the first Gus vs. Bus, with the focus on reaching the bus before it gets away.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":550,"height":400},{"type":"flash","id":"hobo-brawl","slug":"hobo-brawl","title":"Hobo Brawl","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":450},{"type":"flash","id":"jimmy-timmy-power-hour-2-co-pilot-chaos","slug":"jimmy-timmy-power-hour-2-co-pilot-chaos","title":"Jimmy-Timmy Power Hour 2: Co-Pilot Chaos","description":"Jimmy-Timmy Power Hour 2: Co-Pilot Chaos is a 2006 Nickelodeon side-scrolling shooter starring the two cartoon heroes.","about":"Jimmy-Timmy Power Hour 2: Co-Pilot Chaos is a side-scrolling shooter from Nickelodeon, released in 2006. Players take control of characters from The Fairly OddParents and Jimmy Neutron in a single-player score-attack arcade game. It is part of the Jimmy-Timmy Power Hour series.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":520,"height":400},{"type":"flash","id":"jojos-circus-jojos-juggling-jumble","slug":"jojos-circus-jojos-juggling-jumble","title":"JoJo’s Circus: JoJo’s Juggling Jumble","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":480,"height":360},{"type":"flash","id":"moose-and-zees-whats-the-word-bird-game-show","slug":"moose-and-zees-whats-the-word-bird-game-show","title":"Moose and Zee’s “What’s the Word, Bird?” Game Show","system":"Flash","genre":"quiz","categories":"quiz|puzzle","core":"swf","width":740,"height":320},{"type":"flash","id":"moose-and-zees-balloon-math","slug":"moose-and-zees-balloon-math","title":"Moose and Zee’s Balloon Math","system":"Flash","genre":"educational","categories":"educational","core":"swf","width":600,"height":400},{"type":"flash","id":"pac-man","slug":"pac-man","title":"Pac-Man","description":"Pac-Man, Neave's 2002 arcade maze game, tasks players with clearing every white dot while avoiding the ghosts that roam the level.","about":"This arcade maze game from 2002 has the player steer Pac-Man around each level, eating all of the white dots. Ghosts wander the maze and must be avoided, since being caught costs one of the three lives. Levels continue without an upper limit.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":360,"height":420},{"type":"flash","id":"papas-sushiria","slug":"papas-sushiria","title":"Papa’s Sushiria","description":"Papa's Sushiria is a 2016 simulation game from Flipline Studios where players run a sushi restaurant and serve customers.","about":"In Papa's Sushiria, the player runs a sushi restaurant after breaking Papa Louie's lucky cat statue. The game involves cooking, seasoning, and spreading rice with the Sushi Square, then filling, rolling, and topping sushi with various ingredients. Players also cut sushi into bite-size pieces and mix bubble tea with flavored teas, milk, and toppings like tapioca pearls. The goal is to manage time and turn the restaurant's luck around.","system":"Flash","genre":"simulation","categories":"simulation","core":"swf","width":640,"height":480},{"type":"flash","id":"ping-pong-3d","slug":"ping-pong-3d","title":"Ping Pong 3D","description":"Ping Pong 3D is a 2002 table tennis arcade game from Luděk Salamánek in which only paddles appear on screen.","about":"Ping Pong 3D strips table tennis down to its essentials. The paddles are the only things visible on the table, with no player bodies shown. Players take part in a straightforward match of table tennis, using those paddles to send the ball back and forth. The result is a simple sports arcade game built around the basic exchange of a rally.","system":"Flash","genre":"sports","categories":"sports|arcade","core":"swf","width":700,"height":500},{"type":"flash","id":"scooby-doo-creepy-run","slug":"scooby-doo-creepy-run","title":"Scooby-Doo!: Creepy Run","description":"Scooby-Doo!: Creepy Run is a 2010 arcade game where Shaggy runs through a graveyard while dodging obstacles and a ghost.","about":"Shaggy is trying to get out of a graveyard, and the path is full of obstacles that must be avoided. A ghost is also chasing him, so staying clear of it is part of the run. The game was released in 2010 by 123Chase and Funnychasegames.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":650,"height":450},{"type":"flash","id":"skywire","slug":"skywire","title":"Skywire","system":"Flash","genre":"puzzle","categories":"puzzle","core":"swf","width":550,"height":400},{"type":"flash","id":"snow-siege","slug":"snow-siege","title":"Snow Siege","description":"Snow Siege is a 2006 arcade shooter from Corus Entertainment in which players pelt attacking gremlins with an endless supply of snowballs.","about":"Snow Siege is a winter-themed arcade shooter from 2006. Gremlins are on the attack, and the player holds them off by throwing snowballs. The supply of snowballs never runs out, so the challenge comes from the gremlins rather than from running low on ammunition.","system":"Flash","genre":"shooter","categories":"shooter|arcade","core":"swf","width":550,"height":440},{"type":"flash","id":"steakandjakemidnightmarch","slug":"steakandjakemidnightmarch","title":"Steak and Jake Midnight","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":672,"height":480},{"type":"flash","id":"swindler","slug":"swindler","title":"Swindler","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":550,"height":550},{"type":"flash","id":"the-batman-the-cobblepot-caper","slug":"the-batman-the-cobblepot-caper","title":"The Batman: The Cobblepot Caper","system":"Flash","genre":"action","categories":"action","core":"swf","width":600,"height":400},{"type":"flash","id":"the-glass-slipper-ball","slug":"the-glass-slipper-ball","title":"The Glass Slipper Ball","description":"The Glass Slipper Ball is a 2006 single-player adventure from Playhouse Disney and Cricket Moon Media.","about":"Players take part in a single-player adventure released in 2006 by Playhouse Disney and Cricket Moon Media. The game is tied to the Little Einsteins series and presents its story through a comic-style format.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":480,"height":360},{"type":"flash","id":"throw-me","slug":"throw-me","title":"Throw Me","description":"Throw Me is a 2007 arcade game from ThorGaming where players launch a small alien as far as possible using the mouse.","about":"In this colourful arcade title, the goal is to fling a little alien character as far as possible. Throwing is done with the mouse, and a limited spacebar boost is available for when the alien gets into trouble. The game keeps things simple, with distance as the measure of success.","system":"Flash","genre":"arcade","categories":"arcade","core":"swf","width":800,"height":550},{"type":"flash","id":"underlovetale","slug":"underlovetale","title":"UnderLOVETale","description":"UnderLOVETale is a 2016 adventure dating simulator from Chibixi where players talk with Undertale characters.","about":"Players find themselves in the world of Undertale and have 30 days to build love with its characters. Progress comes from talking to them and answering their questions, with the goal of reaching 100 percent. Eight characters can be interacted with, and ten different endings exist, along with secrets to discover. The game began as a belated April Fools project, and characters such as Sans, Papyrus, Mettaton and Susie were added in later updates.","system":"Flash","genre":"adventure","categories":"adventure","core":"swf","width":800,"height":600},{"type":"flash","id":"winnie-the-poohs-home-run-derby","slug":"winnie-the-poohs-home-run-derby","title":"Winnie the Pooh’s Home Run Derby","system":"Flash","genre":"sports","categories":"sports","core":"swf","width":640,"height":480},{"type":"flash","id":"yeti-sports-3-seal-bounce","slug":"yeti-sports-3-seal-bounce","title":"Yeti Sports 3: Seal Bounce","description":"Yeti Sports 3: Seal Bounce is a 2004 arctic sports arcade game from Edelweiss Medienwerkstatt and Chris Hilgert.","about":"Yeti Sports 3: Seal Bounce is an arctic-themed sports arcade game in the Yeti Sports series, released in 2004 by Edelweiss Medienwerkstatt and Chris Hilgert. It is played by a single player.","system":"Flash","genre":"sports","categories":"sports|arcade","core":"swf","width":500,"height":308},{"type":"retro","id":"1941","slug":"1941-counter-attack","title":"1941: Counter Attack","description":"Capcom's vertical shooter sends you skyward in February 1990, with a high-score quirk only export cabinets share.","about":"1941 - Counter Attack is a Capcom arcade shooter that reached players outside Japan in February 1990. It runs on the CP System hardware. Export versions carry a small difference from the Japanese original: the fifth spot on the high score table reads 'a02' rather than 'j01'. The board is identified as B-Board 89624B-3.","system":"Capcom CPS1","genre":"shooter","categories":"shooter","developer":"Capcom","year":1990,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 27 February 1990","core":"arcade"},{"type":"retro","id":"dino","slug":"cadillacs-and-dinosaurs","title":"Cadillacs and Dinosaurs","description":"Cadillacs and Dinosaurs pits street brawlers against prehistoric beasts in Capcom's 1993 arcade hit.","about":"Cadillacs and Dinosaurs is a Capcom arcade game released in February 1993 outside Japan, where it was known as Cadillacs Kyouryuu Shin Seiki, or Cadillacs New Dinosaur Century. This export version runs on Capcom Play System hardware with a B-Board numbered 91635B-2. One difference from the Japanese original: the scrolling text effect during the storyline was removed from all export releases.","system":"Capcom CPS1","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1993,"players":3,"hardware":"Capcom CP System (CPS1) with QSound","version":"World version of 1 February 1993","core":"arcade"},{"type":"retro","id":"captcomm","slug":"captain-commando","title":"Captain Commando","description":"Capcom's 1991 arcade brawler arrives in an export version with renamed heroes Ginzu, Mack the Knife, and Baby Head.","about":"Captain Commando is a 1991 Capcom arcade release, developed in Japan and issued as an export version on B-Board 91635B-2. In this export release, Sho is called Ginzu, Jennety is called Mack the Knife, and Hoover is called Baby Head.","system":"Capcom CPS1","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1991,"players":4,"hardware":"Capcom CP System (CPS1)","version":"World version of 2 December 1991","core":"arcade"},{"type":"retro","id":"cawing","slug":"carrier-air-wing","title":"Carrier Air Wing","description":"Capcom's 1990 arcade shooter flies as an export release with one notable graphical change from the Japanese version.","about":"Carrier Airwing is a 1990 Capcom arcade release, developed in Japan and issued as an export version on CP System hardware with B-Board ID 89624B-3. A character resembling Sean Connery looks even more like him in the Japanese release than in the export versions, where the graphic was changed — perhaps to avoid license issues in the U.S.","system":"Capcom CPS1","genre":"shooter","categories":"shooter","developer":"Capcom","year":1990,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 12 October 1990","core":"arcade"},{"type":"retro","id":"dynwar","slug":"dynasty-wars","title":"Dynasty Wars","description":"Capcom's 1989 arcade brawler Dynasty Wars brings ancient Chinese warfare to the coin-op screen.","about":"Dynasty Wars is a Capcom arcade game released in July 1989 outside Japan, where it was titled Tenchi wo Kurau, translating to Heaven and Earth Receiving Blows. This export version runs on CP System hardware with a B-Board ID of 88622B-3.","system":"Capcom CPS1","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1989,"players":1,"hardware":"Capcom CP System (CPS1)","version":"USA version","core":"arcade"},{"type":"retro","id":"ffight","slug":"final-fight","title":"Final Fight","description":"Capcom's 1990 arcade brawler cleans up the streets with fists and fury.","about":"Final Fight is a Capcom arcade beat'em up released in 1990. This export version was developed in Japan and runs on CP System hardware with B-Board ID 89624B-3. The original Japanese release included a scene showing Jessica in underwear on a TV in abstract mode, which was removed from all export versions. Completing the game on a single credit unlocks a special credits screen.","system":"Capcom CPS1","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1989,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version","core":"arcade"},{"type":"retro","id":"knights","slug":"knights-of-the-round","title":"Knights of the Round","description":"Capcom's 1991 arcade hack-and-slash lets you become a knight of the round table.","about":"This is the export version of Capcom's 1991 arcade beat 'em up, Knights of the Round. It is a side-scrolling action game based on the legends of King Arthur and his knights. For more information about the game itself, please see the original Japanese release entry. It runs on the CP System hardware.","system":"Capcom CPS1","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1991,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 27 November 1991","core":"arcade"},{"type":"retro","id":"msword","slug":"magic-sword","title":"Magic Sword","description":"Capcom's 1990 CPS1 export release of Magic Sword brings its heroic fantasy arcade action to Western players.","about":"Magic Sword - Heroic Fantasy is an arcade game released by Capcom in 1990, running on CP System hardware. This entry is the export version of a title developed in Japan.","system":"Capcom CPS1","genre":"action","categories":"action","developer":"Capcom","year":1990,"players":1,"hardware":"Capcom CP System (CPS1)","version":"World version of 25 July 1990","aka":["Magic Sword: Heroic Fantasy"],"core":"arcade"},{"type":"retro","id":"mtwins","slug":"mega-twins","title":"Mega Twins","description":"Capcom's 1990 CPS1 export release of Mega Twins delivers the arcade action of Chiki Chiki Boys overseas.","about":"Mega Twins is an arcade game released by Capcom in 1990, running on CP System hardware. This export version was developed in Japan, and the kidnapped bikini girls seen in later levels of the original are absent.","system":"Capcom CPS1","genre":"platformer","categories":"platformer","developer":"Capcom","year":1990,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 19 June 1990","core":"arcade"},{"type":"retro","id":"mbombrd","slug":"muscle-bomber-duo-ultimate-team-battle","title":"Muscle Bomber Duo: Ultimate Team Battle","description":"Capcom's 1993 wrestling tag battle brings team-based slamdowns to the arcade.","about":"Muscle Bomber Duo - Ultimate Team Battle is Capcom's 1993 export release of the tag-team wrestling fighter, running on Capcom Play System hardware. For non-Japanese audiences, several wrestlers were renamed: Zalazoff became Biff Slamkovich, Colt became Gunloc, Budo became Oni, Stinger became El Stingray, Sheep became Alexander The Grater, Gomes became Rasta, Kimala became Jumbo, and Astro became Scorpion.","system":"Capcom CPS1","genre":"fighting","categories":"fighting","developer":"Capcom","year":1993,"players":4,"hardware":"Capcom CP System (CPS1)","version":"World version of 6 December 1993","core":"arcade"},{"type":"retro","id":"pang3","slug":"pang-3","title":"Pang! 3","description":"Mitchell's bubble-bursting arcade series returns for a third round of frantic action.","about":"Pang! 3 is Mitchell's 1995 arcade release, developed in Japan and distributed as an export title. For full details on the game itself, see the original Japanese entry, Pang! 3 - Kaitou Tachi no Karei na Gogo. North American players know the game as Buster Buddies. The official record for it belongs to Sheila Van Buren, with 2,256,411 points.","system":"Capcom CPS1","genre":"puzzle","categories":"puzzle","developer":"Mitchell","year":1995,"players":2,"hardware":"Capcom CP System (CPS1)","version":"Europe version of 1 June 1995","core":"arcade"},{"type":"retro","id":"pnickj","slug":"pnickies","title":"Pnickies","description":"Capcom and Compile's colorful puzzle game brings blob-matching action to arcades.","about":"Pnickies is a puzzle game released by Capcom in June 1994 for Japanese arcades. Up to two players can compete simultaneously using an 8-way joystick and two buttons each. It was developed by Compile and was known as the 29th video game made for the CP System hardware.","system":"Capcom CPS1","genre":"puzzle","categories":"puzzle","developer":"Compile (Capcom license)","year":1994,"players":2,"hardware":"Capcom CP System (CPS1)","version":"Japan version of 8 June 1994","core":"arcade"},{"type":"retro","id":"sf2ce","slug":"street-fighter-ii-champion-edition","title":"Street Fighter II': Champion Edition","description":"The 1992 arcade export edition of Street Fighter II' Champion Edition from Capcom, running on CPS-1 hardware.","about":"Street Fighter II' - Champion Edition is a 1992 Capcom arcade fighting game released as an export version and developed in Japan. It runs on Capcom Play System hardware, with the B-Board numbered 91635B-2. This export release is tied to the original Japanese version, Street Fighter II' - Champion Edition [B-Board 91634B-2], for full details about the game itself.","system":"Capcom CPS1","genre":"fighting","categories":"fighting","developer":"Capcom","year":1992,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 13 May 1992","core":"arcade"},{"type":"retro","id":"sf2hf","slug":"street-fighter-ii-hyper-fighting","title":"Street Fighter II': Hyper Fighting","description":"Capcom's 1992 export arcade fighter Street Fighter II' Hyper Fighting, built on CPS-1 hardware.","about":"Street Fighter II' - Hyper Fighting is a 1992 Capcom arcade fighting game released as an export version and developed in Japan. It runs on Capcom Play System hardware, with the B-Board numbered 91635B-2. Outside Japan it arrived in December 1992, while in Japan the same game is known as Street Fighter II' Turbo - Hyper Fighting. For details about the game itself, see the original Japanese release entry.","system":"Capcom CPS1","genre":"fighting","categories":"fighting","developer":"Capcom","year":1992,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 9 December 1992","core":"arcade"},{"type":"retro","id":"kod","slug":"the-king-of-dragons","title":"The King of Dragons","description":"Capcom's 1991 fantasy beat-'em-up lets you battle dragons and monsters as five distinct hero classes.","about":"The King of Dragons is a 1991 Capcom arcade beat-'em-up released on CPS1 hardware. Players pick from character classes including Fighter, Cleric, and Wizard, each leveling up and gaining new abilities as they fight through a fantasy world of orcs, lizardmen, and dragons. This B-Board 89625B-1 revision differs notably from the earlier World version: the Cleric starts with 40 HP instead of 48, the first extra life arrives at 200,000 points rather than 100,000, fruit restores only 12 HP, and new foes like green lizard spearmen appear. It uses a single 4-Mbit EPROM instead of four 1-Mbit chips.","system":"Capcom CPS1","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1991,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 5 August 1991","core":"arcade"},{"type":"retro","id":"3wonders","slug":"three-wonders","title":"Three Wonders","description":"Capcom's three-in-one 1991 arcade package, with export tweaks to the action chapter.","about":"Three Wonders is a Capcom arcade release from 1991, running on the CP System hardware with B-Board 89624B-3. It was developed in Japan and saw export releases. Export versions differ from the Japanese original: the action game is titled 'Midnight Wanderers' instead of 'Roosters', and it plays slightly easier, with the stage 1 mid-boss firing at a lower rate and the stage 1 end-boss shooting more while punching less.","system":"Capcom CPS1","genre":"action","categories":"action","developer":"Capcom","year":1991,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 20 May 1991","core":"arcade"},{"type":"retro","id":"unsquad","slug":"u-n-squadron","title":"U.N. Squadron","description":"Capcom's 1989 arcade shooter soars into North American arcades with intense aerial combat.","about":"U.N. Squadron is Capcom USA's North American arcade release from August 1989, known in Japan as Area 88. It is a side-scrolling shoot-'em-up. This version notably omits the special mission found in the Japanese original. It runs on Capcom Play System hardware.","system":"Capcom CPS1","genre":"shooter","categories":"shooter","developer":"Daipro (Capcom license)","year":1989,"players":2,"hardware":"Capcom CP System (CPS1)","version":"USA version","core":"arcade"},{"type":"retro","id":"varth","slug":"varth-operation-thunderstorm","title":"Varth: Operation Thunderstorm","description":"Capcom's 1992 vertical shooter deploys worldwide for relentless arcade aerial warfare.","about":"Varth: Operation Thunderstorm is Capcom's 1992 export release of the Japanese-developed arcade shooter. It runs on CP System hardware. For full gameplay details, refer to the original Japanese release entry.","system":"Capcom CPS1","genre":"shooter","categories":"shooter","developer":"Capcom","year":1992,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 14 July 1992","core":"arcade"},{"type":"retro","id":"wof","slug":"warriors-of-fate","title":"Warriors of Fate","description":"Capcom's 1992 beat 'em up Warriors of Fate brings Three Kingdoms combat to arcades worldwide.","about":"Warriors of Fate is a 1992 Capcom Company, Limited arcade game released worldwide on CP System hardware, developed in Japan and known there as Tenchi wo Kurau II - Sekiheki no Tatakai and in Asia as Sangokushi II. It runs on a B-Board 91635B-2. Released in October 1992, the export version trims many scenes from the Japanese original: cutscenes with the third emperor, advisor messages, boss dialogues across stages, and a long stage 5 scene with a woman and baby. In-game names lost their kanji and were changed without proper translation.","system":"Capcom CPS1","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1992,"players":2,"hardware":"Capcom CP System (CPS1) with QSound","version":"World version of 31 October 1992","core":"arcade"},{"type":"retro","id":"willow","slug":"willow","title":"Willow","description":"Capcom USA's 1989 arcade release Willow arrives on CP System hardware for export regions.","about":"Willow is a 1989 Capcom USA, Incorporated arcade video game released for export territories and developed in Japan. It runs on the CP System hardware with B-Board ID 89624B-3.","system":"Capcom CPS1","genre":"action","categories":"action","developer":"Capcom","year":1989,"players":1,"hardware":"Capcom CP System (CPS1)","version":"World version","core":"arcade"},{"type":"retro","id":"1944","slug":"1944-the-loop-master","title":"1944: The Loop Master","description":"Capcom's CPS-II aerial shooter landed in the USA on June 20, 2000, and it runs on the blue board.","about":"1944 - The Loop Master is a Capcom arcade shooter built for the CP System II hardware, arriving in North America on June 20, 2000. The game was developed in Japan. The USA release uses the blue board configuration.","system":"Capcom CPS2","genre":"shooter","categories":"shooter","developer":"Eighting / Raizing (Capcom license)","year":2000,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 20 June 2000","core":"arcade"},{"type":"retro","id":"19xx","slug":"19xx-the-war-against-destiny","title":"19XX: The War Against Destiny","description":"Capcom's 1996 CPS-II shooter reached North America and Europe on the blue board hardware.","about":"19XX - The War Against Destiny is a Capcom arcade shooter released in 1996 for the CP System II hardware. It saw a North American and European release, with development handled in Japan. The overseas version runs on the blue board configuration.","system":"Capcom CPS2","genre":"shooter","categories":"shooter","developer":"Capcom","year":1996,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 4 January 1996","core":"arcade"},{"type":"retro","id":"avsp","slug":"alien-vs-predator","title":"Alien vs. Predator","description":"Capcom's 1994 CPS-II crossover pits the galaxy's deadliest hunters against its deadliest prey.","about":"Alien vs. Predator is an arcade game released by Capcom USA, Incorporated in 1994 on CP System II hardware, in North American and European release. It was developed in Japan. This Blue Board edition followed the original Japanese release, Alien vs. Predator, which arrived on a Green Board.","system":"Capcom CPS2","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1994,"players":3,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 20 May 1994","core":"arcade"},{"type":"retro","id":"armwar","slug":"armored-warriors","title":"Armored Warriors","description":"Capcom's 1994 CPS-II mech brawler, released in North America and Europe after its Japanese debut.","about":"Armored Warriors is an arcade game released by Capcom Company, Limited in 1994 on CP System II hardware, in North American and European release. It was developed in Japan. This Blue Board edition followed the original Japanese release, Powered Gear - Strategic Variant Armor Equipment, which arrived on a Green Board.","system":"Capcom CPS2","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1994,"players":3,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 24 October 1994","core":"arcade"},{"type":"retro","id":"batcir","slug":"battle-circuit","title":"Battle Circuit","description":"Capcom's 1997 CPS-II brawler arrived in Europe as a blue-board release.","about":"Battle Circuit is a Capcom arcade beat-'em-up that ran on CP System II hardware. The version covered here is the European blue-board release. Developed in Japan in 1997, it reached Europe under Capcom Company, Limited. A separate original Japanese green-board release also exists.","system":"Capcom CPS2","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1997,"players":4,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 19 March 1997","core":"arcade"},{"type":"retro","id":"csclub","slug":"capcom-sports-club","title":"Capcom Sports Club","description":"Capcom's sports mini-game collection arrives on CPS-II hardware in this European release.","about":"Capcom Sports Club is a Capcom CPS-II arcade title released in 1997, developed in Japan and published in Europe on Blue Board hardware.","system":"Capcom CPS2","genre":"sports","categories":"sports","developer":"Capcom","year":1997,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 17 October 1997","core":"arcade"},{"type":"retro","id":"cybots","slug":"cyberbots-fullmetal-madness","title":"Cyberbots: Fullmetal Madness","description":"Pilot massive mechs into combat in Capcom's 2D fighting game of armored duels.","about":"Cyberbots - Fullmetal Madness is a Capcom CPS-II arcade fighting game released in 1995, developed in Japan and published across North America and Europe. The export versions differ from the Japanese original: the Vs. screen drops the chapter titles and VA model numbers, victory quotes lose their voice samples, and a POWEREDGEAR HIGHSCORE CAMPAIGN after the credits is absent. Devilotte's servants Dr. Shutain and Jigoku Daishi become Xavier and Gary, and Gawaine's sword Magnablade goes unnamed.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1995,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 24 April 1995","core":"arcade"},{"type":"retro","id":"dstlk","slug":"darkstalkers-the-night-warriors","title":"Darkstalkers: The Night Warriors","description":"Capcom's 1994 CPS-II fighter unleashes vampires, werewolves and other night creatures on the arcade.","about":"Released in July 1994 outside Japan, Darkstalkers: The Night Warriors is Capcom's North American and European version of the game known in Japan as Vampire: The Night Warriors. Several characters carry different names in these export versions: Gallon becomes Jon Talbain, Zabel Zarock becomes Lord Raptor, Aulbath becomes Rikuo, and Phobos becomes Huitzil. Justin Wong holds the official record with 687,800 points set on May 30, 2008, and a Darkstalkers unit appears in the 1995 movie The Net.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1994,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 5 July 1994","core":"arcade"},{"type":"retro","id":"dimahoo","slug":"dimahoo","title":"Dimahoo","description":"Capcom's 2000 CPS-II shooter Dimahoo arrives in its North American and European arcade release.","about":"A Capcom CPS-II arcade game from 2000, this is the North American and European release of Dimahoo, developed in Japan. It runs on the CP System II hardware, using the Blue Board configuration for USA and Europe.","system":"Capcom CPS2","genre":"shooter","categories":"shooter","developer":"Eighting / Raizing (Capcom license)","year":2000,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 21 January 2000","core":"arcade"},{"type":"retro","id":"ddsom","slug":"dungeons-and-dragons-shadow-over-mystara","title":"Dungeons & Dragons: Shadow Over Mystara","description":"Capcom's CPS-II sequel brings the Dungeons & Dragons arcade saga back for another round of monster-filled brawling.","about":"A Capcom CPS-II arcade release from 1996, this is the North American and European version of Dungeons & Dragons: Shadow Over Mystara, developed in Japan. It runs on the CP System II hardware, specifically the Blue Board configuration used for USA and Europe.","system":"Capcom CPS2","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1996,"players":4,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 19 June 1996","core":"arcade"},{"type":"retro","id":"ddtod","slug":"dungeons-and-dragons-tower-of-doom","title":"Dungeons & Dragons: Tower of Doom","description":"Capcom's 1994 CPS-II brawler brings the Dungeons & Dragons tabletop world to the arcade.","about":"A Capcom CPS-II arcade title from 1994, this is the North American and European release of Dungeons & Dragons: Tower of Doom, with development handled in Japan. It runs on the CP System II hardware, on the Blue Board used for USA and Europe.","system":"Capcom CPS2","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1993,"players":4,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 12 April 1994","core":"arcade"},{"type":"retro","id":"ecofghtr","slug":"eco-fighters","title":"Eco Fighters","description":"Capcom's 1993 CPS-II shooter sends you into battle to protect the planet's wildlife.","about":"Eco Fighters is a Capcom arcade title released in 1993 on CP System II hardware. This North American and World release was developed in Japan, where it appeared under the title Ultimate Ecology. The game runs on the CP System II platform, specifically the Blue Board version distributed in the USA and other territories.","system":"Capcom CPS2","genre":"shooter","categories":"shooter","developer":"Capcom","year":1993,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"World version of 3 December 1993","core":"arcade"},{"type":"retro","id":"gigawing","slug":"giga-wing","title":"Giga Wing","description":"A vertical shooter with frantic bullet patterns and massive scores arrives in North America.","about":"Giga Wing is a Capcom arcade shooter released in North America on CPS-II hardware, developed in Japan. It runs on the Blue Board.","system":"Capcom CPS2","genre":"shooter","categories":"shooter","developer":"Takumi (Capcom license)","year":1999,"players":1,"hardware":"Capcom CP System II (CPS2)","version":"USA version of 22 February 1999","core":"arcade"},{"type":"retro","id":"hsf2","slug":"hyper-street-fighter-ii-the-anniversary-edition","title":"Hyper Street Fighter II: The Anniversary Edition","description":"Capcom marks Street Fighter II's anniversary with a CPS-II fighter spanning every version.","about":"Hyper Street Fighter II - The Anniversary Edition is Capcom's 2004 arcade fighter, released in North America on CPS-II hardware. The game was developed in Japan. For details about the game itself, see the original Japanese release entry, 'Hyper Street Fighter II - The Anniversary Edition [Green Board]'. This version runs on the blue board.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":2004,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"USA version of 2 February 2004","core":"arcade"},{"type":"retro","id":"mmatrix","slug":"mars-matrix","title":"Mars Matrix","description":"Mars Matrix - Hyper Solid Shooting arrives as a 2000 Capcom CPS-II North American cart.","about":"Mars Matrix - Hyper Solid Shooting is a 2000 Capcom Ent., Inc. CPS-II cart released in North America and developed in Japan. It runs on CP System II hardware on a Blue Board [USA], and is the North American counterpart to the Japanese release Mars Matrix - Hyper Solid Shooting [Green Board].","system":"Capcom CPS2","genre":"shooter","categories":"shooter","developer":"Takumi (Capcom license)","year":2000,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"USA version of 12 April 2000","aka":["Mars Matrix: Hyper Solid Shooting"],"core":"arcade"},{"type":"retro","id":"msh","slug":"marvel-super-heroes","title":"Marvel Super Heroes","description":"Marvel Super Heroes lands on Capcom CPS-II in 1995 for North America and Europe.","about":"Marvel Super Heroes is a 1995 Capcom Company, Limited CPS-II cart released in North America and Europe and developed in Japan. It runs on CP System II hardware on a Blue Board [USA & Europe], and is the regional counterpart to the Japanese release Marvel Super Heroes [Green Board]. It was released on October 24, 1995 (Tuesday).","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1995,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 24 October 1995","core":"arcade"},{"type":"retro","id":"mshvsf","slug":"marvel-super-heroes-vs-street-fighter","title":"Marvel Super Heroes vs. Street Fighter","description":"Marvel Super Heroes vs. Street Fighter hits Capcom CPS-II in 1997 for the West.","about":"Marvel Super Heroes vs. Street Fighter is a 1997 Capcom Company, Limited CPS-II cart released in North America and Europe and developed in Japan. It runs on CP System II hardware on a Blue Board [USA & Europe], and is the regional counterpart to the Japanese release Marvel Super Heroes vs. Street Fighter [Green Board].","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1997,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 25 June 1997","core":"arcade"},{"type":"retro","id":"mvsc","slug":"marvel-vs-capcom-clash-of-super-heroes","title":"Marvel vs. Capcom: Clash of Super Heroes","description":"Marvel heroes and Capcom fighters collide in a fast tag-team brawler built for the CPS-II arcade board.","about":"Marvel vs. Capcom - Clash of Super Heroes is a 1998 Capcom arcade fighting game on CPS-II hardware, released in North America and Europe after its Japanese debut. When the announcer's lines were recorded, she had to say both the original Japanese character names and the export versions; alternate pronunciations were also taped, including a Chun-Li take where 'Chun' rhymes with 'fun' and an unused Zangief reading heard in the Sound Test.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1998,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 23 January 1998","core":"arcade"},{"type":"retro","id":"megaman2","slug":"mega-man-2-the-power-fighters","title":"Mega Man 2: The Power Fighters","description":"Capcom's 1996 sequel brings more Robot Master duels to the CPS-II arcade board.","about":"Mega Man 2 - The Power Fighters is Capcom's 1996 North American and European arcade release, developed in Japan and running on CP System II hardware. It continues the arcade fighting take on the Mega Man series.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1996,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"USA version of 8 July 1996","core":"arcade"},{"type":"retro","id":"mpang","slug":"mighty-pang","title":"Mighty! Pang","description":"Mighty! Pang brings Mitchell Corp's 2000 bubble-bursting action to Capcom's CPS-II.","about":"Mighty! Pang is a 2000 Mitchell Corp CPS-II cart released across North America and Europe and developed in Japan. It runs on CP System II hardware on a Blue Board [USA & Europe], and is the regional counterpart to the Japanese release Mighty! Pang [Green Board].","system":"Capcom CPS2","genre":"puzzle","categories":"puzzle","developer":"Mitchell (Capcom license)","year":2000,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 10 October 2000","core":"arcade"},{"type":"retro","id":"nwarr","slug":"night-warriors-darkstalkers-revenge","title":"Night Warriors: Darkstalkers' Revenge","description":"Capcom's Darkstalkers sequel brings its monster roster to Western arcades.","about":"Night Warriors - Darkstalkers' Revenge is the North American and European release of Capcom's 1995 CPS-II fighting game, developed in Japan. For details on the game itself, see the original Japanese entry, Vampire Hunter - Darkstalkers' Revenge. The export versions dropped the expanded character epilogues found in the Japanese release, leaving only background character art. Several names were also changed for these versions: Gallon became Jon Talbain, Zabel Zarock became Lord Raptor, Aulbath became Rikuo, Phobos became Huitzil and Lei-Lei became Hsien-Ko.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1995,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 16 March 1995","core":"arcade"},{"type":"retro","id":"progear","slug":"progear-storm-of-progia","title":"Progear: Storm Of Progia","description":"Capcom's bullet-hell shooter storms arcades with stylish steampunk dogfighting action.","about":"Progear is a horizontally scrolling shoot-em-up released by Capcom in 2001 on CPS-II hardware. This entry is the North American release of the game developed in Japan. For details about the game itself, see the original Japanese release entry, Progear no Arashi.","system":"Capcom CPS2","genre":"shooter","categories":"shooter","developer":"Cave (Capcom license)","year":2001,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 17 January 2001","core":"arcade"},{"type":"retro","id":"pzloop2","slug":"puzz-loop-2","title":"Puzz Loop 2","description":"Mitchell's 2001 puzzle sequel Puzz Loop 2 arrives on Capcom CPS-II hardware in its European release.","about":"Puzz Loop 2 is a 2001 Mitchell Corp arcade game, released in Europe on a Capcom CPS-II cart and developed in Japan. It runs on CP System II hardware. For more on the game itself, see the original Japanese release entry, 'Puzz Loop 2 [Green Board]'.","system":"Capcom CPS2","genre":"puzzle","categories":"puzzle","developer":"Mitchell (Capcom license)","year":2001,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 2 March 2001","core":"arcade"},{"type":"retro","id":"ringdest","slug":"ring-of-destruction-slam-masters-2","title":"Ring of Destruction: Slam Masters 2","description":"Capcom's 1994 wrestling brawler Ring of Destruction: Slam Masters 2 hits the CPS-II ring.","about":"Ring of Destruction: Slam Masters 2 is a 1994 Capcom arcade wrestling game running on CPS-II hardware, released in Europe and developed in Japan. It continues the Super Muscle Bomber series. Export versions renamed many fighters, though the Tokyo stage still shows their original Japanese names on a jumbo monitor before displaying the Super Muscle Bomber logo.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1994,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 2 September 1994","aka":["Ring of Destruction: Slammasters II"],"core":"arcade"},{"type":"retro","id":"sfa2","slug":"street-fighter-alpha-2","title":"Street Fighter Alpha 2","description":"Street Fighter Alpha 2, Capcom's 1996 CPS-II arcade sequel, arrived in North America and Europe.","about":"Street Fighter Alpha 2 is a 1996 Capcom arcade fighting game on a CPS-II cartridge, released in North America and Europe and developed in Japan. For more about the game itself, see the original Japanese release entry, Street Fighter Zero 2 [Green Board]. Europe got it in February 1996 and the USA in March 1996. Export versions renamed Nash to Charlie, Vega to M. Bison, Gouki to Akuma, Shin Gouki to Shin Akuma, and Satsui no Hadou ni Mezameta Ryu to Evil Ryu. Japanese versions showed specific stage locations, while export versions listed only the country.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1996,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 29 February 1996","core":"arcade"},{"type":"retro","id":"sfa3","slug":"street-fighter-alpha-3","title":"Street Fighter Alpha 3","description":"Street Fighter Alpha 3, Capcom's 1998 CPS-II fighter, hit North American and European arcades.","about":"Street Fighter Alpha 3 is a 1998 Capcom arcade fighting game on a CPS-II cartridge, released in North America and Europe and developed in Japan. For more about the game itself, see the original Japanese release entry, Street Fighter Zero 3 [Green Board]. Export versions renamed Gouki to Akuma, M. Bison to Balrog, Nash to Charlie, Vega to M. Bison, Shin Vega to Final Bison, and Balrog to Vega; in Europe and the Western Hemisphere the Z-ISM became A-ISM. Specific Japanese stage locations were dropped from export versions, leaving only country names.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1998,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 4 September 1998","core":"arcade"},{"type":"retro","id":"sfa","slug":"street-fighter-alpha-warriors-dreams","title":"Street Fighter Alpha: Warriors' Dreams","description":"Street Fighter Alpha: Warriors' Dreams brought Capcom's 1995 CPS-II fighter to North America and Europe.","about":"Street Fighter Alpha - Warriors' Dreams is a 1995 Capcom USA arcade fighting game on a CPS-II cartridge, released in North America and Europe and developed in Japan. For more about the game itself, see the original Japanese release entry, Street Fighter Zero [Green Board]. This export version landed in June 1995. To stay consistent with earlier games, Nash became Charlie, Gouki became Akuma, and Vega became M. Bison. The Japanese version used an instrumental of 'Itoshisato Setsunasato Kokorotsuyosato' during Dramatic Battle mode, a change also made in the home ports.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1995,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 27 July 1995","core":"arcade"},{"type":"retro","id":"sfz2al","slug":"street-fighter-zero-2-alpha","title":"Street Fighter Zero 2 Alpha","description":"Capcom's 1996 arcade upgrade to Street Fighter Zero 2, packed with new moves and modes.","about":"Street Fighter Zero 2 Alpha is an enhanced arcade edition of Street Fighter Zero 2, arriving in Japanese, Southeast Asian, Brazilian, and Hispanic arcades in August 1996. Outside those regions it reached players only on home consoles. It stays close to its predecessor while handing several fighters an extra move or two, and it adds modes including Dramatic Battle, Shin Akuma Mode, and Survival. The game runs on Capcom's CPS-II hardware.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1996,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Asia version of 26 August 1996","core":"arcade"},{"type":"retro","id":"sgemf","slug":"super-gem-fighter-mini-mix","title":"Super Gem Fighter Mini Mix","description":"Capcom's 1997 CPS-II fighter mixing Pocket Fighter action with gem-powered mini battles.","about":"Super Gem Fighter - Mini Mix is the North American and European release of a Capcom fighting game built for CPS-II hardware and developed in Japan. It arrived in 1997. The Japanese arcade original is Pocket Fighter, released on a Green Board, while this version runs on a Blue Board. Details of the game itself are covered under that original entry.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1997,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"USA version of 4 September 1997","core":"arcade"},{"type":"retro","id":"spf2t","slug":"super-puzzle-fighter-ii-turbo","title":"Super Puzzle Fighter II Turbo","description":"Capcom's 1996 puzzle spinoff brings Super Puzzle Fighter II Turbo to CPS-II arcade cabinets.","about":"Super Puzzle Fighter II Turbo is a Capcom arcade title released in 1996 on the CP System II hardware, distributed as an export release with the game developed in Japan. This Blue Board version covers USA and Europe. It is the export counterpart to the original Japanese entry, Super Puzzle Fighter 2 II [Green Board].","system":"Capcom CPS2","genre":"puzzle","categories":"puzzle","developer":"Capcom","year":1996,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 29 May 1996","core":"arcade"},{"type":"retro","id":"ssf2t","slug":"super-street-fighter-ii-turbo","title":"Super Street Fighter II Turbo","description":"Capcom's 1994 CPS-II fighter, where Akuma debuted overseas with his victory quotes and ending stripped out.","about":"A 1994 Capcom arcade fighting game on CPS-II hardware, released outside Japan in February 1994 as the export version of Super Street Fighter II X - Grand Master Challenge. In these overseas releases, the character Gouki appears as Akuma, but all of his dialogue was removed rather than translated, leaving him without victory quotes and with no ending at all, only a credit roll and images of his defeated opponents.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1994,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"World version of 23 February 1994","core":"arcade"},{"type":"retro","id":"vhunt2","slug":"vampire-hunter-2-darkstalkers-revenge","title":"Vampire Hunter 2: Darkstalkers' Revenge","description":"Fourteen hellish creatures clash for control of the nether-realms in Capcom's 1997 fighter.","about":"Vampire Hunter 2: Darkstalkers' Revenge is a 1997 Capcom CPS-II arcade fighting game released only in Japan, where it was the 27th title for the CPS2 hardware. Up to two players battle with an 8-way joystick and six buttons covering light, medium, and heavy punches and kicks. Rather than a true sequel, it is a redesigned version built on the newest Darkstalkers engine, even reworking Vampire Savior 2's intro to remove references to Jedah, Bulleta, Q-Bee, and Lilith.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1997,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Japan version of 29 September 1997","core":"arcade"},{"type":"retro","id":"vsav2","slug":"vampire-savior-2","title":"Vampire Savior 2","description":"Fifteen fighters clash to stop Jedah in Capcom's 1997 CPS-II sequel, released in Japanese arcades.","about":"Vampire Savior 2 - The Lord of Vampire is a 1997 Capcom fighting game on CPS-II hardware, where fifteen characters battle to end Jedah's reign and save their souls. It hit Japanese arcades in September 1997 as the 26th CPS2 title, supporting two players with an 8-way joystick and six buttons each. The intro hides a split-second montage of character sketches. Donovan's inclusion stems from a Capcom change: the original Vampire Savior draft had him turned into a demon and Anita added as a teen, but both were cut and only restored, ageless, here. The game isn't canon, partly due to Pyron, destroyed in the first tournament.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1997,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Japan version of 13 September 1997","aka":["Vampire Savior 2: The Lord of Vampire"],"core":"arcade"},{"type":"retro","id":"vsav","slug":"vampire-savior-the-lord-of-vampire","title":"Vampire Savior: The Lord Of Vampire","description":"Capcom's 1997 CPS-II fighter brings darkstalkers to battle, with renamed characters for Western arcades.","about":"Vampire Savior - The Lord of Vampire is a 1997 Capcom arcade fighting game released on CPS-II hardware for North America and Europe. It was developed in Japan and runs on the CP System II, specifically the Blue Board for USA and Europe. In these export versions, several fighters carry different names: Bulleta becomes B. B. Hood, Lei-Lei is Hsien-Ko, Gallon is Jon Talbain, Zabel Zarock is Lord Raptor, and Aulbath is Rikuo.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1997,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 19 May 1997","core":"arcade"},{"type":"retro","id":"xmvsf","slug":"x-men-vs-street-fighter","title":"X-Men vs Street Fighter","description":"Capcom's 1996 CPS-II crossover X-Men vs. Street Fighter pits mutant against martial artist in arcades.","about":"X-Men vs. Street Fighter is a 1996 Capcom Company, Limited arcade fighting game released for North America and Europe on CPS-II hardware, developed in Japan. It runs on the CP System II, specifically the Blue Board for USA and Europe.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1996,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 4 October 1996","core":"arcade"},{"type":"retro","id":"xmcota","slug":"x-men-children-of-the-atom","title":"X-Men: Children Of The Atom","description":"Capcom's 1994 CPS-II fighter X-Men: Children of the Atom lands in North American and European arcades.","about":"X-Men - Children of the Atom is a 1994 Capcom Company, Limited arcade fighting game released for North America and Europe on CPS-II hardware, developed in Japan. It runs on the CP System II, specifically the Blue Board for USA and Europe.","system":"Capcom CPS2","genre":"fighting","categories":"fighting","developer":"Capcom","year":1994,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"Europe version of 31 March 1995","core":"arcade"},{"type":"retro","id":"jojoba","slug":"jojo-s-bizarre-adventure","title":"JoJo's Bizarre Adventure","description":"Capcom's 1999 CPS-III fighter continues the JoJo saga with new characters and abilities.","about":"Released by Capcom in 1999 for the CPS-III arcade system, this is the export version of the second JoJo fighting game. It continues the series' unique style of combat. For more information about the game itself, please see the original Japanese version entry, JoJo no Kimyou na Bouken - Mirai e no Isan.","system":"Capcom CPS3","genre":"fighting","categories":"fighting","developer":"Capcom","year":1999,"players":2,"hardware":"Capcom CP System III (CPS3)","version":"Europe version of 15 October 1999","core":"arcade"},{"type":"retro","id":"jojo","slug":"jojo-s-venture","title":"JoJo's Venture","description":"Capcom's 1998 arcade fighter brings the bizarre world of JoJo to the CPS-III system.","about":"This is the export version of Capcom's 1998 arcade fighting game, released for the CPS-III system. It is based on the popular manga and anime series JoJo's Bizarre Adventure. For details on the game itself, see the original Japanese version, JoJo no Kimyou na Bouken.","system":"Capcom CPS3","genre":"fighting","categories":"fighting","developer":"Capcom","year":1998,"players":2,"hardware":"Capcom CP System III (CPS3)","version":"Europe version of 28 January 1999","core":"arcade"},{"type":"retro","id":"redearth","slug":"red-earth","title":"Red Earth","description":"Capcom's 1996 CPS-III fantasy fighter Red Earth pits warriors against mighty beasts.","about":"Red Earth is a Capcom arcade title released in October 1996 on the CPS-III hardware, known in Japan as War-Zard. It was the very first game produced for Capcom's Play System III board. This export release was developed in Japan and carries the distinction of launching a new generation of Capcom arcade hardware.","system":"Capcom CPS3","genre":"fighting","categories":"fighting","developer":"Capcom","year":1996,"players":2,"hardware":"Capcom CP System III (CPS3)","version":"Europe version of 21 November 1996","core":"arcade"},{"type":"retro","id":"sfiii2","slug":"street-fighter-iii-2nd-impact","title":"Street Fighter III: 2nd Impact","description":"Street Fighter III: 2nd Impact - Giant Attack, Capcom's 1997 CPS-III sequel with Hugo and Urien.","about":"Street Fighter III - 2nd Impact: Giant Attack is a 1997 Capcom arcade fighting game released as a CPS-III kit and the sequel to Street Fighter III - New Generation. It adds Hugo, Urien and returning character Akuma (Gouki in Japan), plus a speed increase, new moves and several damage-related tweaks. It launched on September 30, 1997. The 'Giant Attack' subtitle refers to the two huge new characters, Hugo and Urien. It is the only CPS3 game with a widescreen mode. Hugo is based on the late WWF Hall of Famer Andre The Giant, and Firstsmile released a limited-edition soundtrack album on December 17, 1997.","system":"Capcom CPS3","genre":"fighting","categories":"fighting","developer":"Capcom","year":1997,"players":2,"hardware":"Capcom CP System III (CPS3)","version":"USA version of 30 September 1997","aka":["Street Fighter III 2nd Impact: Giant Attack"],"core":"arcade"},{"type":"retro","id":"sfiii3","slug":"street-fighter-iii-3rd-strike","title":"Street Fighter III: 3rd Strike","description":"Street Fighter III: 3rd Strike - Fight For The Future, Capcom's 1999 CPS-III arcade fighter.","about":"Street Fighter III - 3rd Strike: Fight For The Future is a 1999 Capcom one-on-one fighting game for one or two players, released as a CPS-III kit and the second follow-up to Street Fighter III after 2nd Impact. It added five characters, including Chun-Li, plus Remy, Makoto, Q and Twelve, bringing the roster to twenty, and reintroduced the 'Destroy the Car' bonus stage. New mechanics include the Guard Parry, or 'Red Parry', letting players parry during guard stun with correct timing, and after-match evaluations grading Offense, Defence, Tech and Extra from E to MSF. It released in May 1999 and was the first Street Fighter game with a rap/hip hop urban theme.","system":"Capcom CPS3","genre":"fighting","categories":"fighting","developer":"Capcom","year":1999,"players":2,"hardware":"Capcom CP System III (CPS3)","version":"Europe version of 8 June 1999","aka":["Street Fighter III 3rd Strike: Fight for the Future"],"core":"arcade"},{"type":"retro","id":"sfiii","slug":"street-fighter-iii-new-generation","title":"Street Fighter III: New Generation","description":"Street Fighter III: New Generation, Capcom's 1997 CPS-III arcade fighter with landmark 2-D animation.","about":"Street Fighter III - New Generation is a 1997 Capcom arcade fighting game released as a CPS-III kit. It features larger character sprites than earlier Street Fighter games and, at release, the smoothest and most detailed 2-D animation ever made, a quality still unmatched outside the Street Fighter III series as of 2004; some critics felt too much was animated, slowing the pace. It hit Japanese arcades on February 17, 1997, and Capcom's flyer states animations run at up to 64 frames per second. The marquee simply calls it 'Three'. Sean was originally meant to be the only fighter using Ryu and Ken's style, with Ken and Ryu added later by fan demand.","system":"Capcom CPS3","genre":"fighting","categories":"fighting","developer":"Capcom","year":1997,"players":2,"hardware":"Capcom CP System III (CPS3)","version":"Europe version of 4 February 1997","core":"arcade"},{"type":"retro","id":"3countb","slug":"3-count-bout","title":"3 Count Bout","description":"SNK's 100-Mega Shock wrestling game pits 10 grapplers against each other in the ring.","about":"Fire Suplex is a pro-wrestling game for the Neo-Geo MVS, known outside Japan as 3 Count Bout. Ten wrestlers bring Power Attacks and Malevolent Moves into the ring, biting, kicking, and punching toward the top spot, with competitive play and tag match battles. It supports two players with four buttons each. Released in Japan on March 25, 1993, it was developed by UPL and stands as the last game that manufacturer produced. It is the only 'true' wrestling title on the MVS hardware, with King of The Monsters predating it in the giant-monster sense. Game ID: NGM-043.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1993,"players":2,"hardware":"Neo Geo MVS","aka":["Fire Suplex"],"core":"arcade"},{"type":"retro","id":"sonicwi2","slug":"aero-fighters-2","title":"Aero Fighters 2","description":"Eight pilots, eight jets, and randomized bosses fill Video System's 1994 Neo-Geo shooter Sonic Wings 2.","about":"Sonic Wings 2 is a vertically scrolling shoot-em-up released by Video System on July 18, 1994, and known outside Japan as Aero Fighters 2. Players pick from eight fighter pilots, each flying a distinct jet such as the F-117A Nighthawk or the Rafale, battling jets, boats, helicopters, gun emplacements, and huge bosses whose identities change between playthroughs. Story and endings shift based on the pilot pair selected, with 47 endings in total, and the game famously blocks the initials 'SEX' on the high score table, changing them to 'OH!'. It runs on Neo-Geo MVS hardware under game ID NGM-075.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"Video System Co.","year":1994,"players":2,"hardware":"Neo Geo MVS","aka":["Sonic Wings 2"],"core":"arcade"},{"type":"retro","id":"sonicwi3","slug":"aero-fighters-3","title":"Aero Fighters 3","description":"Video System's 1995 Neo-Geo shooter sends ten pilots worldwide to crush terrorism, then into outer space.","about":"Sonic Wings 3 is the third entry in Video System's shoot-em-up series, released in October 1995 and known outside Japan as Aero Fighters 3. Players pilot jet fighters from country to country destroying terrorist forces before heading into outer space, with each pilot carrying a personal storyline. A single enemy shot destroys your plane and releases its power-up, and the space mission restarts from the beginning unless a second player is active. The game offers 23 endings, four random last bosses, and blocks the initials 'SEX', changing them to 'HEY'. It runs on Neo-Geo MVS hardware under game ID NGM-097.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"Video System Co.","year":1995,"players":2,"hardware":"Neo Geo MVS","aka":["Sonic Wings 3"],"core":"arcade"},{"type":"retro","id":"alpham2","slug":"alpha-mission-ii","title":"Alpha Mission II","description":"SNK's vertically scrolling Neo-Geo shooter, known outside Japan as Alpha Mission II.","about":"ASO II - Last Guardian is SNK's full-screen vertically scrolling shoot'em up for the Neo-Geo MVS, released in Japan on March 25, 1991. Outside Japan it is known as Alpha Mission II. Game ID: NGM-007. Two players can join with four buttons each, three of them usable, and the controls differ by type: Type A maps missile/laser/attach armor, armor attack, and menu, while Type B maps laser/attach armor, missile, and menu.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"SNK","year":1991,"players":2,"hardware":"Neo Geo MVS","aka":["ASO II: Last Guardian"],"core":"arcade"},{"type":"retro","id":"androdun","slug":"andro-dunos","title":"Andro Dunos","description":"Visco's 1992 Neo-Geo shooter lets you swap weapon types on the fly across a horizontal battlefield.","about":"Andro Dunos is a horizontally scrolling shoot'em up released by Visco Corp in 1992 on SNK Neo-Geo MVS hardware. Players can switch between different weapon settings during play. Arriving on June 15, 1992, it holds the distinction of being Visco's first game developed and released for the SNK Neo-Geo MVS platform. Its Game ID is NGM-049.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"Visco","year":1992,"players":1,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"aof2","slug":"art-of-fighting-2","title":"Art of Fighting 2","description":"SNK's 1994 Neo-Geo sequel pits 12 fighters against each other with visible damage accumulating in battle.","about":"Ryuuko no Ken 2 is a martial arts fighting game released by SNK Corp in 1994 on Neo-Geo MVS hardware. It offers 12 selectable characters, each showing progressive damage on their bodies as the fight goes on. Released in Japan in March 1994 and known overseas as Art of Fighting 2, it includes a guest appearance by Geese Howard that ties its story to the Fatal Fury games. Its Game ID is NGM-056.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1994,"players":2,"hardware":"Neo Geo MVS","aka":["Ryuuko no Ken 2"],"core":"arcade"},{"type":"retro","id":"aof3","slug":"art-of-fighting-3","title":"Art of Fighting 3","description":"SNK's 1996 Neo-Geo fighter brings motion-captured animation and Mexican locales to the series.","about":"Art of Fighting - Ryuuko no Ken Gaiden is a fighting game released by SNK Corp in 1996 on Neo-Geo MVS hardware. Ten selectable characters battle across various locations in Mexico, with fluid animation produced through motion capture technology. Released in Japan on March 12, 1996, its subtitle translates as 'Dragon and Tiger Fist Side Story' and it is known overseas as Art of Fighting 3. A limited-edition soundtrack album was issued by Pony Canyon / Scitron on 03/04/1996. Game ID: NGM-096.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1996,"players":2,"hardware":"Neo Geo MVS","aka":["Art of Fighting 3: The Path of the Warrior","Art of Fighting: Ryuuko no Ken Gaiden"],"core":"arcade"},{"type":"retro","id":"bangbead","slug":"bang-bead","title":"Bang Bead","description":"Visco's 2001 Neo-Geo twist on Pong lets you pick a fighter and battle for the ball.","about":"Bang Bead is a Neo-Geo MVS take on Pong, with a roster of selectable characters and a competitive two-player setup. Each player uses three of the four available buttons to return the ball, trigger a threat or slide, and unleash a Miracle Swing at maximum power. Arriving in May 2001 from Visco Corp, it ran on SNK's MVS hardware and appeared only in Europe. It never made it to the Neo-Geo AES home console.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"Visco","year":2000,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"bstars2","slug":"baseball-stars-2","title":"Baseball Stars 2","description":"SNK's 1992 sequel expands the diamond with 18 teams and deep league play.","about":"Baseball Stars 2 is SNK's arcade baseball sequel, letting players build leagues of up to 125 games with six teams meeting 25 times. It tracks standings, average, home runs, RBIs, ERA, wins, and saves, and players can fire or upgrade athletes via the 15-point system from the original. Eighteen teams span the beginner Exciting League and expert Fighting League. Released in April 1992 for the Neo-Geo MVS, it supports two players with four buttons each.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"SNK","year":1992,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"bstars","slug":"baseball-stars-professional","title":"Baseball Stars Professional","description":"SNK's 1990 comical baseball game was the Neo-Geo MVS's first diamond outing.","about":"Baseball Stars Professional is SNK's comical arcade baseball game, running on the Neo-Geo MVS with two players and four buttons each for batting, pitching, running, bunting, and timeouts. It hit arcades on April 26, 1990, and holds the distinction of being the first baseball game released for SNK's Neo-Geo MVS hardware.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"SNK","year":1990,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"blazstar","slug":"blazing-star","title":"Blazing Star","description":"Yumekobo's 1998 Neo-Geo shooter follows six pilots turned against the machines.","about":"Blazing Star is a horizontally scrolling shoot-'em-up set amid the endless war between Remuria and Mutras, where the sentient weapon Brawshella assimilates all life. Six assimilated pilots regain their humanity and fight back. Controlled with a joystick and two buttons, it offers normal, rapid, and charged shots plus a break attack. Released in January 1998, it was Yumekobo's first Neo-Geo MVS title, and a limited soundtrack album followed on March 18, 1998.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"Yumekobo","year":1998,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"bjourney","slug":"blue-s-journey","title":"Blue's Journey","description":"Alpha Denshi's 1991 Neo-Geo platformer sends Blue to save a polluted planet.","about":"Raguy, known outside Japan as Blue's Journey, is an environmentally themed platformer for one or two players. The Daruma tribe is draining planet Raguy, so Blue (and Princess Fa in two-player mode) must clear fourteen stages across four worlds. Heroes stun foes with a large leaf, then throw them at other enemies, and can shrink to reach hidden areas. Released in March 1991 by Alpha Denshi Company, Limited, it runs on SNK's Neo-Geo MVS.","system":"Neo Geo","genre":"platformer","categories":"platformer","developer":"Alpha Denshi Co.","year":1990,"players":2,"hardware":"Neo Geo MVS","aka":["Raguy"],"core":"arcade"},{"type":"retro","id":"breakrev","slug":"breakers-revenge","title":"Breakers Revenge","description":"Visco's 1998 Neo-Geo fighter adds Saizo and recolored stages to the Breakers lineup.","about":"Breaker's Revenge is a modest update to Breakers, adding the new selectable fighter Saizo along with differently colored backgrounds. It runs on SNK's Neo-Geo MVS and supports two players with four buttons each for punches and kicks. Visco Corp released it in Japan on July 3, 1998, and it never appeared on the Neo-Geo AES home console. It was among the first four gigapower games, and a USA-bios coin-insert bug on single-slot cabinets was fixed afterward.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Visco","year":1998,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"burningf","slug":"burning-fight","title":"Burning Fight","description":"Two NYPD detectives and a martial arts ally take on a Japanese crime syndicate in SNK's 1991 brawler.","about":"Burning Fight is a 1991 SNK Neo-Geo MVS beat-'em-up in which New York detectives Duke and Billy pursue a dangerous Japanese crime syndicate. Their investigation brings them to Japan, where they team up with Ryu, a police officer and martial arts expert, to hunt down the syndicate bosses. Released in April 1991, the game runs on Neo-Geo MVS hardware with 2 players and 4 buttons each. Duke later appears as a striker in The King of Fighters 2000.","system":"Neo Geo","genre":"beat-em-up","categories":"beat-em-up","developer":"SNK","year":1991,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"crsword","slug":"crossed-swords","title":"Crossed Swords","description":"Become a wandering knight, slashing demons and casting spells in this 3rd-person fantasy action game.","about":"A 3rd-person fantasy action game for the Neo-Geo, where you play a traveling knight helping those in need of a hero by cutting down the monsters and demons disrupting the peace. Your sword skills, spells and special weapons bought along the way carry you through the battle. Released in Japan on July 25, 1991, it was the Neo-Geo's second action-RPG after Riding Hero.","system":"Neo Geo","genre":"action","categories":"action","developer":"Alpha Denshi Co.","year":1991,"players":1,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"crswd2bl","slug":"crossed-swords-2","title":"Crossed Swords 2","description":"A pirate Neo-Geo take on the Crossed Swords CD adventure, released by Razoola.","about":"Crossed Swords II is a pirate version of the CD game, released for SNK Neo-Geo MVS hardware by Razoola.","system":"Neo Geo","genre":"action","categories":"action","developer":"bootleg (Razoola)","year":1996,"players":1,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"doubledr","slug":"double-dragon-neo-geo","title":"Double Dragon (Neo Geo)","description":"Double Dragon's 1995 Neo Geo fighter turns the movie's martial arts showdown into a one-on-one tournament.","about":"Based on the 1994 Double Dragon movie, this head-to-head fighter gathers series regulars Billy, Jimmy, Marian, Abobo and Burnov alongside five original characters, all competing in a martial arts tournament against crime lord Koga Shuko. Destructible environments and a super move meter that fills according to remaining energy give weaker fighters a fighting chance. Released in February 1995, it was Technos' first game for Neo-Geo hardware, and April Simmonds holds the official record with 96,700 points set on April 21, 2007.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Technos Japan","year":1995,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"eightman","slug":"eightman","title":"EightMan","description":"SNK's 1991 Neo-Geo brawler brings a classic anime hero to the arcade screen.","about":"Eightman is a side-scrolling beat'em up and platform game released by SNK in 1991 for the Neo-Geo MVS. Developed by Pallas, it launched in September 1991 and draws from a Japanese cartoon series from the 1960s. The characters diverge from the traditional Eightman look, and Nineman is simply a palette swap of the main hero. Taiyo System later produced a pachislot adaptation in 2000.","system":"Neo Geo","genre":"beat-em-up","categories":"beat-em-up","developer":"SNK / Pallas","year":1991,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"kabukikl","slug":"far-east-of-eden-kabuki-klash","title":"Far East of Eden: Kabuki Klash","description":"Hudson's 1995 Neo-Geo fighter brings the Far East of Eden RPG world to the arcade.","about":"This 1995 Neo-Geo MVS fighting game from Hudson Soft features eight selectable characters and four end-bosses, with random bonus items appearing during battles. It is a Japanese swordplay fighter set in the Far East of Eden RPG universe. Released in Japan in June 1995, it was Hudson's first game for the Neo-Geo MVS. A limited-edition soundtrack was released by Pony Canyon / Scitron on 17/11/1995.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Hudson","year":1995,"players":2,"hardware":"Neo Geo MVS","aka":["Tengai Makyou: Shin Den"],"core":"arcade"},{"type":"retro","id":"fatfury1","slug":"fatal-fury","title":"Fatal Fury","description":"SNK's 1991 fighter launches Terry Bogard on a quest for revenge in the King of Fighters.","about":"Fatal Fury is a 1991 SNK Neo-Geo MVS fighting game known in Japan as Garou Densetsu - Shukumei no Tatakai. Terry and Andy Bogard enter the King of Fighters tournament to find their father's killer, the sponsor and champion Geese Howard. Two-plane backgrounds give battles a pseudo 3-D feel. Originally titled Real Bout, the game introduced Terry Bogard, who became one of SNK's most recognizable fighters.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1991,"players":2,"hardware":"Neo Geo MVS","aka":["Fatal Fury: King of Fighters","Garou Densetsu: Shukumei no Tatakai"],"core":"arcade"},{"type":"retro","id":"fatfury3","slug":"fatal-fury-3-road-to-the-final-victory","title":"Fatal Fury 3: Road to the Final Victory","description":"SNK's 1995 fighter follows the lone wolves into a battle over the Shiranui Scrolls.","about":"Fatal Fury 3: Road to the Final Victory is an SNK Neo-Geo MVS fighting game released in 1995, known in Japan as Garou Densetsu 3 - Harukanaru Tatakai. Terry, Andy, Joe, and Mai get caught in a hunt for the Shiranui Scrolls. The game introduced a deeper plane-change system, chain combos, and new fighters including Blue Mary and Ryuji Yamazaki. A limited soundtrack album came from Pony Canyon on April 21, 1995.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1995,"players":2,"hardware":"Neo Geo MVS","aka":["Garou Densetsu 3: Haruka-naru Tatakai"],"core":"arcade"},{"type":"retro","id":"fatfursp","slug":"fatal-fury-special","title":"Fatal Fury Special","description":"SNK's 1993 special edition of Fatal Fury 2 packs new fighters and refined combat.","about":"Fatal Fury Special is an SNK Neo-Geo MVS fighting game from 1993, known in Japan as Garou Densetsu Special. It builds on Fatal Fury 2 with two-plane backgrounds, tighter controls, and plenty of secrets. Duck King, Tung Fu Rue, Geese Howard, and Ryo Sakazaki join the roster. The combo system was refined, damage reduced, and game speed increased. A limited soundtrack album arrived via Pony Canyon on 21/10/1993.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1993,"players":2,"hardware":"Neo Geo MVS","aka":["Garou Densetsu Special"],"core":"arcade"},{"type":"retro","id":"ganryu","slug":"ganryu","title":"Ganryu","description":"A Neo-Geo sword-fighting tale inspired by the legendary duel of Musashi and Kojiro.","about":"Musashi Ganryuki is a fighting game released by Visco in 1999 for the SNK Neo-Geo MVS. Known outside Japan as Ganryu, its title translates as 'Musashi Ganryu Tale'. Two players choose fighters and use an 8-way joystick with buttons for sword attack, jump, and chain attack. The game draws on the famous 1612 duel in which Musashi defeated Sasaki Ganryu Kojiro with a wooden sword carved from a boat oar. Kojiro appears with a huge gash on his forehead, and the storyline has him returning from the dead to kill Musashi. The game runs on Neo-Geo MVS but was never released on the Neo-Geo AES home console.","system":"Neo Geo","genre":"action","categories":"action","developer":"Visco","year":1999,"players":2,"hardware":"Neo Geo MVS","aka":["Musashi Ganryuki"],"core":"arcade"},{"type":"retro","id":"gpilots","slug":"ghost-pilots","title":"Ghost Pilots","description":"Two ace pilots take on Axis forces in SNK's 1991 vertical World War II shoot-em-up.","about":"Ghost Pilots is SNK's 1991 vertically-scrolling shoot-em-up for one or two players, set in World War II. Freelance aces Tom Phillips and Charlie Stingley, the 'Ghost Pilots', fly seaplanes against an ambitious Nazi general's forces. Before each stage you pick one of two bomb types, and in certain later stages a third unique bomb becomes available. You start with three bombs and can carry up to nine. Shooting a row of red planes drops power-ups, bombs, or extra lives.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"SNK","year":1991,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"goalx3","slug":"goal-goal-goal","title":"Goal! Goal! Goal!","description":"Pick from 28 national teams and battle through group and knockout rounds in this Neo-Geo soccer classic.","about":"Goal! Goal! Goal! is a 1995 Neo-Geo MVS soccer game from Visco Corp that pits 28 national teams against each other in a tournament. Play starts with a group stage, then moves into a round-robin elimination phase where one loss can end your run. Hold the shoot button to fill the power bar and unleash a powerful super shot. The game ran on SNK's Neo-Geo MVS hardware and never saw a Neo-Geo AES home console release.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"Visco","year":1995,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"karnovr","slug":"karnov-s-revenge","title":"Karnov's Revenge","description":"Data East's 1994 fighter returns with faster combat and new moves on Neo-Geo MVS.","about":"This 1994 Neo-Geo MVS fighter is the sequel to Fighter's History. It features faster, more technical battles, new hidden moves, and an enhanced color palette. The game is known as Karnov's Revenge in Europe and Fighter's History Dynamite in Japan and the USA. Released on March 17, 1994, it was the third Data East game made for Neo-Geo hardware. It switched from a six-button to a four-button control scheme and added new stages, music, and endings for every character.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Data East Corporation","year":1994,"players":2,"hardware":"Neo Geo MVS","aka":["Fighter's History Dynamite"],"core":"arcade"},{"type":"retro","id":"lresort","slug":"last-resort","title":"Last Resort","description":"SNK's 1992 Neo-Geo shooter drops you into a city that echoes Neo Tokyo from Akira.","about":"Last Resort is an SNK Neo-Geo MVS release from 1992. Two players can team up, each using two of the four available buttons for attacking and charging attacks. The opening two stages feature a city strongly resembling Neo Tokyo from the anime film Akira. A limited-edition soundtrack album was issued by Pony Canyon / Scitron on 21/05/1992.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"SNK","year":1992,"players":1,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"lbowling","slug":"league-bowling-neo-geo","title":"League Bowling (Neo Geo)","description":"SNK's 1990 Neo-Geo ten-pin game bowls up three scoring modes for one to four players.","about":"SNK's 1990 Neo-Geo MVS release is a colourful ten-pin bowling game for one to four players with three scoring methods: Regulation, Flash and Strike 90. You choose a right- or left-handed bowler and ball weight, then time Power and Direction meters within twenty seconds per shot. Strike 90 awards ninety points for a strike and sixty for a spare, while Flash adds the points shown when pins fall. Released on December 10, 1990, it includes a cameo by Nadia from Secret of Blue Water in the background.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"SNK","year":1990,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"magdrop2","slug":"magical-drop-ii","title":"Magical Drop II","description":"Data East's 1996 Neo-Geo puzzler proves that puzzle games can be furiously fast-paced.","about":"Magical Drop II arrived on SNK's Neo-Geo MVS in 1996 from Data East. Two players grab an 8-way joystick and two buttons to catch and throw balloons in hectic puzzle battles with lively animations and music. The roster draws loosely on figures from well-known Tarot cards, and a limited-edition soundtrack album came out via Pony Canyon / Scitron on June 21, 1996.","system":"Neo Geo","genre":"puzzle","categories":"puzzle","developer":"Data East Corporation","year":1996,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"magdrop3","slug":"magical-drop-iii-toretate-zoukangou","title":"Magical Drop III Toretate Zoukangou!","description":"Data East's final arcade game brings more characters and more frantic balloon-matching chaos.","about":"Magical Drop III hit the Neo-Geo MVS in 1997 from Data East, expanding the puzzle action with extra characters and modes for one or two players. A joystick and three buttons let you catch, throw, and shift balloons downward. It stands as Data East's last arcade video game, and its cast parodies all 22 Major Arcana Tarot cards, numbered 0 through 21, plus the bonus character Black Pierrot. A limited-edition soundtrack landed March 21, 1997.","system":"Neo Geo","genre":"puzzle","categories":"puzzle","developer":"Data East Corporation","year":1997,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"maglord","slug":"magician-lord","title":"Magician Lord","description":"Alpha Denshi's 1990 Neo-Geo debut casts you as Elta, the last Magician Lord.","about":"Magician Lord launched on SNK's Neo-Geo MVS in 1990 from Alpha Denshi. You guide the wizard Elta through eight side-scrolling stages, jumping and firing energy shots in four directions while collecting colored orbs to transform into six different powerful forms. It was Alpha Denshi's first Neo-Geo title and the first game to exploit the hardware's dezooming and rotation. Though 27 transformations were planned, only six made the final cut.","system":"Neo Geo","genre":"platformer","categories":"platformer","developer":"Alpha Denshi Co.","year":1990,"players":1,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"matrim","slug":"matrimelee","title":"Matrimelee","description":"The Goketsuji clan returns on Neo-Geo with fresh fighters and a wild marriage battle.","about":"Matrimelee came to SNK's Neo-Geo MVS from Playmore in 2002, reviving the Gouketsuji / Power Instinct series. Two players use an 8-way joystick and four buttons for weak and strong punches and kicks, with 11 familiar faces joined by four newcomers. Developed by Noise Factory and Atlus, it officially reached the public in March 2003 despite its 2002 copyright. Its Japanese soundtrack is notable for an unusually large number of vocal tracks across many stages.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Noise Factory / Atlus","year":2003,"players":2,"hardware":"Neo Geo MVS","aka":["Shin Gouketsuji Ichizoku Toukon"],"core":"arcade"},{"type":"retro","id":"mslug","slug":"metal-slug","title":"Metal Slug","description":"Metal Slug's 1996 Neo-Geo debut delivers run-and-gun war parody for one or two players.","about":"Metal Slug - Super Vehicle-001 is Nazca's 1996 SNK Neo-Geo MVS scrolling run-and-gun platform game for one or two players, a humorous parody of war and specifically World War II and the Nazis. It spans six enemy-packed levels called missions, starting players with only a pistol while extra weapons can be picked up for greater firepower. At certain points players find an unused Super Vehicle-001, or Metal Slug, tank to enter and drive; it is slow but heavily armed, and if it takes too many hits it breaks down and flashes, forcing a quick exit before it explodes. Enemies field tanks, boats, and helicopters, and levels are littered with bearded hostages who award points bonuses or weapon…","system":"Neo Geo","genre":"run-and-gun","categories":"run-and-gun","developer":"Nazca","year":1996,"players":2,"hardware":"Neo Geo MVS","aka":["Metal Slug: Super Vehicle-001"],"core":"arcade"},{"type":"retro","id":"mslug3","slug":"metal-slug-3","title":"Metal Slug 3","description":"SNK's 2000 Neo-Geo classic sends Marco and Tarma against Morden's army, with branching routes and wild transformations.","about":"Metal Slug 3 is a side-scrolling run-and-gun action game released by SNK in 2000 for the Neo-Geo MVS. Players control returning heroes from the first two games as they battle General Morden's forces, with a heavier focus on massive boss encounters than its predecessors. Most levels offer multiple paths, such as choosing between land or a submarine on the first stage, boosting replay value. Picking up too much food turns characters obese, while zombie attacks cause zombification, and the Mars People aliens in Mission 5 reference Independence Day.","system":"Neo Geo","genre":"run-and-gun","categories":"run-and-gun","developer":"SNK","year":2000,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"mslug4","slug":"metal-slug-4","title":"Metal Slug 4","description":"Playmore's 2002 Neo-Geo entry pits four heroes against the Amadeus cyber-terror threat and a still-living Morden.","about":"Metal Slug 4 is a side-scrolling action game released by Playmore Corp in 2002 for the Neo-Geo MVS. A computer virus from the terrorist group Amadeus threatens every nation's military systems, and four heroes—Marco Rossi, Fio Germi, Nadia Cassel and Trevor Spacey—set out to stop it, discovering along the way that Morden is still alive. The game was developed by South Korean company Mega Enterprise, which had held SNK copyrights for South Korea since 1999. A hack version is known as Metal Slug 4 Plus.","system":"Neo Geo","genre":"run-and-gun","categories":"run-and-gun","developer":"Mega / Noise Factory / Playmore","year":2002,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"mslug5","slug":"metal-slug-5","title":"Metal Slug 5","description":"SNK Playmore's 2003 Neo-Geo chapter sends Marco, Tarma, Eri and Fio after the Ptolemaic Army and stolen Metal Slug secrets.","about":"Metal Slug 5 is a side-scrolling action game released by SNK Playmore in 2003 for the Neo-Geo MVS. After unknown forces raid a research site and steal a disk of Metal Slug secrets, Marco and Tarma give chase while Eri and Fio investigate the Ptolemaic Army at the ancient ruin called The Corridor of Fire. This entry added a slide move performed by holding the B button, and players can fire while sliding. A hack version is known as Metal Slug 5 Plus.","system":"Neo Geo","genre":"run-and-gun","categories":"run-and-gun","developer":"SNK Playmore","year":2003,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"mslugx","slug":"metal-slug-x","title":"Metal Slug X","description":"SNK's 1999 Neo-Geo remaster of Metal Slug 2 fixes slowdown and adds new enemies, weapons, secrets and a reworked final boss.","about":"Metal Slug X - Super Vehicle-001 is a side-scrolling run-and-gun game released by SNK in 1999 for the Neo-Geo MVS. It was built to address problems in Metal Slug 2, most notably the notorious slowdown, while also adding new enemies, a different end boss layout and extra weapons and secrets. During the credits, up to five different sets of twelve character, enemy and vehicle artwork images can appear.","system":"Neo Geo","genre":"run-and-gun","categories":"run-and-gun","developer":"SNK","year":1999,"players":2,"hardware":"Neo Geo MVS","aka":["Metal Slug X: Super Vehicle-001"],"core":"arcade"},{"type":"retro","id":"mutnat","slug":"mutation-nation","title":"Mutation Nation","description":"SNK's 1992 Neo-Geo brawler sends two mutant-powered warriors into a futuristic wasteland to restore order.","about":"Mutation Nation is a side-scrolling beat-'em-up released by SNK in March 1992 for the Neo-Geo MVS. Two lone warriors wielding special mutant powers fight to bring order back to a futuristic wasteland. Each player uses a four-button layout, with attack and jump as the two functional inputs.","system":"Neo Geo","genre":"beat-em-up","categories":"beat-em-up","developer":"SNK","year":1992,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"nam1975","slug":"nam-1975","title":"NAM-1975","description":"Two soldiers blast into the Vietnam war's final months to rescue a kidnapped scientist and his daughter.","about":"NAM-1975 is SNK's 1990 Neo-Geo MVS war-themed shoot-em-up for one or two players, following soldiers Silver and Brown as they enter the conflict to rescue Dr. R. Muckly and his daughter Nancy from the Northside Terrorists. Played from a third-person into-the-screen view, it arms players with an infinite-ammo machine gun and ten grenades, with stronger guns and grenades dropped by certain enemies. Released April 26, 1990 in Japan, it was the first game developed for the Neo-Geo MVS hardware and drew influence from Stanley Kubrick's 1987 film Full Metal Jacket.","system":"Neo Geo","genre":"run-and-gun","categories":"run-and-gun","developer":"SNK","year":1990,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"neobombe","slug":"neo-bomberman","title":"Neo Bomberman","description":"Hudson's bomb-dropping multiplayer favorite lands on the Neo-Geo MVS with one-button mayhem.","about":"Neo Bomber Man is a 1997 Hudson Soft arcade game released on SNK's Neo-Geo MVS hardware, with a single button handling bomb setting, kicking and throwing for two players. It came out in May 1997 in Japan and, despite running on the MVS, never saw a release on the Neo-Geo AES home console.","system":"Neo Geo","genre":"action","categories":"action","developer":"Hudson","year":1997,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"neodrift","slug":"neo-drift-out","title":"Neo Drift Out","description":"Pick your rally car and race six stages against the clock in this isometric Neo-Geo racer.","about":"Neo Drift Out - New Technology is an overhead isometric rally racer from Visco, released on SNK's Neo-Geo MVS in 1996. You choose between the Mitsubishi Lancer, Subaru Impreza or Toyota Celica, each with its own balance of Speed, Control and Body. After a short practice stage, up to six race stages await, each with unique locations and driving conditions. You must reach the finish before the timer runs out, hitting a mid-way checkpoint along the way. Arrows warn of corners, prompts flag hazards like ice, rocks, barrels, cones and ramps, and rival drivers can ram you into a spin. It hit Japanese arcades on March 28, 1996.","system":"Neo Geo","genre":"racing","categories":"racing","developer":"Visco","year":1996,"players":2,"hardware":"Neo Geo MVS","aka":["Neo Drift Out: New Technology"],"core":"arcade"},{"type":"retro","id":"neomrdo","slug":"neo-mr-do","title":"Neo Mr. Do!","description":"Visco's Neo-Geo take on the classic Mr. Do! formula, made for two players.","about":"Neo Mr. Do! is a Visco Corp arcade title released on SNK's Neo-Geo MVS hardware in 1996. It supports two players, using an 8-way joystick with a single attack button. Despite arriving on the MVS platform, the game never saw a release on the Neo-Geo AES home console.","system":"Neo Geo","genre":"action","categories":"action","developer":"Visco","year":1996,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"turfmast","slug":"neo-turf-masters","title":"Neo Turf Masters","description":"Choose from six golfers with distinct strengths and tee off across four eighteen-hole courses.","about":"Big Tournament Golf is an arcade golf game from Nazca Corporation, released in January 1996 for the Neo-Geo MVS. One or two players pick from six golfers, each with different driving, accuracy, skill, recovery, and putting ratings. Four eighteen-hole courses are available: Germany, Japan, Australia, and U.S.A. Modes include one-player stroke play against the CPU, or stroke and match-play against a second player. Known outside Japan as Neo Turf Masters, it was Nazca's first game for the Neo-Geo MVS.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"Nazca","year":1996,"players":2,"hardware":"Neo Geo MVS","aka":["Big Tournament Golf"],"core":"arcade"},{"type":"retro","id":"nitd","slug":"nightmare-in-the-dark","title":"Nightmare in the Dark","description":"A gravekeeper battles zombies and night dwellers in this charming Neo-Geo action game.","about":"Nightmare in the Dark is a 2000 Neo-Geo MVS release from Eleven and Gavaking. A peaceful but creepy-looking gravekeeper takes the night shift to stop a grave-robbing mystery before the villagers panic. The action follows the Snow Bros., Tumble Pop and Zupapa! style, backed by detailed graphics and a strong soundtrack. Two players can join in with an 8-way joystick and three buttons. It launched in January 2000, never appeared on the Neo-Geo AES, and famously swaps the initials 'SEX' to 'KING' on its high score table.","system":"Neo Geo","genre":"platformer","categories":"platformer","developer":"Eleven / Gavaking","year":2000,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"ncombat","slug":"ninja-combat","title":"Ninja Combat","description":"Storm the ninja castle and turn defeated bosses into playable fighters.","about":"Ninja Combat is a 1990 Neo-Geo MVS arcade game from Alpha Denshi Company, Limited, in which players invade a ninja castle. Beating certain boss enemies makes them playable characters as well. It launched in July 1990.","system":"Neo Geo","genre":"beat-em-up","categories":"beat-em-up","developer":"Alpha Denshi Co.","year":1990,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"ncommand","slug":"ninja-commando","title":"Ninja Commando","description":"Three ninjas chase a madman named Spider through time to stop him rewriting history.","about":"Ninja Commando is a 1992 Neo-Geo MVS arcade title from Alpha Denshi Company, Limited, sending three ninjas after a madman named Spider who aims to use a time machine to tamper with history. It plays as a tongue-in-cheek reworking of Time Soldiers, which Alpha Denshi made five years earlier, this time with ninjas as the heroes. It was released on April 30, 1992.","system":"Neo Geo","genre":"beat-em-up","categories":"beat-em-up","developer":"Alpha Denshi Co.","year":1992,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"overtop","slug":"over-top","title":"Over Top","description":"Race varied vehicles through handsome backdrops and hunt down hidden shortcuts.","about":"Over Top is a 1996 Neo-Geo MVS racer from ADK that presents 3D-like action with 2D visuals and notably well-crafted backgrounds. You drive a range of different vehicles. The goal is to finish every race before the clock runs out, and the stages hide plenty of shortcuts to discover. It arrived in April 1996, supports two players, and uses an 8-way joystick with two buttons: one to accelerate and one to slow down.","system":"Neo Geo","genre":"racing","categories":"racing","developer":"ADK","year":1996,"players":1,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"panicbom","slug":"panic-bomber","title":"Panic Bomber","description":"Bomber formations collide in this Neo-Geo puzzler from Eighting and Hudson Soft.","about":"Panic Bomber brings formation-based puzzle action to the Neo-Geo MVS. You rearrange falling bombers with the joystick and a single button to clear the board and outlast your opponent. Hudson Soft developed the game, which first appeared on the PC-Engine CD as Panic Bomber - Bomber Man. The arcade version hit Neo-Geo MVS in January 1995 but never made it to the AES home console.","system":"Neo Geo","genre":"puzzle","categories":"puzzle","developer":"Eighting / Hudson","year":1994,"players":1,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"preisle2","slug":"prehistoric-isle-2","title":"Prehistoric Isle 2","description":"Two high-tech helicopters battle a dinosaur invasion in this Neo-Geo shooter sequel.","about":"Prehistoric Isle 2 is a side-scrolling shooter set in a future overrun by dinosaurs. You pilot one of two helicopters: the Blue One fires a wide straight shot with a wave-cannon bomb, while the Green One uses a spread shot and grenade barrage. Rescuing civilian survivors earns points and power-ups. Released in September 1999 by Yumekobo, it runs on Neo-Geo MVS but never saw an AES home release. In Japan it is known as Prehistoric Isle 2 - Genshi Tou.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"Yumekobo / Saurus","year":1999,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"pulstar","slug":"pulstar","title":"Pulstar","description":"A lone pilot faces an alien invasion in this visually stunning Neo-Geo shoot-em-up.","about":"Pulstar is a side-scrolling shooter set in 2248, after a signal from Mars draws an alien fleet that devastates the Solar System. You fly the Dino246 as Kaoru Yamazaki, one of the last survivors of the Pulstar attack force. The game borrows heavily from Irem's R-Type series, including the Beam weapon and pod attachment. Released in August 1995 by Aicom, it was among the first Neo-Geo titles to use SGI-rendered graphics. Its pre-production name was Reaction.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"Aicom","year":1995,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"pbobblen","slug":"puzzle-bobble","title":"Puzzle Bobble","description":"Taito's bubble-popping puzzler lands on Neo-Geo MVS with two-player color-matching action.","about":"Puzzle Bobble comes to the Neo-Geo MVS as a conversion of Taito's B System original. Aim and fire bubbles to match three or more of the same color and clear the playfield. This MVS release arrived in December 1994 and was Taito's first game on the hardware, six months after the B System original. A limited-edition soundtrack, Puzzle Bobble Variety, was released by Zuntata Records on March 28, 1997.","system":"Neo Geo","genre":"puzzle","categories":"puzzle","developer":"Taito","year":1994,"players":2,"hardware":"Neo Geo MVS","aka":["Bust-A-Move"],"core":"arcade"},{"type":"retro","id":"pbobbl2n","slug":"puzzle-bobble-2-bust-a-move-2","title":"Puzzle Bobble 2 / Bust-A-Move 2","description":"SNK's MVS conversion of the bubble-bursting classic, known in the US as Bust-A-Move Again.","about":"Puzzle Bobble 2 arrives on Neo-Geo MVS as a conversion of Taito's original F3 title. Fire bubbles, match colors, and clear the board before your rival does. In North America the game is called Bust-A-Move Again, and its marquee and fliers even billed it as Bust-A-Move Again EX. While the original US F3 release swapped out Bub and Bob for generic hands, this MVS port keeps the original Puzzle Bobble 2 assets. It is also noted as the first coin-op to coin-op port.","system":"Neo Geo","genre":"puzzle","categories":"puzzle","developer":"Taito (SNK license)","year":1999,"players":2,"hardware":"Neo Geo MVS","aka":["Bust-A-Move Again"],"core":"arcade"},{"type":"retro","id":"rotd","slug":"rage-of-the-dragons","title":"Rage of the Dragons","description":"Rage of the Dragons brings 14 fighters plus hidden boss Abubo to the Neo-Geo in 2002.","about":"Rage of the Dragons is a 2002 Playmore Corp fighting game on Neo-Geo MVS, offering 14 selectable fighters along with Abubo as sub-boss and Johann as the final boss. Four buttons cover weak and strong punches and kicks. Released in June 2002, it was Evoga Entertainment's first fighting game, made with Brezza Soft and Noise Factory after Technos Japan declined to sell the Double Dragon rights, so the team built an homage instead.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Evoga / Playmore","year":2002,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"rbff1","slug":"real-bout-fatal-fury","title":"Real Bout Fatal Fury","description":"SNK's 1995 fighter Real Bout Fatal Fury brings 16 fighters and plane-switching to the Neo-Geo.","about":"Real Bout Garou Densetsu is a 1995 SNK Neo-Geo MVS fighting game, known outside Japan as Real Bout Fatal Fury. Its 16-character roster mixes old and new faces to refresh the Fatal Fury series, using a four-button setup (punch, kick, power attack, plane switch). Released in Japan on December 21, 1995, it stands out as one of the few 2-D fighters with ring outs. Newcomers include Kim Kaphwan, Duck King and Billy Kane, and Pony Canyon put out a limited-edition soundtrack on 07/02/1996.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1995,"players":2,"hardware":"Neo Geo MVS","aka":["Real Bout Garou Densetsu"],"core":"arcade"},{"type":"retro","id":"rbff2","slug":"real-bout-fatal-fury-2-the-newcomers","title":"Real Bout Fatal Fury 2: The Newcomers","description":"Real Bout Fatal Fury 2: The Newcomers packs 23 South Town fighters into SNK's 1998 Neo-Geo bout.","about":"Real Bout Garou Densetsu 2 - The Newcomers is a 1998 SNK Corp Neo-Geo MVS fighter, the 7th installment in the series, known outside Japan as Real Bout Fatal Fury 2 - The Newcomers. It brings 23 South Town fighters and returns to single-plane stages where you can slam enemies into background objects. Shown at the 1998 AOU Amusement Expo in Japan and released that March, it adds Li Xiangfei, Rick Strowd and Alfred. It's one of the first four 'gigapower' games, and Pony Canyon / Scitron released a limited-edition soundtrack on April 17, 1998.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1998,"players":2,"hardware":"Neo Geo MVS","aka":["Real Bout Garou Densetsu 2: The Newcomers"],"core":"arcade"},{"type":"retro","id":"rbffspec","slug":"real-bout-fatal-fury-special","title":"Real Bout Fatal Fury Special","description":"SNK's 1997 Real Bout Fatal Fury Special brings 19 selectable fighters to the Neo-Geo MVS.","about":"Real Bout Garou Densetsu Special is a 1997 SNK Corp Neo-Geo MVS fighter, known outside Japan as Real Bout Fatal Fury Special. It returns more Fatal Fury favorites, raising the selectable roster to 19, and tweaks the plane-switching system while turning ring outs into an instant dizzy system triggered by breaking background objects. Though the copyright reads 1996, it launched in Japan on January 28, 1997. Newcomers include Cheng Sinzan, Tung Fu Rue, Laurence Blood and Wolfgang Krauser, with 'evil' character versions also available.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1996,"players":2,"hardware":"Neo Geo MVS","aka":["Real Bout Garou Densetsu Special"],"core":"arcade"},{"type":"retro","id":"roboarmy","slug":"robo-army","title":"Robo Army","description":"SNK's 1991 Robo Army sends two cyber soldiers against the invading Hell Jeed army.","about":"Robo Army is a 1991 SNK Neo-Geo MVS side-scrolling beat-em-up for one or two players, starring cyber soldiers Rocky and Maxima battling the Hell Jeed army. Three buttons handle attack, jump, and energy blast. Released in Japan on October 30, 1991, the game lets players rip weakened enemies in half and even club robots with fallen limbs. Rocky later appeared as a striker in The King of Fighters 2000.","system":"Neo Geo","genre":"beat-em-up","categories":"beat-em-up","developer":"SNK","year":1991,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"samsho3","slug":"samurai-shodown-iii","title":"Samurai Shodown III","description":"Twelve fighters take on the demon samurai Zankuro in SNK's 1995 weapons-based fighter.","about":"Samurai Spirits - Zankurou Musouken is a weapons-based fighting game from SNK, released in October 1995 on the Neo-Geo MVS. Twelve selectable characters fight to defeat Zankuro, a very powerful demon samurai. Known outside Japan as Samurai Shodown III and in Korea as Fighters Swords, its full US name is Samurai Shodown III - Blades of Blood. The subtitle translates as 'Zankuro's Matchless Sword'. Kafuin Gaira, a Buddhist monk, wields giant mala prayer beads.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1995,"players":2,"hardware":"Neo Geo MVS","aka":["Samurai Spirits: Zankurou Musouken"],"core":"arcade"},{"type":"retro","id":"samsho4","slug":"samurai-shodown-iv-amakusa-s-revenge","title":"Samurai Shodown IV: Amakusa's Revenge","description":"Seventeen fighters and two bosses clash in SNK's 1996 weapons-based fighter with CD combos and fatalities.","about":"Samurai Shodown IV: Amakusa's Revenge is the fourth entry in SNK's weapons-based one-on-one fighting series, released on October 25, 1996 on the Neo-Geo MVS. It features seventeen selectable characters and two end bosses. The formula changed with the removal of aerial blocking, the switch-around move, dodges, and POW gauge charging. A new CD combo was added, along with a suicide move that forfeits a round but grants a full POW gauge next round, plus certain fatalities. Older characters like Charlotte, Tam Tam, and Jubei Yagyu returned.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1996,"players":2,"hardware":"Neo Geo MVS","aka":["Samurai Spirits: Amakusa Kourin"],"core":"arcade"},{"type":"retro","id":"samsh5fe","slug":"samurai-shodown-v-special","title":"Samurai Shodown V Special","description":"SNK Playmore's 2004 Samurai Shodown V Special adds four fighters to the Neo-Geo roster.","about":"Samurai Shodown V Special is a 2004 SNK Playmore Neo-Geo MVS fighter, upgrading Samurai Spirits Zero with its 24 fighters plus Amakusa, Gaoh, Zankuro, and Mizuki. Four buttons handle light and medium attacks, kick/break defence, and dodges. Released in Japan in April 2004, it is often called the ultimate MVS title, arriving as SNK Playmore shifted development to AtomisWave. Corrected cartridges added missing fatalities, marked by a small NeoGeo sticker.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Yuki Enterprise / SNK Playmore","year":2004,"players":2,"hardware":"Neo Geo MVS","aka":["Samurai Spirits Zero Special"],"core":"arcade"},{"type":"retro","id":"sengoku","slug":"sengoku","title":"Sengoku","description":"Two spiritually gifted warriors battle to stop the Mad Shogun's resurrection in this 1991 Neo-Geo brawler.","about":"Sengoku Densyo is a 1991 Neo-Geo MVS game from SNK, released on February 12, 1991 in Japan and known outside Japan as Sengoku. Two warriors with spiritual gifts fight to stop the resurrection of the Mad Shogun, facing strange enemies and striking scenery, with the ability to morph into different fighters. Items change special attacks: ten green items grant a 1-up, while red, blue, and purple grant a samurai sword, double sword, and holy sword. A level 2 background store, 'Boutique Athena', shows the original 1986 Athena logo.","system":"Neo Geo","genre":"beat-em-up","categories":"beat-em-up","developer":"SNK","year":1991,"players":2,"hardware":"Neo Geo MVS","aka":["Sengoku Denshou"],"core":"arcade"},{"type":"retro","id":"sengoku2","slug":"sengoku-2","title":"Sengoku 2","description":"The Mad Shogun returns to conquer the timestream in this 1993 Neo-Geo sequel with permanent sword combat.","about":"Sengoku Densyo 2 is a 1993 Neo-Geo MVS game from SNK, released on February 18, 1993 in Japan and known outside Japan as Sengoku 2. The Mad Shogun rises again, taking over various periods in the time stream. Players are permanently armed with a sword and must save different eras from the Mad Shogun's wrath. On foot, buttons handle slicing, severing, jumping, and changing form; on a horse, they handle forward and rear attacks.","system":"Neo Geo","genre":"beat-em-up","categories":"beat-em-up","developer":"SNK","year":1993,"players":2,"hardware":"Neo Geo MVS","aka":["Sengoku Denshou 2"],"core":"arcade"},{"type":"retro","id":"sengoku3","slug":"sengoku-3","title":"Sengoku 3","description":"SNK's 2001 Neo-Geo brawler brings fighting-game depth with chain combos and stashable throwing weapons.","about":"Sengoku 3 is a horizontally-scrolling beat-em-up for one or two players, released in October 2001 on the Neo-Geo MVS. It stands out for its complex chain-combo combat system, using light, heavy, and long-ranged attack buttons rather than simple mashing. Each of the four playable characters has directional special moves and a super bar with several super moves. Players can stash one type of ranged weapon, including shuriken, bombs, and kunai, and weave them into combos. It was developed by Noise Factory as their first game and was SNK's last official title.","system":"Neo Geo","genre":"beat-em-up","categories":"beat-em-up","developer":"Noise Factory / SNK","year":2001,"players":2,"hardware":"Neo Geo MVS","aka":["Sengoku Densho 2001"],"core":"arcade"},{"type":"retro","id":"shocktro","slug":"shock-troopers","title":"Shock Troopers","description":"SNK's 1997 Neo Geo shooter sends one or two troopers through three branching mission routes.","about":"Shock Troopers is SNK's 1997 multi-directional scrolling shooter for one or two players, built on the foundations of Capcom's Commando and Mercs. Players fight a terrorist group holding a girl hostage to force her grandfather into surrendering a mind-controlling drug. Alongside enemy troops come tanks, choppers, and landmines, with weapons and health found in destroyed vehicles and supply crates. Three selectable routes make it effectively three games in one, and stages include vehicle chases and rock climbing. It released in November 1997 and never came to the Neo-Geo AES home console.","system":"Neo Geo","genre":"run-and-gun","categories":"run-and-gun","developer":"Saurus","year":1997,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"shocktr2","slug":"shock-troopers-2nd-squad","title":"Shock Troopers - 2nd Squad","description":"SNK's 1998 Neo Geo run-and-gun returns with sharper graphics and more inventive level design.","about":"Shock Troopers - 2nd Squad is SNK's 1998 Neo Geo follow-up to the previous year's game. One or two players battle a terrorist army threatening to unleash a new weapon of mass destruction unless it is handed control of the new nation of Billberk. More an update than a full sequel, it polishes the graphics and offers more imaginative level design than the original. It arrived in October 1998, and Pony Canyon / Scitron issued a limited-edition soundtrack in January 1999.","system":"Neo Geo","genre":"run-and-gun","categories":"run-and-gun","developer":"Saurus","year":1998,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"svc","slug":"snk-vs-capcom-svc-chaos","title":"SNK vs. Capcom: SVC Chaos","description":"The 2003 Neo-Geo crossover fighter pitting seventeen SNK combatants against seventeen Capcom characters.","about":"A one-on-one fighting game released in July 2003 by Playmore on SNK Neo-Geo MVS hardware, SVC Chaos - SNK Vs. Capcom pits seventeen well-known SNK combatants against seventeen famous Capcom characters. It mainly uses the command system of the King of Fighters series, with light and strong kicks and punches, cancels and charging attacks, and unlike Capcom vs. SNK 2 it has no air guards and no groove system, focusing instead on quicker play and online competition. Each character has a basic three-bar system for executing Exceeds, filled by strikes and damage, and the sprites from the various series received new models while some command-list special effects changed.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Playmore / Capcom","year":2003,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"socbrawl","slug":"soccer-brawl","title":"Soccer Brawl","description":"SNK's futuristic soccer arcade game from 1992 mixes power shots, sliding cuts, and arm punches on the Neo-Geo.","about":"Soccer Brawl is a futuristic soccer game released by SNK in February 1992 for the Neo-Geo MVS arcade hardware. Two players face off using four buttons each, with two in use: attack with a kick or power shot, and pass, while defence offers a sliding cut or arm punch and a header. It runs on SNK's Neo-Geo MVS platform under game ID NGM-031.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"SNK","year":1991,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"spinmast","slug":"spinmaster","title":"Spinmaster","description":"Johnny and Tom chase map pieces and rescue Mary in Data East's 1993 Neo-Geo platformer, known as Spinmaster.","about":"Miracle Adventure, known outside Japan as Spinmaster, is a platformer released by Data East on December 16, 1993, and the company's first game developed for the SNK Neo-Geo MVS hardware. Two treasure seekers, Johnny and Tom, must save their friend Mary from the evil Mad Doctor and his henchmen while gathering map pieces to find the world's biggest treasure. The game features cartoon-like character designs, giant bosses such as a Chinese dragon, and fast platforming, with a style heavily inspired by Data East's Caveman Ninja. It runs under game ID NGM-062 with three buttons: shoot or power attack, jump, and super attack.","system":"Neo Geo","genre":"platformer","categories":"platformer","developer":"Data East Corporation","year":1993,"players":2,"hardware":"Neo Geo MVS","aka":["Miracle Adventure"],"core":"arcade"},{"type":"retro","id":"strhoop","slug":"street-hoop","title":"Street Hoop","description":"Data East's 1994 Neo-Geo street basketball game: pick one of ten countries for three-on-three slamdunkin' action.","about":"A Data East basketball game on SNK Neo-Geo MVS hardware, released in Japan on December 8, 1994 as Dunk Dream and known outside Japan as Street Hoop and in the US as Street Slam. Ten countries are selectable for three-on-three street action. Two players share an 8-way joystick and two buttons: on offense A shoots or dunks and B passes, while on defense A blocks a shot and B steals the ball. A limited-edition soundtrack, Dunk Dream / Gun Hard, was released by Pony Canyon / Scitron on January 20, 1995.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"Data East Corporation","year":1994,"players":2,"hardware":"Neo Geo MVS","aka":["Street Slam","Dunk Dream"],"core":"arcade"},{"type":"retro","id":"sdodgeb","slug":"super-dodge-ball","title":"Super Dodge Ball","description":"Three-on-three dodge ball with special moves and team attacks hits the Neo-Geo MVS in 1996.","about":"Super Dodge Ball is a 1996 Neo-Geo MVS game from Technos Japan Corp, known in Japan as Kunio no Nekketsu Toukyuu Densetsu. Teams of three try to knock each other out using special moves and team attacks. You control a team and must beat all others, even recruiting defeated leaders, to face the reigning champion. It features anime-style graphics and runs on Neo-Geo MVS but was never released on the Neo-Geo AES home console. Technos Japan went bankrupt on December 15, 1995.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"Technos Japan","year":1996,"players":2,"hardware":"Neo Geo MVS","aka":["Kunio no Nekketsu Toukyuu Densetsu"],"core":"arcade"},{"type":"retro","id":"irrmaze","slug":"the-irritating-maze","title":"The Irritating Maze","description":"Guide a stick through a maze without touching the walls in this SNK trackball challenge from 1997.","about":"Based on a Japanese game show, this SNK title for the Neo-Geo MVS challenges players to navigate a stick through a maze without touching the sides. It is a test of steady nerves and precision. Released in Japan in August 1997, it was the first Neo-Geo MVS game to require a trackball and was never ported to the home Neo-Geo AES console.","system":"Neo Geo","genre":"puzzle","categories":"puzzle","developer":"SNK / Saurus","year":1997,"players":2,"hardware":"Neo Geo MVS","aka":["Ultra Denryu Iraira Bou"],"core":"arcade"},{"type":"retro","id":"kof94","slug":"the-king-of-fighters-94","title":"The King of Fighters '94","description":"SNK's 1994 classic launched the 3-on-3 team battle system with 24 fighters against Rugal.","about":"The King of Fighters '94 is SNK's Neo-Geo MVS fighting game released in August 1994, featuring 24 selectable characters in fixed teams of three battling to defeat Rugal Bernstein. It revolutionized the fighter genre with the introduction of 3-member team fighting called the team battle system, combining elements of Fatal Fury and Art of Fighting while bringing back characters from Ikari Warriors and Psycho Soldier. A new game in the series is produced every year. In the demo before the first Rugal encounter, Rugal shows statues he has gathered by turning opponents into them, including one resembling Capcom's Guile making a Sonic Boom.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1994,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"kof95","slug":"the-king-of-fighters-95","title":"The King of Fighters '95","description":"SNK's 1995 sequel pits eight teams of three against Rugal, introducing rival Iori Yagami.","about":"The King of Fighters '95 is SNK's Neo-Geo MVS fighting game, released on July 25, 1995 in Japanese arcades. Eight teams of three characters each square off again to take out Rugal Bernstein. The background for the Japan Team is a real place. Iori Yagami was introduced as Kyo's rival, a member of a rival martial arts school connected to the Ancient Arts of the Kusanagi, wielding red flames. His intense personality, unique moves, hairstyle, and provocative lines like 'You cry! You scream! Then you die!' broke the mold for fighting game characters at the time, and he stood out most during initial location tests.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1995,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"kof96","slug":"the-king-of-fighters-96","title":"The King of Fighters '96","description":"The third KOF chapter unites 27 SNK characters against final boss Goenitz.","about":"The King of Fighters '96 is SNK's Neo-Geo MVS fighting game released in July 1996, the third chapter in the series, bringing 27 classic SNK characters together against final boss Goenitz. It is the first game to include special phrases and poses when two particular characters fight, happening here only with Kyo vs. Iori, Terry vs. Geese, and Ralf Jones vs. Clark Steel. Cut moves found in the game code include Kyo's Saishuu Kessen Ougi 'Mu Shiki', Geese's Deadly Rave, and Choi's Hou'ou Kyaku, some of which debuted in later games. Leona entered the series as a replacement for Heidern, leader of the Ikari Team.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1996,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"kof97","slug":"the-king-of-fighters-97","title":"The King of Fighters '97","description":"Pick from 29 fighters and take down Orochi in SNK's 1997 Neo-Geo tag-team brawler.","about":"SNK's 1997 Neo-Geo MVS fighter lets you build teams of three from nine squads plus two solo entries, bringing the roster to 29 fighters. The goal is to defeat the evil Orochi and those tainted by his blood. Yuri's Hien Rekkou special is a nod to Ken's Shoryuu Reppa, and the Kowloon backdrop hides cameos from Top Hunter and Art of Fighting 3. The names of Kyo, Iori and Chizuru echo the legend of the Great Serpent.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1997,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"kof2000","slug":"the-king-of-fighters-2000","title":"The King of Fighters 2000","description":"SNK's 2000 fighter brings 34 characters and the Striker system against the formidable Zero.","about":"The King of Fighters 2000 is SNK's Neo-Geo MVS fighting game released in July 2000, featuring 34 characters and the popular Striker assist system. Teams battle to defeat the mighty Zero and his bladed coat. Ramon was designed with South American audiences in mind, a masked Lucha Libre wrestler full of tricky body slams. Vanessa was conceived as a thirty-something woman who broke the mold of teenage female fighters, having first appeared as a Striker in the Dreamcast version of KOF '99 before officially joining KOF 2000 as a playable character.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":2000,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"kof2001","slug":"the-king-of-fighters-2001","title":"The King of Fighters 2001","description":"Eolith's 2001 KOF entry delivers 40 fighters and one of fighting games' hardest boss pairs.","about":"The King of Fighters 2001 is a Neo-Geo MVS fighting game released in October 2001 by Eolith. With the largest KOF roster at the time totaling 40 characters, it delivers high-quality fighting action alongside one of the most difficult pairs of bosses in fighting game history. Ron, chief of the Flying Brigands, first appeared in KOF 2000's Benimaru Team ending, which earned first-rate reviews and became one of KOF's most popular episodes. He uses tricky Chinese boxing techniques and pursues a ghoulish goal of manipulating the dead, making his grand entrance in KOF 2001 as the boss characters' Striker.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Eolith / SNK","year":2001,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"kof2002","slug":"the-king-of-fighters-2002","title":"The King of Fighters 2002","description":"Playmore's 2002 fighter drops the Striker format and returns to classic 3-on-3 team battles.","about":"The King of Fighters 2002 - Challenge to Ultimate Battle is a one-on-one fighting game for one or two players, developed by Eolith and released in October 2002 by Playmore Corp. It is the ninth game in the series. The game discarded the 4-on-4 Striker Match format of the previous three entries and returned to the 3-on-3 Battle format used before KOF '98, while revamping the Power Gauge system into a format similar to KOF '97's. Kusanagi was inserted into the game at the last moment due to demand for the return of the old Kyo, whose trademark black school uniform endures even though he is over 20.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Eolith / Playmore","year":2002,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"kof2003","slug":"the-king-of-fighters-2003","title":"The King of Fighters 2003","description":"SNK Playmore's 2003 KOF introduces the Tactical Leader System and Multi-Shift team battles.","about":"The King of Fighters 2003 is an SNK Playmore Neo-Geo MVS fighting game released in November 2003. It offers 32 selectable fighters plus Evil Kusanagi, Chizuru and Maki Kagura, Adelheid Bernstein, and final boss Mukai. It was the latest entry in the series to run on Neo-Geo MVS hardware. Two new systems debut: the Tactical Leader System, which gives one team member favorable treatment in capability, and Multi-Shift, which lets players change characters freely during 3-on-3 battle. Ash Crimson was designed with the intent to create an attractive evil character.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK Playmore","year":2003,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"lastblad","slug":"the-last-blade","title":"The Last Blade","description":"SNK's 1997 weapons fighter pairs striking artwork with twelve blades and two bosses.","about":"SNK's 1997 Neo-Geo MVS weapons-based fighter, known in Japan as Bakumatsu Rouman - Gekka no Kenshi, pairs beautiful artwork and sound with twelve selectable characters and two end bosses. Outside Japan it is called The Last Blade, and in Korea The Last Soldier. Released in Japan on December 5, 1997, it draws partly on the manga Rurouni Kenshin and is set during the Bakumatsu period (1860-1899). Its four avatar characters mirror the four gods of Japanese mythology.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1997,"players":2,"hardware":"Neo Geo MVS","aka":["Bakumatsu Roman: Gekka no Kenshi"],"core":"arcade"},{"type":"retro","id":"lastbld2","slug":"the-last-blade-2","title":"The Last Blade 2","description":"SNK's 1998 swordplay sequel delivers sixteen fighters and one final boss.","about":"SNK's 1998 Neo-Geo MVS sequel, Bakumatsu Rouman Dai-ni Maku - Gekka no Kenshi, is a much-acclaimed swordplay fighter with sixteen selectable characters and one end boss. Outside Japan it is known as The Last Blade 2. Released in Japan on November 25, 1998, it includes homages to the legend behind Mulan and to Cantonese hero Wong Fei Hung. Akari and Juzoh serve as comedic relief, appearing beside the elephant depending on the matchup.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"SNK","year":1998,"players":2,"hardware":"Neo Geo MVS","aka":["Bakumatsu Roman: Dai Ni Maku Gekka no Kenshi"],"core":"arcade"},{"type":"retro","id":"superspy","slug":"the-super-spy","title":"The Super Spy","description":"SNK's 1990 Neo-Geo first-person beat-em-up with RPG elements, sending you into terrorist hideouts.","about":"An SNK Neo-Geo MVS game released in October 1990, The Super Spy is a first-person beat-em-up with RPG elements in which players infiltrate terrorist hideouts and fight the bad guys. A few rooms hide a G-Mantle poster on the wall, a character later used as a striker in The King of Fighters 2000. Two players use an 8-way joystick with three buttons: A punches or uses a weapon, B kicks, and C chooses a weapon.","system":"Neo Geo","genre":"action","categories":"action","developer":"SNK","year":1990,"players":1,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"ssideki4","slug":"the-ultimate-11-snk-football-championship","title":"The Ultimate 11: SNK Football Championship","description":"SNK's 1996 Neo-Geo soccer cart, known abroad as The Ultimate 11 - SNK Football Championship.","about":"An SNK Neo-Geo MVS soccer game released in Japan in October 1996, titled Tokuten Oh - Honoo no Libero, which translates as 'Top Scorer - Flame of Libero'. Outside Japan it is known as The Ultimate 11 - SNK Football Championship. Two players use an 8-way joystick and three buttons that change function by situation: on offense A shoots or makes a low pass, B a high pass, and C a short pass, while on defense A slides, B plays rough, and C shifts the action player.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"SNK","year":1996,"players":2,"hardware":"Neo Geo MVS","aka":["The Ultimate 11: The SNK Football Championship","Tokuten Ou: Honoo no Libero"],"core":"arcade"},{"type":"retro","id":"trally","slug":"thrash-rally","title":"Thrash Rally","description":"Pick your vehicle and race across snow, gravel, sand, and water in this top-down Neo-Geo rally game.","about":"Thrash Rally is a top-down rally racing game from Alpha Denshi, released on November 8, 1991 for the Neo-Geo MVS. One or two players choose from vehicles with differing handling, acceleration, endurance, and top speed. World Rally Championship mode offers six rally cars across lap-based circuits with time limits. Paris-to-Dakar mode is a point-to-point race that also includes a buggy, motorbike, and truck. Tracks feature varied surfaces plus jumps, chicanes, and obstacles to avoid.","system":"Neo Geo","genre":"racing","categories":"racing","developer":"Alpha Denshi Co.","year":1991,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"tophuntr","slug":"top-hunter-roddy-and-cathy","title":"Top Hunter: Roddy & Cathy","description":"Two bounty hunters battle galactic pirates across four elemental planets in this SNK Neo-Geo beat-em-up.","about":"Top Hunter: Roddy & Cathy is a horizontally-scrolling beat-em-up released by SNK on May 18, 1994 for the Neo-Geo MVS. One or two players control Roddy and Cathy, bounty hunters tasked with stopping the Klaptons, galactic pirates threatening the cosmos. Players jump between foreground and background planes, and can extend their arms to grab items and enemies, or pull themselves onto ledges. The game borrows special moves from SNK fighting games like Fatal Fury and Art of Fighting, including Ko'ouken and shoryuken-style attacks. Pony Canyon/Scitron released a limited-edition soundtrack on July 21, 1994.","system":"Neo Geo","genre":"run-and-gun","categories":"run-and-gun","developer":"SNK","year":1994,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"twinspri","slug":"twinkle-star-sprites","title":"Twinkle Star Sprites","description":"Cute versus shooting meets puzzle mayhem as Load Ran fights to save her world in this SNK Neo-Geo classic.","about":"A competitive scrolling shooter from ADK, Twinkle Star Sprites blends fixed-shooter action with versus puzzle mechanics. Players chain shots and timed power-ups to damage their opponent, with attacks doubling as counters. It was ADK's final Neo-Geo production. Story Mode follows Load Ran and Rabbicat on their quest for the Magical Twinkle Star against the evil Mevious. Free Character Mode offers other fighters and unique comical endings, while a second player can jump in anytime.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"ADK / SNK","year":1996,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"wakuwak7","slug":"waku-waku-7","title":"Waku Waku 7","description":"Sunsoft's 1996 Neo-Geo parody fighter packs seven selectable characters and a memorably nasty boss.","about":"Waku Waku 7 is a 1996 Sunsoft arcade fighting game on SNK Neo-Geo MVS hardware, parodying anime and video game styles with seven selectable characters and a tough end boss. Released in November 1996, it supports two players with an 8-way joystick and four buttons. The bonus stage against Bonus Kun, a Shotokan punching bag, parodies Ryu and Ken from Street Fighter, and its music echoes Ryu's theme. Pony Canyon put out a limited soundtrack album (PCCB-00215) on 21/08/1996.","system":"Neo Geo","genre":"fighting","categories":"fighting","developer":"Sunsoft","year":1996,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"wjammers","slug":"windjammers","title":"Windjammers","description":"Data East's 1994 Neo-Geo flying disc game, known outside Japan as Windjammers, hits the arcade.","about":"Flying Power Disc is a 1994 Data East Corp flying disc arcade game on SNK Neo-Geo MVS hardware, released February 17, 1994 in Japan and known elsewhere as Windjammers. Two players use an 8-way joystick and two buttons to slide, receive, throw, and lob. Each character speaks their own native language, and two mini-games appear: Dog Distance after match two and Flying Disc Bowling after match four. The game draws on the real sport 10-S, created in 1977 and copyrighted in 1980, without permission. On the USA territory dip switch, Korea's B. Yoo is swapped for Britain's S. Miller, keeping the same sprites but an English voice.","system":"Neo Geo","genre":"sports","categories":"sports","developer":"Data East Corporation","year":1994,"players":2,"hardware":"Neo Geo MVS","aka":["Flying Power Disc"],"core":"arcade"},{"type":"retro","id":"zedblade","slug":"zed-blade","title":"Zed Blade","description":"Blast through space in this Neo-Geo shooter with three ships, swappable weapons, and a high-score table that bans 'AAA'.","about":"Operation Ragnarok is a side-scrolling shoot-'em-up for one or two players on SNK's Neo-Geo MVS hardware, released by NMK in 1994. Players pick from three ships with different speeds, then configure front, rear, and projectile weapons such as Homing Missiles. Destroyed enemies and waves sometimes drop bonuses, weapon power-ups, and Hyper-Bombs, powerful smart bombs. Known as Zed Blade outside Japan, it hit Japanese arcades in September 1994 and never appeared on the Neo-Geo AES console. The high-score table refuses the initials 'AAA', changing them to 'YOU'.","system":"Neo Geo","genre":"shooter","categories":"shooter","developer":"NMK","year":1994,"players":2,"hardware":"Neo Geo MVS","aka":["Operation Ragnarok"],"core":"arcade"},{"type":"retro","id":"zupapa","slug":"zupapa","title":"Zupapa!","description":"Guide a boxing-glove-wearing hero and his four Zooks through nine whimsical lands in this colorful Neo-Geo platformer.","about":"Zupapa! is a whimsical action-platformer released by SNK for the Neo-Geo MVS in 2001. You control a long-eared, boxing-glove-wearing hero alongside four little sidekicks called Zooks, battling colorful enemies across worlds like Nightmare Land, Circus Land, Toy Land, and Dragon Land. Face first showed the game at the 1994 AOU Show, but it only saw official release years later, making it the only Neo-Geo unreleased prototype to eventually launch. It arrived months after Nightmare in the Dark, a game so similar that some players call it the adult counterpart to Zupapa's cute version.","system":"Neo Geo","genre":"platformer","categories":"platformer","developer":"SNK","year":2001,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"2020bb","slug":"2020-super-baseball","title":"2020 Super Baseball","description":"SNK's futuristic baseball sim lets you pick from 12 teams of men, women, and robots.","about":"2020 Super Baseball is SNK's Neo-Geo MVS take on the sport, set in a future where the Super Baseball Association has rigged games using a control computer. Players who discovered the manipulation removed the computer's connecting parts, leading to a fair match at 'CYBER EGG'. You choose from 12 teams mixing men, women, and robot players, with fast-paced rules and prizes earned from amazing catches that strengthen your squad. Two players can compete simultaneously with a CONTINUE mode. The game arrived in Japan on September 20, 1991, running on Neo-Geo MVS hardware with game ID NGM-030.","system":"Arcade","genre":"sports","categories":"sports","developer":"SNK / Pallas","year":1991,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"aburner2","slug":"after-burner-ii","title":"After Burner II","description":"Sega's 1987 jet-fighter sequel puts you in an F14 Tomcat across 21 fast-moving stages.","about":"After Burner II is Sega's 1987 arcade shooter built on the company's 3-D sprite-scaling technology, seating players in an F14 Tomcat. Across 21 colourful stages you gun down enemy fighters with an infinite-ammo machine gun and a limited stock of homing missiles, locking on before firing. Missiles are replenished every second stage via a support plane link-up or an automatic airstrip landing. Released in October 1987, it was once planned as a World War II-themed realistic flight sim before Yu Suzuki dropped that direction. Landing cut-scenes hide cameos: the Hang-On motorcyclist and the Out Run-style sports car. David Hernly set a record of 2,215,620 points on June 1, 2008, and an ABII unit…","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Sega","year":1987,"players":1,"hardware":"Sega X Board","core":"arcade"},{"type":"retro","id":"astorm","slug":"alien-storm","title":"Alien Storm","description":"SEGA's 1990 arcade run-and-gun sends players against an alien invasion in a two-player world release.","about":"Alien Storm is an arcade game released by SEGA Enterprises, Ltd in 1990. This is the two-player export (world) release, and the game was developed in Japan. It follows the original version, which was released as Model 317-0146. This edition carries Game ID 317-0154.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Sega","year":1990,"players":2,"hardware":"Sega System 18","version":"World version","core":"arcade"},{"type":"retro","id":"altbeast","slug":"altered-beast","title":"Altered Beast","description":"SEGA's 1988 arcade beat-'em-up where heroes transform into mighty beasts to battle the underworld.","about":"Altered Beast is an arcade action game released by SEGA Enterprises, Ltd in 1988. It is a Re-Edition of the original arcade version, which was released as Model 317-0066, while this edition carries Game ID 317-0078.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Sega","year":1988,"players":2,"hardware":"Sega System 16B","core":"arcade"},{"type":"retro","id":"aof","slug":"art-of-fighting","title":"Art of Fighting","description":"SNK's 1992 Neo-Geo fighter introduced the camera zoom and spirit meter to the martial arts genre.","about":"Ryuuko no Ken is a martial arts fighting game released by SNK Corp in 1992 on Neo-Geo MVS hardware. One-player mode offers 2 selectable characters, while two-player mode offers 8, and a long-nosed boss awaits at the end. Progressive damage appears on each fighter's face. Launched in Japan in September 1992, its title translates as 'Dragon and Tiger Fist' and it is known overseas as Art of Fighting. It was SNK's second fighting-game franchise and the first fighting game to use a camera zoom and a spirit meter, with character designs by former SNK illustrator Shinkiro. Game ID: NGM-044.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"SNK","year":1992,"players":2,"hardware":"Neo Geo MVS","aka":["Ryuuko no Ken"],"core":"arcade"},{"type":"retro","id":"batman","slug":"batman","title":"Batman","description":"Atari's 1990 arcade action game pits Batman against the Joker across Gotham City.","about":"Batman is Atari Games' 1990 arcade action title in which the Dark Knight races to save Gotham City from the Joker. Alongside side-scrolling stages, it mixes in first-person Batmobile and Batwing sequences drawn from the movie. Released June 16, 1990 as a conversion kit priced at 1,095 USD, it shipped 500 kits in the United States and 101 in Ireland. Its digitized audio sampled Michael Keaton and Jack Nicholson, and a unit once belonged to Michael Jackson.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Atari Games","year":1991,"players":1,"core":"arcade"},{"type":"retro","id":"btoads","slug":"battletoads","title":"Battletoads","description":"Three Battletoads brawl through six wild stages to stop the Dark Queen in this rare arcade-only beat-'em-up.","about":"Battletoads is a mostly side-scrolling beat-'em-up for up to three players, who choose Rash, Pimple, or Zitz. Each Toad has a distinct fighting style — Rash is nimble, Pimple is burly, and Zitz balances the two — plus a signature attack that turns limbs into axes, drills, and more. The six stages mix 2.5D brawling with strictly 2D platforming, jet-pack tunnels, and a vehicle-shooting finale. Enemies include aliens, mutant rodents, and snowmen, and foes can be knocked off-screen toward the players. Released in December 1994 by Electronic Arts and licensed from Rare, it was never ported to consoles.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Rare / Electronic Arts","year":1994,"players":2,"core":"arcade"},{"type":"retro","id":"sailormn","slug":"bishoujo-senshi-sailor-moon","title":"Bishoujo Senshi Sailor Moon","description":"Banpresto's 1995 Sailor Moon arcade brawler sends the Sailor Senshi through five levels.","about":"Pretty Soldier Sailormoon is a 1995 Banpresto arcade side-scrolling beat-em-up for one or two players, following the Sailor Senshi through five levels of anime-style combat. Players pick from five fighters who punch, kick, jump, and throw before facing each level's boss. Released on March 22, 1995 and developed by Gazelle, it uses magic crystals to fuel a screen-clearing special attack, much like Shinobi, and draws its moves from the Toei anime.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Gazelle (Banpresto license)","year":1995,"players":1,"core":"arcade"},{"type":"retro","id":"buckrog","slug":"buck-rogers-planet-of-zoom","title":"Buck Rogers: Planet of Zoom","description":"Sega's 1982 cockpit arcade shooter sends Buck Rogers racing through a zooming alien gauntlet.","about":"Buck Rogers - Planet of Zoom is a 1982 Sega arcade release, developed in Japan and offered in a cockpit model. It was published in December 1982 and also appeared as an upright model.","system":"Arcade","genre":"action","categories":"action","developer":"Sega","year":1982,"players":1,"hardware":"Sega Z80-3D hardware","core":"arcade"},{"type":"retro","id":"captaven","slug":"captain-america-and-the-avengers","title":"Captain America and the Avengers","description":"Captain America, Iron Man, Vision, and Hawkeye battle Red Skull's forces in Data East's 1991 brawler.","about":"Captain America and the Avengers is a 1991 Data East side-scrolling beat-'em-up with occasional shoot-'em-up sections. Players pick Captain America, Iron Man, Vision, or Hawkeye, each with a distinct weapon — shield, repulsor rays, solar beam, or bow and arrows — and allies like Quicksilver, Sub-Mariner, Wonder Man, and The Wasp appear to help. Foes include Klaw, The Living Laser, Whirlwind, The Grim Reaper, The Wizard, The Controllers, The Mandarin, The Juggernaut, Ultron, and Crossbones across five stages. Released in October 1991, it runs on Data East ARM6 hardware. Josh Bycer set the official record with 496,801 points on April 20, 1997.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Data East Corporation","year":1991,"players":4,"hardware":"Data East DECO 32","version":"Asia version","core":"arcade"},{"type":"retro","id":"columns","slug":"columns","title":"Columns","description":"Sega's 1990 falling-block puzzler drops three-block columns and rewards clever cascades over Tetris-style rotation.","about":"Columns is Sega's 1990 answer to Tetris. A column of three stacked blocks drops from the top; players move it left or right but cannot rotate it. Instead, a button shifts the order of the colored blocks by one position. Matching three or more like-colored blocks horizontally, vertically, or diagonally clears them, and blocks above fall into the gap, often triggering cascades. Released in March 1990, it runs on Sega System C-2 hardware with 2 players, a 4-way joystick, and one rotate button. April Simmonds of Winnipeg, Manitoba, Canada, holds the official record with 267,360 points on November 13, 2006.","system":"Arcade","genre":"puzzle","categories":"puzzle","developer":"Sega","year":1990,"players":2,"hardware":"Sega System C","version":"World version","core":"arcade"},{"type":"retro","id":"congo","slug":"congo-bongo","title":"Congo Bongo","description":"Sega's 1983 arcade favorite Congo Bongo appears here in its two-board version.","about":"Congo Bongo is a 1983 Sega arcade release, developed in Japan. This entry covers the two-board version, SEGA ID 834-5180, using PCBs 834-5181 and 834-5167.","system":"Arcade","genre":"action","categories":"action","developer":"Sega","year":1983,"players":1,"hardware":"Sega Zaxxon hardware","core":"arcade"},{"type":"retro","id":"contra","slug":"contra","title":"Contra","description":"Grab a friend and battle Red Falcon's forces across ten stages in this classic run-and-gun arcade shooter.","about":"In 2631, a meteor crashes into the Galuga archipelago near New Zealand, bringing a dormant alien with it. Two years later, the terrorist group Red Falcon seizes the island to launch an invasion of Earth, and Contra operatives Bill Rizer and Lance Bean are dispatched to stop them. This one or two player platform shooter spans 10 stages, mixing side-view action with 3D maze corridors inside enemy bases. Your semi-automatic machine gun has unlimited ammo, and you can move, jump and fire in eight directions at once. One hit kills you and costs you your current weapon.","system":"Arcade","genre":"run-and-gun","categories":"run-and-gun","developer":"Konami","year":1987,"players":2,"hardware":"Konami GX633","version":"USA / Asia version","core":"arcade"},{"type":"retro","id":"eswat","slug":"cyber-police-eswat","title":"Cyber Police ESWAT","description":"Sega's 1989 arcade action game pits cyber police against the city's criminal underworld.","about":"Cyber Police E-SWAT - The Ultimate Factor in the Battle Against Crime is a Sega arcade game from 1989. This export release was developed in Japan, where it debuted under the same title. The game carries the identifier 317-0130 and runs on Sega's arcade hardware of the era.","system":"Arcade","genre":"run-and-gun","categories":"run-and-gun","developer":"Sega","year":1989,"players":1,"hardware":"Sega System 16B","core":"arcade"},{"type":"retro","id":"ddragon","slug":"double-dragon","title":"Double Dragon","description":"Two brothers take on the streets in Taito's export release of the iconic beat-'em-up.","about":"Double Dragon is a 1987 arcade game published by Taito Corp for releases outside Japan, under license from Technos Japan.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Technos Japan (Taito license)","year":1987,"players":2,"version":"World version","core":"arcade"},{"type":"retro","id":"ddragon3","slug":"double-dragon-3-the-rosetta-stone","title":"Double Dragon 3: The Rosetta Stone","description":"Billy and Jimmy Lee chase the Rosetta Stone across the globe in the final arcade chapter of Double Dragon.","about":"A fortune teller warns Billy and Jimmy Lee of a rising enemy in Egypt, and the brothers set out on a worldwide quest for the Rosetta Stone, picking up new allies along the way. This third and final arcade entry in the Double Dragon series swapped out the earlier gameplay and graphics for a new system, adding moves like the belly-to-back throw and back-to-back hurricane kick while dropping the hair grab and elbow punch. It was developed by East Technology rather than Technos' internal team, and supports up to three players, with the third controlling Sonny, a yellow-clad Lee brother unique to this game.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"East Technology / Technos Japan","year":1990,"players":2,"version":"USA version","core":"arcade"},{"type":"retro","id":"ddragon2","slug":"double-dragon-ii-the-revenge","title":"Double Dragon II: The Revenge","description":"Billy and Jimmy Lee return to avenge Marian's death in this upgraded arcade beat-'em-up sequel.","about":"After his defeat in the original Double Dragon, Black Warriors leader Willy strikes back by murdering Billy and Jimmy Lee's friend Marian, sending the brothers on a quest for revenge. The sequel keeps the original's attacks and combos while adding new moves like the invincible Cyclone Kick, plus redesigned stages, weapons and traps such as a bulldozer in Mission 3. Released in December 1988, the game swapped the usual punch and kick buttons for left and right attack controls. It began as a chip upgrade of the first game before growing into new hardware, and the coin-insert yell comes from the stick-wielding Mission 3 boss Chin Taimei.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Technos Japan","year":1988,"players":2,"version":"World version","core":"arcade"},{"type":"retro","id":"dbz","slug":"dragon-ball-z","title":"Dragon Ball Z","description":"Pick your favorite fighter from Akira Toriyama's manga and battle it out in this arcade adaptation.","about":"Based on Akira Toriyama's famous manga, this 1993 Banpresto arcade game lets you play as many of the well-known characters from the show. It supports two players using an 8-way joystick and three buttons for punch, kick and hard attack. Released in November 1993, a limited-edition soundtrack album followed in 2005.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"Banpresto","year":1993,"players":2,"core":"arcade"},{"type":"retro","id":"fireshrk","slug":"fire-shark","title":"Fire Shark","description":"Toaplan's 1989 vertical shooter soars into battle with relentless aerial action.","about":"Fire Shark is a Toaplan arcade shoot'em up released in 1989, known in Japan as Same! Same! Same! This export version runs on Toaplan hardware under game ID TP-017. Romstar handled USA distribution and Dooyong handled Korean distribution. The Japanese original differs in that it allows only one player at a time, and after being hit you restart slightly behind where you left off.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Toaplan","year":1990,"players":1,"hardware":"Toaplan BCU-2 / FCU-2 hardware","core":"arcade"},{"type":"retro","id":"flicky","slug":"flicky","title":"Flicky","description":"Guide Flicky the flightless bird as she rescues her lost chicks and dodges hungry house cats.","about":"Flicky is a side-scrolling platform arcade game from Sega. Players control a flightless bird who must gather her scattered chicks, called chirps, and lead them to the exit door bearing her name. Cats emerging from cat-flaps roam the stages; contact costs a life, and any chick touched by a cat must be retrieved again. Each round is cleared by bringing all chirps to the exit. The first two rounds have six chirps, later rounds eight. Bonus rounds let Flicky catch falling chirps in a net for a Perfect bonus. The game was developed under the names Busty and Flipp before becoming Flicky, and released in May 1984 in Japan.","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Sega","year":1984,"players":1,"hardware":"Sega System 1","core":"arcade"},{"type":"retro","id":"forgottn","slug":"forgotten-worlds","title":"Forgotten Worlds","description":"A Capcom arcade classic returns, bringing its distinctive run-and-gun action to a new generation.","about":"Forgotten Worlds is an arcade release from Capcom USA, an updated version of the game originally published in Japan as Lost Worlds. It runs on CP System hardware, B-Board 88621B-2.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Capcom","year":1988,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version","core":"arcade"},{"type":"retro","id":"frogger","slug":"frogger","title":"Frogger","description":"Hop across busy roads and treacherous rivers to guide Frogger safely home.","about":"Frogger is a one- or two-player arcade game from Konami. Players guide a green amphibian from the bottom of the screen to one of five home bases at the top, crossing five lanes of traffic and then a fast-flowing river filled with logs, crocodiles, and turtles that serve as platforms. Vehicle types move at different speeds, and some turtles dive underwater, drowning Frogger on contact. Konami released the game in Japan in June 1981, and it became a runaway hit. The coin-insert sound was later sampled by producer Richard X for the Sugababes' song 'Freak Like Me'.","system":"Arcade","genre":"action","categories":"action","developer":"Konami","year":1981,"players":2,"hardware":"Namco Galaxian hardware","core":"arcade"},{"type":"retro","id":"gground","slug":"gain-ground","title":"Gain Ground","description":"Rescue stranded troops and battle through fields and castles in this Sega shoot-em-up.","about":"Gain Ground is a one- or two-player shoot-em-up released by Sega in 1988 on System 24 hardware. Each single-screen level challenges players to rescue lost troops before reaching the exit, choosing from three characters with unique weapons, strengths, and weaknesses. Time pressure means any troops left behind are lost, while rescued soldiers join as bonus players. Stages range across fields, castles, forests, and forts. The game arrived in Japan in November 1988. Cyber, one of the playable characters, was clearly influenced by the 1987 film RoboCop, and the final boss resembles ED-209 from the same movie.","system":"Arcade","genre":"run-and-gun","categories":"run-and-gun","developer":"Sega","year":1988,"players":3,"hardware":"Sega System 24","version":"World version","core":"arcade"},{"type":"retro","id":"garou","slug":"garou-mark-of-the-wolves","title":"Garou: Mark of the Wolves","description":"Southtown hosts a new tournament as SNK's Fatal Fury saga enters its ninth chapter.","about":"Garou: Mark of the Wolves is a one-on-one fighting game and the ninth entry in SNK's Fatal Fury series, released for the Neo-Geo MVS in November 1999. Set ten years after Geese Howard's death in a peaceful Second Southtown, it features 12 characters and drops the plane-switching battles of its predecessors for standard single-plane combat. The game introduced the Tactical Offense Position, a zone on the life gauge that grants a T.O.P. attack, gradual life recovery, and increased damage, plus the Just Defend system rewarding last-moment blocks. 'Garou' translates from Japanese as 'Hungry Wolf'.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"SNK","year":1999,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"ghouls","slug":"ghouls-n-ghosts","title":"Ghouls'n Ghosts","description":"Capcom's ghoulish action classic brings its demon-filled quest to arcades outside Japan.","about":"Ghouls'n Ghosts is an export arcade release from Capcom, developed in Japan and published in December 1988 outside the country. In Japan, the game is known as Daimakaimura. It runs on CP System hardware with B-Board 88620B-2.","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Capcom","year":1988,"players":1,"hardware":"Capcom CP System (CPS1)","version":"World version","core":"arcade"},{"type":"retro","id":"goldnaxe","slug":"golden-axe","title":"Golden Axe","description":"Three warriors storm Death Adder's realm in Sega's 1989 fantasy beat-em-up classic.","about":"Golden Axe is Sega's 1989 side-scrolling beat-em-up set in a fantasy world where three heroes fight to rescue a kidnapped King and Queen from Death Adder. Choose Tyris Flare the Amazon, Ax Battler the Barbarian, or Gilius Thunderhead the Viking dwarf. Press jump and attack together for a special move, or double-tap left or right to charge. Knock a rider off a creature to mount it yourself, and hit Thieves to grab food and magic potions. The title screen's kanji reads 'Senpu', meaning 'Fighting Axe'.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Sega","year":1989,"players":2,"hardware":"Sega System 16B","core":"arcade"},{"type":"retro","id":"growl","slug":"growl","title":"Growl","description":"Taito's 1991 arcade brawler Growl brings the fight to US shores as an export release.","about":"Growl is the 1991 export version of Taito America Corp's arcade beat-em-up, released in the US in February 1991. It runs on the Taito F2 System hardware. For details about the game itself, see the original Japanese release, Runark. The title screen may read 1990, but the US release date was February 1991.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Taito Corporation Japan","year":1990,"players":1,"hardware":"Taito F2 System","version":"World version","core":"arcade"},{"type":"retro","id":"hellfire","slug":"hellfire","title":"Hellfire","description":"Taito's 1989 horizontal shooter lets you aim your fire in multiple directions.","about":"Hellfire is Taito Corp's 1989 horizontal shoot-em-up, notable for letting players select their shooting direction. It arrived in Japanese arcades on April 20, 1989. An early version carried the title 'Captain Lancer'. Polystar put out a limited-edition soundtrack album for the game on June 25, 1989.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Toaplan (Taito license)","year":1989,"players":1,"hardware":"Toaplan BCU-2 / FCU-2 hardware","core":"arcade"},{"type":"retro","id":"hitice","slug":"hit-the-ice","title":"Hit the Ice","description":"No-holds-barred hockey hits the arcade with fights, brutal checks, and power drinks.","about":"Hit the Ice - The Video Hockey League is Williams Electronics Games' 1990 arcade hockey title, built around the Reds versus Blues rivalry. Pass, shoot, and check opponents, each with their own bone-crushing style, and start fights to heat things up. An extra credit buys a 'power drink' that boosts speed and shot power for one minute at the start of a period. Released in December 1990 and developed by Taito Corp, the game appears in the 1991 film 'Terminator 2 - Judgment Day'.","system":"Arcade","genre":"sports","categories":"sports","developer":"Taito Corporation (Williams license)","year":1990,"players":2,"hardware":"Taito B System","version":"USA version","core":"arcade"},{"type":"retro","id":"hook","slug":"hook","title":"Hook","description":"The Lost Boys take on Captain Hook in Irem's 1992 arcade adaptation of the Robin Williams film.","about":"Hook is Irem's 1992 arcade game drawn from the Peter Pan saga and the Robin Williams film, with the Never-Never Land children fighting to stop Captain Hook. It arrived in December 1992. All four Lost Boys appear, but only Rufio is named in the movie.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Irem","year":1992,"players":1,"hardware":"Irem M92","version":"World version","core":"arcade"},{"type":"retro","id":"kingball","slug":"king-and-balloon","title":"King & Balloon","description":"Defend the king from balloon abductions in this classic 1980 arcade title.","about":"This is the North American release of the 1980 arcade game King & Balloon, developed in Japan by Game Plan, Inc. The goal is to protect the king from balloons that try to carry him away. Released in the USA in December 1980, two months after the Japanese version, it featured redone voice samples. The king's cry for help was changed from a Japanese-accented 'Herupuu!' to a clearer English 'Help!'.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Namco","year":1980,"players":2,"hardware":"Namco Galaxian hardware","version":"USA version","core":"arcade"},{"type":"retro","id":"kotm","slug":"king-of-the-monsters","title":"King of the Monsters","description":"Smash cities and rivals in SNK's 1991 Neo-Geo monster brawler set in Japan.","about":"SNK's 1991 Neo-Geo MVS release pits giant monsters against each other as they wreck a Japanese city. Think Rampage as a beat-'em-up: destroy the city while destroying your opponent. Released on February 25, 1991, it also received a limited-edition soundtrack album from Pony Canyon / Scitron on 21/09/1991.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"SNK","year":1991,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"kotm2","slug":"king-of-the-monsters-2","title":"King of the Monsters 2","description":"SNK's 1992 monster sequel adds pesky small enemies alongside each stage's main foe.","about":"This 1992 SNK Neo-Geo MVS sequel to King of the Monsters adds new elements, including small, annoying enemies on the battlefield in addition to the main foe in each stage. The MVS version was released on May 25, 1992.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"SNK","year":1992,"players":2,"hardware":"Neo Geo MVS","aka":["King of the Monsters 2: The Next Thing"],"core":"arcade"},{"type":"retro","id":"klax","slug":"klax","title":"Klax","description":"Catch falling tiles and build lines of three in Atari's 1990 puzzle classic, Klax.","about":"Klax is a 1990 arcade puzzle game from Atari Games. Players catch falling colored tiles on a paddle and flip them into bins to form lines of three or more, either horizontally, vertically, or diagonally. The goal is to complete waves without letting tiles fall into the pit. Though the title screen says 1989, it was released in February 1990. It was originally programmed in Amiga Basic by Dave Akers before being ported to C and running on hardware from Escape From the Planet of the Robot Monsters.","system":"Arcade","genre":"puzzle","categories":"puzzle","developer":"Atari Games","year":1990,"players":1,"core":"arcade"},{"type":"retro","id":"megaman","slug":"mega-man-the-power-battle","title":"Mega Man: The Power Battle","description":"Capcom's 1995 arcade fighter pits the Blue Bomber against a roster of Robot Masters.","about":"Mega Man - The Power Battle is Capcom USA's 1995 North American arcade release, developed in Japan and running on CP System hardware. It is the arcade fighting spin on the classic Mega Man series.","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Capcom","year":1995,"players":2,"hardware":"Capcom CP System (CPS1)","core":"arcade"},{"type":"retro","id":"mercs","slug":"mercs","title":"Mercs","description":"Capcom's 1990 arcade export Mercs brings explosive run-and-gun action to the CP System.","about":"Mercs is a 1990 Capcom arcade export developed in Japan and running on CP System hardware with B-Board ID 89624B-3. It is the export counterpart to the Japanese release Senjou no Ookami II [B-Board 89625B-1].","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Capcom","year":1990,"players":3,"hardware":"Capcom CP System (CPS1)","version":"World version of 2 March 1990","core":"arcade"},{"type":"retro","id":"mwalk","slug":"michael-jackson-s-moonwalker","title":"Michael Jackson's Moonwalker","description":"Guide Michael Jackson and his chimp Bubbles through isometric stages to rescue kids from Mr. Big's clutches.","about":"Michael Jackson's MoonWalker is a 1990 Sega arcade scrolling isometric beat-'em-up based on the film, tasking Michael and his chimp Bubbles with saving children and toppling the evil Mr. Big. Players clear each round's henchmen and machines using charged magical energy shots or Dance Magic smart bombs, and touching Bubbles transforms Michael into the laser-and-missile-firing Moonwalker robot. Its five stages each carry a different Michael Jackson track, including 'Bad', 'Smooth Criminal', 'Beat It' and 'Another Part of Me', with 'Billie Jean' playing at the ending.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Sega","year":1990,"players":1,"hardware":"Sega System 18","version":"World version","core":"arcade"},{"type":"retro","id":"mk","slug":"mortal-kombat","title":"Mortal Kombat","description":"Mortal Kombat's 1992 arcade debut brought digitized fighters, blood, and Fatalities to the world.","about":"Mortal Kombat is Midway's 1992 one-on-one arcade fighting game and the first entry in the series, starring seven characters: Johnny Cage, Kano, Raiden, Liu Kang, Scorpion, Sub-Zero, and Sonya Blade. Battles use a best-of-three round format, drawing inspiration from Capcom's Street Fighter II for special moves and projectiles while introducing photo-realistic digitized fighters. After a win, a voice calls 'Finish Him/Her!' and the victor has seconds to perform a Fatality. Released October 8th, 1992 in the USA, it was renowned as the first fighting game to use digitized characters and blood, and was developed as a reaction to Street Fighter II with simpler controls. Its graphic violence…","system":"Arcade","genre":"fighting","categories":"fighting","developer":"Midway","year":1992,"players":2,"hardware":"Midway T-Unit","core":"arcade"},{"type":"retro","id":"mk2","slug":"mortal-kombat-ii","title":"Mortal Kombat II","description":"Mortal Kombat II expands the roster to 12 fighters and adds Babalities and Friendships.","about":"Mortal Kombat II is Midway Mfg. Co.'s 1993 arcade sequel to the 1992 original, growing the character roster from 7 to 12 and improving the graphics. Matches are divided into rounds, with victory going to the first player to win two, and the losing fighter becomes dazed so the winner can attempt a finishing move. Standard moves were expanded: a crouching punch was added, the roundhouse kick is more powerful and knocks opponents across the screen, and hit box differences between high and low kicks are more marked. Returning characters gain new special moves, and MKII marks the first appearance of multiple Fatalities plus non-lethal finishers like Babalities and Friendships. Released in June…","system":"Arcade","genre":"fighting","categories":"fighting","developer":"Midway","year":1993,"players":2,"hardware":"Midway T-Unit","core":"arcade"},{"type":"retro","id":"mspacman","slug":"ms-pac-man","title":"Ms. Pac-Man","description":"Midway's 1982 maze sequel stars gaming's first female lead, with moving fruit, four maze layouts and the familiar ghosts.","about":"Ms. Pac-Man is an arcade maze game released by Midway in 1982, the first proper sequel to Namco's pill-eating original. Players clear mazes of dots while dodging Blinky, Pinky, Inky and Sue, with four Power Pills in each maze. Ms. Pac-Man wears a bow and lipstick, and the bonus fruit moves randomly rather than sitting still. Four maze layouts rotate every two to four rounds. The game began as an enhancement kit called Crazy Otto by General Computing, and the name shifted from Mrs. Pac-Man to Miss Pac-Man before settling on Ms. Pac-Man.","system":"Arcade","genre":"action","categories":"action","developer":"Midway / General Computer Corporation","year":1981,"players":2,"hardware":"Namco Pac-Man hardware","core":"arcade"},{"type":"retro","id":"nbajamte","slug":"nba-jam-tournament-edition","title":"NBA Jam Tournament Edition","description":"Licensed NBA stars trade physics-defying dunks in wild two-on-two arcade basketball.","about":"NBA Jam Tournament Edition is Midway's 1994 arcade basketball game for one or two players, built around two-on-two action with real licensed NBA teams and digitized players. An eight-way joystick and three buttons cover Shoot/Block, Pass/Steal and Turbo, with no fouls or free throws beyond goaltending and 24-second violations, letting players push and elbow freely as they leap far beyond human height for slam dunks. Each team carries three players and allows substitutions. It arrived on January 17, 1994 as a direct sequel to NBA Jam and an officially licensed NBA product.","system":"Arcade","genre":"sports","categories":"sports","developer":"Midway","year":1994,"players":4,"hardware":"Midway T-Unit","core":"arcade"},{"type":"retro","id":"nemo","slug":"nemo","title":"Nemo","description":"Capcom's 1990 arcade Nemo sends players into a dreamworld adventure on CP System hardware.","about":"Nemo is a 1990 Capcom arcade game developed in Japan and released in export territories, running on CP System hardware. It shares its board lineage with the original Japanese release entry, Nemo [B-Board 89625B-1].","system":"Arcade","genre":"action","categories":"action","developer":"Capcom","year":1990,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 30 November 1990","core":"arcade"},{"type":"retro","id":"outrun","slug":"outrun","title":"OutRun","description":"Drive a red Ferrari Testarossa through Europe in Sega's legendary arcade racer.","about":"Out Run is Sega's 1986 arcade racing landmark. You pilot a red Ferrari Testarossa across colourful European locations, dodging civilian traffic on twisting, hilly roads while racing each checkpoint's tight time limit. At every stage's end a fork in the road lets you choose your next route, and the in-car radio offers three tunes: 'Magical Sound Shower', 'Passing Breeze' and 'Splash Wave'. It launched internationally on September 20, 1986, and its deluxe cabinet came as a hydraulic tilting Ferrari Testarossa shell with speakers right behind the player's head.","system":"Arcade","genre":"racing","categories":"racing","developer":"Sega","year":1986,"players":1,"hardware":"Sega Out Run hardware","core":"arcade"},{"type":"retro","id":"pacman","slug":"pac-man-arcade-1980","title":"Pac-Man (Arcade 1980)","description":"The arcade icon that swallowed a generation, licensed by Midway for North America.","about":"Pac-Man is Midway Mfg.'s 1980 export release of Namco's Japanese hit Puckman, brought to North America under license. Midway renamed the game and its hero, and gave the ghosts the nicknames Blinky, Pinky, Inky and Clyde. It launched in the USA on October 10, 1980, with 96,000 units produced in America. The game's early-'80s cult status even spawned Buckner and Garcia's single 'Pac-Man Fever', which reached #9 on the pop charts after its December 1981 release.","system":"Arcade","genre":"action","categories":"action","developer":"Namco (Midway license)","year":1980,"players":2,"hardware":"Namco Pac-Man hardware","core":"arcade"},{"type":"retro","id":"pitfight","slug":"pit-fighter","title":"Pit-Fighter","description":"Three digitized brawlers take on street thugs in Atari's crowd-brawling arcade fighter.","about":"Pit-Fighter pits digitized fighters against a range of street thugs, with crowd interference and usable weapons adding chaos to the brawling. A Grudge Match mode lets players turn on each other. Released in August 1990 as a dedicated cabinet, it was one of the first fighting games with fully digitized protagonists, arriving two years before Mortal Kombat. The dedicated machine supported up to three players, while conversion kits typically went into two-player cabinets.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"Atari Games","year":1990,"players":3,"core":"arcade"},{"type":"retro","id":"puyopuy2","slug":"puyo-puyo-2","title":"Puyo Puyo 2","description":"Compile's 1994 puzzle sequel Puyo Puyo 2 brings the addictive falling-blob action back for two players.","about":"Puyo Puyo 2 is a 1994 arcade puzzle game by Compile, the sequel to the hugely popular Puyo Puyo. It plays much like the original, matching falling blobs to clear them, and remains just as addictive and fun. The title screen reads 'Puyo Puyo Tsu' — 'Tsu' is a pun pronounced like 'Two'. It was licensed to Sega for manufacture and runs on Sega System C-2 hardware.","system":"Arcade","genre":"puzzle","categories":"puzzle","developer":"Compile (Sega license)","year":1994,"players":2,"hardware":"Sega System C-2","version":"Japan version","core":"arcade"},{"type":"retro","id":"rbisland","slug":"rainbow-islands","title":"Rainbow Islands","description":"Taito's 1987 Rainbow Islands casts Bub and Bob as humans building rainbows to scale each isle.","about":"Rainbow Islands - The Story of Bubble Bobble 2 is a 1987 Taito arcade game, a sequel to Bubble Bobble. One or two players control Bub and Bob, restored to human form, who create solid rainbows used both as weapons and as temporary platforms while racing to the top of each island before time runs out. Released in October 1987, its fifth island, DOH Island, pays homage to Taito's Arkanoid, complete with Arkanoid-style enemies, block platforms and even its Game Over music. A bootleg called 'Jumping' appeared in 1989.","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Taito Corporation","year":1987,"players":1,"core":"arcade"},{"type":"retro","id":"rambo3","slug":"rambo-iii","title":"Rambo III","description":"Taito's 1989 arcade shooter Rambo III sends you into Afghanistan to battle the Soviet army.","about":"Rambo III is a 1989 Taito Corp arcade game where you take the role of Rambo and Colonel Sam Trautman fighting the Soviet army in Afghanistan. It runs on Taito B System hardware. Based on the film of the same name, it launched in Japan in May 1989 and in Europe that September. The movie is rated R by the MPAA, intended for mature audiences with parental guidance advised and no under-17s admitted without a parent or adult guardian.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Taito Europe Corporation","year":1989,"players":2,"hardware":"Taito B System","version":"Europe version","core":"arcade"},{"type":"retro","id":"rthun2","slug":"rolling-thunder-2","title":"Rolling Thunder 2","description":"Namco's 1991 Rolling Thunder 2 returns agents to battle GERDRA with co-op play.","about":"Rolling Thunder 2 is a 1991 Namco arcade scrolling platform shooter, continuing the 1986 original as secret agents fight the GERDRA organization. Doors hide enemies, weapons, and ammunition, and two players can now team up, with a female agent leading the solo role. Despite a 1990 title screen, the game arrived in March 1991. Victor Entertainment issued a limited soundtrack album on June 21, 1991.","system":"Arcade","genre":"run-and-gun","categories":"run-and-gun","developer":"Namco","year":1990,"players":2,"hardware":"Namco System 2","core":"arcade"},{"type":"retro","id":"samsho","slug":"samurai-shodown","title":"Samurai Shodown","description":"SNK's 1993 Samurai Shodown brought weapons-based dueling to the Neo-Geo.","about":"Samurai Spirits, known outside Japan as Samurai Shodown, is a 1993 SNK Neo-Geo MVS weapons-based fighter with 12 characters, bonus rounds, and one end boss. Four buttons shift between armed and unarmed attacks. Released in Japan in July 1993, it pioneered weapon fighting in the genre using an upgraded scaling engine from Art of Fighting. Many characters draw on history, including Haohmaru, inspired by Miyamoto Musashi.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"SNK","year":1993,"players":2,"hardware":"Neo Geo MVS","aka":["Samurai Spirits"],"core":"arcade"},{"type":"retro","id":"samsho2","slug":"samurai-shodown-ii","title":"Samurai Shodown II","description":"Fifteen weapon-wielding warriors clash in SNK's 1994 fighter that introduced the parry and POW meter.","about":"Shin Samurai Spirits - Hahmaru Jigokuhen is a one-on-one fighting game from SNK, released in October 1994 on the Neo-Geo MVS. Fifteen weapon-wielding combatants battle to earn the right to face a powerful and difficult end boss. Building on the first game, SNK added characters and moves, including the POW meter for super specials that can break an opponent's weapon. It also introduced rolling, ducking, small hops, and the first offensive blocking technique, the parry. The game is known outside Japan as Samurai Shodown II.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"SNK","year":1994,"players":2,"hardware":"Neo Geo MVS","aka":["Shin Samurai Spirits: Haohmaru Jigokuhen"],"core":"arcade"},{"type":"retro","id":"slammast","slug":"saturday-night-slam-masters","title":"Saturday Night Slam Masters","description":"Capcom's 1993 wrestling brawler brings Muscle Bomber action to arcades outside Japan.","about":"Saturday Night Slam Masters is Capcom's 1993 arcade wrestling game, developed in Japan and released internationally in July 1993. Japanese players know it as Muscle Bomber - The Body Explosion. Several wrestlers were renamed for audiences abroad, including Biff Slamkovich (Aleksey Zalazof), Gunloc (Lucky Colt), The Great Oni (Mysterious Budo), and El Stingray (El Stinger). The game runs on Capcom's CP System hardware.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"Capcom","year":1993,"players":4,"hardware":"Capcom CP System (CPS1)","version":"World version of 13 July 1993","core":"arcade"},{"type":"retro","id":"sonic","slug":"segasonic-the-hedgehog","title":"SegaSonic the Hedgehog","description":"Sonic, Ray, and Mighty race across Eggman Island in Sega's 1992 isometric arcade game for up to three players.","about":"Segasonic The Hedgehog is a scrolling isometric racing game released by Sega, supporting one to three players as Sonic, Ray, and Mighty escape Eggman Island after Dr. Robotnik imprisons them in a tower. Gameplay keeps series staples like jumping on enemies and collecting golden rings, while levels are filled with lava flows, collapsible platforms, and locked gates. Though the title screen reads 1992, the game actually launched in Japan in September 1993, and it marked the first appearance of Ray and Mighty. It runs on Sega's System 32 hardware with a trackball and one button per player.","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Sega","year":1992,"players":3,"hardware":"Sega System 32","version":"Japan version","core":"arcade"},{"type":"retro","id":"shdancer","slug":"shadow-dancer","title":"Shadow Dancer","description":"Sega's 1989 ninja sequel teams a shinobi with a loyal dog to defuse a terrorist bomb plot.","about":"Shadow Dancer - Kage no Mai is Sega's 1989 arcade sequel to 1988's Shinobi. A young ninja and his canine partner hunt down time bombs planted across a metropolis by a terrorist group, fighting through jump-and-projectile action to stop the criminal mastermind. A key new move sends the dog at the nearest enemy by pulling down and pressing attack, pinning the foe until the player finishes them. If the dog is hurt it shrinks to a puppy and regrows after enough kills. The subtitle translates as Dance of Shadows.","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Sega","year":1989,"players":1,"hardware":"Sega System 18","version":"World version","core":"arcade"},{"type":"retro","id":"snowbros","slug":"snow-bros-nick-and-tom","title":"Snow Bros.: Nick & Tom","description":"Nick and Tom roll snowballs, trap monsters, and kick them flying in this cute 1990 Toaplan arcade classic.","about":"Snow Bros. - Nick & Tom is a single-screen platform arcade game from Toaplan, released in April 1990. One or two players control snowmen Nick and Tom, throwing snowballs to encase enemies and then kicking the giant snowballs across the screen to destroy anything in their path. Across fifty levels, an invincible pumpkin head appears if you take too long, spawning unkillable ghosts. Defeated enemies may drop coloured potion power-ups, and the game was licensed to Romstar for USA distribution and ran on JAMMA-compatible hardware.","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Toaplan","year":1990,"players":2,"hardware":"Kaneko Pandora hardware","core":"arcade"},{"type":"retro","id":"sharrier","slug":"space-harrier","title":"Space Harrier","description":"Sega's 1985 sprite-scaling shooter sends a jetpack hero through a surreal 18-stage fantasy world.","about":"Space Harrier is Sega's 1985 sprite-scaling shoot-em-up, set in the Fantasy Zone, a surreal landscape of abstract structures and checkerboard ground. The jetpack-carrying hero flies or runs while firing a laser at mammoths, alien pods, giant mushrooms, and a fireball-spitting Chinese Dragon boss. Across 18 stages, bosses wait at the end of nearly every one, with bonus stages at the 5th and 12th and a boss rush at the 18th. The game hit Japanese arcades in October 1985, and an early build had players piloting a spaceship instead of a flying man.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Sega","year":1985,"players":1,"hardware":"Sega Hang-On hardware","core":"arcade"},{"type":"retro","id":"starwars","slug":"star-wars","title":"Star Wars","description":"Atari's 1983 vector shooter puts you in Luke's X-Wing to fire a Proton Torpedo into the Death Star's exhaust port.","about":"A single-player 3-D shoot-em-up from Atari, released in May 1983 and based on the first Star Wars film, Episode IV: A New Hope. Players are Luke Skywalker (Red Five), aiming to destroy the Death Star by firing a Proton Torpedo into an exposed exhaust port, surviving three attack phases first: a dogfight with Darth Vader and TIE Fighters, a run across the Death Star surface past laser turrets and towers, and the trench. The game engine came from a two-year-old space project called Warp-Speed, the controls were adapted from Battle Zone, and it was Atari's first game with speech, including Obi-Wan Kenobi's line 'The force will be with you--always'. 10,245 upright units sold at $2,295.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Atari","year":1983,"players":1,"core":"arcade"},{"type":"retro","id":"sf2","slug":"street-fighter-ii-the-world-warrior","title":"Street Fighter II: The World Warrior","description":"Capcom's 1991 arcade landmark Street Fighter II - The World Warrior, running on CP System hardware.","about":"Street Fighter II - The World Warrior is an arcade fighting game published in 1991 by Capcom Company, Limited, running on CP System hardware. This entry covers a re-release on updated hardware. For details about the game itself, see the original Japanese release entry, Street Fighter II - The World Warrior [B-Board 90629B].","system":"Arcade","genre":"fighting","categories":"fighting","developer":"Capcom","year":1991,"players":2,"hardware":"Capcom CP System (CPS1)","version":"World version of 22 May 1991","core":"arcade"},{"type":"retro","id":"strider","slug":"strider","title":"Strider","description":"Capcom's 1989 arcade action game, whose export title screen renders Strider in English over the burning Hiryu kanji.","about":"A 1989 Capcom arcade game on CP System hardware, released overseas as an export version developed in Japan. On the export title screen, Strider appears in English above the 'Hiryu' kanji, which are colored with a purple gradient and start out red before catching fire, unlike the Japanese version where Strider is written in katakana to the left of the kanji. In the US version, Strider Hiryu is missing his yell when swinging his sword. The game was soon re-edited as Strider [B-Board 89624B-3].","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Capcom","year":1989,"players":1,"hardware":"Capcom CP System (CPS1)","version":"USA version","core":"arcade"},{"type":"retro","id":"shangon","slug":"super-hang-on","title":"Super Hang-On","description":"Sega's 1987 superbike racer adds turbo boosts and four global courses to the Hang-On formula.","about":"Super Hang-On is Sega's 1987 checkpoint-based racing sequel to Hang-On, which arrived two years earlier. Riders steer a superbike past rival bikers and roadside obstacles, reaching each stage's checkpoint before time runs out, across courses set in Africa, Asia, America, and Europe. Sega brought in the rolling roads seen in 1986's Out Run and added a turbo button. Holding turbo pushes the bike from its 280kph top speed to 324kph, a risky boost that is often needed to meet the game's tight time limits. It launched in April 1987.","system":"Arcade","genre":"racing","categories":"racing","developer":"Sega","year":1987,"players":1,"hardware":"Sega Out Run hardware","core":"arcade"},{"type":"retro","id":"ssf2","slug":"super-street-fighter-ii-the-new-challengers","title":"Super Street Fighter II: The New Challengers","description":"Capcom's 1993 CPS-II fighter Super Street Fighter II: The New Challengers arrives in its export arcade release.","about":"Super Street Fighter II - The New Challengers is a Capcom arcade fighting game released in 1993 on the CP System II hardware, developed in Japan and distributed as an export release on the Blue Board for USA and other territories. The export versions took localization liberties, altering Cammy's and Fei-Long's endings and changing some voice samples: Cammy's 'Spiral Arrow' became 'Cannon Drill' and 'Cannon Spike' became 'Thrust Kick', while Dee Jay's 'Slash' became 'Max Out'.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"Capcom","year":1993,"players":2,"hardware":"Capcom CP System II (CPS2)","version":"World version of 5 October 1993","core":"arcade"},{"type":"retro","id":"superman","slug":"superman","title":"Superman","description":"Taito's 1988 arcade brawler sends one or two Supermen across US cities to battle the Alien Powers.","about":"A horizontal Taito arcade game released in December 1988 in North America and Europe, then February 1989 in Japan, playable by one or two players, with the second controlling a red Superman against the Alien Powers. Each player moves on foot or in flight with a joystick and uses two buttons to punch, kick, or fire Heat Vision, a high-intensity laser. Colored crystals grant extra energy and weapons such as the Super Blast Punch and Mass Terminator, and cars and gasoline cans can be picked up and hurled at enemies. Rounds take place in New York, San Francisco, Las Vegas, Washington, and an Alien Space Ship. The game opens with John Williams' brilliant musical score from 'Superman... The…","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Taito Corporation","year":1988,"players":2,"hardware":"Taito X System","version":"World version","core":"arcade"},{"type":"retro","id":"kof98","slug":"the-king-of-fighters-98","title":"The King of Fighters '98","description":"SNK's 1998 dream match brings 38 fighters and two fighting styles to the Neo-Geo.","about":"This 1998 SNK one-on-one fighter offers 38 selectable characters and two play styles. Extra mode suits defensive players with a single power gauge, sidesteps and unlimited supers at low energy, while Advanced mode adds the evasive roll and up to three storable gauges. Released in Japan on July 23, 1998, it is known there as Dream Match Never Ends and is framed as Shingo's dream. Its soundtrack borrows themes from earlier KOF titles.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"SNK","year":1998,"players":2,"hardware":"Neo Geo MVS","aka":["The King of Fighters '98: The Slugfest","King of Fighters '98: Dream Match Never Ends"],"core":"arcade"},{"type":"retro","id":"kof99","slug":"the-king-of-fighters-99","title":"The King of Fighters '99","description":"SNK's 1999 Neo-Geo fighter debuts the striker system and expands teams to four characters.","about":"SNK's 1999 Neo-Geo MVS entry introduces the striker system, expanding each team to four characters for a total of 30 selectable fighters. The goal is to defeat Krizalid and his evil feather coat. Released in Japan on July 22, 1999, it features a remixed Fatal Fury Wild Ambition theme for the Fatal Fury Team. K's original slicked-back hairstyle was changed, and Maxima began as a body-slam concept before becoming a fist-fighter.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"SNK","year":1999,"players":2,"hardware":"Neo Geo MVS","aka":["The King of Fighters '99: Millennium Battle"],"core":"arcade"},{"type":"retro","id":"tnzs","slug":"the-new-zealand-story","title":"The New Zealand Story","description":"Guide Tiki the Kiwi through eight-way scrolling stages to rescue his caged friends from a hungry leopard seal.","about":"The New Zealand Story is an eight-way scrolling platform arcade game from Taito Corp, released in September 1988. Players control Tiki the Kiwi, who escapes the clutches of Wally, a large blue leopard seal, and sets out to free his kidnapped friends. Tiki starts with a bow and arrows but can pick up bombs, laser guns, and bouncing fireballs. Jump strength depends on how long the button is held, and players can commandeer balloons, blimps, and UFOs. Tiki also appears as a guest star in Taito's Liquid Kids and Bubble Symphony.","system":"Arcade","genre":"platformer","categories":"platformer","developer":"Taito Corporation Japan","year":1988,"players":2,"version":"World version","core":"arcade"},{"type":"retro","id":"punisher","slug":"the-punisher","title":"The Punisher","description":"Capcom's 1993 arcade brawler puts you in the Punisher's boots, with an export version twist.","about":"The Punisher is a 1993 Capcom arcade game, an export release of the Japanese original, built on CP System hardware. It's a side-scrolling beat-'em-up where you fight through enemies as the Punisher. One notable difference in export versions: the Super Kick produces blood graphics on enemies, replacing the blue flames seen in the Japanese release.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Capcom","year":1993,"players":2,"hardware":"Capcom CP System (CPS1) with QSound","version":"World version of 22 April 1993","core":"arcade"},{"type":"retro","id":"toki","slug":"toki","title":"Toki","description":"TAD Corp's arcade export release from 1989, named after the son of the company's owner.","about":"Toki is an arcade export release from TAD Corp, published in 1989. It was released in the USA on February 22, 1990. The export version was named after Toki, the son of TAD's owner. 1452 PCBs were available at launch, with 150 more added in March. The American version adds a 'Winners Don't Use Drugs' screen during attract mode.","system":"Arcade","genre":"platformer","categories":"platformer","developer":"TAD Corporation","year":1989,"players":2,"version":"World version","core":"arcade"},{"type":"retro","id":"truxton","slug":"truxton","title":"Truxton","description":"Pilot a lone fighter against an alien armada hiding inside five gargantuan asteroids.","about":"Tatsujin is a vertical scrolling shooter released by Taito Corp on October 13, 1988. After surviving an attack on a cargo barge, players pilot a remaining fighter to repel an alien invasion and divert five asteroid fortresses. The game spans eight levels of non-stop action with five bosses. Its title translates from Japanese as 'Master', and it is known outside Japan as Truxton. Polystar released a limited-edition soundtrack album on June 25, 1989.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Toaplan / Taito Corporation","year":1988,"players":2,"hardware":"Toaplan BCU-2 / FCU-2 hardware","version":"Europe / USA version","aka":["Tatsujin"],"core":"arcade"},{"type":"retro","id":"twincobr","slug":"twin-cobra","title":"Twin Cobra","description":"Taito's two-player export shooter from 1987, licensed to Romstar for US distribution.","about":"Twin Cobra is an arcade export release from Taito Corp, published in October 1987. It was licensed to Romstar for US distribution in November 1987. Unlike the Japanese version Kyuukyoku Tiger, Twin Cobra supports two simultaneous players, stores three characters for high scores, and respawns killed players at their current position. Player 1's hero is red and player 2's is blue. These differences make Twin Cobra considerably easier than its Japanese counterpart.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Toaplan / Taito Corporation","year":1987,"players":2,"version":"World version","core":"arcade"},{"type":"retro","id":"twinhawk","slug":"twin-hawk","title":"Twin Hawk","description":"Taito's 1989 export shooter with two-player action and respawning at your current position.","about":"Twin Hawk is an arcade export release from Taito, published in June 1989 and developed in Japan. It is the export version of Dai Senpuu. Twin Hawk supports two simultaneous players, with purple and pink planes for players 1 and 2. When a player dies, they continue at their current position, compensated by tougher larger enemies and increased dynamic difficulty. Small orange bullets are harder to see than in the Japanese version.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Taito Corporation Japan","year":1989,"players":2,"hardware":"Taito X System","version":"World version","core":"arcade"},{"type":"retro","id":"twocrude","slug":"two-crude-dudes","title":"Two Crude Dudes","description":"Data East's 1990 arcade brawler hits North America with street-fighting attitude and two-player action.","about":"Two Crude is the North American arcade release of Data East's Crude Buster, arriving in April 1990. It is a side-scrolling beat-'em-up for one or two players. For full gameplay details, refer to the original Crude Buster entry.","system":"Arcade","genre":"beat-em-up","categories":"beat-em-up","developer":"Data East USA","year":1990,"players":2,"hardware":"Data East DECO IC16 hardware","version":"USA version","core":"arcade"},{"type":"retro","id":"umk3","slug":"ultimate-mortal-kombat-3","title":"Ultimate Mortal Kombat 3","description":"Midway's 1995 fighter expands Mortal Kombat 3 with new combatants and extra finishing moves.","about":"Ultimate Mortal Kombat 3 is Midway's 1995 arcade update to Mortal Kombat 3, adding new characters to the original MK3 roster along with other additions and extras. Two players battle using an 8-way joystick and six buttons for punches, kicks, block, and run. Released in the USA on October 6, 1995, the game runs on Midway Wolf Unit hardware. A subtle detail: Rain's name in the demonstration uses a different font than the other fighters.","system":"Arcade","genre":"fighting","categories":"fighting","developer":"Midway","year":1994,"players":2,"hardware":"Midway Wolf Unit","core":"arcade"},{"type":"retro","id":"viewpoin","slug":"viewpoint","title":"Viewpoint","description":"Sammy's isometric Neo-Geo shooter sends you through claustrophobic space corridors against swarms.","about":"Viewpoint is Sammy's 1992 isometric shooter for SNK Neo-Geo MVS, the company's only game developed and released for that hardware. Players pilot a ship through futuristic, claustrophobic corridors armed with a chargeable pulse laser and three bombs: a scrolling wave of fire, a circular nova blast, and homing mini-missiles. Six stages await. Released in October 1992, it won Best Graphics and Best Music in a Cartridge Game at Electronic Gaming Monthly's 1992 awards. The opening cue \"One, Two, Three, Four, Hit It!\" was sampled from Kurtis Blow's \"AJ Scratch.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Sammy / Aicom","year":1992,"players":2,"hardware":"Neo Geo MVS","core":"arcade"},{"type":"retro","id":"volfied","slug":"volfied","title":"Volfied","description":"Taito's 1989 abstract shooter sends a lone pilot to reclaim his homeworld from alien invaders.","about":"Volfied is Taito's 1989 abstract action shoot-'em-up and an update of the 1981 classic Qix. A space pilot returns to his homeworld of Volfied to find it under alien attack; the surviving inhabitants, hiding underground, signal him for help. Controlling a craft called The Monotros, the player moves along a rectangle's edges and holds the draw button to venture into unclaimed territory, creating closed shapes to capture areas. Each stage has one large enemy plus smaller foes; claimed sections trap and destroy smaller enemies inside for bonus points. Danger only comes while drawing a line.","system":"Arcade","genre":"puzzle","categories":"puzzle","developer":"Taito Corporation Japan","year":1989,"players":2,"version":"World version","core":"arcade"},{"type":"retro","id":"zerowing","slug":"zero-wing","title":"Zero Wing","description":"Toaplan's 1989 arcade shooter began as a training project for new hires before blasting into Japanese arcades.","about":"Zero Wing is a 1989 arcade shoot-'em-up from Toaplan, released in Japan on October 20, 1989. It started as a non-commercial project to train Toaplan recruits, reusing the engine from Hellfire, before the team decided to release it. Staff from Hellfire and Truxton mixed with newcomers, and the soundtrack came from three composers with distinct styles.","system":"Arcade","genre":"shooter","categories":"shooter","developer":"Toaplan","year":1989,"players":1,"hardware":"Toaplan BCU-2 / FCU-2 hardware","core":"arcade"}];
